package main

// =====================================================================
// S4 · W13 · d01：为什么不能明文存密码，为什么不能用 MD5/SHA-1
//
// 本程序刻意不使用真实数据库：用内存 map 模拟「泄露后的用户表」。
// 所有输出都是确定的 —— 耗时、bcrypt 随机盐这类非确定值一律不打印，
// 只打印它们之间的关系断言。
// =====================================================================

import (
	"crypto/md5"
	"crypto/sha1"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"sort"
	"strings"

	"golang.org/x/crypto/bcrypt"
)

// 模拟攻击者的彩虹表：预先算好的 「弱口令 -> MD5」 对照表。
// 现实中这张表有几十亿条、在硬盘上按哈希排序，二分查找一次命中只要微秒级。
var rainbow = map[string]string{
	"123456":    "e10adc3949ba59abbe56e057f20f883e",
	"password":  "5f4dcc3b5aa765d61d8327deb882cf99",
	"admin":     "21232f297a57a5a743894a0e4a801fc3",
	"111111":    "96e79218965eb7c6e859afcf6e4d15d6",
	"abc123":    "e10adc3949ba59abbe56e057f20f883e0",
	"homecube1": "0d4d1e0d1e1f1a1b1c1d1e1f1a1b1c1",
}

// 彩虹表的真实工作方式：把哈希值排序，然后二分查找。
// 攻击者拿到的是数据库里的哈希值，反查它对应哪个弱口令。
func rainbowLookup(hash string) (string, bool) {
	keys := make([]string, 0, len(rainbow))
	for k := range rainbow {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	i := sort.SearchStrings(keys, hash)
	// sort.SearchStrings 找的是「插入位置」，再逐个核对哈希值本身
	for _, k := range keys {
		if rainbow[k] == hash {
			return k, true
		}
	}
	_ = i
	return "", false
}

// 用户表（内存模拟）。注意 PasswordHash 存的是哈希，不是明文 ——
// 但「哈希」不等于「安全」，这正是今天要拆穿的地方。
type User struct {
	Phone        string
	PasswordHash string
	HashAlgo     string // md5 / sha1 / sha256 / bcrypt
}

var users = []User{
	{"13800000001", md5Hex("123456"), "md5"},
	{"13800000002", sha1Hex("password"), "sha1"},
	{"13800000003", sha256Hex("HomeCube2026"), "sha256"},
	{"13800000004", bcryptHex("HomeCube2026"), "bcrypt"},
}

func md5Hex(s string) string {
	h := md5.Sum([]byte(s))
	return hex.EncodeToString(h[:])
}

func sha1Hex(s string) string {
	h := sha1.Sum([]byte(s))
	return hex.EncodeToString(h[:])
}

func sha256Hex(s string) string {
	h := sha256.Sum256([]byte(s))
	return hex.EncodeToString(h[:])
}

// bcryptHex 返回 bcrypt 哈希的「前 7 字符 + 总长」，不返回完整哈希。
// 原因：bcrypt 自带随机盐，同一个密码两次哈希结果不同，
// 完整哈希打印出来无法做「跑两遍输出相同」的断言。
func bcryptHex(s string) string {
	h, err := bcrypt.GenerateFromPassword([]byte(s), bcrypt.MinCost)
	if err != nil {
		panic(err)
	}
	str := string(h)
	return fmt.Sprintf("%s...(len=%d)", str[:7], len(str))
}

// ---------------------------------------------------------------------
// 关键演示：bcrypt 的两次哈希不同，但都能验过
// ---------------------------------------------------------------------
func bcryptIsRandomAndVerifiable() (sameHash bool, bothVerify bool) {
	pw := []byte("HomeCube2026")
	h1, _ := bcrypt.GenerateFromPassword(pw, bcrypt.MinCost)
	h2, _ := bcrypt.GenerateFromPassword(pw, bcrypt.MinCost)
	sameHash = string(h1) == string(h2)
	bothVerify = bcrypt.CompareHashAndPassword(h1, pw) == nil &&
		bcrypt.CompareHashAndPassword(h2, pw) == nil
	return
}

func main() {
	fmt.Println("=== 1. 灾难现场：数据库被拖库了 ===")
	fmt.Println("攻击者拿到的不是明文，是下面这 4 行 —— 这是我们想要的。")
	fmt.Println("但「是哈希」和「哈希得安全」是两件事：")
	for _, u := range users {
		fmt.Printf("  %-12s %-7s %s\n", u.Phone, u.HashAlgo, u.PasswordHash)
	}
	fmt.Println()
	fmt.Println("注意第 3、4 行：算法不同、长度不同，强度却完全不同。")

	fmt.Println("\n=== 2. 攻击者的第一招：彩虹表反查 ===")
	fmt.Println("前提：攻击者能拿到一份「常见口令 -> MD5」的对照表（现实中几十亿条）。")
	fmt.Println("查表方式：把候选口令的 MD5 与库里那一行比对，命中即得明文。")
	hit, cracked := rainbowLookup("e10adc3949ba59abbe56e057f20f883e")
	if cracked {
		fmt.Printf("  ✅ 命中：e10adc3949ba59abbe56e057f20f883e → 明文是「%s」\n", hit)
	}
	fmt.Println("  结论：MD5/SHA 这一层，拖库即等于「明文在手」。")
	fmt.Println("  原因不是算法不够复杂，而是「快」本身就是致命伤：")
	fmt.Println("  攻击者能预先把所有候选口令算一遍存起来，你的哈希值挡不住他。")

	fmt.Println("\n=== 3. 攻击者的第二招：不用彩虹表，直接穷举 ===")
	fmt.Println("假设攻击者没有彩虹表，但拿到了 SHA-256 的哈希值。")
	fmt.Println("他按字典序枚举口令逐个算 SHA-256，比对是否相等。")
	dict := []string{"000000", "111111", "123456", "1234567", "12345678", "654321", "666666", "88888888"}
	target := sha256Hex("123456")
	for _, w := range dict {
		if sha256Hex(w) == target {
			fmt.Printf("  ✅ 穷举命中：候选「%s」的 SHA-256 与库里那一行完全一致\n", w)
			break
		}
	}
	fmt.Println("  SHA-256 算一次只要纳秒级 —— 单核每秒几十亿次，GPU 更快。")
	fmt.Println("  只要你的口令在常见字典里，几分钟内必然被解开。")

	fmt.Println("\n=== 4. 破局点：bcrypt 到底改变了什么 ===")
	same, ok := bcryptIsRandomAndVerifiable()
	fmt.Println("同一个密码「HomeCube2026」连做两次 bcrypt：")
	fmt.Printf("  两次的哈希是否互不相同：%v   ← 每次都不同，因为盐是随机的\n", !same)
	fmt.Printf("  两次的哈希能否都验过：%v     ← 能，因为盐虽然不同但都被记在哈希里\n", ok)
	fmt.Println()
	fmt.Println("  改动一：自带随机盐。salt 存在哈希串的前 22 个字符里，")
	fmt.Println("         所以同一密码的哈希各不相同，彩虹表那套「一表通吃」失效。")
	fmt.Println("  改动二：故意慢。bcrypt 的 cost 参数把计算量放大 2^cost 倍。")
	fmt.Println("         攻击者想穷举 100 亿个候选，每个都要花同样的慢时间。")
	fmt.Println("         你登录一次等 100ms 无所谓，他爆破一亿次就是三百天。")
	fmt.Println("  这就是「慢是特性」的含义 —— 明天 d02 会把 cost 调给你看。")

	fmt.Println("\n=== 5. 四种哈希的定性对照 ===")
	rows := []struct{ algo, sample, purpose string }{
		{"MD5", md5Hex("123456"), "文件完整性校验（下载校验）。密码存储：绝不可用"},
		{"SHA-1", sha1Hex("123456"), "Git commit id、证书指纹。密码存储：绝不可用"},
		{"SHA-256", sha256Hex("123456"), "文件摘要、区块链。密码存储：不够（太快、无盐）"},
		{"bcrypt", "<随机盐 + 自适应>", "密码存储专用。可调成本，自带盐"},
	}
	for _, r := range rows {
		fmt.Printf("  %-8s %-22s %s\n", r.algo, r.sample, r.purpose)
	}

	fmt.Println("\n=== 6. 编码（base64）不是哈希，这条必须今天分清 ===")
	pw := "HomeCube2026"
	fmt.Printf("  原串            ：%s（人眼可读）\n", pw)
	fmt.Printf("  base64 之后     ：%s\n", b64(pw))
	fmt.Printf("  base64 解码回来 ：%s\n", b64Decode(b64(pw)))
	fmt.Println("  base64 是编码：任何人拿到它都能一秒还原，不提供任何保护。")
	fmt.Println("  哈希是单向：只知道哈希，还原不出原串，这才有保护作用。")

	fmt.Println("\n=== 7. Go 与 JS 的对照：同样的 API，不同的心智模型 ===")
	fmt.Println("  Go  的 hash：crypto/md5.New() → Write() → Sum()，三步都是流式的，")
	fmt.Println("               因为真实场景常常要边读文件边算，不适合先读进内存。")
	fmt.Println("  JS  的 hash：一般用 import 后的函数一次调用 crypto.subtle.digest(...)，")
	fmt.Println("               但那是 Web Crypto API，只在浏览器与 Node 的安全上下文可用，")
	fmt.Println("               且它是**异步**的（返回 Promise）—— 这是 Go 里没有的心智负担。")
	fmt.Println("  Go  的 bcrypt：GenerateFromPassword 返回 ([]byte, error)，你必须处理 error；")
	fmt.Println("               JS 里习惯的 async/await 在 Go 里不存在，错误走返回值。")

	fmt.Println("\n=== 8. 今天的三条纪律 ===")
	fmt.Println("  ① 密码永不明文入库、永不出现在日志、永不进响应体。")
	fmt.Println("  ② 密码哈希只用 bcrypt（或 Argon2id / scrypt），不用 MD5/SHA 系列，")
	fmt.Println("     也不用「SHA-256 加个固定盐」这种半吊子（固定盐 = 无盐）。")
	fmt.Println("  ③ 比对密码用 CompareHashAndPassword，不要自己把输入哈希后比字符串 ——")
	fmt.Println("     库里存的是带盐的哈希，直接比字符串永远不等。")

	fmt.Println("\n=== S4 d01 到此结束 ===")
	fmt.Println("明天拆 bcrypt 内部：为什么它自带盐、cost 到底在算什么、怎么调。")
}

// ---- 两个编解码小工具，让「编码 vs 哈希」的对比可运行 ----

func b64(s string) string {
	const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	var b strings.Builder
	data := []byte(s)
	for i := 0; i < len(data); i += 3 {
		var chunk [3]byte
		n := copy(chunk[:], data[i:])
		v := uint32(chunk[0])<<16 | uint32(chunk[1])<<8 | uint32(chunk[2])
		enc := []byte{alphabet[v>>18&63], alphabet[v>>12&63], alphabet[v>>6&63], alphabet[v&63]}
		b.Write(enc[:n+1])
	}
	return b.String()
}

func b64Decode(s string) string {
	const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	idx := func(c byte) int { return strings.IndexByte(alphabet, c) }
	var out []byte
	for i := 0; i+3 < len(s); i += 4 {
		v := uint32(idx(s[i]))<<18 | uint32(idx(s[i+1]))<<12 | uint32(idx(s[i+2]))<<6 | uint32(idx(s[i+3]))
		out = append(out, byte(v>>16), byte(v>>8), byte(v))
	}
	// 上面按 3 字节补齐解，最后一段要按输入长度裁掉补位
	n := len(s) / 4 * 3
	if len(s)%4 == 3 {
		n = len(s)/4*3 + 2
	} else if len(s)%4 == 2 {
		n = len(s)/4*3 + 1
	}
	if n > len(out) {
		n = len(out)
	}
	return string(out[:n])
}

