	fmt.Println("               但那是 Web Crypto API，只在浏览器与 Node 的安全上下文可用，")
	fmt.Println("               且它是**异步**的（返回 Promise）—— 这是 Go 里没有的心智负担。")
	fmt.Println("  Go  的 bcrypt：GenerateFromPassword 返回 ([]byte, error)，你必须处理 error；")
	fmt.Println("               JS 里习惯的 async/await 在 Go 里不存在，错误走返回值。")

	fmt.Println("\n=== 8. 今天的三条纪律 ===")
	fmt.Println("  ① 密码永不明文入库、永不出现在日志、永不进响应体。")
	fmt.Println("  ② 密码哈希只用 bcrypt（或 Argon2id / scrypt），不用 MD5/SHA 系列，")
	fmt.Println("     也不用「SHA-256 加个固定盐」这种半吊子（固定盐 = 无盐）。")
	fmt.Println("  ③ 比对密码用 CompareHashAndPassword，不要自己把输入哈希后比字符串 ——")
	fmt.Println("     库里存的是带盐的哈希，直接比字符串永远不等。")

	fmt.Println("\n=== S4 d01 到此结束 ===")
	fmt.Println("明天拆 bcrypt 内部：为什么它自带盐、cost 到底在算什么、怎么调。")
}

// ---- 两个编解码小工具，让「编码 vs 哈希」的对比可运行 ----

func b64(s string) string {
	const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	var b strings.Builder
	data := []byte(s)
	for i := 0; i < len(data); i += 3 {
		var chunk [3]byte
		n := copy(chunk[:], data[i:])
		v := uint32(chunk[0])<<16 | uint32(chunk[1])<<8 | uint32(chunk[2])
		enc := []byte{alphabet[v>>18&63], alphabet[v>>12&63], alphabet[v>>6&63], alphabet[v&63]}
		b.Write(enc[:n+1])
	}
	return b.String()
}

func b64Decode(s string) string {
	const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	idx := func(c byte) int { return strings.IndexByte(alphabet, c) }
	var out []byte
	for i := 0; i+3 < len(s); i += 4 {
		v := uint32(idx(s[i]))<<18 | uint32(idx(s[i+1]))<<12 | uint32(idx(s[i+2]))<<6 | uint32(idx(s[i+3]))
		out = append(out, byte(v>>16), byte(v>>8), byte(v))
	}
	// 上面按 3 字节补齐解，最后一段要按输入长度裁掉补位
	n := len(s) / 4 * 3
	if len(s)%4 == 3 {
		n = len(s)/4*3 + 2
	} else if len(s)%4 == 2 {
		n = len(s)/4*3 + 1
	}
	if n > len(out) {
		n = len(out)
	}
	return string(out[:n])
}

// =====================================================================
// S4 · W13 · d02：bcrypt 详解
//
//   为什么自带盐 / 为什么慢是特性 / cost 参数到底在算什么
//
// 关键约束：耗时是真实测量值，会随机器波动，所以本程序**不打印耗时数字**，
// 只打印理论倍数（2^(cost-4)，完全确定）与「谁比谁慢」的布尔断言。
// =====================================================================

import (
	"crypto/sha256"
	"errors"
	"fmt"
	"strings"
	"time"

	"golang.org/x/crypto/bcrypt"
)

const pw = "HomeCube2026"

func main() {
	fmt.Println("=== 1. bcrypt 哈希串的解剖（60 个字符，六段） ===")
	h, err := bcrypt.GenerateFromPassword([]byte(pw), 10)
	if err != nil {
		panic(err)
	}
	s := string(h)
	// 盐与哈希值是随机的，不能直接打印（否则两次运行输出不同）。
	// 这里只打印确定的部分：版本号、cost、以及两段的字符数。
	seg := []struct {
		name  string
		v     string
		chars int
		what  string
	}{
		{"$ 前缀", s[0:1], 1, "所有 bcrypt 哈希都以 $ 开头"},
		{"版本号", s[1:3], 2, "$2a$ 的中间两位。2a 是 bcrypt，2b/2y 是后来的变体，读法一样"},
		{"cost", s[4:6], 2, "十进制的 10，表示内部循环 2^10 = 1024 次"},
		{"盐", "「随机 22 字符」", 22, "s[7:29]，bcrypt 自带的 base64 变体盐，明文存在哈希里"},
		{"哈希值", "「随机 31 字符」", 31, "s[29:60]，口令 + 盐 经 Blowfish 变体密钥扩展的结果"},
	}
	for _, x := range seg {
		fmt.Printf("  %-8s [%s]  %d 字符  %s\n", x.name, x.v, x.chars, x.what)
	}
	fmt.Printf("  完整串 ：%s〔盐22字符〕〔哈希31字符〕\n", s[:7])
	fmt.Printf("  实际长度：%d 个字符（bcrypt 固定 60，这是它的一个特点）\n", len(s))
	fmt.Println("  ↑ 位置 0-6 的「$2a$10$」是确定的；")
	fmt.Println("    位置 7 之后的 53 个字符每次都不一样，因为盐是随机的。")
	fmt.Println("    所以手工切字符串时，索引别写死 —— 用 s[:7] 取前缀，")
	fmt.Println("    用 bcrypt.Cost(h) 取 cost，这两个才是接口该给你用的东西。")
	fmt.Println()
	fmt.Println("  三个必须记住的事实：")
	fmt.Println("   ① 盐在哈希串里 —— 所以不需要单独建 salt 列，也不可能「盐丢了导致全库不可用」。")
	fmt.Println("   ② cost 也在哈希串里 —— 所以你可以在任何时候调高 cost，")
	fmt.Println("      而老用户下次登录时自动用老哈希里的 cost 验证，成功后顺手升级为新 cost。")
	fmt.Println("      这个机制叫「渐进升级」，d05 会真跑一遍。")
	fmt.Println("   ③ bcrypt 只处理前 72 字节。超过 72 字节的部分被静默丢弃 ——")
	fmt.Println("      所以 bcrypt 不适合加密长口令或文件，用它的地方只有口令。")

	fmt.Println("\n=== 2. 为什么自带盐：亲手构造一次「无盐」的失败 ===")
	plain := sha256Hex(pw)
	fmt.Printf("  SHA-256(HomeCube2026) = %s\n", plain)
	fmt.Printf("  再算一次               = %s\n", sha256Hex(pw))
	fmt.Println("  两次完全相同 → 攻击者的彩虹表里只要有一行「这个口令的哈希」，")

