package main

// =====================================================================
// S4 · W13 · d03：用户表设计与建档
//
//   手机号 + 密码、邮箱/手机号唯一索引、用户状态
//
// 本机没有 Postgres，所以：
//   · DDL 作为字符串常量给出（完整可执行，S3 d21 之后直接贴进迁移文件）
//   · 用内存 map 模拟表，真跑一遍「建档 / 唯一约束 / 状态流转」

// ---------------------------------------------------------------------

type User struct {
	ID             string
	Phone          string
	Email          *string // 可空 → Go 里必须用指针
	PasswordHash   string
	Status         string
	FailedAttempts int
	LockedUntil    *string // 可空
	DeletedAt      *string // 软删（W13 d3 就带上，呼应铁律 2）
	Version        int
}

type UserStore struct {
	rows map[string]*User // 主键索引
}

func NewUserStore() *UserStore {
	return &UserStore{rows: map[string]*User{}}
}

var (
	ErrPhoneTaken   = errors.New("phone already registered")
	ErrEmailTaken   = errors.New("email already registered")
	ErrBadPhone     = errors.New("phone must be 11 digits")
	ErrBadEmail     = errors.New("email format invalid")
	ErrUserNotFound = errors.New("user not found")
	ErrDisabled     = errors.New("user account disabled")
)

var (
	rePhone = regexp.MustCompile(`^[0-9]{11}$`)
	reEmail = regexp.MustCompile(`^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$`)
)

// Create 建档。**注意校验顺序**：先跑正则（便宜的），再查唯一索引（贵的）。
// 顺序反了会让每个非法请求都白跑一次唯一索引查询。
func (s *UserStore) Create(id, phone string, email *string, password string) (*User, error) {
	if !rePhone.MatchString(phone) {
		return nil, ErrBadPhone
	}
	if email != nil && !reEmail.MatchString(*email) {
		return nil, ErrBadEmail
	}
	for _, u := range s.rows {
		if u.DeletedAt != nil {
			continue // 已软删的不占唯一索引
		}
		if u.Phone == phone {
			return nil, fmt.Errorf("%w: %s", ErrPhoneTaken, phone)
		}
		if email != nil && u.Email != nil && *u.Email == *email {
			return nil, fmt.Errorf("%w: %s", ErrEmailTaken, *email)
		}
	}
	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return nil, err
	}
	u := &User{
		ID:           id,
		Phone:        phone,
		Email:        email,
		PasswordHash: string(hash),
		Status:       "active",
		Version:      1,
	}
	s.rows[id] = u
	return u, nil
}

// Verify 登录校验：先看状态，再验密码。顺序不能反 ——
// 对一个已停用的账号跑 bcrypt 是纯浪费（那 100ms 谁付？）。

func u0ID(u *User) string {
	if u == nil {
		return "-"
	}
	return u.ID
}

func hashPrefix(u *User) string {
	if u == nil || len(u.PasswordHash) < 7 {
		return "-"
	}
	return u.PasswordHash[:7]
}

func u0Version(u *User) int {
	if u == nil {
		return 0
	}
	return u.Version
}

var _ = strings.TrimSpace

code.content:
package main

// =====================================================================
// S4 · W13 · d04：手机号验证码登录
//
//   生成 / 哈希存储（不存明文）/ 限流（每分钟 1 次、每天 10 次）/ 过期
//
// 时间用「假时钟」：所有 now() 都是一个手动推进的变量，
// 这样输出完全确定，又能真跑出「30 秒后过期」「1 分钟后才能重发」的效果。
// =====================================================================

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"

	"golang.org/x/crypto/bcrypt"
)

// ---------------------------------------------------------------------
// 假时钟：整个程序唯一的「现在」
// ---------------------------------------------------------------------

type Clock struct{ now time.Time }

func (c *Clock) Now() time.Time          { return c.now }
func (c *Clock) Advance(d time.Duration) { c.now = c.now.Add(d) }

var clock = &Clock{now: time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)}

// ---------------------------------------------------------------------
// 验证码表
// ---------------------------------------------------------------------

type SmsCode struct {
	Phone      string
	Hash       string // SHA-256(验证码 + 服务端 pepper)，**不是明文**
	Cost       int    // 记录当时的 bcrypt cost 仅为教学展示
	ExpiresAt  time.Time
	Used       bool
	Attempts   int // 校验失败次数，超过 3 次即作废
	CreatedAt  time.Time
	Purpose    string // register / login / reset_password
	Scenario   string // 用途分离：同一手机号可以同时有一个 register 和一个 login 待校验
	DeviceHint string
}

var (
	codes   = map[string]*SmsCode{}
	sentLog []string
)

var (
	ErrTooFrequent   = errors.New("sms too frequent")
	ErrDailyExceeded = errors.New("daily limit reached: 10/10")
	ErrCodeExpired   = errors.New("code expired")
	ErrCodeWrong     = errors.New("code mismatch")
	ErrCodeUsed      = errors.New("code already used")
	ErrCodeAbandoned = errors.New("too many wrong attempts: code revoked")
	ErrNoPendingCode = errors.New("no pending code for this phone and purpose")
)

// 计数窗口
type Window struct {
	PerMinute map[string][]time.Time
	PerDay    map[string][]time.Time
}

func NewWindow() *Window {
	return &Window{PerMinute: map[string][]time.Time{}, PerDay: map[string][]time.Time{}}
}

// Send 发一条验证码。**返回的明文只出现在这一行的响应体里，绝不入库。**
func (w *Window) Send(phone, purpose, deviceHint string) (string, error) {
	now := clock.Now()
	key := phone + ":" + purpose

	// 窗口一：每分钟最多 1 次（tech-plan §8.5 与 PRD 3.7 都要求）
	min := prune(w.PerMinute[key], now.Add(-time.Minute))
	if len(min) > 0 {
		wait := int(min[len(min)-1].Add(time.Minute).Sub(now).Seconds()) + 1
		return "", fmt.Errorf("%w: %ds", ErrTooFrequent, wait)
	}
	// 窗口二：每天最多 10 次
	day := pruneDay(w.PerDay[phone], now)
	if len(day) >= 10 {
		return "", fmt.Errorf("%w: %d/10", ErrDailyExceeded, len(day))
	}

	code, err := randCode()
	if err != nil {
		return "", err
	}
	w.PerMinute[key] = append(min, now)
	w.PerDay[phone] = append(day, now)

	// 库里只存哈希。注意：这里**故意不用 bcrypt** —— 验证码是 6 位数字，
	// 空间只有 100 万，bcrypt 的慢在这里毫无意义（穷举一百万次只要几分钟）。
	// 正确做法是 SHA-256(验证码 + 服务端 pepper)，pepper 存在环境变量里，
	// 不在数据库。这样即使库被拖走，攻击者也拿不到 pepper。
	codes[hashKey(phone, purpose)] = &SmsCode{
		Phone:     phone,
		Hash:      pepperHash(code),
		ExpiresAt: now.Add(5 * time.Minute),
		CreatedAt: now,
		Purpose:   purpose,
		Scenario:  deviceHint,
	}
	sentLog = append(sentLog, fmt.Sprintf("[%s] → %s  purpose=%s device=%s 验证码=%s（仅出现在这一次响应里）",
		now.Format("15:04:05"), maskPhone(phone), purpose, deviceHint, code))
	return code, nil
}

// 真 crypto/rand 的验证：只看「长度、是否为纯数字、两次是否不同」，
// 不打印具体值（值本来也不该出现在日志里）。
func cryptoRandSanity() (lenOK, digitsOK, diff bool) {
	a, err1 := randCodeFrom(rand.Reader)
	b, err2 := randCodeFrom(rand.Reader)
	if err1 != nil || err2 != nil {
		return false, false, false
	}
	lenOK = len(a) == 6 && len(b) == 6
	digitsOK = allDigits(a) && allDigits(b)
	diff = a != b
	return
}

func randCodeFrom(r ByteSource) (string, error) {
	var b [4]byte
	if _, err := r.Read(b[:]); err != nil {
		return "", err
	}
	n := int(b[0])<<24 | int(b[1])<<16 | int(b[2])<<8 | int(b[3])
	return fmt.Sprintf("%06d", n%1000000), nil
}

func allDigits(s string) bool {
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return len(s) > 0
}

// Verify 校验。同一个 (phone, purpose) 只保留一条待校验记录。
func Verify(phone, purpose, input string) error {
	rec, ok := codes[hashKey(phone, purpose)]
	if !ok {
		return ErrNoPendingCode
	}
	now := clock.Now()
	if rec.Used {
		return ErrCodeUsed
	}
	if now.After(rec.ExpiresAt) {
		return fmt.Errorf("%w: sent at %s, ttl 5m", ErrCodeExpired,
			rec.CreatedAt.Format("15:04:05"))
	}
	if rec.Attempts >= 3 {
		return ErrCodeAbandoned
	}
	if pepperHash(input) != rec.Hash {
		rec.Attempts++
		return fmt.Errorf("%w: attempt %d/3", ErrCodeWrong, rec.Attempts)
	}
	rec.Used = true
	return nil
}

// ---------------------------------------------------------------------
// 随机源：接口化，方便「真 crypto/rand」与「确定的演示序列」共存
// ---------------------------------------------------------------------

type ByteSource interface{ Read(p []byte) (int, error) }

// detSeq 是一个**确定**的字节源，只用于本程序的演示输出。
// 换成 crypto/rand.Reader 行为完全一样，区别只在可预测性。
type detSeq struct {
	state uint64
	seq   []uint32 // 预置的一串码，保证每次运行输出相同
	i     int
}

func (d *detSeq) Read(p []byte) (int, error) {
	if d.i >= len(d.seq) {
		d.state = d.state*6364136223846793005 + 1442695040888963407
		v := uint32(d.state >> 33)
		for i := 0; i < len(p); i++ {
			p[i] = byte(v >> (8 * (i % 4)))
		}
		d.i++
		return len(p), nil
	}
	v := d.seq[d.i]
	d.i++
	for i := 0; i < len(p); i++ {
		p[i] = byte(v >> (8 * (i % 4)))
	}
	return len(p), nil
}

// src 是全局随机源。生产环境必须是 crypto/rand.Reader。
var src ByteSource = &detSeq{seq: []uint32{
	823448, 761284, 195783, 57673, 245047, 418822, 903176, 552314, 178093, 664820,
}}

func randCode() (string, error) {
	// 读 4 字节凑成 32 位无符号数，对 10^6 取模得到 6 位数字。
	// 取模会有极小的分布偏差（因为 2^32 不是 10^6 的整数倍），
	// 对验证码来说完全可接受 —— 要严格无偏要用 rejection sampling，
	// 但那时 6 位数字里 000000-000003 这些值出现概率略高是理论问题，不是安全问题。
	var b [4]byte
	if _, err := src.Read(b[:]); err != nil {
		return "", err
	}
	n := int(b[0])<<24 | int(b[1])<<16 | int(b[2])<<8 | int(b[3])
	return fmt.Sprintf("%06d", n%1000000), nil
}

// pepper 从环境变量来。硬编码在源码里的 pepper 等于没有 pepper。
const pepper = "从环境变量 HOMEOS_SMS_PEPPER 读进来"

func pepperHash(code string) string {
	h := sha256.Sum256([]byte(pepper + ":" + code))
	return hex.EncodeToString(h[:])
}

// hashKey 只是让 map 的 key 短一点，不是安全措施 —— 说明这一点很重要。
func hashKey(phone, purpose string) string {
	return phone + "|" + purpose
}

func prune(ts []time.Time, before time.Time) []time.Time {
	out := ts[:0:0]
	for _, t := range ts {
		if t.After(before) {
			out = append(out, t)
		}
	}
	return out
}

func pruneDay(ts []time.Time, now time.Time) []time.Time {
	start := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
	out := ts[:0:0]
	for _, t := range ts {
		if t.After(start) {
			out = append(out, t)
		}
	}
	return out
}

func maskPhone(p string) string {
	if len(p) != 11 {
		return p
	}
	return p[:3] + "****" + p[7:]
}

func main() {
	w := NewWindow()

	fmt.Println("=== 1. 验证码的六条规则（本项目取值） ===")
	rules := []struct{ k, v, why string }{
		{"长度", "6 位数字", "输入成本要低（手机上打字），但 10^6 的空间配合「限 3 次尝试 + 5 分钟过期」够用"},
		{"过期", "5 分钟", "太长会被别人捡到（短信可能留在锁屏上），太短用户体验差"},
		{"每分钟", "1 次", "防「拿到别人手机号轰炸短信」，也是用户体验底线"},
		{"每天", "10 次", "防短信费用被刷（PRD 14.6 明确本期不接商用短信通道，这条是替身约束）"},
		{"校验失败", "3 次即作废", "6 位数字只有 100 万种，限 3 次 = 单条码最多被试 3 次"},
		{"用途", "register / login / reset_password 分开", "同一手机号可以同时有一个注册码和一个登录码，不会互相顶掉"},
	}
	for _, r := range rules {
		fmt.Printf("  %-6s %-28s %s\n", r.k, r.v, r.why)
	}
	fmt.Println()

	fmt.Println("=== 2. 发第一条验证码 ===")
	code1, err := w.Send("13800000001", "login", "iphone15")
	if err != nil {
		fmt.Printf("  ❌ %v\n", err)
		return
	}
	fmt.Printf("  响应体 data.code = %s\n", code1)
	fmt.Println("  → 这一行是接口唯一一次出现明文的地方。入库的是它的 SHA-256，不是它。")
	rec := codes[hashKey("13800000001", "login")]
	fmt.Printf("  → 入库的是：code_hash=%s...\n", rec.Hash[:32])
	fmt.Printf("  → expires_at=%s  used=%v  attempts=%d\n",
		rec.ExpiresAt.Format("15:04:05"), rec.Used, rec.Attempts)

	fmt.Println("\n=== 3. 立刻重发：被每分钟 1 次拦住 ===")
	_, err = w.Send("13800000001", "login", "iphone15")
	fmt.Printf("  ❌ %v\n", err)
	fmt.Println("  注意错误里带上了「还要等多久」—— 前端可以直接显示倒计时，")
	fmt.Println("  而不是一个干巴巴的「操作过于频繁」。")

	fmt.Println("\n=== 4. 校验：先看错、再看对（顺序很重要） ===")
	c1b, _ := w.Send("13800000001", "register", "iphone15")
	err = Verify("13800000001", "login", "000000")
	fmt.Printf("  传错验证码 → %v\n", err)
	fmt.Println("     attempts 被记为 1。注意没有把真码告诉他 —— 错误信息里不能有它。")
	err = Verify("13800000001", "login", code1)
	if err == nil {
		fmt.Printf("  再传真码   → ✅ 通过\n")
	} else {
		fmt.Printf("  再传真码   → ❌ %v\n", err)
	}
	err = Verify("13800000001", "login", code1)
	fmt.Printf("  再传一次   → %v\n", err)
	fmt.Println("     一次性：校验通过后立刻置 used，不给「同一个码反复用」留口子。")
	_ = c1b
	fmt.Println("  ⚠ 顺带一提：13800000001 上还挂着一个 register 用途的码（第一条日志）。")
	fmt.Println("     它和 login 用途的码互不影响 —— 用途分离就是为了这个。")

	fmt.Println("\n=== 5. 3 次失败即作废（先造一条新码来试） ===")
	c2, _ := w.Send("13800000002", "login", "pixel8")
	for i := 1; i <= 4; i++ {
		err := Verify("13800000002", "login", "111111")
		fmt.Printf("  第 %d 次错误校验 → %v\n", i, err)
	}
	fmt.Println("  第 4 次开始返回的不是「验证码错误」而是「已作废」——")
	fmt.Println("  这两者必须分开报错：前者说明还可以继续试，后者说明这条码没救了。")
	fmt.Println("  （顺带验证：作废之后即使拿到真码也过不了）")
	err = Verify("13800000002", "login", c2)
	fmt.Printf("  用真码再试 → %v\n", err)

	fmt.Println("\n=== 6. 5 分钟过期（推进假时钟，不 sleep） ===")
	// 两个手机号，各发一条码：一个用来验「还在有效期内」，一个用来验「已过期」。
	cOK, _ := w.Send("13800000003", "login", "iphone15")
	cExpired, _ := w.Send("13800000005", "login", "iphone15")
	fmt.Printf("  %s 给两个手机号各发一条验证码\n", clock.Now().Format("15:04:05"))
	clock.Advance(4 * time.Minute)
	err = Verify("13800000003", "login", cOK)
	if err == nil {
		fmt.Printf("  %s 校验 A（还剩 1 分钟）→ ✅ 通过\n", clock.Now().Format("15:04:05"))
	} else {
		fmt.Printf("  %s 校验 A（还剩 1 分钟）→ ❌ %v\n", clock.Now().Format("15:04:05"), err)
	}
	clock.Advance(2 * time.Minute)
	err = Verify("13800000005", "login", cExpired)
	fmt.Printf("  %s 校验 B（已过 6 分钟）→ %v\n", clock.Now().Format("15:04:05"), err)
	fmt.Println("  ⚠ 过期判断必须放在「比对哈希」之前。否则一条 6 位数字的码，")
	fmt.Println("    在过期后仍然可以被无限次试到对 —— 过期这个字段就白设了。")
	fmt.Println("  ⚠ 另一个顺序问题：已过期 / 验证码错误 / 已作废，三者要分开返回。")
	fmt.Println("    「已过期」可以引导用户「重新获取」，另两个只能给统一的模糊提示。")
	fmt.Println("    否则攻击者能靠错误类型判断「我猜的码离正确答案差多远」——")
	fmt.Println("    这就是枚举码泄露，和 d03 里的用户枚举是同一类问题。")

	fmt.Println("\n=== 7. 每天 10 次上限（跨过午夜窗口重置） ===")
	clock.Advance(24 * time.Hour)
	fmt.Printf("  现在是 %s（跨了一天，昨天那些发送记录不在今天的窗口里）\n",
		clock.Now().Format("01-02 15:04"))
	_, err = w.Send("13800000004", "login", "iphone15")
	fmt.Printf("  换一个手机号发第一条 → 成功=%v\n", err == nil)
	fmt.Println("  每分钟窗口和每天窗口是**两个独立计数器**，别用一个计数器凑。")
	fmt.Println("  而且「每天」的窗口要按**自然日**切（本地时区 00:00），")
	fmt.Println("  不能写成「最近 24 小时内最多 10 次」—— 后者在跨午夜那几分钟")
	fmt.Println("  会让用户莫名其妙地被限。这条要在真库里用 created_at 的日期分组来算。")

	fmt.Println("\n=== 8. 全部发送记录（模拟服务端写日志） ===")
	fmt.Println("  ⚠ 这份日志是「我们自己」打印的调试日志。生产环境里它必须是：")
	fmt.Println("     只记手机号（脱敏）+ 用途 + 是否成功，**绝不记验证码明文**。")
	fmt.Println()
	fmt.Println("  另注：本程序为了让输出确定，randCode 走的是一个固定序列，")
	fmt.Println("  生产环境必须换成 crypto/rand.Reader —— 两者接口完全一样，换一行即可：")
	lenOK, digitsOK, diff := cryptoRandSanity()
	fmt.Printf("     换成真 crypto/rand 后：长度都是 6=%v  全是数字=%v  两次不同=%v\n", lenOK, digitsOK, diff)
	fmt.Println()
	for i, l := range sentLog {
		fmt.Printf("  %2d. %s\n", i+1, l)
	}

	fmt.Println("\n=== 9. 哈希 vs bcrypt：这里为什么**不该**用 bcrypt ===")
	// 真跑一次对比：bcrypt 存验证码要多花多少时间（只打印量级判断）
	start := time.Now()
	_, _ = bcrypt.GenerateFromPassword([]byte("123456"), bcrypt.DefaultCost)
	slow := time.Since(start)
	fmt.Printf("  bcrypt 一次耗时是否达到 50ms 量级：%v\n", slow >= 40*time.Millisecond)
	fmt.Println("  理由：")
	fmt.Println("   · bcrypt 的价值是「让穷举变慢」，但验证码空间只有 10^6，")
	fmt.Println("     限 3 次 + 5 分钟过期已经把在线猜测压到 3 次，bcrypt 的慢在这里不产生额外价值。")
	fmt.Println("   · 而慢是有代价的：每次登录接口要多等 100ms，P95 直接顶上去。")
	fmt.Println("   · 结论：长期凭证（密码）用 bcrypt；短期凭证（验证码）用 SHA-256 + pepper。")
	fmt.Println("     pepper 才是真正的防线 —— 它不在数据库里。")

	fmt.Println("\n=== 10. Go 与 JS 的差异 ===")
	fmt.Println("  ① crypto/rand.Read 在 Go 里返回 (n, error)，必须处理。")
	fmt.Println("     JS 里 crypto.getRandomValues 是同步的且不返回错误（它抛异常）。")
	fmt.Println("  ② 时间处理：Go 用 time.Time + time.Duration，Add/Sub 都是值语义。")
	fmt.Println("     JS 里是 number（毫秒时间戳）+ 加减天数要自己乘 86400000。")
	fmt.Println("     这也是我今天必须引入假时钟的原因：Go 里把 now 抽成一个变量，")
	fmt.Println("     比在 JS 里 mock Date.now() 干净得多 —— 因为 Go 的 Clock 是显式传进去的。")
	fmt.Println("  ③ 补零：Go 用 fmt.Sprintf 加「零填充宽度 6 + d」指令；")
	fmt.Println("     JS 里是 (n % 1e6).toString().padStart(6, '0')，")
	fmt.Println("     同一个意思，但 JS 必须手写 padStart，Go 的 fmt 内置支持。")

	fmt.Println("\n=== S4 d04 到此结束 ===")
	fmt.Println("明天把注册流程补齐：密码强度、重复手机号、注册后要不要自动登录。")
	_ = strconv.Itoa
	_ = strings.TrimSpace
}

