package main

// =====================================================================
// S4 · W13 · d04：手机号验证码登录
//
//   生成 / 哈希存储（不存明文）/ 限流（每分钟 1 次、每天 10 次）/ 过期
//
// 时间用「假时钟」：所有 now() 都是一个手动推进的变量，
// 这样输出完全确定，又能真跑出「30 秒后过期」「1 分钟后才能重发」的效果。

func (c *Clock) Advance(d time.Duration) { c.now = c.now.Add(d) }

var clock = &Clock{now: time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)}

// ---------------------------------------------------------------------
// 验证码表
// ---------------------------------------------------------------------

type SmsCode struct {
	Phone      string
	Hash       string // SHA-256(验证码 + 服务端 pepper)，**不是明文**
	Cost       int    // 记录当时的 bcrypt cost 仅为教学展示
	ExpiresAt  time.Time
	Used       bool
	Attempts   int // 校验失败次数，超过 3 次即作废
	CreatedAt  time.Time
	Purpose    string // register / login / reset_password
	Scenario   string // 用途分离：同一手机号可以同时有一个 register 和一个 login 待校验
	DeviceHint string
}

var (
	codes   = map[string]*SmsCode{}
	sentLog []string
)

var (
	ErrTooFrequent   = errors.New("sms too frequent")
	ErrDailyExceeded = errors.New("daily limit reached: 10/10")
	ErrCodeExpired   = errors.New("code expired")
	ErrCodeWrong     = errors.New("code mismatch")
	ErrCodeUsed      = errors.New("code already used")
	ErrCodeAbandoned = errors.New("too many wrong attempts: code revoked")
	ErrNoPendingCode = errors.New("no pending code for this phone and purpose")
)

// 计数窗口

type Window struct {
	PerMinute map[string][]time.Time
	PerDay    map[string][]time.Time
}

func NewWindow() *Window {
	return &Window{PerMinute: map[string][]time.Time{}, PerDay: map[string][]time.Time{}}
}

// Send 发一条验证码。**返回的明文只出现在这一行的响应体里，绝不入库。**
func (w *Window) Send(phone, purpose, deviceHint string) (string, error) {
	now := clock.Now()
	key := phone + ":" + purpose

	// 窗口一：每分钟最多 1 次（tech-plan §8.5 与 PRD 3.7 都要求）
	min := prune(w.PerMinute[key], now.Add(-time.Minute))
	if len(min) > 0 {
		wait := int(min[len(min)-1].Add(time.Minute).Sub(now).Seconds()) + 1
		return "", fmt.Errorf("%w: %ds", ErrTooFrequent, wait)
	}
	// 窗口二：每天最多 10 次
	day := pruneDay(w.PerDay[phone], now)
	if len(day) >= 10 {
		return "", fmt.Errorf("%w: %d/10", ErrDailyExceeded, len(day))
	}

	code, err := randCode()
	if err != nil {
		return "", err
	}
	w.PerMinute[key] = append(min, now)
	w.PerDay[phone] = append(day, now)

	// 库里只存哈希。注意：这里**故意不用 bcrypt** —— 验证码是 6 位数字，
	// 空间只有 100 万，bcrypt 的慢在这里毫无意义（穷举一百万次只要几分钟）。
	// 正确做法是 SHA-256(验证码 + 服务端 pepper)，pepper 存在环境变量里，
	// 不在数据库。这样即使库被拖走，攻击者也拿不到 pepper。
	codes[hashKey(phone, purpose)] = &SmsCode{
		Phone:     phone,
		Hash:      pepperHash(code),
		ExpiresAt: now.Add(5 * time.Minute),
		CreatedAt: now,
		Purpose:   purpose,
		Scenario:  deviceHint,
	}
	sentLog = append(sentLog, fmt.Sprintf("[%s] → %s  purpose=%s device=%s 验证码=%s（仅出现在这一次响应里）",
		now.Format("15:04:05"), maskPhone(phone), purpose, deviceHint, code))
	return code, nil
}

// 真 crypto/rand 的验证：只看「长度、是否为纯数字、两次是否不同」，
// 不打印具体值（值本来也不该出现在日志里）。

func cryptoRandSanity() (lenOK, digitsOK, diff bool) {
	a, err1 := randCodeFrom(rand.Reader)
	b, err2 := randCodeFrom(rand.Reader)
	if err1 != nil || err2 != nil {
		return false, false, false
	}
	lenOK = len(a) == 6 && len(b) == 6
	digitsOK = allDigits(a) && allDigits(b)
	diff = a != b
	return
}

func randCodeFrom(r ByteSource) (string, error) {
	var b [4]byte
	if _, err := r.Read(b[:]); err != nil {
		return "", err
	}
	n := int(b[0])<<24 | int(b[1])<<16 | int(b[2])<<8 | int(b[3])
	return fmt.Sprintf("%06d", n%1000000), nil
}

func allDigits(s string) bool {
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return len(s) > 0
}

// Verify 校验。同一个 (phone, purpose) 只保留一条待校验记录。
func Verify(phone, purpose, input string) error {
	rec, ok := codes[hashKey(phone, purpose)]
	if !ok {
		return ErrNoPendingCode
	}
	now := clock.Now()
	if rec.Used {
		return ErrCodeUsed
	}
	if now.After(rec.ExpiresAt) {
		return fmt.Errorf("%w: sent at %s, ttl 5m", ErrCodeExpired,
			rec.CreatedAt.Format("15:04:05"))
	}
	if rec.Attempts >= 3 {
		return ErrCodeAbandoned
	}
	if pepperHash(input) != rec.Hash {
		rec.Attempts++
		return fmt.Errorf("%w: attempt %d/3", ErrCodeWrong, rec.Attempts)
	}
	rec.Used = true
	return nil
}

// ---------------------------------------------------------------------
// 随机源：接口化，方便「真 crypto/rand」与「确定的演示序列」共存

// ---------------------------------------------------------------------

type ByteSource interface{ Read(p []byte) (int, error) }

// detSeq 是一个**确定**的字节源，只用于本程序的演示输出。
// 换成 crypto/rand.Reader 行为完全一样，区别只在可预测性。
type detSeq struct {
	state uint64
	seq   []uint32 // 预置的一串码，保证每次运行输出相同
	i     int
}

func (d *detSeq) Read(p []byte) (int, error) {
	if d.i >= len(d.seq) {
		d.state = d.state*6364136223846793005 + 1442695040888963407
		v := uint32(d.state >> 33)
		for i := 0; i < len(p); i++ {
			p[i] = byte(v >> (8 * (i % 4)))
		}
		d.i++
		return len(p), nil
	}
	v := d.seq[d.i]
	d.i++
	for i := 0; i < len(p); i++ {
		p[i] = byte(v >> (8 * (i % 4)))
	}
	return len(p), nil
}

// src 是全局随机源。生产环境必须是 crypto/rand.Reader。
var src ByteSource = &detSeq{seq: []uint32{
	823448, 761284, 195783, 57673, 245047, 418822, 903176, 552314, 178093, 664820,
}}

func randCode() (string, error) {
	// 读 4 字节凑成 32 位无符号数，对 10^6 取模得到 6 位数字。
	// 取模会有极小的分布偏差（因为 2^32 不是 10^6 的整数倍），
	// 对验证码来说完全可接受 —— 要严格无偏要用 rejection sampling，
	// 但那时 6 位数字里 000000-000003 这些值出现概率略高是理论问题，不是安全问题。
	var b [4]byte
	if _, err := src.Read(b[:]); err != nil {
		return "", err
	}
	n := int(b[0])<<24 | int(b[1])<<16 | int(b[2])<<8 | int(b[3])
	return fmt.Sprintf("%06d", n%1000000), nil
}

// pepper 从环境变量来。硬编码在源码里的 pepper 等于没有 pepper。
const pepper = "从环境变量 HOMEOS_SMS_PEPPER 读进来"

func pepperHash(code string) string {
	h := sha256.Sum256([]byte(pepper + ":" + code))
	return hex.EncodeToString(h[:])
}

// hashKey 只是让 map 的 key 短一点，不是安全措施 —— 说明这一点很重要。

