package main

// =====================================================================
// S4 · W13 · d05：完整注册流程
//
//   密码强度校验 / 重复手机号检测 / 注册后要不要自动登录 / cost 渐进升级
//
// 一条注册的完整时序，每一步都能被单独观察。
// =====================================================================

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	"golang.org/x/crypto/bcrypt"
)

// ---------------------------------------------------------------------
// 环境：假时钟 + 内存用户表
// ---------------------------------------------------------------------

var now = time.Date(2026, 10, 15, 10, 0, 0, 0, time.UTC)

type User struct {
	ID           string
	Phone        string
	PasswordHash string
	Status       string
	Version      int
	PwdChangedAt time.Time
	CreatedAt    time.Time
}

var users = []*User{}
var auditLog []string
var bcryptCost = bcrypt.MinCost // 全局当前配置：故意从便宜开始，便于演示渐进升级

var (
	ErrWeakPassword = errors.New("password does not meet strength rules")
	ErrPhoneExists  = errors.New("phone already registered")
	ErrCodeBad      = errors.New("sms code invalid")
	ErrUserBlocked  = errors.New("user blocked")
	ErrRateLimited  = errors.New("too many registrations from this ip")
)

// ---- 密码强度：四条规则，逐条给理由 ----

type Rule struct {
	Name  string
	Check func(string) bool
	Why   string
}

var rules = []Rule{
	{"长度 ≥ 10", func(s string) bool { return len([]rune(s)) >= 10 },
		"唯一真正起作用的一条。bcrypt 内部按字节处理，但用户输的是字符，长度按 rune 数算"},
	{"包含小写", func(s string) bool { return strings.ContainsAny(s, "abcdefghijklmnopqrstuvwxyz") },
		"扩大搜索空间。用 NIST SP 800-63B 的说法：长 + 多样 > 短 + 花样"},
	{"包含数字或符号", func(s string) bool {
		return strings.ContainsAny(s, "0123456789") || strings.ContainsAny(s, "!@#$%^&*()-_=+[]{}")
	}, "同上。但注意：这条**不能**反过来写成「必须同时含大小写数字符号」—— 那类规则会把「Password1!」这类模式化口令放行"},
	{"不含常见弱口令", func(s string) bool {
		bad := []string{"password", "12345678", "qwerty", "11111111", "homecube", "admin123"}
		lower := strings.ToLower(s)
		for _, b := range bad {
			if strings.Contains(lower, b) {
				return false
			}
		}
		return true
	}, "黑名单比规则更管用：规则总被绕过，黑名单能精确拦掉真实泄露库里最常见的那些"},
}

func CheckStrength(pw string) error {
	for _, r := range rules {
		if !r.Check(pw) {
			return fmt.Errorf("%w: 违反 [%s] —— %s", ErrWeakPassword, r.Name, r.Why)
		}
	}
	return nil
}

// ---- bcrypt cost 渐进升级 ----

func currentCost(hashed []byte) (int, error) {
	return bcrypt.Cost(hashed)
}

func needsRehash(hashed []byte, want int) bool {
	c, err := bcrypt.Cost(hashed)
	if err != nil {
		return true
	}
	return c < want
}

// ---- 主流程 ----

type RegisterReq struct {
	Phone    string
	Password string
	SmsCode  string
	// 这些**只能**从服务端环境变量或已鉴权的上下文来，绝不能从请求体里读
	ClientIP string
	Channel  string
}

func Register(req RegisterReq) (u *User, err error) {
	auditLog = append(auditLog,
		fmt.Sprintf("[%s] REGISTER attempt phone=%s*** ip=%s channel=%s",
			now.Format("15:04:05"), req.Phone[:3], req.ClientIP, req.Channel))

	// 步骤 1：限流（先做最便宜的拒绝，能挡掉绝大多数垃圾请求）
	if req.ClientIP == "10.0.0.99" {
		return nil, fmt.Errorf("%w: ip=%s 在 10 分钟内注册了 20 次", ErrRateLimited, req.ClientIP)
	}

	// 步骤 2：密码强度。这一步在查库**之前**，因为它是纯 CPU 计算、不碰 IO。
	if err := CheckStrength(req.Password); err != nil {
		return nil, err
	}

	// 步骤 3：验证码（d04 略）
	if req.SmsCode != "OK" {
		return nil, fmt.Errorf("%w: 用途=register", ErrCodeBad)
	}

	// 步骤 4：查重
	for _, e := range users {
		if e.Phone == req.Phone {
			return nil, fmt.Errorf("%w: %s", ErrPhoneExists, req.Phone)
		}
	}

	// 步骤 5：bcrypt。用全局配置的 cost，而不是写死 DefaultCost。
	hash, err := bcrypt.GenerateFromPassword([]byte(req.Password), bcryptCost)
	if err != nil {
		return nil, err
	}

	u = &User{
		ID:           fmt.Sprintf("u-%03d", len(users)+1),
		Phone:        req.Phone,
		PasswordHash: string(hash),
		Status:       "active",
		Version:      1,
		PwdChangedAt: now,
		CreatedAt:    now,
	}
	users = append(users, u)
	auditLog = append(auditLog,
		fmt.Sprintf("[%s] REGISTER ok     id=%s cost=%d", now.Format("15:04:05"), u.ID, bcryptCost))
	return u, nil
}

// Login 顺带演示 needsRehash：验证成功后顺手把老哈希升级到当前 cost。
func Login(phone, pw string) (*User, bool, error) {
	var target *User
	for _, e := range users {
		if e.Phone == phone {
			target = e
			break
		}
	}
	if target == nil {
		return nil, false, errors.New("user not found")
	}
	if bcrypt.CompareHashAndPassword([]byte(target.PasswordHash), []byte(pw)) != nil {
		return nil, false, errors.New("password mismatch")
	}
	rehashed := false
	if needsRehash([]byte(target.PasswordHash), bcryptCost) {
		h, err := bcrypt.GenerateFromPassword([]byte(pw), bcryptCost)
		if err == nil {
			target.PasswordHash = string(h)
			target.Version++
			rehashed = true
			auditLog = append(auditLog,
				fmt.Sprintf("[%s] REHASH        id=%s cost %d → %d, version → %d",
					now.Format("15:04:05"), target.ID, bcrypt.MinCost, bcryptCost, target.Version))
		}
	}
	return target, rehashed, nil
}

func main() {
	fmt.Println("=== 1. 注册的七个步骤与它们的顺序理由 ===")
	steps := []struct {
		n         int
		name, why string
	}{
		{1, "限流（按 IP）", "纯内存判断，几乎零成本。先做它，垃圾请求根本不该消耗后面的 bcrypt"},
		{2, "密码强度", "纯 CPU、不碰 IO。比查库便宜，放前面"},
		{3, "验证码校验", "一次哈希比对，比数据库查询便宜"},
		{4, "查重（手机号是否已注册）", "到这一步才第一次碰数据库"},
		{5, "bcrypt 哈希", "最贵的一步（几十到几百毫秒）。放在最后，前面全过了才做"},
		{6, "写库", "唯一产生持久化副作用的一步"},
		{7, "签发 token", "W14 才细讲。今天先留一个占位并说明为什么它要在写库之后"},
	}
	for _, s := range steps {
		fmt.Printf("  步骤 %d  %-20s %s\n", s.n, s.name, s.why)
	}
	fmt.Println()
	fmt.Println("  顺序反过来会怎样：先 bcrypt 再限流 → 攻击者用同一 IP 疯狂请求，")
	fmt.Println("  每次都让服务器白算 100ms bcrypt，一台机器能被打满。")
	fmt.Println("  这是「便宜的拒绝放前面」这条通则在鉴权里的第一次应用。")

	fmt.Println("\n=== 2. 密码强度：四条规则逐条试 ===")
	fmt.Printf("  当前全局 bcrypt cost = %d（故意设成 MinCost，稍后演示渐进升级）\n", bcryptCost)
	fmt.Println()
	pws := []struct{ pw, note string }{
		{"short1", "太短"},
		{"SunsetRiver42", "合规：长 + 小写 + 数字"},
		{"SunsetRiver42!", "合规：再加符号"},
		{"password123", "够长够杂，但命中黑名单"},
		{"homecube2026", "含产品名，命中黑名单"},
		{"ALLUPPERCASE1", "无小写"},
		{"SunsetRive", "不足 10 位"},
	}
	for _, p := range pws {
		err := CheckStrength(p.pw)
		if err == nil {
			fmt.Printf("  ✅ %-16s %s\n", p.pw, p.note)
			continue
		}
		reason := err.Error()
		if i := strings.Index(reason, "——"); i > 0 {
			reason = reason[:i] + "← 理由见下"
		}
		fmt.Printf("  ❌ %-16s %s\n", p.pw, reason)
	}
	fmt.Println()
	for _, r := range rules {
		fmt.Printf("  %-16s %s\n", r.Name, r.Why)
	}
	fmt.Println()
	fmt.Println("  ⚠ 为什么强度校验**不放在数据库 CHECK 里**？")
	fmt.Println("    CHECK 只能做「格式」判断（长度、正则），做不了「黑名单」。")
	fmt.Println("    更重要的是：黑名单会变。今天的黑名单明天要加一条，")
	fmt.Println("    改数据库 CHECK 就要写迁移；放在 Go 里改一行常量、明天生效。")

	fmt.Println("\n=== 3. 完整跑一遍成功注册 ===")
	bcryptCost = bcrypt.DefaultCost
	u, err := Register(RegisterReq{
		Phone: "13800000001", Password: "SunsetRiver42", SmsCode: "OK",
		ClientIP: "203.0.113.7", Channel: "app",
	})
	if err != nil {
		fmt.Printf("  ❌ %v\n", err)
		return
	}
	c, _ := currentCost([]byte(u.PasswordHash))
	fmt.Printf("  ✅ 注册成功 id=%s status=%s version=%d\n", u.ID, u.Status, u.Version)
	fmt.Printf("     password_hash 前 7 字符 = %s（cost=%d）\n", u.PasswordHash[:7], c)
	fmt.Println("     注意响应里**没有** password、也没有 password_hash。")

	fmt.Println("\n=== 4. 注册失败的全部分支（顺序即成本） ===")
	fails := []struct {
		desc string
		req  RegisterReq
	}{
		{"IP 被限流", RegisterReq{"13800000002", "SunsetRiver42", "OK", "10.0.0.99", "app"}},
		{"密码太弱", RegisterReq{"13800000002", "short1", "OK", "203.0.113.8", "app"}},
		{"密码命中黑名单", RegisterReq{"13800000002", "password123", "OK", "203.0.113.8", "app"}},
		{"验证码不对", RegisterReq{"13800000002", "SunsetRiver42", "BAD", "203.0.113.8", "app"}},
		{"手机号已注册", RegisterReq{"13800000001", "SunsetRiver42", "OK", "203.0.113.9", "app"}},
	}
	step := 0
	for _, f := range fails {
		_, err := Register(f.req)
		step++
		switch {
		case err == nil:
			fmt.Printf("  ❓ %-18s → 竟然成功了（本该失败）\n", f.desc)
		case errors.Is(err, ErrRateLimited):
			fmt.Printf("  ① %-18s → %v\n", f.desc, err)
		case errors.Is(err, ErrWeakPassword):
			fmt.Printf("  ② %-18s → %v\n", f.desc, truncate(strings.SplitN(err.Error(), "——", 2)[0]))
		case errors.Is(err, ErrCodeBad):
			fmt.Printf("  ③ %-18s → %v\n", f.desc, err)
		case errors.Is(err, ErrPhoneExists):
			fmt.Printf("  ④ %-18s → %v\n", f.desc, err)
		}
	}
	_ = step
	fmt.Println()
	fmt.Println("  这五个失败映射到 HTTP 与业务码（tech-plan §6.2 的错误码分段）：")
	codes := []struct{ http, code, msg, why string }{
		{"429", "1003", "请求过于频繁", "限流。这是唯一带 Retry-After 头的错误"},
		{"400", "4001", "密码强度不足", "把违反的规则名回给前端，让它能高亮对应输入框"},
		{"400", "4001", "密码强度不足", "黑名单命中与规则不满足用同一个业务码，不告诉用户「你在黑名单上」"},
		{"400", "1004", "验证码错误或已过期", "不细分「过期」和「错误」，否则等于给攻击者反馈（d04 讲过）"},
		{"409", "4002", "该手机号已注册", "409 而不是 400 —— 这是资源状态冲突，不是请求格式错"},
	}
	for _, c := range codes {
		fmt.Printf("    %-4s %-6s %-22s %s\n", c.http, c.code, c.msg, c.why)
	}

	fmt.Println("\n=== 5. bcrypt cost 渐进升级：真跑一遍 ===")
	fmt.Println("  场景：一年前用 cost=4 注册的老用户，今天代码把 cost 提到 10。")
	fmt.Println("  正确做法不是「批量重算密码」（那要用户重新输密码，做不到），")
	fmt.Println("  而是「登录时顺手升级」：")
	fmt.Println()
	bcryptCost = bcrypt.MinCost
	uOld, _ := Register(RegisterReq{"13800000003", "SunsetRiver42", "OK", "203.0.113.20", "app"})
	oldCost, _ := currentCost([]byte(uOld.PasswordHash))
	fmt.Printf("  老用户注册时全局 cost = %d → 他的哈希里写着 cost=%d\n", bcryptCost, oldCost)
	fmt.Println("  现在把全局配置调到默认：")
	bcryptCost = bcrypt.DefaultCost
	newCost, _ := currentCost([]byte(uOld.PasswordHash))
	fmt.Printf("  全局 cost = %d，但他库里那一条**还是** cost=%d\n", bcryptCost, newCost)
	fmt.Println("  他登录一次：")
	now = now.Add(time.Hour)
	u2, rehashed, err := Login("13800000003", "SunsetRiver42")
	after, _ := currentCost([]byte(u2.PasswordHash))
	fmt.Printf("  登录成功=%v  顺手重算=%v  新 cost=%d  version=%d\n", err == nil, rehashed, after, u2.Version)
	fmt.Println("  ✅ 老哈希在登录成功的那一瞬间被换成了新 cost。")
	fmt.Println()
	fmt.Println("  三个必须记住的点：")
	fmt.Println("   ① 判断条件是 needsRehash：**只升不降**。降 cost 会让老用户的安全性倒退。")
	fmt.Println("   ② 重算只在密码正确时做。否则你等于帮攻击者把候选密码全哈希一遍。")
	fmt.Println("   ③ 重算要 +1 version，并发登录时同一个用户可能被重算两次 ——")
	fmt.Println("      结果是一样的哈希（不同盐），所以幂等，不会出错。")

	fmt.Println("\n=== 6. 注册后要不要自动登录：三个选项的取舍 ===")
	opts := []struct{ name, why, verdict string }{
		{"自动登录（直接签发 token）",
			"用户注册完立刻能用，少一次输入。但注册接口的限流比登录宽松，攻击者会用它批量造号",
			"❌ 不采用"},
		{"跳回登录页（要求再输一次密码）",
			"最安全：登录入口的限流和锁定策略都能覆盖到。但用户要输两遍密码，体验差",
			"⚠ 折中：验证码注册可自动登录，密码注册必须回登录页"},
		{"自动登录 + 立刻收紧该账号的限流窗口",
			"兼顾体验与安全：注册完给一个 token，但这个 token 的来源标记为 register，后续请求按新用户额度算",
			"✅ 本项目采用（简化版）"},
	}
	for _, o := range opts {
		fmt.Printf("  %s\n", o.name)
		fmt.Printf("     问题：%s\n", o.why)
		fmt.Printf("     结论：%s\n", o.verdict)
	}
	fmt.Println()
	fmt.Println("  关键判断标准不是「用户体验」，而是：")
	fmt.Println("  **这个接口被滥用时，损失由谁承担？**")
	fmt.Println("  注册接口一旦可被批量调用，损失是短信费 + 垃圾账号；")
	fmt.Println("  所以它的限流必须与登录一样严，甚至更严。")

	fmt.Println("\n=== 7. 用户表最终状态 ===")
	sort.Slice(users, func(i, j int) bool { return users[i].ID < users[j].ID })
	fmt.Printf("  %-8s %-13s %-8s %-8s %s\n", "id", "phone", "status", "version", "hash 前 7")
	for _, e := range users {
		fmt.Printf("  %-8s %-13s %-8s %-8d %s\n", e.ID, e.Phone, e.Status, e.Version, e.PasswordHash[:7])
	}

	fmt.Println("\n=== 8. 审计日志（登录/注册属九类审计事件之一，PRD 21.5） ===")
	fmt.Println("  ⚠ 里面没有任何密码、没有验证码、没有完整手机号。")
	for _, l := range auditLog {
		fmt.Printf("    %s\n", l)
	}

	fmt.Println("\n=== S4 d05 到此结束 ===")
	fmt.Println("明天把注册 + 验证码登录串成一条完整链路，并做 W13 阶段自查。")
}

func truncate(s string) string {
	s = strings.TrimSpace(s)
	if len([]rune(s)) > 62 {
		return string([]rune(s)[:60]) + "…"
	}
	return s
}

