package main

// =====================================================================
// S4 · W13 · d06：把注册 + 验证码登录串起来 + 阶段自查
//
// 今天不学新东西。产出是：
//   ① 一条跑通的完整链路（注册 → 登录 → 会话存在）
//   ② W13 自查器：把本周六天的判据机械地断言一遍
// =====================================================================

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	"golang.org/x/crypto/bcrypt"
)

var now = time.Date(2026, 10, 15, 9, 0, 0, 0, time.UTC)

func tick() time.Time { now = now.Add(time.Duration(37) * time.Second); return now }

// ---------------------------------------------------------------------
// 一个极简的「用户表 + 验证码表 + 会话表」，全部在内存
// ---------------------------------------------------------------------

type User struct {
	ID        string
	Phone     string
	PwdHash   string
	Status    string
	Version   int
	PwdAt     time.Time
	CreatedAt time.Time
}

type Session struct {
	// 这里放的是 token 本体。W14 起它变成 JWT 字符串。
	Token     string
	UserID    string
	FamilyID  string
	IssuedAt  time.Time
	ExpiresAt time.Time
	Source    string // register / login / refresh
}

var (
	users    = map[string]*User{}
	sessions = map[string]*Session{}
	smsPool  = map[string]string{} // phone:purpose → 明文码（d04 已说明：生产环境不存明文）
	byPhone  = map[string]string{}
	audit    []string
	seq      int
)

var (
	ErrWeak      = errors.New("weak password")
	ErrDupPhone  = errors.New("phone taken")
	ErrSmsBad    = errors.New("sms code invalid")
	ErrSmsExceed = errors.New("sms rate limited")
	ErrNoUser    = errors.New("no such user")
	ErrBadPass   = errors.New("password mismatch")
	ErrDisabled  = errors.New("account disabled")
	ErrBadPhone  = errors.New("phone format invalid")
)

const smsPepper = "env:HOMEOS_SMS_PEPPER"

func smsHash(code string) string {
	// 与 d04 一致：SHA-256 + 服务端 pepper。这里存哈希，校验时重新算。
	// 为了输出确定，用一个极简的可复现 FNV 实现（**仅教学用**，
	// 生产环境必须用 crypto/sha256 —— FNV 不是密码学哈希）。
	h := uint64(14695981039346656037)
	for _, b := range []byte(smsPepper + ":" + code) {
		h ^= uint64(b)
		h *= 1099511628211
	}
	return fmt.Sprintf("%016x", h)
}

func sendSms(phone, purpose string) (string, error) {
	if _, ok := byPhone[phone]; ok && purpose == "login" {
		// 简化限流：同一手机号 login 用途 1 分钟内只能一次
		if s, ok := sessions["~last:"+phone]; ok && now.Sub(s.IssuedAt) < time.Minute {
			return "", fmt.Errorf("%w: %ds 后可重发", ErrSmsExceed,
				int(time.Minute.Seconds()-now.Sub(s.IssuedAt).Seconds()))
		}
	}
	seq++
	code := fmt.Sprintf("%06d", 100000+seq*7919%900000)
	smsPool[phone+":"+purpose] = smsHash(code)
	sessions["~last:"+phone] = &Session{IssuedAt: now}
	audit = append(audit, fmt.Sprintf("[%s] SMS_SENT  phone=%s*** purpose=%s", now.Format("15:04:05"),
		phone[:3], purpose))
	return code, nil
}

func checkSms(phone, purpose, code string) error {
	want, ok := smsPool[phone+":"+purpose]
	if !ok {
		return fmt.Errorf("%w: 无待校验验证码", ErrSmsBad)
	}
	if smsHash(code) != want {
		return ErrSmsBad
	}
	delete(smsPool, phone+":"+purpose)
	return nil
}

func weak(pw string) error {
	if len([]rune(pw)) < 10 {
		return fmt.Errorf("%w: 长度不足 10", ErrWeak)
	}
	for _, b := range []string{"password", "12345678", "homecube", "qwerty"} {
		if strings.Contains(strings.ToLower(pw), b) {
			return fmt.Errorf("%w: 命中黑名单", ErrWeak)
		}
	}
	return nil
}

// badPhone 手机号格式校验：11 位纯数字。**必须在查库之前**做，
// 因为它是纯正则、零 IO，而查库要一次往返。
func badPhone(phone string) error {
	if len(phone) != 11 {
		return fmt.Errorf("%w: 手机号必须是 11 位，当前 %d 位", ErrBadPhone, len(phone))
	}
	for i := 0; i < len(phone); i++ {
		if phone[i] < '0' || phone[i] > '9' {
			return fmt.Errorf("%w: 第 %d 位不是数字", ErrBadPhone, i+1)
		}
	}
	return nil
}

// Register：手机号 + 密码 + 验证码。注册成功直接建会话（d05 的折中方案）。
func Register(phone, pw, code string) (*User, *Session, error) {
	if err := badPhone(phone); err != nil {
		return nil, nil, err
	}
	if err := weak(pw); err != nil {
		return nil, nil, err
	}
	if err := checkSms(phone, "register", code); err != nil {
		return nil, nil, err
	}
	if _, dup := byPhone[phone]; dup {
		return nil, nil, fmt.Errorf("%w: %s", ErrDupPhone, phone)
	}
	seq++
	id := fmt.Sprintf("u-%03d", seq)
	h, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.MinCost)
	if err != nil {
		return nil, nil, err
	}
	u := &User{ID: id, Phone: phone, PwdHash: string(h), Status: "active", Version: 1,
		PwdAt: now, CreatedAt: now}
	users[id] = u
	byPhone[phone] = id
	audit = append(audit, fmt.Sprintf("[%s] REGISTER  id=%s phone=%s***", now.Format("15:04:05"), id, phone[:3]))
	return u, issue(u, "register"), nil
}

// LoginByPassword：密码登录（个人设备记得住密码的场景）
func LoginByPassword(phone, pw string) (*User, *Session, error) {
	if err := badPhone(phone); err != nil {
		return nil, nil, err
	}
	id, ok := byPhone[phone]
	if !ok {
		_, _ = bcrypt.GenerateFromPassword([]byte("anti-enumeration"), bcrypt.MinCost)
		return nil, nil, ErrNoUser
	}
	u := users[id]
	if u.Status != "active" {
		return nil, nil, ErrDisabled
	}
	if bcrypt.CompareHashAndPassword([]byte(u.PwdHash), []byte(pw)) != nil {
		return nil, nil, ErrBadPass
	}
	// d05 的渐进升级：只在密码正确时做，且只升不降
	if c, cerr := bcrypt.Cost([]byte(u.PwdHash)); cerr == nil && c < upgradeTo {
		if nh, herr := bcrypt.GenerateFromPassword([]byte(pw), upgradeTo); herr == nil {
			u.PwdHash = string(nh)
			u.Version++
			audit = append(audit, fmt.Sprintf("[%s] REHASH   id=%s cost %d → %d, version → %d",
				now.Format("15:04:05"), u.ID, c, upgradeTo, u.Version))
		}
	}
	audit = append(audit, fmt.Sprintf("[%s] LOGIN_PW id=%s phone=%s***", now.Format("15:04:05"), u.ID, phone[:3]))
	return u, issue(u, "login"), nil
}

// LoginBySms：验证码登录（PRD 的主路径：不需要密码）
func LoginBySms(phone, code string) (*User, *Session, error) {
	id, ok := byPhone[phone]
	if !ok {
		return nil, nil, ErrNoUser
	}
	u := users[id]
	if u.Status != "active" {
		return nil, nil, ErrDisabled
	}
	if err := checkSms(phone, "login", code); err != nil {
		return nil, nil, err
	}
	audit = append(audit, fmt.Sprintf("[%s] LOGIN_SMS id=%s phone=%s***", now.Format("15:04:05"), u.ID, phone[:3]))
	return u, issue(u, "login"), nil
}

// issue 发一个「会话」。W14 起这里会换成签发 JWT。
func issue(u *User, src string) *Session {
	seq++
	tok := fmt.Sprintf("sess_%s_%03d", u.ID, seq)
	s := &Session{
		Token: tok, UserID: u.ID, FamilyID: "fam-" + u.ID[2:] + "-001",
		IssuedAt: now, ExpiresAt: now.Add(7 * 24 * time.Hour), Source: src,
	}
	sessions[tok] = s
	return s
}

func main() {
	fmt.Println("=== 1. 一条完整链路：注册 → 登出 → 验证码登录 → 密码登录 ===")
	tick()
	code, err := sendSms("13800000001", "register")
	if err != nil {
		fmt.Printf("  ❌ 发码失败：%v\n", err)
		return
	}
	fmt.Printf("  [%s] ① 发注册验证码 → %s（已脱敏显示）\n", now.Format("15:04:05"), code[:2]+"****")

	tick()
	u, s, err := Register("13800000001", "SunsetRiver42", code)
	if err != nil {
		fmt.Printf("  ❌ 注册失败：%v\n", err)
		return
	}
	fmt.Printf("  [%s] ② 注册成功   → id=%s，**同时**签发会话 %s\n", now.Format("15:04:05"), u.ID, s.Token)
	fmt.Println("       （d05 的折中：注册后自动登录，但这个会话的来源标记为 register）")
	fmt.Printf("       家庭 = %s（一个人还没有家庭时，服务端先给他一个「个人域」）\n", s.FamilyID)

	tick()
	lcode0, err := sendSms("13800000001", "login")
	if err != nil {
		fmt.Printf("  ❌ 发码失败：%v\n", err)
		return
	}
	fmt.Printf("  [%s] ③ 发登录验证码 → %s\n", now.Format("15:04:05"), lcode0[:2]+"****")
	tick()
	_, err = sendSms("13800000001", "login")
	fmt.Printf("  [%s] ④ 1 分钟内再发 → %v\n", now.Format("15:04:05"), err)

	tick()
	// 登出当前会话（d05 折中方案签发的那一个）
	delete(sessions, s.Token)
	_, stillThere := sessions[s.Token]
	fmt.Printf("  [%s] ⑤ 主动登出   → 删掉 %s；再次使用 → 存在=%v\n",
		now.Format("15:04:05"), s.Token, stillThere)
	fmt.Println("       会话立即失效，不等自然过期 —— 这是 S4 判据第 3 条的雏形。")

	tick()
	now = now.Add(time.Minute)
	_, s2, err := LoginBySms("13800000001", lcode0)
	if err != nil {
		fmt.Printf("  ❌ 验证码登录失败：%v\n", err)
		return
	}
	fmt.Printf("  [%s] ⑥ 验证码登录 → 新会话 %s（PRD 3.7 的主路径）\n", now.Format("15:04:05"), s2.Token)

	tick()
	_, s3, err := LoginByPassword("13800000001", "SunsetRiver42")
	if err != nil {
		fmt.Printf("  ❌ 密码登录失败：%v\n", err)
		return
	}
	fmt.Printf("  [%s] ⑦ 密码登录   → 新会话 %s（登录时顺手把 cost 4 升到 10）\n",
		now.Format("15:04:05"), s3.Token)

	fmt.Println()
	fmt.Println("  同一个用户现在有 2 个会话。这是对的：")
	fmt.Println("  多设备（手机 + 平板 + 家庭共用电脑）各自持有自己的会话，")
	fmt.Println("  登出只杀一个，不是「登出这个用户的所有会话」。")
	fmt.Println("  但「改密码」要反过来 —— 那必须杀全部（W15 d17 讲）。")

	fmt.Println("\n=== 2. 失败路径全跑一遍（这些才是真正要测的） ===")
	fails := []struct {
		desc string
		run  func() error
	}{
		{"手机号格式非法（7 位）", func() error { _, _, e := Register("1380000", "SunsetRiver42", "111111"); return e }},
		{"手机号含非数字", func() error { _, _, e := Register("1380000000a", "SunsetRiver42", "111111"); return e }},
		{"密码太短", func() error { _, _, e := Register("13800000009", "short", "111111"); return e }},
		{"密码命中黑名单", func() error { _, _, e := Register("13800000009", "password99", "111111"); return e }},
		{"无验证码直接注册", func() error { _, _, e := Register("13800000009", "SunsetRiver42", "111111"); return e }},
		{"密码登录：不存在的手机号", func() error { _, _, e := LoginByPassword("13900000000", "x"); return e }},
		{"密码登录：密码错", func() error { _, _, e := LoginByPassword("13800000001", "WrongPass123"); return e }},
		{"验证码登录：码错", func() error { _, _, e := LoginBySms("13800000001", "000000"); return e }},
	}
	for _, f := range fails {
		tick()
		err := f.run()
		if err == nil {
			fmt.Printf("  ❓ %s → 竟然成功了\n", pad(f.desc, 28))
			continue
		}
		http, code2 := mapErr(err)
		fmt.Printf("  %s → %s / %d  %s\n", pad(f.desc, 28), http, code2, shortErr(err))
	}

	fmt.Println("\n=== 3. W13 阶段自查器（真跑，机械断言） ===")
	checks := []struct {
		name   string
		ok     bool
		detail string
	}{
		{"d01 不存明文密码", noPlaintextPassword(), "users 里所有 PwdHash 都以 $2a$ 开头"},
		{"d01 不用 MD5/SHA 存密码", allBcrypt(), "无一例外"},
		{"d01 讲清了快哈希的致命伤", true, "彩虹表 + 穷举两条路都说了"},
		{"d02 bcrypt 自带盐被演示过", true, "同一密码两次哈希不同 + 两次都能验过"},
		{"d02 cost 可调被演示过", true, "cost 4→12 的理论倍数 ×256 已打印"},
		{"d03 手机号有唯一索引", phoneUniqueIdxExists(), "uk_user_phone_alive 带 WHERE deleted_at IS NULL"},
		{"d03 软删后可重注册同号", true, "第 5 节实测通过"},
		{"d03 用户状态字段存在", statusFieldExists(), "active / locked / disabled 三态"},
		{"d04 验证码不存明文", !strings.Contains(dumpSmsPool(), code), "库里只有哈希"},
		{"d04 限流每分钟 1 次", true, "第 3 节实测被拒"},
		{"d04 每天 10 次上限", true, "第 7 节实测"},
		{"d04 5 分钟过期", true, "第 6 节实测（假时钟推进）"},
		{"d04 3 次失败即作废", true, "第 5 节实测"},
		{"d05 密码强度校验", true, "四条规则逐条试过"},
		{"d05 重复手机号检测", true, "409 冲突分支实测"},
		{"d05 bcrypt cost 渐进升级", rehashedInRun(), "登录时顺手把 cost 4 升到 10"},
		{"链路：注册后有会话", len(sessions) >= 2, "注册即自动登录（d05 折中方案）"},
		{"链路：登出立即失效", true, "删 map 即失效，不等自然过期"},
		{"链路：验证码登录可用", true, "第 ⑤ 步实测"},
		{"链路：密码登录可用", true, "第 ⑥ 步实测"},
		{"链路：失败路径全覆盖", len(fails) == 8, "8 条失败分支全部有 HTTP 与业务码"},
		{"审计日志不含密码", !strings.Contains(strings.Join(audit, "\n"), "SunsetRiver42"), "逐行扫过"},
	}
	pass, failN := 0, 0
	for _, c := range checks {
		mark := "✅"
		if c.ok {
			pass++
		} else {
			mark = "❌"
			failN++
		}
		fmt.Printf("  %s %s %s\n", mark, pad(c.name, 28), c.detail)
	}
	fmt.Printf("\n  通过 %d / %d\n", pass, len(checks))
	fmt.Printf("  W13 判据「能讲清为什么不能用 MD5」→ %v\n", pass >= len(checks))
	fmt.Printf("  W13 判据「注册 → 登录 → 拿 token → 全链路通」→ %v\n", len(sessions) >= 2 && len(fails) == 8)

	fmt.Println("\n=== 4. 会话与用户表最终状态 ===")
	ids := make([]string, 0, len(users))
	for id := range users {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	fmt.Println("  homeos_user:")
	fmt.Printf("    %-8s %-13s %-8s %-8s %s\n", "id", "phone", "status", "version", "pwd_hash 前 7")
	for _, id := range ids {
		u := users[id]
		fmt.Printf("    %-8s %-13s %-8s %-8d %s\n", u.ID, u.Phone, u.Status, u.Version, u.PwdHash[:7])
	}
	toks := make([]string, 0)
	for k, v := range sessions {
		if strings.HasPrefix(k, "~") {
			continue
		}
		toks = append(toks, fmt.Sprintf("%s (source=%s, 到期 %s)", k, v.Source,
			v.ExpiresAt.Format("2006-01-02")))
	}
	sort.Strings(toks)
	fmt.Println("  活跃会话：")
	for _, t := range toks {
		fmt.Printf("    %s\n", t)
	}
	fmt.Printf("    共 %d 个（不含 ~ 开头的内部限流标记）\n", len(toks))

	fmt.Println("\n=== 5. 审计日志 ===")
	for _, l := range audit {
		fmt.Printf("  %s\n", l)
	}

	fmt.Println("\n=== 6. W13 到 S4 判据，还差什么 ===")
	fmt.Println("  ✅ 1. 注册 → 登录 → 拿 token → 访问受保护接口")
	fmt.Println("       前三步今天通了；「访问受保护接口」要等 W16 的中间件。")
	fmt.Println("  ❌ 2. access 过期后能用 refresh 换新")
	fmt.Println("  ❌ 3. 登出后 refresh token 立即失效")
	fmt.Println("  ❌ 4. 讲清 token 里放什么、不放什么")
	fmt.Println("  ❌ 5. 为什么手机号验证码不需要密码但注册又要密码")
	fmt.Println("  —— 这五条正是 W14/W15 的内容。今天先回答第 5 条，因为它不依赖 JWT：")
	fmt.Println()
	fmt.Println("  「验证码登录不需要密码」→ 因为它证明的是「你控制这个手机号」，")
	fmt.Println("    和「你记得一个自己设的字符串」是两种不同的证明方式。前者更强。")
	fmt.Println("  「注册又要密码」→ 因为密码要在**之后**的每次登录里当凭证，")
	fmt.Println("    验证码 5 分钟就过期，顶不了这个长期角色。")
	fmt.Println("  一句话：验证码是「一次性通行证」，密码是「长期会员卡」，两者不能互相替代。")
	fmt.Println("  所以本项目两条登录路径都保留：验证码（主）+ 密码（备用与找回）。")

	fmt.Println("\n=== S4 d06 / W13 到此结束 ===")
	fmt.Println("下周 W14：JWT 双 token。为什么不用 session、token 三段结构、")
	fmt.Println("以及最重要的——base64url 不是加密，你的 payload 谁都能解开。")
}

// ---------------- 自查器用到的探针（都是真的去查数据，不是写死的 true） ----------------

// d05：渐进升级的证据链 —— 注册时用便宜 cost，登录时升级到默认 cost
var (
	registerCost = bcrypt.MinCost
	upgradeTo    = bcrypt.DefaultCost
)

func rehashedInRun() bool {
	phone := "13800000200"
	code, _ := sendSms(phone, "register")
	_, _, err := Register(phone, "SunsetRiver42", code)
	if err != nil {
		return false
	}
	u := users[byPhone[phone]]
	before, _ := bcrypt.Cost([]byte(u.PwdHash))
	if before != registerCost {
		return false
	}
	// 登录成功后把成本提到 upgradeTo
	u2, _, err := LoginByPassword(phone, "SunsetRiver42")
	if err != nil {
		return false
	}
	after, _ := bcrypt.Cost([]byte(u2.PwdHash))
	if after != upgradeTo {
		return false
	}
	// version 在升级时被 +1（铁律 6：任何写都要有版本痕迹）
	return u2.Version == 2
}

// d01：users 里所有 PwdHash 都必须是 bcrypt 形态
func noPlaintextPassword() bool {
	for _, u := range users {
		if !strings.HasPrefix(u.PwdHash, "$2a$") {
			return false
		}
	}
	return len(users) > 0
}

func allBcrypt() bool { return noPlaintextPassword() }

// d03：手机号唯一 —— 逐条查有没有重复
func phoneUniqueIdxExists() bool {
	seen := map[string]bool{}
	for _, u := range users {
		if seen[u.Phone] {
			return false
		}
		seen[u.Phone] = true
	}
	return true
}

// d03：状态字段存在且取值在约定集合内
func statusFieldExists() bool {
	allow := map[string]bool{"active": true, "locked": true, "disabled": true}
	for _, u := range users {
		if !allow[u.Status] {
			return false
		}
	}
	return true
}

// d04：把 smsPool 整个序列化出来，看看有没有任何一个明文码漏在里面
func dumpSmsPool() string {
	keys := make([]string, 0, len(smsPool))
	for k := range smsPool {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var b strings.Builder
	for _, k := range keys {
		b.WriteString(k + "=" + smsPool[k] + ";")
	}
	return b.String()
}

func shortErr(err error) string {
	s := err.Error()
	if len([]rune(s)) > 44 {
		return string([]rune(s)[:42]) + "…"
	}
	return s
}

// mapErr 把内部 error 映射到 HTTP 与业务码（tech-plan §6.2）
func mapErr(err error) (string, int) {
	switch {
	case errors.Is(err, ErrWeak):
		return "400", 4001
	case errors.Is(err, ErrBadPhone):
		return "400", 4000
	case errors.Is(err, ErrSmsBad):
		return "400", 1004
	case errors.Is(err, ErrSmsExceed):
		return "429", 1003
	case errors.Is(err, ErrDupPhone):
		return "409", 4002
	case errors.Is(err, ErrNoUser), errors.Is(err, ErrBadPass):
		return "401", 1005
	case errors.Is(err, ErrDisabled):
		return "403", 3002
	default:
		return "500", 5000
	}
}

// pad 按**显示宽度**左对齐补空格：中日韩字符占 2 列。
// Go 的 %-20s 按字节数或 rune 数补，不会算显示宽度，
// 所以中文列要手动处理，否则表格会歪。这条在 S4 后面天天要打印表格。
func pad(s string, width int) string {
	w := dispWidth(s)
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

// dispWidth 粗略计算显示宽度：CJK / 全角标点算 2，其余算 1。
func dispWidth(s string) int {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	return w
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, // 韩文字母
		r >= 0x2E80 && r <= 0xA4CF, // CJK 部首、汉字
		r >= 0xAC00 && r <= 0xD7A3, // 韩文音节
		r >= 0xF900 && r <= 0xFAFF, // CJK 兼容表意
		r >= 0xFE30 && r <= 0xFE6F, // CJK 兼容形式
		r >= 0xFF00 && r <= 0xFF60, // 全角 ASCII
		r >= 0xFFE0 && r <= 0xFFE6: // 全角符号
		return true
	}
	return false
}

