package main

// =====================================================================
// S4 · W14 · d07：为什么用 JWT —— 对比 session
//
// 核心：JWT 的两个特性「自包含」与「不可撤销」，一个是优点，一个是债。
// 本程序把两种方案各跑一遍，用同一条请求去观察差异。
// =====================================================================

import (
	"crypto/hmac"
	"crypto/sha256"
	"fmt"
	"strings"
)

var now = "2026-10-15 10:00:00"

// ---- 会话方案：服务端存表 ----

type SessionRow struct {
	Token     string
