	sessionTable[tok] = SessionRow{
		Token: tok, UserID: userID, FamilyID: familyID,
		IssuedAt: now, ExpiresAt: "2026-10-22 10:00:00",
	}
	return tok
}

func sessionAuth(tok string) (userID, familyID string, ok bool) {
