// ---- JWT 方案：手写 HS256，不依赖任何第三方库 ----

const jwtSecret = "本项目从环境变量 HOMEOS_JWT_SECRET 读进来，绝不写死在代码里"

func b64urlEncode(b []byte) string {
	const alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
	var sb strings.Builder
	for i := 0; i < len(b); i += 3 {
		var c [3]byte
		n := copy(c[:], b[i:])
		v := uint32(c[0])<<16 | uint32(c[1])<<8 | uint32(c[2])
		sb.WriteByte(alpha[v>>18&63])
		sb.WriteByte(alpha[v>>12&63])
		if n > 1 {
			sb.WriteByte(alpha[v>>6&63])
		} else {
			sb.WriteByte('=')
		}
		if n > 2 {
			sb.WriteByte(alpha[v&63])
		} else {
			sb.WriteByte('=')
		}
	}
	return sb.String()
}

func b64urlDecode(s string) []byte {
	const alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
	idx := func(c byte) int {
		if c == '=' {
			return -1
		}
		return strings.IndexByte(alpha, c)
	}
	var out []byte
	for i := 0; i+3 < len(s); i += 4 {
		a, b, c, d := idx(s[i]), idx(s[i+1]), idx(s[i+2]), idx(s[i+3])
		v := uint32(a)<<18 | uint32(b)<<12
		if c >= 0 {
			v |= uint32(c) << 6
		}
		if d >= 0 {
			v |= uint32(d)
		}
		out = append(out, byte(v>>16))
		if c >= 0 {
			out = append(out, byte(v>>8))
		}
		if d >= 0 {
			out = append(out, byte(v))
		}
	}
	return out
}

func jwtIssue(userID, familyID, role string, expMin int) string {
	header := `{"alg":"HS256","typ":"JWT"}`
	payload := fmt.Sprintf(
		`{"uid":"%s","fam":"%s","role":"%s","typ":"access","iat":1760000000,"exp":%d}`,
		userID, familyID, role, 1760000000+expMin*60)
	signing := b64urlEncode([]byte(header)) + "." + b64urlEncode([]byte(payload))
	return signing + "." + b64urlEncode([]byte(hmacSHA256(jwtSecret, signing)))
}

// jwtVerify 这里**只**做解析与签名校验，完整实现见 d10。
func jwtVerify(tok string) (map[string]string, bool) {
	parts := strings.Split(tok, ".")
	if len(parts) != 3 {
		return nil, false
	}
	signing := parts[0] + "." + parts[1]
	if b64urlEncode([]byte(hmacSHA256(jwtSecret, signing))) != parts[2] {
		return nil, false
	}
	claims := map[string]string{}
	body := string(b64urlDecode(parts[1]))
	for _, kv := range strings.Split(strings.Trim(body, "{}"), ",") {
		p := strings.SplitN(kv, ":", 2)
		if len(p) != 2 {
			continue
		}
		claims[strings.Trim(p[0], `"`)] = strings.Trim(p[1], `"`)
	}
	return claims, true
}

