	Typ  string `json:"typ"`  // access / refresh
	IAT  int64  `json:"iat"`
	EXP  int64  `json:"exp"`
	JTI  string `json:"jti"` // 这枚 token 的唯一 id
}

// 本项目的密钥来自环境变量。写死在代码里的密钥 = 所有环境共用一把钥匙。

var secret = []byte("env:HOMEOS_JWT_SECRET（生产环境从环境变量读，绝不写死在代码里）")

func sign(signing string) string {
	m := hmac.New(sha256.New, secret)
	m.Write([]byte(signing))
	return b64urlEncode(m.Sum(nil))
}

// Issue 签发一枚 token。

func tweakAt(s string, pos int) string {
	b := []byte(s)
	if pos >= len(b) {
		return s
	}
	if b[pos] == 'A' {
		b[pos] = 'B'
	} else {
		b[pos] = 'A'
	}
	return string(b)
}

func hexOf(b []byte) string {
	const h = "0123456789abcdef"
	out := make([]byte, 0, len(b)*2)
	for _, c := range b {
		out = append(out, h[c>>4], h[c&0x0f])
	}
	return string(out)
}

func indent(s string, n int) string {
	pad := strings.Repeat(" ", n)
	lines := strings.Split(strings.TrimSpace(s), "\n")
	for i := range lines {
		lines[i] = pad + lines[i]
	}
	return strings.Join(lines, "\n")
}

