package main

// =====================================================================
// S4 · W14 · d09：base64url 不是加密
//
// 今天最重要的一天。你要亲眼看到：
//   任何拿到 token 的人，不带任何密钥，一秒就能解开 payload。
//
// 本程序的角色分配：
//   「攻击者」只用 encoding/base64 这个标准库，
//   完全没有密钥、也没有访问我们的函数或变量。
// =====================================================================

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"strings"
)

// ---------- 服务端（持有密钥） ----------

var serverSecret = []byte("env:HOMEOS_JWT_SECRET（服务端才有，攻击者拿不到）")

type Claims struct {
	UID  string `json:"uid"`
	MID  string `json:"mid"`
	Fam  string `json:"fam"`
	Role string `json:"role"`
	PVer int    `json:"pver"`
	Typ  string `json:"typ"`
	IAT  int64  `json:"iat"`
	EXP  int64  `json:"exp"`
	JTI  string `json:"jti"`
}

const b64alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"

func b64urlEncode(b []byte) string {
	var sb strings.Builder
	for i := 0; i < len(b); i += 3 {
		var c [3]byte
		n := copy(c[:], b[i:])
		v := uint32(c[0])<<16 | uint32(c[1])<<8 | uint32(c[2])
		sb.WriteByte(b64alpha[v>>18&63])
		sb.WriteByte(b64alpha[v>>12&63])
		if n > 1 {
			sb.WriteByte(b64alpha[v>>6&63])
		} else {
			sb.WriteByte('=')
		}
		if n > 2 {
			sb.WriteByte(b64alpha[v&63])
		} else {
			sb.WriteByte('=')
		}
	}
	return sb.String()
}

func sign(s string) string {
	m := hmac.New(sha256.New, serverSecret)
	m.Write([]byte(s))
	return b64urlEncode(m.Sum(nil))
}

func issueToken() string {
	h := `{"alg":"HS256","typ":"JWT"}`
	p := `{"uid":"u-001","mid":"m-001","fam":"fam-001001","role":"owner",` +
		`"pver":7,"typ":"access","iat":1760000000,"exp":1760000900,` +
		`"jti":"jti-20261015-0001"}`
	signing := b64urlEncode([]byte(h)) + "." + b64urlEncode([]byte(p))
	return signing + "." + sign(signing)
}

// ---------- 攻击者（只有标准库，没有密钥） ----------

// attackerDecode 只用 encoding/base64。它是「标准操作」，任何语言都有。
func attackerDecode(seg string) (string, error) {
	// base64url → 标准 base64：换字符集 + 补 padding
	std := strings.NewReplacer("-", "+", "_", "/").Replace(seg)
	switch len(std) % 4 {
	case 2:
		std += "=="
	case 3:
		std += "="
	case 1:
		return "", fmt.Errorf("非法的 base64url 长度 %d", len(seg))
	}
	raw, err := base64.StdEncoding.DecodeString(std)
	if err != nil {
		return "", err
	}
	return string(raw), nil
}

func main() {
	tok := issueToken()
	segs := strings.Split(tok, ".")

	fmt.Println("=== 1. 服务端签发了一枚 token ===")
	fmt.Printf("  %s\n", tok)
	fmt.Printf("  共 %d 字符，%d 段。\n\n", len(tok), len(segs))

	fmt.Println("=== 2. 攻击者手里只有上面这一行字，除此之外什么都没有 ===")
	fmt.Println("  没有密钥、没有数据库访问、没有我们程序的任何变量。")
	fmt.Println("  只用 Go 标准库 encoding/base64 —— 这是公开算法，不是秘密。")
	fmt.Println()

	fmt.Println("--- 攻击者的第 1 步：按 . 切开 ---")
	fmt.Printf("  seg[0] = %s\n", segs[0])
	fmt.Printf("  seg[1] = %s\n", segs[1])
	fmt.Printf("  seg[2] = %s\n\n", segs[2])

	fmt.Println("--- 攻击者的第 2 步：解码第 0 段（header）---")
	h, err := attackerDecode(segs[0])
	if err != nil {
		fmt.Printf("  解码失败：%v\n", err)
		return
	}
	fmt.Printf("  → %s\n", h)
	fmt.Printf("  攻击者一眼就知道该用什么算法验：alg = HS256（对称，服务端自己就能验）\n")
	fmt.Println()

	fmt.Println("--- 攻击者的第 3 步：解码第 1 段（payload）---")
	p, err := attackerDecode(segs[1])
	if err != nil {
		fmt.Printf("  解码失败：%v\n", err)
		return
	}
	fmt.Printf("  → %s\n", p)
	fmt.Println()

	fmt.Println("--- 攻击者的第 4 步：把 payload 解析成结构体 ---")
	var c Claims
	if err := json.Unmarshal([]byte(p), &c); err != nil {
		fmt.Printf("  解析失败：%v\n", err)
		return
	}
	fmt.Println("  ✅ 攻击者现在知道了：")
	rows := []struct{ k, v string }{
		{"用户 id", c.UID},
		{"成员 id", c.MID},
		{"当前家庭", c.Fam},
		{"角色", c.Role},
		{"权限版本", fmt.Sprint(c.PVer)},
		{"token 类型", c.Typ},
		{"签发时间", fmt.Sprint(c.IAT) + "（2025-10-09 前后）"},
		{"过期时间", fmt.Sprint(c.EXP) + "（签发后 15 分钟）"},
		{"token 唯一 id", c.JTI},
	}
	for _, r := range rows {
		fmt.Printf("     %-14s %s\n", r.k, r.v)
	}

	fmt.Println("\n=== 3. 结论：JWT 的 payload 是明文 ===")
	fmt.Println("  这枚 token 经过了 HTTPS 传输，但那只是**传输过程**被加密；")
	fmt.Println("  落地之后：")
	fmt.Println("   · 前端内存里有明文（前端必须能解出来才能读 uid/fam）")
	fmt.Println("   · 浏览器 devtools 的 Application → Local Storage 里有明文")
	fmt.Println("   · **服务端日志里如果你打了整枚 token，也是明文可读**")
	fmt.Println("   · 用户截图给你看 token 时，他顺便把家庭 id 和角色也给你了")
	fmt.Println("  所以第一条纪律：**永远不要往 payload 里放敏感数据**。")
	fmt.Println("  密码、手机号、真实姓名、金额、身份证号 —— 一律不放。")

	fmt.Println("\n=== 4. 那签名到底防住了什么 ===")
	fmt.Println("  签名不防「看」，只防「改」。演示：")
	bad := segs[0] + "." + b64urlEncode([]byte(
		`{"uid":"u-999","mid":"m-999","fam":"fam-001001","role":"owner",`+
			`"pver":7,"typ":"access","iat":1760000000,"exp":1760000900,`+
			`"jti":"jti-forged"}`)) + "." + segs[2]
	fmt.Println("  攻击者把 uid 从 u-001 改成 u-999、mid 从 m-001 改成 m-999，")
	fmt.Println("  role 保持 owner，然后**沿用原来的签名**：")
	var forged Claims
	raw, _ := attackerDecode(strings.Split(bad, ".")[1])
	_ = json.Unmarshal([]byte(raw), &forged)
	fmt.Printf("     他伪造出的 token 解开是：uid=%s role=%s —— 看起来完全合法\n", forged.UID, forged.Role)
	fmt.Println()
	fmt.Println("  服务端验签时：")
	badSegs := strings.Split(bad, ".")
	fmt.Printf("     他带的签名            ：%s...\n", badSegs[2][:24])
	fmt.Printf("     服务端用密钥重新算的 ：%s...\n", sign(badSegs[0] + "." + badSegs[1])[:24])
	fmt.Printf("     两者是否相同：%v\n", badSegs[2] == sign(badSegs[0]+"."+badSegs[1]))
	fmt.Println("     → 验签失败 → 401。")
	fmt.Println()
	fmt.Println("  换个说法：")
	fmt.Println("     「篡改 u-999 这件事本身是**零成本**的，base64 不是障碍；")
	fmt.Println("       真正让他失败的是他算不出一个能让服务端认可的签名，")
	fmt.Println("       因为算签名需要 serverSecret。」")

	fmt.Println("\n=== 5. 那 attackerDecode 到底做了什么：与真加密的对比 ----------")
	cmps := []struct{ k, b64, enc string }{
		{"需要密钥吗", "不需要。算法是公开的，标准库白送", "需要。密钥是安全性的全部来源"},
		{"能否还原原文", "能，一秒", "有密钥才能，没有就只是乱码"},
		{"输出长度", "约为输入的 4/3（33 字节 → 44 字符）", "密文长度 ≈ 明文 + 少量开销"},
		{"安全边界", "**零**。只把二进制搬成 6 位可打印字符", "有。它就是为保密而存在的"},
		{"本质", "编码（encoding）", "加密（encryption）"},
	}
	fmt.Printf("  %-14s %-40s %s\n", "维度", "base64url", "真正的加密")
	for _, c := range cmps {
		fmt.Printf("  %s %s %s\n", pad(c.k, 14), pad(c.b64, 40), c.enc)
	}
	fmt.Println()
	fmt.Println("  编码与加密的区别，是 S4 最容易混的一对概念：")
	fmt.Println("   · 编码的目标是「让数据能在不安全的环境里传输/存储」（二进制 → 文本）")
	fmt.Println("   · 加密的目标是「让不该看的人看不到」")
	fmt.Println("   · **base64 是编码，不是加密**。它没有任何密钥参数可传 ——")
	fmt.Println("     光这一点就足以证明它不是加密：加密算法必然需要一个密钥。")

	fmt.Println("\n=== 6. 手工验证 base64 的数学：为什么它一定不是加密 ----------")
	fmt.Println("  base64 的核心是「每 3 个字节 = 24 比特 → 4 个 6 位字符」。")
	seg := segs[1]
	rawSeg, _ := attackerDecode(seg)
	fmt.Printf("  这段 base64url 长度 %d，解码后 %d 字节。\n", len(seg), len(rawSeg))
	fmt.Printf("  %d × 8 = %d 比特 = %d 个 6 位字符组 = %d 个字符（含 padding）\n",
		len(rawSeg), len(rawSeg)*8, len(rawSeg)*8/6, (len(rawSeg)*8+5)/6)
	fmt.Println("  这是一个**双射**：每个字符位置只有 6 种可能，映射关系完全公开。")
	fmt.Println("  加密不是双射 —— 加密后的密文长度可以与明文无关，解密需要一个映射的逆。")
	fmt.Println("  你只要有一张 64 项的替换表（就是 base64 那个字母表），就能手工解任何一个 token。")

	fmt.Println("\n=== 7. 如果真的需要保密：三个正确做法 ----------")
	ways := []struct{ name, how, cost, fit string }{
		{"HTTPS/TLS", "整条链路加密，token 在网络上是密文",
			"最低，几乎零成本", "✅ 本项目的底线。生产环境不配 TLS = 自杀"},
		{"JWE（RFC 7516）", "把 payload 用公钥加密，只有持私钥的能解开",
			"中，JWT 变长 2-3 倍，前端必须能验或只能交给后端解",
			"本项目不用：前端不需要读 payload，可读性反而是负担"},
		{"敏感数据根本不放 token", "token 里只放 id 与快照，其余每次请求现查",
			"最低，一次数据库查询（本项目本来就要查 family/module）",
			"✅ 本项目采用。这就是 d11 的主题"},
	}
	for _, w := range ways {
		fmt.Printf("  ▸ %s\n", w.name)
		fmt.Printf("      做法：%s\n", w.how)
		fmt.Printf("      代价：%s\n", w.cost)
		fmt.Printf("      本项目：%s\n", w.fit)
	}
	fmt.Println()
	fmt.Println("  特别注意第三条：本项目的 token 里没有任何一个字段是「用户不知道也没关系、")
	fmt.Println("  但泄露了会造成损害」的。uid/fam/role 这些泄露了会怎样？")
	fmt.Println("  泄露 fam 只能让攻击者知道「你属于哪个家庭」，他要读数据仍然需要有效签名 ——")
	fmt.Println("  因为服务端所有查询都带 WHERE family_id = <token.fam>（W16 d22）。")
	fmt.Println("  这就是「不敏感」的真实含义：**泄露了不等于能用来做坏事**。")

	fmt.Println("\n=== 8. 与 JS 的对照 ----------")
	fmt.Println("  ① 前端解 payload 一行就够：")
	fmt.Println("       const payload = JSON.parse(atob(token.split('.')[1]))")
	fmt.Println("     注意必须先替换回标准 base64 字符集（-→+、_→/）并补 padding，")
	fmt.Println("     atob 对非法字符直接抛异常。这是前端最常见的 JWT 解码 bug。")
	fmt.Println("  ② Node 里的对应写法：Buffer.from(seg, 'base64url').toString('utf8')。")
	fmt.Println("     Node 的 Buffer 从 v15 起原生支持 'base64url' 编码名，比浏览器方便。")
	fmt.Println("  ③ 但**永远不要**在前端做验签。浏览器里没有 serverSecret，")
	fmt.Println("     你要是把密钥打包进 JS 产物，那它对任何人都是公开的 ——")
	fmt.Println("     前端的「鉴权」只能是 UI 层的显示控制，真正的判定必须在服务端。")
	fmt.Println("     这与「localStorage 能不能放 token」是同一个话题，d25 会展开。")

	fmt.Println("\n=== S4 d09 到此结束 ===")
	fmt.Println("明天讲签名：HMAC 是什么、为什么改一个字符就验不过、")
	fmt.Println("以及 RS256 与 HS256 的选择（以及那个著名的算法混淆攻击）。")
}

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

