package main

// =====================================================================
// S4 · W14 · d10：签名与校验
//
//   HMAC 是什么 / 为什么改一个字符就验不过 / 完整校验的七个步骤
//   / HS256 与 RS256 的选择 / 算法混淆攻击
//
// 本程序手写完整校验器，故意把它写得啰嗦 —— 因为 d16 之后你会看到
// 「七个步骤少一个都出事」的清单。
// =====================================================================

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

// ---------- 配置与状态 ----------

var secret = []byte("env:HOMEOS_JWT_SECRET 生产密钥至少 32 字节随机")

// 假时钟：2026-10-15 10:00:00 UTC
var nowUnix int64 = 1760604000

var errs = []struct {
	Code int
	Err  error
}{
	{1001, errors.New("token expired")},
	{1002, errors.New("token signature invalid")},
	{1006, errors.New("token not yet valid (nbf)")},
	{1007, errors.New("token type mismatch: refresh used as access")},
	{1008, errors.New("token revoked (jti in denylist)")},
}

func errCode(e error) int {
	for _, x := range errs {
		if errors.Is(e, x.Err) {
			return x.Code
		}
	}
	return 1000
}

// ---------- JWT 原语 ----------

const b64alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"

func b64urlEncode(b []byte) string {
	var sb strings.Builder
	for i := 0; i < len(b); i += 3 {
		var c [3]byte
		n := copy(c[:], b[i:])
		v := uint32(c[0])<<16 | uint32(c[1])<<8 | uint32(c[2])
		sb.WriteByte(b64alpha[v>>18&63])
		sb.WriteByte(b64alpha[v>>12&63])
		if n > 1 {
			sb.WriteByte(b64alpha[v>>6&63])
		} else {
			sb.WriteByte('=')
		}
		if n > 2 {
			sb.WriteByte(b64alpha[v&63])
		} else {
			sb.WriteByte('=')
		}
	}
	return sb.String()
}

func b64urlDecode(s string) []byte {
	idx := func(c byte) int {
		if c == '=' {
			return -1
		}
		return strings.IndexByte(b64alpha, c)
	}
	var out []byte
	for i := 0; i+3 < len(s); i += 4 {
		a, b, c, d := idx(s[i]), idx(s[i+1]), idx(s[i+2]), idx(s[i+3])
		v := uint32(a)<<18 | uint32(b)<<12
		if c >= 0 {
			v |= uint32(c) << 6
		}
		if d >= 0 {
			v |= uint32(d)
		}
		out = append(out, byte(v>>16))
		if c >= 0 {
			out = append(out, byte(v>>8))
		}
		if d >= 0 {
			out = append(out, byte(v))
		}
	}
	return out
}

type Claims struct {
	UID  string `json:"uid"`
	MID  string `json:"mid"`
	Fam  string `json:"fam"`
	Role string `json:"role"`
	PVer int    `json:"pver"`
	Typ  string `json:"typ"`
	NBF  int64  `json:"nbf"`
	IAT  int64  `json:"iat"`
	EXP  int64  `json:"exp"`
	JTI  string `json:"jti"`
}

func hmacSHA256(key, msg []byte) []byte {
	m := hmac.New(sha256.New, key)
	m.Write(msg)
	return m.Sum(nil)
}

// denylist：被撤销的 jti。生产环境放 Redis 或数据库，进程内 map 只在单实例下有效。
var denylist = map[string]string{}

// ---------- 签发 ----------

func Issue(c Claims) string {
	h := `{"alg":"HS256","typ":"JWT"}`
	hb, _ := json.Marshal(json.RawMessage(h))
	pb, _ := json.Marshal(c)
	signing := b64urlEncode(hb) + "." + b64urlEncode(pb)
	return signing + "." + b64urlEncode(hmacSHA256(secret, []byte(signing)))
}

// ---------- 校验：七个步骤，顺序固定 ----------

func Verify(tok string, wantType string) (*Claims, error) {
	// ① 结构：必须是三段
	parts := strings.Split(tok, ".")
	if len(parts) != 3 || parts[0] == "" || parts[1] == "" || parts[2] == "" {
		return nil, fmt.Errorf("malformed token: %d segments", len(parts))
	}

	// ② header：**不信任**，只用来确认我们能解析它
	hdr := map[string]string{}
	if err := json.Unmarshal(b64urlDecode(parts[0]), &hdr); err != nil {
		return nil, fmt.Errorf("malformed header: %v", err)
	}
	// 关键：不管 header 写什么，我们都用配置里的 HS256。
	// 如果这里写 `if hdr["alg"] == "none" { return ok }` 或者
	// `useAlgorithm(hdr["alg"])`，就是经典的 alg=none / 算法混淆漏洞。
	if hdr["alg"] != "HS256" {
		return nil, fmt.Errorf("%w: header says alg=%s, server pinned HS256",
			errs[1].Err, hdr["alg"])
	}

	// ③ 签名：hmac.Equal 做**恒定时间**比较
	want := b64urlEncode(hmacSHA256(secret, []byte(parts[0]+"."+parts[1])))
	if !hmac.Equal([]byte(want), []byte(parts[2])) {
		return nil, fmt.Errorf("%w: want %s got %s", errs[1].Err, want[:20], parts[2][:min(20, len(parts[2]))])
	}

	// ④ 到此才能信任 payload
	var c Claims
	if err := json.Unmarshal(b64urlDecode(parts[1]), &c); err != nil {
		return nil, fmt.Errorf("malformed payload: %v", err)
	}

	// ⑤ nbf（未生效）
	if c.NBF != 0 && nowUnix < c.NBF {
		return nil, fmt.Errorf("%w: nbf=%d now=%d", errs[2].Err, c.NBF, nowUnix)
	}
	// ⑥ exp（已过期）。留 5 秒余量（leeway），防客户端与服务端时钟漂移。
	leeway := int64(5)
	if nowUnix > c.EXP+leeway {
		return nil, fmt.Errorf("%w: exp=%d now=%d", errs[0].Err, c.EXP, nowUnix)
	}
	// ⑦ 类型：refresh 不能当 access 用（这是双 token 的关键闸门，W15 依赖它）
	if wantType != "" && c.Typ != wantType {
		return nil, fmt.Errorf("%w: want %s got %s", errs[3].Err, wantType, c.Typ)
	}
	// ⑧ 撤销名单
	if reason, hit := denylist[c.JTI]; hit {
		return nil, fmt.Errorf("%w: jti=%s reason=%s", errs[4].Err, c.JTI, reason)
	}
	return &c, nil
}

func goodClaims(typ string, ttlMin int) Claims {
	return Claims{
		UID: "u-001", MID: "m-001", Fam: "fam-001001", Role: "owner", PVer: 7,
		Typ: typ, NBF: nowUnix, IAT: nowUnix, EXP: nowUnix + int64(ttlMin*60),
		JTI: fmt.Sprintf("jti-%s-%d", typ, ttlMin),
	}
}

func main() {
	fmt.Println("=== 1. HMAC 是什么：两个输入，一个固定输出 ===")
	fmt.Println("  HMAC(key, message) = H((key ⊕ opad) ‖ H((key ⊕ ipad) ‖ message))")
	fmt.Println("  它的三个性质，正是签名需要的三条：")
	props := []struct{ k, v string }{
		{"确定性", "同样的 key + 同样的 message = 同样的输出。所以服务端能验"},
		{"密钥依赖", "换一字节 key，输出完全变样。攻击者没有 key 就只能猜"},
		{"抗长度扩展", "这是 HMAC 存在的全部理由：裸 SHA256(secret ‖ msg) 有长度扩展漏洞"},
	}
	for _, p := range props {
		fmt.Printf("     %-8s %s\n", p.k, p.v)
	}
	fmt.Println("     HMAC-SHA256 输出固定 32 字节 → base64url 后 44 字符（含一个 = padding）")

	fmt.Println("\n=== 2. 同一个 key + message 算两次，输出相同吗 ===")
	msg := []byte("header.payload")
	a := b64urlEncode(hmacSHA256(secret, msg))
	b := b64urlEncode(hmacSHA256(secret, msg))
	fmt.Printf("  第 1 次：%s\n", a)
	fmt.Printf("  第 2 次：%s\n", b)
	fmt.Printf("  相同：%v   ← 这是验签能工作的前提\n", a == b)
	fmt.Println()
	fmt.Println("  ⚠ 注意与 d04 的对比：bcrypt 加盐是为了让**同一密码的哈希不同**；")
	fmt.Println("    HMAC 不加盐，因为它要的正相反 —— 签发方和验证方必须算出同一个值。")

	fmt.Println("\n=== 3. 改一个字符就验不过：逐位实测 ===")
	tok := Issue(goodClaims("access", 15))
	parts := strings.Split(tok, ".")
	fmt.Printf("  原始 token 三段：\n    header  %s\n    payload %s...\n    签名    %s\n",
		parts[0], parts[1][:40], parts[2])
	fmt.Println("  先看签名对 payload 每一位的敏感度（只动第 40 位这一个字符）：")
	fmt.Printf("    原签名第 20-40 位：%s\n", parts[2][20:40])
	fmt.Printf("    改后第 20-40 位  ：%s\n",
		b64urlEncode(hmacSHA256(secret, []byte(parts[0]+"."+tweakAt(parts[1], 40))))[20:40])
	fmt.Println("  → 一个字符的差异让签名面目全非。")
	fmt.Println()
	fmt.Println("  构造七个「只动一处」的变体，看服务端分别怎么判：")
	type mutant struct {
		desc string
		make func() string
	}
	ms := []mutant{
		{"payload 第 40 位改一个字符", func() string {
			p := []byte(parts[1])
			if p[40] == 'A' {
				p[40] = 'B'
			} else {
				p[40] = 'A'
			}
			return parts[0] + "." + string(p) + "." + parts[2]
		}},
		{"payload 换掉整段（伪造别人的 claims）", func() string {
			return parts[0] + "." + b64urlEncode([]byte(
				`{"uid":"u-999","mid":"m-999","fam":"fam-001001","role":"owner","pver":7,"typ":"access","nbf":1760604000,"iat":1760604000,"exp":1760604900,"jti":"forged"}`)) + "." + parts[2]
		}},
		{"header 的 alg 改成 none", func() string {
			return b64urlEncode([]byte(`{"alg":"none","typ":"JWT"}`)) + "." + parts[1] + "." + parts[2]
		}},
		{"header 的 alg 改成 RS256（算法混淆）", func() string {
			return b64urlEncode([]byte(`{"alg":"RS256","typ":"JWT"}`)) + "." + parts[1] + "." + parts[2]
		}},
		{"签名换一字节", func() string {
			s := []byte(parts[2])
			if s[0] == 'A' {
				s[0] = 'B'
			} else {
				s[0] = 'A'
			}
			return parts[0] + "." + parts[1] + "." + string(s)
		}},
		{"删掉签名段", func() string { return parts[0] + "." + parts[1] }},
		{"多一个点（多一段）", func() string { return tok + "." + parts[2] }},
	}
	for _, m := range ms {
		_, err := Verify(m.make(), "access")
		status := fmt.Sprintf("✅ 通过 (code=%d)", 0)
		if err != nil {
			status = fmt.Sprintf("❌ 拒绝 code=%d %s", errCode(err), shortOf(err))
		}
		fmt.Printf("    %s %s\n", pad(m.desc, 38), status)
	}

	fmt.Println("\n=== 4. 过期：唯一一个「签名正确但仍然要拒」的情况 ===")
	fmt.Println("  注意这一点：过期不是签名问题。签名是对的，payload 里 exp 就是过去了，")
	fmt.Println("  但服务端**主动**拒绝。所以校验器必须有「时间判断」这一步，")
	fmt.Println("  光验签是不够的 —— 这是手写 JWT 最常见的漏项。")
	for _, ttl := range []int{-1, 0, 1, 15, 60} {
		c := goodClaims("access", ttl)
		c.JTI = fmt.Sprintf("jti-ttl%d", ttl)
		t := Issue(c)
		_, err := Verify(t, "access")
		left := c.EXP - nowUnix
		if err != nil {
			fmt.Printf("    剩余 %+5ds → ❌ %s\n", left, err)
			continue
		}
		note := ""
		if left == 0 {
			note = "（正好等于 exp，落在 leeway 5 秒内，仍放行）"
		}
		fmt.Printf("    剩余 %+5ds → ✅ 通过%s\n", left, note)
	}
	fmt.Println("  注意 leeway=5 秒：服务端时钟比客户端快 3 秒也不会误判过期。")

	fmt.Println("\n=== 5. typ 字段：refresh 不能当 access 用 ===")
	refreshTok := Issue(goodClaims("refresh", 60*24*30))
	_, err := Verify(refreshTok, "access")
	fmt.Printf("  拿 refresh token 调业务接口 → %v\n", err)
	fmt.Println("  这是双 token 体系的第一道闸门。少了它，攻击者可以拿那个 30 天的")
	fmt.Println("  refresh token 直接当 access 用所有接口，等于长效 token 白做了。")
	fmt.Println()
	fmt.Println("  ⚠ 另一种错误写法：`if c.Typ != \"access\" { reject }` 写死在中间件里。")
	fmt.Println("    这样写的问题不是安全，而是 —— 同一个中间件没法给 /auth/refresh 用。")
	fmt.Println("    正确做法：中间件接收一个「期望的类型」参数：")
	fmt.Println("      auth.Require(\"access\")   → 挂在业务路由组上")
	fmt.Println("      auth.Require(\"refresh\") → 只挂在 /api/homeos/auth/refresh 上")

	fmt.Println("\n=== 6. 撤销名单：唯一能让已签发的 token 立即作废的机制 ===")
	c := goodClaims("access", 15)
	c.JTI = "jti-to-revoke"
	tk := Issue(c)
	_, err = Verify(tk, "access")
	fmt.Printf("  撤销前校验：%v\n", err == nil)
	denylist[c.JTI] = "user logged out at 2026-10-15 10:05"
	_, err = Verify(tk, "access")
	fmt.Printf("  加入名单后：  %v (code=%d)\n", err, errCode(err))
	fmt.Println("  这就是「登出后 refresh token 立即失效」的实现方式（S4 判据第 3 条）。")
	fmt.Println("  但注意：**access token 不查名单**。理由在 W15 讲：")
	fmt.Println("  access 只有 15 分钟，让它自然过期比每次查名单便宜得多。")
	fmt.Println("  如果你要「立即踢掉」，查名单；如果只是「别再发新的」，让 access 过期。")

	fmt.Println("\n=== 7. HS256 与 RS256：对称与非对称 ===")
	cmpRows := []struct{ k, hs, rs string }{
		{"密钥关系", "同一把密钥既签名又验签", "私钥签名、公钥验签"},
		{"谁需要密钥", "验签方都要密钥（含前端就危险）", "只有签发方需要私钥"},
		{"分发难度", "三个服务都要拿到同一把密钥", "分发公钥即可，可以公开"},
		{"token 长度", "签名 32 字节 → 44 字符", "签名 256 字节 → 342 字符"},
		{"计算成本", "快 5-10 倍", "慢（RSA-2048 签名约 1ms）"},
		{"适合场景", "单体 / 内部少量可信方", "第三方 / 公钥可公开"},
	}
	fmt.Printf("  %-12s %-30s %s\n", "维度", "HS256（本项目）", "RS256")
	for _, c := range cmpRows {
		fmt.Printf("  %s %s %s\n", pad(c.k, 14), pad(c.hs, 36), c.rs)
	}
	fmt.Println()
	fmt.Println("  本项目选 HS256，理由很实在：")
	fmt.Println("   · 三个服务都是**自建**的（tech-plan §22.2：数据与代码不与其他项目复用）")
	fmt.Println("   · 密钥通过部署时的环境变量注入，不进代码库、不进镜像层")
	fmt.Println("   · token 更短 —— access 15 分钟、每 15 分钟换一次，长度直接影响每请求的开销")
	fmt.Println()
	fmt.Println("  但如果你要接第三方（比如让别家的 App 用你的账号体系），")
	fmt.Println("  必须换 RS256 或 ES256 —— 因为那时验签方（第三方）必须能验，")
	fmt.Println("  而你绝不能把 HMAC 密钥给第三方。")

	fmt.Println("\n=== 8. 算法混淆攻击：为什么「按 header 选算法」是错的 ----------")
	fmt.Println("  错误写法一：alg=none")
	fmt.Println("    攻击者把 alg 改成 none、签名段删空，某些库直接放行")
	fmt.Println("  错误写法二：HS256 ↔ RS256 混淆")
	fmt.Println("    1. 服务端用 RSA 公钥验签")
	fmt.Println("    2. 攻击者拿到的是**公钥**（本来就公开）")
	fmt.Println("    3. 攻击者把 alg 改成 HS256，用公钥当 HMAC 密钥，自己签一个 token")
	fmt.Println("    4. 服务端「按 header 选算法」，于是用同一个公钥去验 HMAC → 签名正确 → 放行")
	fmt.Println("    攻击者零成本获得了伪造能力。")
	fmt.Println()
	fmt.Println("  本程序第 2 步的处理（正确姿势）：")
	fmt.Printf("    if hdr[\"alg\"] != \"HS256\" { reject }\n")
	fmt.Println("    —— 算法是**服务端配置**，不是客户端声明。")
	fmt.Println("    上表里「header 的 alg 改成 RS256」那一行被拒，就是这条在起作用。")
	fmt.Println("    golang-jwt/v5 的 API 本身就不接受「从 token 里读算法」这种用法：")
	fmt.Println("    jwt.Parse(token, keyFunc)，而 keyFunc 忽略 header，用你闭包里给的 key。")

	fmt.Println("\n=== 9. 恒定时间比较：为什么不能用 == 或 strings.Compare ----------")
	fmt.Println("  普通字符串比较会在第一个不同的字节处返回。")
	fmt.Println("  攻击者可以逐字节试探：签名前 10 字节对 → 多花一点时间；第 11 字节错 → 立刻返回。")
	fmt.Println("  几万次请求就能还原出一个合法签名 —— 这是真实可行的侧信道攻击。")
	fmt.Println()
	fmt.Println("  hmac.Equal 的实现是逐字节 XOR 后**累加**，最后只返回一个 bool：")
	shown := []byte("ABcdEFgh")
	given := []byte("ABcdEFgz")
	acc := byte(0)
	for i := range shown {
		acc |= shown[i] ^ given[i]
	}
	fmt.Printf("    逐字节 XOR 后累加（示例）：%d\n", acc)
	fmt.Printf("    所有字节相同时：%d\n", xorAll([]byte("same"), []byte("same")))
	fmt.Println("    0 表示完全相同。累加保证「必须看完所有字节」才能给结论，")
	fmt.Println("    所以无论在第几位不同，耗时都一样。")

	fmt.Println("\n=== 10. Go 与 JS 的差异 ----------")
	fmt.Println("  ① crypto/hmac 在 Go 里是流式的：h := hmac.New(sha256.New, key); h.Write(msg); h.Sum(nil)。")
	fmt.Println("     JS 的 crypto.subtle.sign 是**异步**的，返回 Promise<ArrayBuffer>。")
	fmt.Println("     Node 从 v15 起才有同步的 crypto.createHmac('sha256', key).update(msg).digest()。")
	fmt.Println("  ② Go 的 hmac.Equal(a, b) 要求两个切片**等长**，不等长直接返回 false。")
	fmt.Println("     所以你必须先比长度再比内容，否则不同长度会 panic 或误判。")
	fmt.Println("     本程序里先比 want 与 got 的长度（签名段固定 44 字符，一般不会不等长），")
	fmt.Println("     但这是一个必须养成的习惯 —— 别人给你的 token 长度可能是任意的。")
	fmt.Println("  ③ Go 的 error 用 errors.Is / %w；JS 里对应 try/catch + err instanceof。")
	fmt.Println("     本程序 errs 表里那些 sentinel error 就是为了 errors.Is 能判。")

	fmt.Println("\n=== S4 d10 到此结束 ===")
	fmt.Println("明天讲 token 里放什么、不放什么：对照 HomeCube 的")
	fmt.Println("uid / mid / fam / role / pver / typ 六个字段逐条论证。")
}

// tweakAt 把 base64url 串的第 pos 位换成另一个合法字符。
func tweakAt(s string, pos int) string {
	b := []byte(s)
	if pos >= len(b) {
		return s
	}
	if b[pos] == 'A' {
		b[pos] = 'B'
	} else {
		b[pos] = 'A'
	}
	return string(b)
}

func xorAll(a, b []byte) byte {
	var acc byte
	for i := range a {
		if i < len(b) {
			acc |= a[i] ^ b[i]
		} else {
			acc |= 1
		}
	}
	return acc
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func shortOf(err error) string {
	s := err.Error()
	rs := []rune(s)
	if len(rs) > 52 {
		return string(rs[:50]) + "…"
	}
	return s
}

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

build.add:
// =====================================================================
// S4 · W14 · d10：签名与校验
//
//   HMAC 是什么 / 为什么改一个字符就验不过 / 完整校验的七个步骤
//   / HS256 与 RS256 的选择 / 算法混淆攻击
//
// 本程序手写完整校验器，故意把它写得啰嗦 —— 因为 d16 之后你会看到
// 「七个步骤少一个都出事」的清单。
// =====================================================================

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

// ---------- 配置与状态 ----------

var secret = []byte("env:HOMEOS_JWT_SECRET 生产密钥至少 32 字节随机")

// 假时钟：2026-10-15 10:00:00 UTC
var nowUnix int64 = 1760604000

var errs = []struct {
	Code int
	Err  error
}{
	{1001, errors.New("token expired")},
	{1002, errors.New("token signature invalid")},
	{1006, errors.New("token not yet valid (nbf)")},
	{1007, errors.New("token type mismatch: refresh used as access")},
	{1008, errors.New("token revoked (jti in denylist)")},
}

func errCode(e error) int {
	for _, x := range errs {
		if errors.Is(e, x.Err) {
			return x.Code
		}
	}
	return 1000
}

// ---------- JWT 原语 ----------

const b64alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"

func b64urlEncode(b []byte) string {
	var sb strings.Builder
	for i := 0; i < len(b); i += 3 {
		var c [3]byte
		n := copy(c[:], b[i:])
		v := uint32(c[0])<<16 | uint32(c[1])<<8 | uint32(c[2])
		sb.WriteByte(b64alpha[v>>18&63])
		sb.WriteByte(b64alpha[v>>12&63])
		if n > 1 {
			sb.WriteByte(b64alpha[v>>6&63])
		} else {
			sb.WriteByte('=')
		}
		if n > 2 {
			sb.WriteByte(b64alpha[v&63])
		} else {
			sb.WriteByte('=')
		}
	}
	return sb.String()

}

func b64urlDecode(s string) []byte {
	idx := func(c byte) int {
		if c == '=' {
			return -1
		}
		return strings.IndexByte(b64alpha, c)
	}
	var out []byte
	for i := 0; i+3 < len(s); i += 4 {
		a, b, c, d := idx(s[i]), idx(s[i+1]), idx(s[i+2]), idx(s[i+3])
		v := uint32(a)<<18 | uint32(b)<<12
		if c >= 0 {
			v |= uint32(c) << 6
		}
		if d >= 0 {
			v |= uint32(d)
		}
		out = append(out, byte(v>>16))
		if c >= 0 {
			out = append(out, byte(v>>8))
		}
		if d >= 0 {
			out = append(out, byte(v))
		}
	}
	return out
}

