func hmacSHA256(key, msg []byte) []byte {
	m := hmac.New(sha256.New, key)
	m.Write(msg)
	return m.Sum(nil)
}

// denylist：被撤销的 jti。生产环境放 Redis 或数据库，进程内 map 只在单实例下有效。
var denylist = map[string]string{}

// ---------- 签发 ----------

func Issue(c Claims) string {
	h := `{"alg":"HS256","typ":"JWT"}`
	hb, _ := json.Marshal(json.RawMessage(h))
	pb, _ := json.Marshal(c)
	signing := b64urlEncode(hb) + "." + b64urlEncode(pb)
	return signing + "." + b64urlEncode(hmacSHA256(secret, []byte(signing)))
}

// ---------- 校验：七个步骤，顺序固定 ----------

func Verify(tok string, wantType string) (*Claims, error) {
	// ① 结构：必须是三段
	parts := strings.Split(tok, ".")
	if len(parts) != 3 || parts[0] == "" || parts[1] == "" || parts[2] == "" {
		return nil, fmt.Errorf("malformed token: %d segments", len(parts))

	}

	// ② header：**不信任**，只用来确认我们能解析它
	hdr := map[string]string{}
	if err := json.Unmarshal(b64urlDecode(parts[0]), &hdr); err != nil {
		return nil, fmt.Errorf("malformed header: %v", err)
	}
	// 关键：不管 header 写什么，我们都用配置里的 HS256。
	// 如果这里写 `if hdr["alg"] == "none" { return ok }` 或者
	// `useAlgorithm(hdr["alg"])`，就是经典的 alg=none / 算法混淆漏洞。
	if hdr["alg"] != "HS256" {
		return nil, fmt.Errorf("%w: header says alg=%s, server pinned HS256",
			errs[1].Err, hdr["alg"])
	}

	// ③ 签名：hmac.Equal 做**恒定时间**比较
	want := b64urlEncode(hmacSHA256(secret, []byte(parts[0]+"."+parts[1])))
	if !hmac.Equal([]byte(want), []byte(parts[2])) {
		return nil, fmt.Errorf("%w: want %s got %s", errs[1].Err, want[:20], parts[2][:min(20, len(parts[2]))])
	}

	// ④ 到此才能信任 payload
	var c Claims
	if err := json.Unmarshal(b64urlDecode(parts[1]), &c); err != nil {
		return nil, fmt.Errorf("malformed payload: %v", err)
	}

	// ⑤ nbf（未生效）
	if c.NBF != 0 && nowUnix < c.NBF {
		return nil, fmt.Errorf("%w: nbf=%d now=%d", errs[2].Err, c.NBF, nowUnix)
	}
	// ⑥ exp（已过期）。留 5 秒余量（leeway），防客户端与服务端时钟漂移。
	leeway := int64(5)
	if nowUnix > c.EXP+leeway {
		return nil, fmt.Errorf("%w: exp=%d now=%d", errs[0].Err, c.EXP, nowUnix)
	}
	// ⑦ 类型：refresh 不能当 access 用（这是双 token 的关键闸门，W15 依赖它）
	if wantType != "" && c.Typ != wantType {
		return nil, fmt.Errorf("%w: want %s got %s", errs[3].Err, wantType, c.Typ)
	}
	// ⑧ 撤销名单
	if reason, hit := denylist[c.JTI]; hit {
		return nil, fmt.Errorf("%w: jti=%s reason=%s", errs[4].Err, c.JTI, reason)
	}
	return &c, nil
}

func goodClaims(typ string, ttlMin int) Claims {
	return Claims{
