// tweakAt 把 base64url 串的第 pos 位换成另一个合法字符。
func tweakAt(s string, pos int) string {
	b := []byte(s)
	if pos >= len(b) {
		return s
	}
	if b[pos] == 'A' {
		b[pos] = 'B'
	} else {
		b[pos] = 'A'
	}
	return string(b)
}

func xorAll(a, b []byte) byte {
	var acc byte
	for i := range a {
		if i < len(b) {
			acc |= a[i] ^ b[i]
		} else {
			acc |= 1
		}
	}
	return acc
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func shortOf(err error) string {
	s := err.Error()
	rs := []rune(s)
	if len(rs) > 52 {
		return string(rs[:50]) + "…"
	}
	return s
}

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false

