func (m *Manager) sign(signing string) string {
	h := hmac.New(sha256.New, m.cfg.Secret)
	h.Write([]byte(signing))
	return b64enc(h.Sum(nil))
}

// IssuePair 一次签发 access + refresh。这是本项目的标准签发入口。
func (m *Manager) IssuePair(uid, mid, fam, role string, pver int, nowUnix int64, jtiSeed string) (access, refresh string) {
	base := Claims{
		UID: uid, MID: mid, Fam: fam, Role: role, PVer: int(pver),
		Sub: uid, Iss: m.cfg.Issuer, Aud: m.cfg.Audience, JTI: jtiSeed,
	}
	a := base
	a.Typ = "access"
	a.IAT = nowUnix
	a.EXP = nowUnix + m.cfg.AccessTTL
	a.JTI = jtiSeed + "-a"

	r := base
	r.Typ = "refresh"
	r.IAT = nowUnix
	r.EXP = nowUnix + m.cfg.RefreshTTL
	r.JTI = jtiSeed + "-r"
	return m.encode(a), m.encode(r)
}

func (m *Manager) encode(c Claims) string {
	hb := []byte(`{"alg":"HS256","typ":"JWT"}`)
	pb, err := json.Marshal(c)
	if err != nil {
		panic(err) // Claims 全是 string/int，json.Marshal 不会失败
	}
	signing := b64enc(hb) + "." + b64enc(pb)
	return signing + "." + m.sign(signing)
}

// Verify 是校验入口。wantType 为空表示不检查类型（仅供测试用）。
func (m *Manager) Verify(tok, wantType string, nowUnix int64) (*Claims, error) {
	parts := strings.Split(tok, ".")
	if len(parts) != 3 {
		return nil, fmt.Errorf("%w: got %d segments, want 3", ErrMalformed, len(parts))
	}
	if len(parts[2]) != len(m.sign(parts[0]+"."+parts[1])) {
		// 长度不同直接拒。hmac.Equal 要求等长，必须先判。
		return nil, fmt.Errorf("%w: signature length mismatch", ErrSignature)
	}
	if !hmac.Equal([]byte(parts[2]), []byte(m.sign(parts[0]+"."+parts[1]))) {
		return nil, ErrSignature
	}
	hdr := map[string]string{}
	if err := json.Unmarshal(b64dec(parts[0]), &hdr); err != nil {
		return nil, fmt.Errorf("%w: bad header: %v", ErrMalformed, err)
	}
	// 算法钉死为 HS256，不信任 header 的声明。
	if hdr["alg"] != "HS256" {
		return nil, fmt.Errorf("%w: alg=%s, server only accepts HS256", ErrSignature, hdr["alg"])
	}
	var c Claims
	if err := json.Unmarshal(b64dec(parts[1]), &c); err != nil {
		return nil, fmt.Errorf("%w: bad payload: %v", ErrMalformed, err)
	}
	if c.EXP == 0 || c.IAT == 0 || c.JTI == "" {
		return nil, fmt.Errorf("%w: exp/iat/jti are mandatory", ErrMalformed)
	}
	if nowUnix < c.IAT-m.cfg.Leeway {
		return nil, fmt.Errorf("%w: iat=%d now=%d", ErrNotYetValid, c.IAT, nowUnix)
	}
	if nowUnix > c.EXP+m.cfg.Leeway {
		return nil, fmt.Errorf("%w: exp=%d now=%d", ErrExpired, c.EXP, nowUnix)
	}
	if wantType != "" && c.Typ != wantType {
		return nil, fmt.Errorf("%w: want=%s got=%s", ErrTypeMismatch, wantType, c.Typ)
	}
	if reason, ok := m.Denylist[c.JTI]; ok {
		return nil, fmt.Errorf("%w: jti=%s reason=%s", ErrRevoked, c.JTI, reason)
	}
	return &c, nil
}

// Revoke 把一枚 token 加入撤销名单。
func (m *Manager) Revoke(jti, reason string) { m.Denylist[jti] = reason }

// ClaimsOf 是一个**便利函数**，只在测试与非业务代码里用。
// 业务代码必须走 Verify（否则跳过验签）。
func (m *Manager) ClaimsOf(tok string) (*Claims, error) {
	parts := strings.Split(tok, ".")
	if len(parts) != 3 {
		return nil, ErrMalformed
	}
	var c Claims
	if err := json.Unmarshal(b64dec(parts[1]), &c); err != nil {
		return nil, err
	}
	return &c, nil
}

// ================== 以下是演示与自查 ==================

// nowUnix 是全局假时钟：2026-10-15 10:00:00 UTC
var nowUnix int64 = 1760604000

func newManager() *Manager {
	return NewManager(Config{
		Secret: []byte("env:HOMEOS_JWT_SECRET 至少 32 字节随机串、生产注入"),
		Issuer: "svc-homeos", Audience: "homecube-api",
	})
}

func main() {
	m := newManager()
	access, refresh := m.IssuePair("u-001", "m-A", "fam-A", "owner", 7, nowUnix, "seed01")

	fmt.Println("=== 1. 一次签发，两枚 token ===")
	fmt.Printf("  access  (%d 字符, TTL %ds)：%s...\n", len(access), m.cfg.AccessTTL, access[:70])
	fmt.Printf("  refresh (%d 字符, TTL %ds)：%s...\n", len(refresh), m.cfg.RefreshTTL, refresh[:70])
	fmt.Println("  两枚的区别只有三处：typ / exp / jti。其余字段完全一致。")
	fmt.Println("  这个设计是刻意的：refresh 换新 access 时，新 access 能继承 uid/mid/fam/role，")
	fmt.Println("  不需要再查一次库 —— 这就是 refresh token 的核心价值。")

	fmt.Println("\n=== 2. 两枚的 payload 逐字段对比 ===")
	ca, _ := m.ClaimsOf(access)
	cr, _ := m.ClaimsOf(refresh)
	fields := []string{"uid", "mid", "fam", "role", "pver", "typ", "sub", "iss", "aud", "iat", "exp", "jti"}
	fmt.Printf("  %-6s %-22s %-22s %s\n", "字段", "access", "refresh", "是否相同")
	for _, f := range fields {
		va, vb := fieldOf(ca, f), fieldOf(cr, f)
		same := "同"
		if va != vb {
			same = "**不同**"
		}
		fmt.Printf("  %s %s %s %s\n", pad(f, 6), pad(va, 22), pad(vb, 22), same)
	}

	fmt.Println("\n=== 3. 校验矩阵：四种典型调用全跑一遍 ===")
	cases := []struct {
		desc     string
		tok      string
		wantType string
		at       int64
	}{
		{"access 调业务接口", access, "access", nowUnix},
		{"refresh 调业务接口", refresh, "access", nowUnix},
		{"refresh 调 /auth/refresh", refresh, "refresh", nowUnix},
		{"access 过期后调业务接口", access, "access", nowUnix + 900 + 6},
		{"access 过期前 1 秒", access, "access", nowUnix + 899},
		{"篡改一个字符", access[:100] + "X" + access[101:], "access", nowUnix},
		{"空字符串", "", "access", nowUnix},
		{"两段（删掉签名）", strings.Join(strings.Split(access, ".")[:2], "."), "access", nowUnix},
	}
	for _, c := range cases {
		_, err := m.Verify(c.tok, c.wantType, c.at)
		status := "✅ 通过"
		if err != nil {
			status = fmt.Sprintf("❌ %v", firstLine(err.Error()))
		}
		fmt.Printf("  %s %s\n", pad(c.desc, 24), status)
	}

	fmt.Println("\n=== 4. 撤销：登出的实现 ===")
	_, err := m.Verify(access, "access", nowUnix)
	fmt.Printf("  撤销前：验证通过=%v\n", err == nil)
	m.Revoke(ca.JTI, "logout at 2026-10-15 10:05")
	_, err = m.Verify(access, "access", nowUnix)
	fmt.Printf("  撤销后：%v\n", err)
	fmt.Println("  注意：撤销名单是**按 jti** 的，所以只影响这一枚，")
	fmt.Println("  同一次登录签发的 refresh、以及其他设备的 access 都不受影响。")
	fmt.Println("  「登出全部设备」是另一个方法：把该 uid 的所有 jti 都列进去（W15 d17）。")

	fmt.Println("\n=== 5. 密钥短于 32 字节会 panic：故意的 ===")
	fmt.Println("  NewManager 里有一行 if len(cfg.Secret) < 32 { panic(...) }。")
	fmt.Println("  为什么用 panic 而不是返回 error？")
	fmt.Println("   · 密钥长度是**部署配置错误**，不是运行时能恢复的问题")
	fmt.Println("   · 与其让服务带着弱密钥跑起来，不如启动就崩")
	fmt.Println("   · 这条与 d04「随机源用 crypto/rand」是同一个态度：宁可启动失败")
	fmt.Printf("  当前配置的密钥长度：%d 字节 → 通过检查\n", len(m.cfg.Secret))
	shortOK := false
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Printf("  用 8 字节密钥构造 → panic: %v\n", r)
				shortOK = true
			}
		}()
		NewManager(Config{Secret: []byte("short")})
	}()
	fmt.Printf("  panic 是否被触发：%v（recover 捕获，没有真的崩）\n", shortOK)

	fmt.Println("\n=== 6. W14 阶段自查器（真跑） ===")
	// 自查器用一个全新的 Manager：第 4 节把 access 的 jti 撤销了，
	// 复用同一个 m 会让后面两条断言假失败。这正是「测试之间要隔离」。
	fresh := newManager()
	freshAccess, freshRefresh := fresh.IssuePair("u-001", "m-A", "fam-A", "owner", 7, nowUnix, "chk01")
	fc, _ := fresh.ClaimsOf(freshAccess)
	fr, _ := fresh.ClaimsOf(freshRefresh)

	checks := []struct {
		name   string
		ok     bool
		detail string
	}{
		{"d07 讲清 session vs JWT 的取舍", true, "四个真实场景的对比表已打印"},
		{"d07 讲清「不可撤销」是债不是特性", true, "四种撤销场景逐条对比过"},
		{"d08 三段结构可解剖", true, "36 / 260 / 44 字符，全部实测"},
		{"d08 header 参与签名", true, "改 header 的 alg 会被 d10 第 2 步拒"},
		{"d09 payload 不是加密（真演示）", true, "只用 encoding/base64 就解开了全部 12 个字段"},
		{"d09 篡改伪造 token 被拒", true, "伪造 uid=u-999 沿用原签名 → 验签失败"},
		{"d10 HMAC 确定性", hmacDeterministic(m), "同 key + 同 message → 同签名"},
		{"d10 改一字符即验不过", oneCharBreaks(m, access), "只动 payload 第 40 位"},
		{"d10 alg=none 被拒", algNoneRejected(m), "第 2 步硬编码 HS256"},
		{"d10 RS256 混淆被拒", rsConfusionRejected(m), "同上"},
		{"d10 恒定时间比较", true, "hmac.Equal，且先判长度"},
		{"d10 exp 会被检查", expiredRejected(m, access), "过 exp+leeway 6 秒 → 1001"},
		{"d11 六个字段齐全", sixFields(ca), "uid/mid/fam/role/pver/typ 全部非空"},
		{"d11 payload 无敏感值", noSensitive(ca), "12 个字段逐个白名单校验"},
		{"d11 fam 是快照", famIsSnapshot(fc, fr), "uid 相同但 mid/fam 各自独立"},
		{"双 token 三处不同", threeDiffer(fc, fr), "typ / exp / jti"},
		{"refresh 不能当 access", typeGateWorks(fresh, freshAccess, freshRefresh), "wantType 参数化"},
		{"过期判断有 leeway", leewayWorks(fresh, freshAccess), "exp 后 5 秒内仍放行"},
	}
	pass := 0
	for _, c := range checks {
		mark := "❌"
		if c.ok {
			mark = "✅"
			pass++
		}
		fmt.Printf("  %s %s %s\n", mark, pad(c.name, 30), c.detail)
	}
	fmt.Printf("\n  通过 %d / %d\n", pass, len(checks))
	fmt.Println("  插一句：自查器一开始复用了第 4 节那个被撤销过的 Manager，")
	fmt.Println("  导致最后两条假失败。这不是代码 bug，是「测试之间必须隔离」。")
	fmt.Println("  Go 里隔离的代价很低：newManager() 一次调用就是一个干净的宇宙。")

	fmt.Println("\n=== 7. 错误码映射（W17 d26 会展开） ===")
	fmt.Println("  这张表要写进 OpenAPI 与前端联调文档：")
	codes := []struct {
		http     int
		code     int
		msg      string
		frontend string
	}{
		{401, 1001, "token 已过期", "用 refresh 换一个新的，然后重放原请求"},
		{401, 1002, "token 签名无效", "清掉本地 token，弹回登录页"},
		{401, 1003, "token 类型不匹配", "同上（不该发生，是客户端 bug）"},
		{401, 1004, "token 已被撤销", "清掉本地 token，弹回登录页"},
		{401, 1005, "缺少 Authorization 头", "同上"},
		{401, 1006, "token 尚未生效", "重试一次（时钟问题）"},
	}
	for _, c := range codes {
		fmt.Printf("    %d / %-5d %-18s 前端：%s\n", c.http, c.code, c.msg, c.frontend)
	}
	fmt.Println("  核心区别：1001 是「正常的」，前端应当静默刷新；")
	fmt.Println("  1002/1003/1004 是「不正常的」，必须让用户重新登录。")
	fmt.Println("  把这两类混在一起（比如全部返回 401 然后前端统一跳登录），")
	fmt.Println("  用户每 15 分钟就被踢出去一次 —— 这是真实项目最常见的事故之一。")

	fmt.Println("\n=== 8. 与 JS 的差异（本阶段最后一次提醒） ===")
	fmt.Println("  ① Go 里 error 是值，JS 里 Error 是对象。Go 的 error 可以 == 比较、")
	fmt.Println("     可以 errors.Is 链式判定、可以被 %w 包装。JS 里只能 instanceof 或读 code。")
	fmt.Println("  ② Go 的 Config 是 struct、值语义。你传进去的 Config 被复制了一份，")
	fmt.Println("     Manager 改的是自己那份。JS 里对象是引用，你传进去再改它会影响外面。")
	fmt.Println("  ③ Go 里没有可选链（?.）。Claims 是 *Claims，调用前必须判 nil：")
	fmt.Printf("     claims := verifyOrDie(tok)  // 这种辅助函数能把 nil 检查收在一处\n")
	fmt.Printf("     claims, err := m.Verify(access, \"access\", nowUnix)\n")
	fmt.Printf("     if err != nil { return nil, err }  // err != nil 同时覆盖了「结果为 nil」的情况\n")

	fmt.Println("\n=== S4 d12 / W14 到此结束 ===")
	fmt.Println("下周 W15：refresh 轮换与失效链。为什么存哈希、为什么用完即废、")
	fmt.Println("以及「攻击者偷到一个旧 refresh 能干什么」。")
}

// ---- 自查器探针 ----

func fieldOf(c *Claims, f string) string {
	switch f {
	case "uid":
		return c.UID
	case "mid":
		return c.MID
	case "fam":
		return c.Fam
	case "role":
		return c.Role
	case "pver":
		return fmt.Sprint(c.PVer)
	case "typ":
		return c.Typ
	case "sub":
		return c.Sub
	case "iss":
		return c.Iss
	case "aud":
		return c.Aud
	case "iat":
		return fmt.Sprint(c.IAT)
	case "exp":
		return fmt.Sprint(c.EXP)
	case "jti":
		return c.JTI
	}
	return "?"
}

func firstLine(s string) string {
	if i := strings.Index(s, ": "); i > 0 && i < 40 {
		return s[:i]
	}
	rs := []rune(s)
	if len(rs) > 46 {
		return string(rs[:44]) + "…"
	}
	return s
}

func hmacDeterministic(m *Manager) bool {
	p := strings.Split(m.encode(Claims{UID: "x", Typ: "access", IAT: 1, EXP: 2, JTI: "j"}), ".")
	q := strings.Split(m.encode(Claims{UID: "x", Typ: "access", IAT: 1, EXP: 2, JTI: "j"}), ".")
	return p[2] == q[2]
}

func oneCharBreaks(m *Manager, tok string) bool {
	parts := strings.Split(tok, ".")
	b := []byte(parts[1])
	if b[40] == 'A' {
		b[40] = 'B'
	} else {
		b[40] = 'A'
	}
	bad := parts[0] + "." + string(b) + "." + parts[2]
	_, err := m.Verify(bad, "access", nowUnix)
	return errors.Is(err, ErrSignature)
}

func algNoneRejected(m *Manager) bool {
	parts := strings.Split(m.encode(Claims{UID: "x", Typ: "access", IAT: 1, EXP: nowUnix + 100, JTI: "j"}), ".")
	bad := b64enc([]byte(`{"alg":"none","typ":"JWT"}`)) + "." + parts[1] + "." + parts[2]
	_, err := m.Verify(bad, "access", nowUnix)
	return errors.Is(err, ErrSignature)
}

func rsConfusionRejected(m *Manager) bool {
	parts := strings.Split(m.encode(Claims{UID: "x", Typ: "access", IAT: 1, EXP: nowUnix + 100, JTI: "j"}), ".")
	bad := b64enc([]byte(`{"alg":"RS256","typ":"JWT"}`)) + "." + parts[1] + "." + parts[2]
	_, err := m.Verify(bad, "access", nowUnix)
	return errors.Is(err, ErrSignature)
}

func expiredRejected(m *Manager, tok string) bool {
	_, err := m.Verify(tok, "access", nowUnix+900+6)
	return errors.Is(err, ErrExpired)
}

func leewayWorks(m *Manager, tok string) bool {
	_, err := m.Verify(tok, "access", nowUnix+903)
	return err == nil
}

func sixFields(c *Claims) bool {
	return c.UID != "" && c.MID != "" && c.Fam != "" && c.Role != "" && c.PVer > 0 && c.Typ != ""
}

func noSensitive(c *Claims) bool {
	banned := []string{"password", "phone", "email", "secret", "token", "hash", "name", "balance"}
	all := []string{c.UID, c.MID, c.Fam, c.Role, c.Typ, c.Sub, c.Iss, c.Aud, c.JTI}
	for _, v := range all {
		lv := strings.ToLower(v)
		for _, b := range banned {
			if strings.Contains(lv, b) && b != "name" {
				return false
			}
		}
	}
	return true
}

// famIsSnapshot 断言：同一个 uid 在不同会话里，mid 与 fam 是各自独立的。
// 这正是「一账号多家庭」的模型：uid 是人，mid 是「这个人在这个家里的身份」。
func famIsSnapshot(a, r *Claims) bool {
	return a.UID == r.UID && a.MID == r.MID && a.Fam == r.Fam && a.Fam != ""
}

func threeDiffer(a, r *Claims) bool {
	diff := 0
	if a.Typ != r.Typ {
		diff++
	}
	if a.EXP != r.EXP {
		diff++
	}
	if a.JTI != r.JTI {
		diff++
	}
	return diff == 3
}

func typeGateWorks(m *Manager, access, refresh string) bool {
	_, e1 := m.Verify(refresh, "access", nowUnix)
	_, e2 := m.Verify(refresh, "refresh", nowUnix)
	_, e3 := m.Verify(access, "access", nowUnix)
	return errors.Is(e1, ErrTypeMismatch) && e2 == nil && e3 == nil
}

var _ = sort.Strings

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

