package main

// =====================================================================
// S4 · W15 · d13：为什么需要双 token
//
//   access 短命 与「用户被改权限要立刻生效」之间的矛盾
//
// 本程序用假时钟把两条策略真跑一遍：单 token 与双 token 各模拟一天。
// =====================================================================

import (
	"fmt"
	"strings"
	"time"
)

// ---------- 假时钟 ----------

var base = time.Date(2026, 10, 15, 8, 0, 0, 0, time.UTC)
var now = base

// tick 把时钟**设定**到 base+d（不是累加），保证绝对时刻可预期。
func tick(d time.Duration) time.Time {
	now = base.Add(d)
	return now
}

func hhmm(t time.Time) string { return t.Format("15:04") }

// ---------- 场景数据 ----------

// 用户在一个真实的一天里打开 App 的次数。
type event struct {
	at   time.Duration
	what string
}

// 一个「上班族」的一天。at 是**相对 base（08:00）的偏移**。
var dayPlan = []event{
	{0, "通勤路上打开 App（看今天要交的水电费）"},
	{5 * time.Minute, "记账：一笔午饭 32 元"},
	{4*time.Hour + 30*time.Minute, "午休看一眼待办"},
	{10*time.Hour + 40*time.Minute, "下班路上把待办勾了"},
	{13 * time.Hour, "睡前看本月预算用了多少"},
}

// 一个「恶意攻击者」在同一天里做的事。
var attackPlan = []event{
	{9 * time.Hour, "攻击者偷到了长期凭证"},
	{9*time.Hour + time.Minute, "尝试访问受保护接口"},
	{11 * time.Hour, "管理员把账号停用（status=disabled）"},
	{11*time.Hour + time.Minute, "攻击者再次尝试"},
	{14 * time.Hour, "攻击者再次尝试"},
}

func main() {
	fmt.Println("=== 1. 先把矛盾摆出来 ===")
	fmt.Println("  两条需求，来自 PRD 3.8 与 tech-plan §8.5，它们互相打架：")
	fmt.Println()
	fmt.Println("  需求 A：access 要**短命**")
	fmt.Println("    理由：泄露的窗口要小。access 会被写进每一份请求，")
	fmt.Println("          日志、代理、抓包都可能留下它。15 分钟是业界共识值。")
	fmt.Println()
	fmt.Println("  需求 B：权限变更要**立刻生效**")
	fmt.Println("    PRD 3.8 + 18.2#6：降权后 ≤1 秒生效；PRD 15.6：进程内缓存 + 事件失效。")
	fmt.Println("    「立刻」意味着不能等 token 自然过期。")
	fmt.Println()
	fmt.Println("  如果只有一个 token，TTL 只能取一个值：")
	single := []struct {
		ttl          string
		meetA, meetB string
	}{
		{"15 分钟", "✅ 满足 A", "❌ 不满足 B：降权后最多 15 分钟才生效"},
		{"3 秒", "✅ 满足 A（更短）", "❌ 不满足 B，但要每秒发 1200 次请求"},
		{"24 小时", "❌ 不满足 A：泄露一整天", "❌ 也不满足 B：更糟"},
		{"0（不设过期）", "❌ 完全不满足 A", "✅ 满足 B（每次都查库）"},
	}
	fmt.Printf("  %s %s %s\n", pad("TTL", 14), pad("需求 A（短命）", 34), "需求 B（立刻生效）")
	for _, row := range single {
		fmt.Printf("  %s %s %s\n", pad(row.ttl, 14), pad(row.meetA, 34), row.meetB)
	}
	fmt.Println()
	fmt.Println("  最后一行「TTL=0」看着像答案：每次都查库，权限当然「立刻」生效。")
	fmt.Println("  但它就是纯 session 方案 —— 我们在 W14 d07 已经算过账了：")
	fmt.Println("  每个请求一次数据库查询，首页聚合接口本来就查十几张表。")
	fmt.Println("  所以「立刻生效」必须靠别的机制，而不是靠一个极短的 TTL。")

	fmt.Println("\n=== 2. 拆开矛盾：两个 token 各承担一件事 ===")
	fmt.Println("  access token：负责「短时间内的高频访问」")
	fmt.Println("     TTL 15 分钟，无状态，服务端不查库")
	fmt.Println("     代价：权限变更有最多 15 分钟的延迟")
	fmt.Println("  refresh token：负责「证明我还是我」")
	fmt.Println("     TTL 30 天，服务端**存库**")
	fmt.Println("     它是唯一能让旧 access 立刻失效的东西 ——")
	fmt.Println("     因为每次 refresh 都会签发新的 access，而旧的不再被续期")
	fmt.Println()
	fmt.Println("  关键一句：双 token 不是「两个长得像的东西」，")
	fmt.Println("  而是「一个无状态 + 一个有状态」的分工。有状态的那个才有撤销能力。")

	fmt.Println("\n=== 3. 单 token 方案跑一整天（用户视角） ----------")
	simSingle("单 token（TTL = 3 小时）")

	fmt.Println("\n=== 4. 双 token 方案跑一整天（用户视角） ----------")
	simDual("双 token（access 15min + refresh 30d）")

	fmt.Println("\n=== 5. 攻击者视角：两套方案下，停用后多久才真正被拒 ----------")
	simAttack()

	fmt.Println("\n=== 6. 关键设计点：refresh 换新的那一刻发生什么 ----------")
	fmt.Println("  流程（真项目的 POST /api/homeos/auth/refresh）：")
	steps := []string{
		"① 前端 access 收到 401/1001（token expired）",
		"② 前端**自动**（不弹窗）带 refresh 调 /auth/refresh",
		"③ 服务端：验 refresh 签名 → 查 homeos_refresh_token 表",
		"④   · 这枚 refresh 的哈希在库里吗？不在 → 1002 refresh 无效",
		"⑤   · 在库里但已被标记 revoked → 1002",
		"⑥   · status 是否还 active？不是 → 1005",
		"⑦   · 该 uid 的 pwd_changed_at 是否晚于这枚 refresh 的签发时间？是 → 1002",
		"⑧ 全部通过 → **作废这一枚**，签发新的一对（access + refresh）",
		"⑨ 返回给前端，前端替换本地两枚 token，重放原请求",
	}
	for _, s := range steps {
		fmt.Printf("  %s\n", s)
	}
	fmt.Println()
	fmt.Println("  第 ⑧ 步的「作废这一枚」就是 d15 的轮换；第 ⑦ 步是 d17 的改密失效链。")
	fmt.Println("  今天只记住这个流程的存在，明天开始逐条拆。")

	fmt.Println("\n=== 7. 为什么 refresh 要比 access 长这么多倍 ===")
	fmt.Println("  如果两边 TTL 一样，双 token 就毫无意义 —— 那还不如单 token。")
	fmt.Println("  长短比例决定了「用户体验 vs 安全性」的取舍点：")
	fmt.Println("    access 越短 → 每 15 分钟就要一次 refresh 请求 → 网络开销与失败率上升")
	fmt.Println("    refresh 越长 → 攻击者偷到后的可用窗口越长")
	fmt.Println()
	ratio := []struct{ a, r, note string }{
		{"15 分钟", "30 天", "本项目取值。refresh:access = 2880:1"},
		{"15 分钟", "7 天", "更保守。用户体验略差但丢一次手机要重新登录"},
		{"30 分钟", "30 天", "省一半 refresh 流量。代价是泄露窗口翻倍"},
		{"15 分钟", "1 年", "❌ 太长。手机丢了就等于一年内有在被盗风险"},
	}
	fmt.Printf("  %s %s %s\n", pad("access TTL", 12), pad("refresh TTL", 12), "说明")
	for _, r := range ratio {
		fmt.Printf("  %s %s %s\n", pad(r.a, 12), pad(r.r, 12), r.note)
	}
	fmt.Println()
	fmt.Println("  30 天这个值还有一个现实理由：**它让「忘记密码」这件事变得可行**。")
	fmt.Println("  用户半年后回来，手机上还有一枚没过期的 refresh，")
	fmt.Println("  配合手机号验证码就能直接换出新 access，不用输密码。")

	fmt.Println("\n=== 8. 一个必须澄清的误解：「refresh 也是 JWT 所以也能免登录」 ----------")
	fmt.Println("  错。它们都是 JWT、都自包含，但服务端对它们的处理完全不同：")
	fmt.Println()
	cmp := []struct{ aspect, access, refresh string }{
		{"验签", "✅", "✅"},
		{"查 exp", "✅", "✅"},
		{"查数据库", "❌ 不查（无状态）", "✅ **必须查**（要确认哈希在库里且未撤销）"},
		{"可撤销", "只能靠 denylist，且本项目不查", "✅ 直接 UPDATE revoked_at"},
		{"轮换", "不轮换（15 分钟后自然死）", "✅ 每次用完即作废"},
		{"发到哪里", "内存 / 请求头", "HttpOnly Cookie（或更安全的存储）"},
		{"能不能调业务接口", "✅ 能", "❌ 不能，typ 不匹配"},
	}
	fmt.Printf("  %s %s %s\n", pad("维度", 16), pad("access", 30), "refresh")
	for _, c := range cmp {
		fmt.Printf("  %s %s %s\n", pad(c.aspect, 16), pad(c.access, 30), c.refresh)
	}
	fmt.Println()
	fmt.Println("  「JWT 无状态」这句话只对 **access** 成立。")
	fmt.Println("  refresh 一旦要入库、要撤销、要查哈希，它就有状态了 ——")
	fmt.Println("  它只是用 JWT 的**签名**来避免「每次都查用户表」，")
	fmt.Println("  而不是因为它自己无状态。")
	fmt.Println("  把「用了 JWT 所以整个鉴权无状态」当成结论，会在 d16 重放演示时付出代价。")

	fmt.Println("\n=== 9. 与 JS 的对照 ----------")
	fmt.Println("  ① 前端的「自动刷新」需要**并发去重**。")
	fmt.Println("     页面同时发 5 个请求，5 个都 401，JS 里就要保证只发一个 refresh。")
	fmt.Println("     这在 React 里靠一个「刷新中的 promise」单例。")
	fmt.Println("  ② Go 里没有全局单例的天然位置，通常挂在请求上下文或一个带锁的字段上。")
	fmt.Println("     这不是 Go 更麻烦，而是「共享状态需要显式保护」这个 Go 哲学的体现。")
	fmt.Println("  ③ 时钟：Go 的 time.Now().Unix() 返回 int64 秒；")
	fmt.Println("     JS 的 Date.now() 返回毫秒。写 exp 时两边必须统一，")
	fmt.Println("     d08 讲过这个坑 —— 混用会导致 token 永不过期或立刻过期。")
	fmt.Println("  ④ 前端的 401 拦截器要区分「1001 过期」与「1002 无效」：")
	fmt.Println("     前者静默刷新，后者清 token 跳登录。这个区分必须在契约里写死。")

	fmt.Println("\n=== S4 d13 到此结束 ===")
	fmt.Println("明天：refresh token 的存储。为什么存哈希不存明文 ——")
	fmt.Println("道理和 d01 的密码完全一样，但容易犯一个不同的错。")
}

// ---------------- 模拟 ----------------

func simSingle(title string) {
	fmt.Printf("  【%s】\n", title)
	now = base
	tokenTTL := 3 * time.Hour
	issues := 0
	firstIssue := base.Add(-tokenTTL)
	lastReq := now
	var rows []string
	for _, e := range dayPlan {
		at := tick(e.at)
		// 逻辑：如果 token 已过期就重新签发
		if at.Sub(firstIssue) >= tokenTTL {
			issues++
			firstIssue = at
		}
		lastReq = at
		note := "直接用现有 token"
		if at.Sub(firstIssue) >= tokenTTL {
			note = "token 过期 → 弹登录页，用户重新输密码"
		}
		rows = append(rows, fmt.Sprintf("    %s %s → %s", hhmm(at), e.what, note))
	}
	fmt.Println(strings.Join(rows, "\n"))
	_ = lastReq
	fmt.Printf("    一天里重新签发 token %d 次\n", issues)
	fmt.Println("    ✓ 优点：用户完全无感")
	fmt.Println("    ✗ 缺点：停用账号后最多 3 小时仍可用；且泄露窗口是 3 小时")
}

func simDual(title string) {
	fmt.Printf("  【%s】\n", title)
	now = base
	accessTTL := 15 * time.Minute
	refreshTTL := 30 * 24 * time.Hour
	issues := 0
	accessAt := base.Add(-accessTTL)
	refreshAt := base
	rows := []string{}
	for _, e := range dayPlan {
		at := tick(e.at)
		note := "直接用"
		if at.Sub(accessAt) >= accessTTL {
			if at.Sub(refreshAt) < refreshTTL {
				issues++
				accessAt = at
				note = "access 过期 → 用 refresh 静默换新"
			} else {
				note = "refresh 也过期 → 回登录页"
				accessAt, refreshAt = at, at
			}
		}
		rows = append(rows, fmt.Sprintf("    %s %s → %s", hhmm(at), e.what, note))
	}
	fmt.Println(strings.Join(rows, "\n"))
	fmt.Printf("    一天里静默刷新 %d 次（用户无感），用户只登录了 1 次\n", issues)
	fmt.Println("    ✓ access 泄露窗口 15 分钟")
	fmt.Println("    ✓ refresh 可撤销：登出/停用/改密都能立刻断掉续期能力")
	fmt.Println("    ✗ 代价：多了一种失败模式（refresh 也过期了）")
}

func simAttack() {
	fmt.Println("  管理员在 11:00 把账号停用。攻击者在 11:01 与 14:00 各试一次。")
	fmt.Println()
	rows := []struct {
		at     string
		single string
		dual   string
	}{
		{"11:01（停用后 1 分钟）", "❌ 通过 —— 只验签，3 小时 TTL 未到", "✅ 通过 —— access 15 分钟还没过期（诚实：停用无法立刻生效）"},
		{"14:00（停用后 3 小时）", "✅ 已被拒 —— 3 小时 TTL 到了", "❌ 通过 —— 攻击者拿 refresh 又换到新 access"},
		{"14:00 + 15 分钟", "✅ 已被拒", "✅ 已被拒 —— 但前提是接口会查 status"},
	}
	fmt.Printf("  %s %-32s %s\n", pad("时刻", 20), pad("单 token 3h", 34), "双 token")
	for _, r := range rows {
		fmt.Printf("  %s %s %s\n", pad(r.at, 20), pad(r.single, 34), r.dual)
	}
	fmt.Println()
	fmt.Println("  这张表暴露了一件事：**双 token 本身不解决「停用要立刻生效」**。")
	fmt.Println("  攻击者拿着 refresh 可以无限续期，等于拿着一张长期门票。")
	fmt.Println("  真正解决问题的是 refresh 接口上那几条检查：")
	fmt.Println("    · status != active → 拒绝")
	fmt.Println("    · refresh 已 revoked → 拒绝")
	fmt.Println("    · pwd_changed_at > 该 refresh 的 iat → 拒绝")
	fmt.Println("  也就是说：**有状态的是 refresh，而撤销能力全部挂在它身上**。")
	fmt.Println("  这三行就是 W15 后三天的全部内容。")
	fmt.Println()
	fmt.Println("  对照 PRD：")
	fmt.Println("    tech-plan §8.5：「登出 / 重置密码 → 该用户所有 refresh token 立即失效」")
	fmt.Println("    PRD 15.6     ：权限变更 ≤1 秒生效（走 pver 与事件，不靠 refresh）")
	fmt.Println("    PRD 3.7 L413 ：移除成员 → 「其令牌即刻失效」")
	fmt.Println("  三处都指向同一件事：**refresh 的状态必须在服务端被主动改掉**。")
}

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

