package main

// =====================================================================
// S4 · W15 · d16：重放攻击演示
//
//   攻击者偷到一个旧 refresh 到底能干什么。
//   轮换怎么把这条路堵死，以及「检测到重放之后该做什么」。
// =====================================================================

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"sort"
	"time"
)

// ---------- 环境 ----------

var pepper = []byte("env:HOMEOS_TOKEN_PEPPER")
var base = time.Date(2026, 10, 15, 9, 0, 0, 0, time.UTC)
var now = base
var seq int

func tick(d time.Duration) time.Time { now = now.Add(d); return now }
func hhmm(t time.Time) string        { return t.Format("15:04") }

// ---------- 表 ----------

type Row struct {
	ID        string
	UserID    string
	ChainID   string
	Gen       int
	ParentID  string
	TokenHash string
	IssuedAt  time.Time
	UsedAt    *time.Time
	RevokedAt *time.Time
	RevokeWhy string
	Status    string // 用户状态
	Version   int
}

var rows = []*Row{}
var alerts []string
var lastIssuedIP string

var (
	ErrNoRow    = errors.New("refresh token not found")
	ErrUsed     = errors.New("refresh token already used")
	ErrRevoked  = errors.New("refresh token revoked")
	ErrInactive = errors.New("user account not active")
)

func hashOf(t string) string {
	m := hmac.New(sha256.New, pepper)
	m.Write([]byte(t))
	return hex.EncodeToString(m.Sum(nil))
}

func mint(userID, chainID, parentID string, gen int) (string, *Row) {
	seq++
	plain := fmt.Sprintf("rt_%s_%06d", userID, seq)
	r := &Row{
		ID: fmt.Sprintf("rt-%06d", seq), UserID: userID, ChainID: chainID,
		Gen: gen, ParentID: parentID, TokenHash: hashOf(plain),
		IssuedAt: now, Status: "active", Version: 1,
	}
	rows = append(rows, r)
	return plain, r
}

func find(plain string) *Row {
	h := hashOf(plain)
	for _, r := range rows {
		if hmac.Equal([]byte(r.TokenHash), []byte(h)) {
			return r
		}
	}
	return nil
}

// childOf 返回 old 的直接子代（用于幂等刷新）。
func childOf(old *Row) *Row {
	for _, r := range rows {
		if r.ParentID == old.ID {
			return r
		}
	}
	return nil
}

// Rotate 带重放检测的完整实现。
func Rotate(tok, ip string) (string, *Row, string, error) {
	r := find(tok)
	if r == nil {
		return "", nil, "", fmt.Errorf("%w: hash=%s...", ErrNoRow, hashOf(tok)[:16])
	}
	// ① 用户状态
	if r.Status != "active" {
		return "", nil, "", fmt.Errorf("%w: status=%s", ErrInactive, r.Status)
	}
	// ② 重放检测**必须排在撤销检查之前**。
	//    因为轮换时 used_at 与 revoked_at 会被**同时**写入 ——
	//    如果先查 revoked，重放会被误判成「一枚已被撤销」，
	//    那样就只会返回 1002 而不会触发整链吊销，报警信号就丢了。
	if r.UsedAt != nil {
		// 幂等：如果是**同一 IP** 的并发请求，返回子代即可
		if ip == lastIssuedIP {
			c := childOf(r)
			if c != nil && c.RevokedAt == nil && c.UsedAt == nil {
				return "", c, "idempotent", nil
			}
		}
		// 不同 IP 且已用过 = 重放。**整链吊销**
		revokeChain(r.ChainID, "replay_detected", "system")
		alerts = append(alerts, fmt.Sprintf(
			"[%s] ⚠ 重放检测：%s 的 gen=%d 从 %s 被再次使用（首次来自 %s）→ 整链吊销",
			hhmm(now), r.UserID, r.Gen, ip, lastIssuedIP))
		return "", nil, "", fmt.Errorf("%w: chain %s fully revoked", ErrUsed, r.ChainID)
	}
	// ③ 撤销（这里只可能是「被管理员/改密撤销」，不含轮换造成的撤销）
	if r.RevokedAt != nil {
		return "", nil, "", fmt.Errorf("%w: %s", ErrRevoked, r.RevokeWhy)
	}
	// 正常轮换
	u := now
	r.UsedAt = &u
	r.RevokedAt = &u
	r.RevokeWhy = "rotated"
	r.Version++
	lastIssuedIP = ip
	np, nr := mint(r.UserID, r.ChainID, r.ID, r.Gen+1)
	return np, nr, "rotated", nil
}

func revokeChain(chainID, why, by string) {
	u := now
	n := 0
	for _, r := range rows {
		if r.ChainID == chainID && r.RevokedAt == nil {
			r.RevokedAt = &u
			r.RevokeWhy = why
			r.Version++
			n++
		}
	}
	returnStr := fmt.Sprintf("chain=%s 吊销 %d 行", chainID, n)
	alerts = append(alerts, fmt.Sprintf("[%s] 整链吊销：%s", hhmm(now), returnStr))
}

// reset 只清表，不清 alerts —— 告警要跨实验累积。
func reset() {
	rows = nil
	seq = 0
	now = base
	lastIssuedIP = "203.0.113.7" // 用户手机的 IP
}

func printChain(chainID string) {
	var cs []*Row
	for _, r := range rows {
		if r.ChainID == chainID {
			cs = append(cs, r)
		}
	}
	sort.Slice(cs, func(i, j int) bool { return cs[i].Gen < cs[j].Gen })
	for _, r := range cs {
		st := "✅ 有效"
		switch {
		case r.RevokeWhy == "replay_detected":
			st = "⛔ 因重放被吊销"
		case r.RevokedAt != nil:
			st = "↻ 已轮换作废"
		}
		fmt.Printf("    gen=%d %s %-9s %s\n", r.Gen, r.ID, st, hhmm(r.IssuedAt))
	}
}

func main() {
	fmt.Println("=== 1. 攻击模型：先说清楚攻击者能做什么、不能做什么 ===")
	fmt.Println("  能：")
	fmt.Println("    · 监听用户的 HTTP 流量 → 拿到 refresh token（前提是没用 HTTPS）")
	fmt.Println("    · 偷到用户的手机 / 拿到备份里的 App 数据")
	fmt.Println("    · 在 XSS 里读前端存储（d25 会讲 localStorage 的问题）")
	fmt.Println("  不能：")
	fmt.Println("    · 猜出 token（256 位随机，比 6 位验证码强 10^250 倍）")
	fmt.Println("    · 伪造 token（没有 JWT 密钥，d10 讲过）")
	fmt.Println("    · 无限次试同一个 token（限流 + 锁定，W17 d27/d28 讲）")
	fmt.Println()
	fmt.Println("  所以攻击者的唯一优势是：**他有一枚真的、当时有效的 token**。")
	fmt.Println("  「重放攻击」就是他反复使用这枚真 token。")
	fmt.Println("  防护的目标就一条：**这枚 token 一旦用过，就再也不能用第二次。**")

	fmt.Println("\n=== 2. 实验 A：没有轮换，攻击者畅通无阻 ===")
	reset()
	fmt.Println("  布置：")
	fmt.Printf("    [%s] 用户在 203.0.113.7（家里 Wi-Fi）登录\n", hhmm(now))
	r1plain, r1 := mint("u-001", "chain-A", "", 1)
	fmt.Printf("            → 拿到 refresh %s（库里存哈希，不存明文）\n", r1.ID)
	_ = r1plain
	fmt.Println()
	fmt.Println("  时间线：")
	// 无轮换的实现：只查「有没有被撤销」，根本不看 used_at
	tryUse := func(who string) {
		r := find(r1plain)
		if r != nil && r.RevokedAt == nil {
			fmt.Printf("    [%s] %s 换到新 access（用的还是 %s）\n", hhmm(now), who, r.ID)
		} else {
			fmt.Printf("    [%s] %s 被拒\n", hhmm(now), who)
		}
	}
	tick(80 * time.Minute)
	tryUse("✅ 用户      ")
	tick(5 * time.Minute)
	fmt.Printf("    [%s] 🕴 攻击者从网络流量里抓到 %s 的明文\n", hhmm(now), r1.ID)
	tick(time.Minute)
	tryUse("💀 攻击者    ")
	tick(time.Minute)
	tryUse("💀 用户再试  ")
	fmt.Println()
	fmt.Println("  结果：")
	fmt.Println("    · 攻击者获得 30 天（refresh TTL）的账号访问权")
	fmt.Println("    · 用户和攻击者可以**同时**在线，服务端分不出谁是谁")
	fmt.Println("    · 日志里看起来一切正常，因为每次请求都是合法的")
	fmt.Println("  这三条叠加起来，就是一次「静默的账号接管」。")

	fmt.Println("\n=== 3. 实验 B：有轮换，重放当场被抓 ----------")
	reset()
	fmt.Printf("  [%s] 用户登录 → 链 chain-B 第 1 代\n", hhmm(now))
	p1, row1 := mint("u-001", "chain-B", "", 1)
	fmt.Printf("            refresh id = %s\n", row1.ID)

	tick(80 * time.Minute)
	fmt.Println()
	fmt.Println("  时间线：")
	np, nr, mode, err := Rotate(p1, "203.0.113.7")
	fmt.Printf("    [%s] ✅ 用户换新（IP 203.0.113.7）→ %s，%s\n", hhmm(now), nr.ID, mode)
	printChain("chain-B")

	tick(5 * time.Minute)
	fmt.Printf("    [%s] 🕴 攻击者偷到旧 token %s\n", hhmm(now), row1.ID)
	fmt.Println()

	tick(time.Minute)
	_, _, mode, err = Rotate(p1, "45.33.32.156")
	fmt.Printf("    [%s] 攻击者重放（IP 45.33.32.156，境外机房）\n", hhmm(now))
	if err != nil {
		fmt.Printf("              → ❌ %v\n", err)
	} else {
		fmt.Printf("              → 💀 居然成功了（不该发生，%s）\n", mode)
	}
	printChain("chain-B")
	fmt.Println()
	fmt.Println("  注意整链吊销的效果：**连用户手里那枚新的也被吊销了**。")
	fmt.Println("  这是刻意的取舍 —— 已经有一枚 token 泄露，")
	fmt.Println("  我们无法判断用户手里那枚是不是干净的。")
	fmt.Println("  所以宁可让用户重新登录一次，也不能让攻击者继续用。")
	fmt.Println("  用户看到的现象是「请重新登录」，是安全与体验的合理交换。")

	fmt.Println("\n=== 4. 为什么「不同 IP」是判定重放的关键信号 ----------")
	fmt.Println("  回到 d15 讲过的并发问题：两次刷新来自同一个 IP，那是网络重试。")
	fmt.Println("  两次刷新来自完全不同的 IP，且同一枚 token —— 那就是两拨人在用。")
	fmt.Println()
	fmt.Println("  但要小心：**IP 不是可靠的身份**。三种情况会让判断失准：")
	caution := []struct{ scene, risk, how string }{
		{"用户在地铁（4G）刷了一次，回办公室（Wi-Fi）又刷了一次",
			"误判为重放 → 吊销链 → 用户被迫重登",
			"加宽限期：used_at 后 60 秒内视为并发，不判重放"},
		{"公司 500 人共用一个出口 NAT，同一枚 token 撞到两次",
			"同上（IP 相同，不算问题；但如果 NAT 轮换出口 IP 就会误判）",
			"主要靠宽限期 + 记录 UA，不要只靠 IP"},
		{"攻击者恰好与用户同一个 IP（同一 Wi-Fi）",
			"**漏判** —— 被当成并发，返回了子代",
			"所以 IP 只能是辅助信号；真正的防线是「用过即废」本身"},
	}
	for _, c := range caution {
		fmt.Printf("  ▸ %s\n", c.scene)
		fmt.Printf("      风险：%s\n", c.risk)
		fmt.Printf("      缓解：%s\n", c.how)
	}
	fmt.Println()
	fmt.Println("  结论：**不要把重放检测建立在 IP 上**。")
	fmt.Println("  正确的主次顺序是：")
	fmt.Println("    1. 主判据：used_at 非空 → 这一枚已经被用过 → 绝不再签发新 token")
	fmt.Println("    2. 辅助判据：IP / UA 不同 → 判定为攻击 → 整链吊销 + 报警")
	fmt.Println("    3. 同 IP + 短时间内 → 判定为并发 → 幂等返回子代")
	fmt.Println("  即使第 2 步误判，第 1 步也已经挡住了实际的危害：")
	fmt.Println("  攻击者拿不到新的 access。")

	fmt.Println("\n=== 5. 实验 C：轮换开着，但误判成并发会怎样 ----------")
	reset()
	p2, r2 := mint("u-001", "chain-C", "", 1)
	fmt.Printf("  [%s] 用户登录 → %s\n", hhmm(now), r2.ID)
	tick(time.Minute)
	np2, nr2, mode2, _ := Rotate(p2, "203.0.113.7")
	fmt.Printf("  [%s] 用户首次换新 → %s\n", hhmm(now), nr2.ID)
	tick(200 * time.Millisecond)
	fmt.Printf("  [%s] 同一 IP 的第二个请求（模拟网络重试）\n", hhmm(now))
	_, child, mode3, err3 := Rotate(p2, "203.0.113.7")
	if err3 == nil && mode3 == "idempotent" {
		fmt.Printf("               → 识别为并发，**返回同一枚子代** %s（没有新建）\n", child.ID)
		fmt.Println("               用户无感，而且链上不会多出一行垃圾数据。")
	} else {
		fmt.Printf("               → 报错 %v（这在生产上就是「用户莫名其妙被登出」）\n", err3)
	}
	fmt.Println()
	fmt.Printf("  链上现在有 %d 行（正确：1 代 + 1 个子代 = 2 行）\n", len(rows))
	printChain("chain-C")
	fmt.Println()
	fmt.Println("  这就是 parent_id 那一列存在的全部理由：")
	fmt.Println("  没有它，幂等刷新无法实现 —— 你无法从「R1 已被用过」")
	fmt.Println("  反推出「R1 的孩子是哪一枚」。")
	fmt.Println("  查询就是一条简单的 SQL：")
	fmt.Println("    SELECT * FROM homeos_refresh_token WHERE parent_id = $1")

	fmt.Println("\n=== 6. 检测到重放之后应该做什么：四件事 ----------")
	acts := []struct{ n, what, why string }{
		{"1", "整链吊销（UPDATE ... WHERE chain_id = ? AND revoked_at IS NULL）",
			"断了所有后续续期。攻击者手里的和用户手里的都断"},
		{"2", "落审计事件 homeos.audit.recorded（PRD 21.5 的九类之一）",
			"登录类审计保留 6 个月。要记：uid / chain_id / IP / UA / gen"},
		{"3", "连续 5 次触发通知管理员（PRD 15.6 的原文）",
			"单次可能是误判，连续 5 次基本可以确定被盗"},
		{"4", "**把该用户的所有链都吊销**，并要求重新登录（含短信验证）",
			"如果一条链泄露了，同一账号的其他链也可能是攻击者建的"},
	}
	for _, a := range acts {
		fmt.Printf("  %s. %s\n", a.n, a.what)
		fmt.Printf("     为什么：%s\n", a.why)
	}
	fmt.Println()
	fmt.Println("  第 4 条经常被忘记。只吊销「出事的那条链」是不够的 ——")
	fmt.Println("  如果攻击者已经登录过一次，他完全可以**自己再开一条新链**。")
	fmt.Println("  所以响应必须是「这个账号的所有会话全部作废」。")

	fmt.Println("\n=== 7. 本程序记录的告警（跨三个实验累积）===")
	for _, a := range alerts {
		fmt.Printf("  %s\n", a)
	}
	fmt.Printf("  共 %d 条。实验 C（幂等刷新）**没有**产生告警 —— 这是对的：\n", len(alerts))
	fmt.Println("  正常的并发重试不该惊动任何人。只有真的换不来 token 时才报警。")
	fmt.Println()
	fmt.Println("  注意告警里有什么：**IP、UA、代数、链 id**。")
	fmt.Println("  这四样合起来才能定位问题；只记「某个用户被攻击了」是没法排查的。")

	fmt.Println("\n=== 8. 与 JS 的对照 ----------")
	fmt.Println("  ① 「重放」在前端有个对应物：**双击提交**。")
	fmt.Println("     React 里用户快速点两次「保存」，会发两个相同请求。")
	fmt.Println("     这是同一个问题的友好版本 —— 服务端要么用幂等键")
	fmt.Println("     （本项目铁律 3：client_request_id）要么用乐观锁。")
	fmt.Println("     S3 d23 讲过 version，S4 d15 讲过 used_at IS NULL，")
	fmt.Println("     三者是同一种模式的三个场景。")
	fmt.Println("  ② Node 里做「检测到重放 → 报警」通常直接打日志：")
	fmt.Println("       logger.warn({uid, chainId, ip}, 'replay detected')")
	fmt.Println("     Go 里对应 slog / zap，但要**注意别把 token 本身打进日志**：")
	fmt.Println("     只打 hash 的前 8 位与 chain_id 就够了。")
	fmt.Println("  ③ Go 的 error 链特别适合这个场景：")
	fmt.Println("     handler 判断 errors.Is(err, auth.ErrUsed) → 记审计 → 返回 1002")
	fmt.Println("     JS 里对应 if (err.code === 'REPLAY')，但 Go 的 errors.Is")
	fmt.Println("     能在包了两层 %w 的情况下仍然判定成功。")

	fmt.Println("\n=== S4 d16 到此结束 ===")
	fmt.Println("明天：登出与失效链。登出要撤销哪些、改密码后为什么必须全链失效。")
	_ = np
	_ = np2
	_ = mode
	_ = mode2
}

