package main

// =====================================================================
// S4 · W15 · d17：登出与失效链
//
//   登出要撤销哪些 / 改密码后为什么必须全链失效
//   tech-plan §8.5：「登出 / 重置密码 → 该用户所有 refresh token 立即失效」

// =====================================================================

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"
)

// ---------- 环境 ----------

var pepper = []byte("env:HOMEOS_TOKEN_PEPPER")

var seq int

func tick(d time.Duration) time.Time { now = now.Add(d); return now }
func hhmm(t time.Time) string        { return t.Format("15:04") }

// ---------- 数据 ----------

type User struct {
	ID         string
	Status     string // active / disabled
	PwdChanged time.Time
	Version    int
}

type Row struct {
	ID        string
	UserID    string
	ChainID   string
	Gen       int
	ParentID  string
	TokenHash string
	IssuedAt  time.Time
	UsedAt    *time.Time
	RevokedAt *time.Time
	RevokeWhy string
	Device    string
}

var users = map[string]*User{}

var audit []string

var (
	ErrNoRow      = errors.New("refresh token not found")
	ErrUsed       = errors.New("refresh token already used")
	ErrRevoked    = errors.New("refresh token revoked")
	ErrInactive   = errors.New("user account not active")
	ErrPwdChanged = errors.New("refresh issued before password change")
)

func hashOf(t string) string {
	m := hmac.New(sha256.New, pepper)
	m.Write([]byte(t))
	return hex.EncodeToString(m.Sum(nil))
}

func seedUser(id string) *User {
	u := &User{ID: id, Status: "active", PwdChanged: base, Version: 1}
	users[id] = u
	return u
}

func mint(u *User, chainID, parentID string, gen int, device string) (string, *Row) {
	seq++
	plain := fmt.Sprintf("rt_%s_%06d", u.ID, seq)
	r := &Row{
		ID: fmt.Sprintf("rt-%06d", seq), UserID: u.ID, ChainID: chainID, Gen: gen,
		ParentID: parentID, TokenHash: hashOf(plain), IssuedAt: now, Device: device,
	}
	rows = append(rows, r)
	return plain, r
}

func find(plain string) *Row {
	h := hashOf(plain)
	for _, r := range rows {
		if hmac.Equal([]byte(r.TokenHash), []byte(h)) {
			return r
		}
	}
	return nil
}

func childOf(old *Row) *Row {
	for _, r := range rows {
		if r.ParentID == old.ID {
			return r
		}
	}
	return nil
}

// Rotate 带**完整**的四道检查。
func Rotate(tok, ip string) (string, *Row, string, error) {
	r := find(tok)
	if r == nil {
		return "", nil, "", fmt.Errorf("%w", ErrNoRow)
	}
	u := users[r.UserID]
	// ① 用户状态
	if u.Status != "active" {
		return "", nil, "", fmt.Errorf("%w: status=%s", ErrInactive, u.Status)
	}
	// ② 改密时间 vs 签发时间（d17 的核心，d16 没有这条）
	if u.PwdChanged.After(r.IssuedAt) {
		return "", nil, "", fmt.Errorf("%w: pwd_changed=%s token_issued=%s",
			ErrPwdChanged, u.PwdChanged.Format("15:04"), r.IssuedAt.Format("15:04"))
	}
	// ③ 重放
	if r.UsedAt != nil {
		c := childOf(r)
		if c != nil && c.RevokedAt == nil && c.UsedAt == nil {
			return "", c, "idempotent", nil
		}
		revokeChain(r.ChainID, "replay_detected")
		audit = append(audit, fmt.Sprintf("[%s] AUDIT replay_detected uid=%s chain=%s ip=%s",
			hhmm(now), r.UserID, r.ChainID, ip))
		return "", nil, "", fmt.Errorf("%w", ErrUsed)
	}
	// ④ 撤销
	if r.RevokedAt != nil {
		return "", nil, "", fmt.Errorf("%w: %s", ErrRevoked, r.RevokeWhy)
	}
	v := now
	r.UsedAt = &v
	r.RevokedAt = &v
	r.RevokeWhy = "rotated"
	np, nr := mint(u, r.ChainID, r.ID, r.Gen+1, r.Device)
	return np, nr, "rotated", nil
}

func revokeWhere(where func(*Row) bool, why string) int {
	v := now
	n := 0
	for _, r := range rows {
		if r.RevokedAt == nil && where(r) {
			r.RevokedAt = &v
			r.RevokeWhy = why
			n++
		}
	}
	return n
}

func revokeChain(chainID, why string) int {
	return revokeWhere(func(r *Row) bool { return r.ChainID == chainID }, why)
}

func activeCount(uid string) int {
	n := 0
	for _, r := range rows {
		if r.UserID == uid && r.RevokedAt == nil {
			n++
		}
	}
	return n
}

func printRows(uid string) {
	var rs []*Row
	for _, r := range rows {
		if r.UserID == uid {
			rs = append(rs, r)
		}
	}
	sort.Slice(rs, func(i, j int) bool {
		if rs[i].ChainID != rs[j].ChainID {
			return rs[i].ChainID < rs[j].ChainID
		}
		return rs[i].Gen < rs[j].Gen
	})
	fmt.Printf("    %s 的 refresh（共 %d 条）：\n", uid, len(rs))
	for _, r := range rs {
		st := "✅ 有效"
		switch {
		case r.RevokeWhy == "rotated":
			st = "↻ 已轮换"
		case r.RevokedAt != nil:
			st = "⛔ " + r.RevokeWhy
		}
		pv := ""
		if r.UsedAt == nil {
			pv = "（从没被用过）"
		}
		fmt.Printf("      %s %s gen=%d %s %s %s\n", pad(r.ChainID, 14), r.ID, r.Gen, st, r.Device, pv)
	}
}

func resetAll() {
	rows = nil
	audit = nil
	seq = 0
	now = base
	users = map[string]*User{}
}

func main() {
	fmt.Println("=== 1. 「登出」其实有五种，它们的范围完全不同 ----------")
	kinds := []struct {
		api, scope, sql string
	}{
		{"POST /api/homeos/auth/logout",
			"登出当前设备",
			"UPDATE ... WHERE token_hash = ? AND revoked_at IS NULL"},
		{"POST /api/homeos/auth/logout-all",
			"登出全部设备",
			"UPDATE ... WHERE user_id = ? AND revoked_at IS NULL"},
		{"POST /api/homeos/auth/password",
			"改密码（必须连带全链失效）",
			"UPDATE homeos_user SET password_hash=?, pwd_changed_at=now()\n  + UPDATE ... WHERE user_id = ? AND revoked_at IS NULL"},
		{"PUT /api/homeos/members/{id}/role",
			"成员角色变更（S5）",
			"pver+1，**不**动 refresh（权限变化由 pver 管）"},
		{"DELETE /api/homeos/members/{id}",
			"移除成员（PRD 3.7 L413：其令牌即刻失效）",
			"同 logout-all，另加审计"},
	}
	for _, k := range kinds {
		fmt.Printf("  ▸ %s\n", k.api)
		fmt.Printf("      范围：%s\n", k.scope)
		fmt.Printf("      动作：%s\n", k.sql)
	}
	fmt.Println()
	fmt.Println("  最容易搞混的是第 4 条：**角色变更不吊销 refresh**。")
	fmt.Println("  因为角色是 token 里的快照 + pver 比对来管的（W16 d23），")
	fmt.Println("  吊销 refresh 会把用户踢下线，而降权只需要他下次请求就少权限。")
	fmt.Println("  这与「踢下线」是完全不同的两个诉求。")

	fmt.Println("\n=== 2. 场景一：单设备登出（最常见）----------")
	resetAll()
	u := seedUser("u-001")
	phonePlain, phoneRow := mint(u, "chain-phone", "", 1, "iPhone/17.1")
	tick(15 * time.Minute)
	np, nr, _, _ := Rotate(phonePlain, "203.0.113.7")
	fmt.Printf("  [%s] iPhone 登录 → %s，然后正常刷新到 %s\n", hhmm(now), phoneRow.ID, nr.ID)
	fmt.Printf("         用户在 iPhone 上点「退出登录」，提交的是 %s\n", np)
	n := revokeWhere(func(r *Row) bool { return r.TokenHash == hashOf(np) }, "logout")
	fmt.Printf("  [%s] 执行：UPDATE WHERE token_hash = '%s...'\n", hhmm(now), hashOf(np)[:12])
	fmt.Printf("         → 影响 %d 行\n", n)
	printRows("u-001")
	fmt.Println()
	fmt.Println("  只有一枚被吊销。这就是「登出当前设备」。")
	fmt.Println("  注意手机上的 access **不会**立刻失效 —— 它还有最多 15 分钟。")
	fmt.Println("  用户如果只想立刻断开，应该调 logout-all 或者把 access TTL 调短。")
	fmt.Println("  本项目选 15 分钟是权衡结果：更短会让 refresh 请求过于频繁。")

	fmt.Println("\n=== 3. 场景二：登出全部设备 ----------")
	resetAll()
	u = seedUser("u-001")
	seedUser("u-002")
	p1, _ := mint(u, "chain-phone", "", 1, "iPhone/17.1")
	tick(15 * time.Minute)
	cur, _, _, _ := Rotate(p1, "203.0.113.7")
	tick(15 * time.Minute)
	_, _, _, _ = Rotate(cur, "203.0.113.7")
	mint(u, "chain-ipad", "", 1, "iPad/17.1")
	mint(users["u-002"], "chain-other", "", 1, "Pixel/9")
	fmt.Println("  布置：u-001 有两台设备各一条链，u-002 有一条链")
	printRows("u-001")
	fmt.Println()
	fmt.Printf("  执行 logout-all：UPDATE ... WHERE user_id = 'u-001' AND revoked_at IS NULL\n")
	n = revokeWhere(func(r *Row) bool { return r.UserID == "u-001" }, "logout_all")
	fmt.Printf("  → 影响 %d 行\n", n)
	printRows("u-001")
	fmt.Printf("\n  u-002 剩余有效 refresh：%d 条（SQL 里带了 user_id 条件，没被误伤）\n", activeCount("u-002"))

	fmt.Println("\n=== 4. 场景三：改密码 —— 为什么必须全链失效 ----------")
	resetAll()
	u = seedUser("u-001")
	pwPlain, _ := mint(u, "chain-phone", "", 1, "iPhone/17.1")
	tick(15 * time.Minute)
	_, _, _, _ = Rotate(pwPlain, "203.0.113.7")
	tick(2 * time.Minute)
	pw2, _ := mint(u, "chain-ipad", "", 1, "iPad/17.1")
	fmt.Println("  布置：")
	fmt.Println("    iPhone 在地铁上（用户本人）")
	fmt.Println("    iPad 落在出租车上（攻击者已拿到）")
	fmt.Println()
	printRows("u-001")
	fmt.Println()
	tick(3 * time.Minute) // 用户花了几分钟才改完
	fmt.Printf("  [%s] 用户在手机上改密码（因为怀疑 iPad 丢了）\n", hhmm(now))
	// 改密：两条都发生在同一事务里
	users["u-001"].PwdChanged = now
	users["u-001"].Version++
	n = revokeWhere(func(r *Row) bool { return r.UserID == "u-001" }, "pwd_changed")
	audit = append(audit, fmt.Sprintf("[%s] AUDIT password_changed uid=u-001 revoked=%d",
		hhmm(now), n))
	fmt.Printf("         pwd_changed_at = %s, version = %d\n",
		users["u-001"].PwdChanged.Format("15:04"), users["u-001"].Version)
	fmt.Printf("         UPDATE refresh SET revoked_at = now(), revoke_why = 'pwd_changed'\n")
	fmt.Printf("         → 影响 %d 行\n", n)
	printRows("u-001")
	fmt.Println()
	tick(time.Minute)
	fmt.Printf("  用户改密发生在 %s，iPad 那枚签发于 %s（**早于**改密 %d 分钟）\n",
		users["u-001"].PwdChanged.Format("15:04"), find(pw2).IssuedAt.Format("15:04"),
		int(users["u-001"].PwdChanged.Sub(find(pw2).IssuedAt).Minutes()))
	fmt.Println()
	fmt.Println("  现在攻击者在 iPad 上刷新：")
	_, _, _, err := Rotate(pw2, "45.33.32.156")
	fmt.Printf("    [%s] → %v\n", hhmm(now), err)
	fmt.Println("    攻击者被挡住了。走的是第 ④ 道检查（revoked_at 非空）。")
	fmt.Println()
	fmt.Println("  但假设上面那条 UPDATE 漏执行了（代码 bug / 事务没提交 / 人为漏写）。")
	fmt.Println("  我们手动把 iPad 那枚的 revoked_at 清掉，只剩第 ② 道防线：")
	for _, r := range rows {
		if r.ID == "rt-000003" {
			r.RevokedAt = nil
			r.RevokeWhy = ""
		}
	}
	_, _, _, err = Rotate(pw2, "45.33.32.156")
	fmt.Printf("    [%s] → %v\n", hhmm(now), err)
	fmt.Println("    仍然被挡住 —— 这次走的是第 ② 道检查（第 ① 步之前）：")
	fmt.Println("    token 的 issued_at 早于用户的 pwd_changed_at。")
	fmt.Println()
	fmt.Println("  ⚠ 但「UPDATE 撤销」这一条**不是必须的**。")
	fmt.Println("    真正兜底的是 ① 这一列：pwd_changed_at。")
	fmt.Println("    即使某条 refresh 漏撤销了（写漏了、事务没提交、")
	fmt.Println("    或者这条链是在改密**之后**才被人新建的），")
	fmt.Println("    只要 token 的 issued_at 早于 pwd_changed_at，就一定被拒。")
	fmt.Println()
	fmt.Println("  这是「两道独立的防线」，与 tech-plan 的多处做法一致：")
	fmt.Println("    · 金额用整数分 + CHECK 约束")
	fmt.Println("    · 游标分页 + 稳定排序键")
	fmt.Println("    · 密码 bcrypt + 强度规则 + 黑名单")
	fmt.Println("  任何一条被绕过，另一条还在。")

	fmt.Println("\n=== 5. 两种做法各自能防住什么 ----------")
	fmt.Printf("  %s %s %s\n", pad("场景", 26), pad("只靠 UPDATE 撤销", 22), "只靠 pwd_changed_at")
	cmp := []struct{ scene, upd, tsc string }{
		{"改密前签发的 refresh", "拒（已被 UPDATE 撤销）", "拒（iat < pwd_changed）"},
		{"改密后攻击者自建的链", "❌ 挡不住（那是新行）", "拒（iat < pwd_changed，因为它建在改密前）"},
		{"UPDATE 漏执行（代码 bug）", "❌ 挡不住", "拒（第二道防线）"},
		{"事务部分提交", "❌ 挡不住", "视情况"},
		{"用户只是登出（没改密）", "拒", "❌ 挡不住（pwd_changed 没变）"},
		{"管理员停用账号（没改密）", "靠 status 检查", "❌ 挡不住"},
	}
	for _, c := range cmp {
		fmt.Printf("  %s %s %s\n", pad(c.scene, 26), pad(c.upd, 22), c.tsc)
	}
	fmt.Println()
	fmt.Println("  结论：两者防的不是同一类问题，**都要有**。")
	fmt.Println("   · UPDATE 撤销：处理「登出」「停用」这类「用户主动/被动断开会话」")
	fmt.Println("   · pwd_changed_at：处理「凭据泄露」这类「旧凭证不能续命」")
	fmt.Println("  前者是状态，后者是不变量。tech-plan 10.3 的架构红线之所以成立，")
	fmt.Println("  就是因为它列的每一条都要求这种双份表达。")

	fmt.Println("\n=== 6. 完整流程：改密码（真项目的 POST /api/homeos/auth/password） ----------")
	flow := []string{
		"① 验身份：需要 access token + **旧密码**（改密码必须验旧密码，否则 CSRF）",
		"② 验新密码：走 d05 的四条强度规则",
		"③ 算 bcrypt（这一步 100ms，正好给攻击者制造等待）",
		"④ **同一事务**里做三件事：",
		"     UPDATE homeos_user SET password_hash=?, pwd_changed_at=now(), version=version+1 WHERE id=?",
		"     UPDATE homeos_refresh_token SET revoked_at=now(), revoke_why='pwd_changed'",
		"       WHERE user_id=? AND revoked_at IS NULL",
		"     INSERT homeos_audit_log (...)   -- PRD 21.5：登录类审计",
		"⑤ 落一条事件 homeos.user.password_changed（供三个服务失效本地缓存）",
		"⑥ 签发**一对新 token** 返回 —— 否则用户改完密码立刻被踢出，很糟",
		"⑦ 前端替换本地 token。**旧 access 最多还有 15 分钟**，这点要告诉用户",
	}
	for _, s := range flow {
		fmt.Printf("  %s\n", s)
	}
	fmt.Println()
	fmt.Println("  第 ⑥ 步是体验与安全的一个平衡点。另一种做法是不发新 token，")
	fmt.Println("  强制用户用新密码重新登录一遍 —— 更安全，但用户刚改完密码")
	fmt.Println("  又要输一遍，直觉上很差。业界主流（OAuth 2.0 Security BCP）")
	fmt.Println("  是：换密时吊销所有既有会话，然后为**当前设备**签发新会话。")
	fmt.Println("  本项目采用这个。")

	fmt.Println("\n=== 7. 一个容易漏的边界：改邮箱/改手机号 ----------")
	fmt.Println("  如果将来加「改手机号」功能（PRD 3.7 有 /members/{id} 但不含改自己手机号），")
	fmt.Println("  那么改手机号**也必须**更新 pwd_changed_at 或另设 pchanged_at。")
	fmt.Println("  理由：手机号是验证码登录的主凭证，改了它意味着")
	fmt.Println("  「能拿到我验证码的人」变了 —— 那也是一次凭据变更。")
	fmt.Println("  通用说法：**任何改变「谁能证明你是我」的变更，都要断链。**")

	fmt.Println("\n=== 8. 与 JS 的对照 ----------")
	fmt.Println("  ① 前端改密码后拿到新 token，但要处理「旧 access 还在用」：")
	fmt.Println("     请求层的 in-flight 请求仍带旧 access，它们会成功到 15 分钟之后。")
	fmt.Println("     所以前端要**立刻**替换 token，并且不在 401 时盲目刷新 ——")
	fmt.Println("     否则它会用已失效的 refresh 去换，换不到，然后弹回登录页。")
	fmt.Println("     正确做法：改密成功后设一个标记「刚从改密页来」，")
	fmt.Println("     该标记存在时 401 直接跳登录，不走刷新。")
	fmt.Println("  ② Go 里同事务的三条语句：")
	fmt.Println("     err := db.Transaction(func(tx *gorm.DB) error { ... })")
	fmt.Println("     GORM 会在返回 error 时自动 rollback。")
	fmt.Println("     Node 里要手写 BEGIN/COMMIT/ROLLBACK，忘了 rollback 就是长事务泄漏。")
	fmt.Println("  ③ 时间比较：Go 里 a.After(b) / a.Before(b)；")
	fmt.Println("     JS 里 a > b（Date 对象可以直接比大小）。")
	fmt.Println("     Go 的 time.Time 比较有个坑：不同 Location 的时间直接比是按绝对时刻，")
	fmt.Println("     但如果你把 Unix() 摘出来比就是整数比较 —— 两种都正确，别混着用。")
	fmt.Println("     本程序全程用 time.Time，统一且安全。")

	fmt.Println("\n=== S4 d17 到此结束 ===")
	fmt.Println("明天 W15 收口：把整条双 token 流程串起来跑一遍，并做阶段自查。")
}

// pad 按显示宽度左对齐补空格（中文占 2 列）

func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

