package main

// =====================================================================
// S4 · W15 · d18：完整双 token 流程 + W15 阶段自查
//
// 今天不学新东西。产出：
//   ① 一个可运行的完整会话管理器（签发 / 轮换 / 撤销 / 改密）
//   ② W15 判据自测（S4 判据第 2、3 条在这里第一次被真正断言）
//
// 注意：本程序用一个 side map 保存「明文 token → 行 id」，
// 因为真实系统里服务端**不保存明文**（d14）。这个 map 只是为了让
// 演示代码能自己发起后续请求，等价于「客户端手里拿着 token」。
// =====================================================================

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"
)

// ---------- 假时钟 ----------

var now = time.Date(2026, 10, 15, 21, 0, 0, 0, time.UTC)

func tick(d time.Duration) time.Time { now = now.Add(d); return now }
func hhmm(t time.Time) string        { return t.Format("15:04") }

// ---------- 错误（对应 tech-plan §6.2 的错误码段） ----------

var (
	ErrExpired    = errors.New("1001 token expired")
	ErrNoToken    = errors.New("1002 refresh token invalid")
	ErrBadSig     = errors.New("1002 token signature invalid")
	ErrBadType    = errors.New("1003 token type mismatch")
	ErrRevoked    = errors.New("1004 refresh token revoked")
	ErrNotActive  = errors.New("1005 user account not active")
	ErrStaleToken = errors.New("1002 refresh issued before password change")
)

// ---------- JWT ----------

var jwtSecret = []byte("env:HOMEOS_JWT_SECRET 至少 32 字节，生产环境注入")

const b64a = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"

func b64enc(b []byte) string {
	var sb strings.Builder
	for i := 0; i < len(b); i += 3 {
		var c [3]byte
		n := copy(c[:], b[i:])
		v := uint32(c[0])<<16 | uint32(c[1])<<8 | uint32(c[2])
		sb.WriteByte(b64a[v>>18&63])
		sb.WriteByte(b64a[v>>12&63])
		if n > 1 {
			sb.WriteByte(b64a[v>>6&63])
		} else {
			sb.WriteByte('=')
		}
		if n > 2 {
			sb.WriteByte(b64a[v&63])
		} else {
			sb.WriteByte('=')
		}
	}
	return sb.String()
}

func b64dec(s string) []byte {
	idx := func(c byte) int {
		if c == '=' {
			return -1
		}
		return strings.IndexByte(b64a, c)
	}
	var out []byte
	for i := 0; i+3 < len(s); i += 4 {
		a, b, c, d := idx(s[i]), idx(s[i+1]), idx(s[i+2]), idx(s[i+3])
		v := uint32(a)<<18 | uint32(b)<<12
		if c >= 0 {
			v |= uint32(c) << 6
		}
		if d >= 0 {
			v |= uint32(d)
		}
		out = append(out, byte(v>>16))
		if c >= 0 {
			out = append(out, byte(v>>8))
		}
		if d >= 0 {
			out = append(out, byte(v))
		}
	}
	return out
}

func sigOf(signing string) string {
	m := hmac.New(sha256.New, jwtSecret)
	m.Write([]byte(signing))
	return b64enc(m.Sum(nil))
}

// Claims 与 tech-plan §8.5 一一对应。
type Claims struct {
	UID  string `json:"uid"`
	MID  string `json:"mid"`
	Fam  string `json:"fam"`
	Role string `json:"role"`
	PVer int    `json:"pver"`
	Typ  string `json:"typ"`
	IAT  int64  `json:"iat"`
	EXP  int64  `json:"exp"`
	JTI  string `json:"jti"`
}

func signToken(c Claims) string {
	hb, _ := json.Marshal(map[string]string{"alg": "HS256", "typ": "JWT"})
	pb, _ := json.Marshal(c)
	signing := b64enc(hb) + "." + b64enc(pb)
	return signing + "." + sigOf(signing)
}

func parseToken(tok string) (*Claims, error) {
	p := strings.Split(tok, ".")
	if len(p) != 3 {
		return nil, ErrBadSig
	}
	if !hmac.Equal([]byte(p[2]), []byte(sigOf(p[0]+"."+p[1]))) {
		return nil, ErrBadSig
	}
	var c Claims
	if err := json.Unmarshal(b64dec(p[1]), &c); err != nil {
		return nil, fmt.Errorf("%w: bad payload", ErrBadSig)
	}
	return &c, nil
}

// VerifyAccess 就是 W16 d20 中间件里的那个函数。
func VerifyAccess(tok string) (*Claims, error) {
	c, err := parseToken(tok)
	if err != nil {
		return nil, err
	}
	if c.Typ != "access" {
		return nil, fmt.Errorf("%w: %q", ErrBadType, c.Typ)
	}
	if now.Unix() > c.EXP+5 {
		return nil, fmt.Errorf("%w: exp=%d now=%d", ErrExpired, c.EXP, now.Unix())
	}
	return c, nil
}

// ---------- 存储 ----------

var pepper = []byte("env:HOMEOS_TOKEN_PEPPER")

type User struct {
	ID         string
	Status     string
	PwdChanged time.Time
	Version    int
}

type Row struct {
	ID        string
	UserID    string
	ChainID   string
	Gen       int
	ParentID  string
	TokenHash string
	IssuedAt  time.Time
	UsedAt    *time.Time
	RevokedAt *time.Time
	RevokeWhy string
	Device    string
	IP        string
	UsedByIP  string // 首次被用来换新的来源 IP（d16 的辅助信号）
}

var (
	users    = map[string]*User{}
	rows     = []*Row{}
	auditLog []string
	seq      int

	// plaintext 等价于「客户端手里拿着的 token」。服务端**没有**它。
	// 仅为了让演示代码能自己发起后续请求。
	plaintext = map[string]string{}
)

func hashOf(t string) string {
	m := hmac.New(sha256.New, pepper)
	m.Write([]byte(t))
	return hex.EncodeToString(m.Sum(nil))
}

func findRow(plain string) *Row {
	h := hashOf(plain)
	for _, r := range rows {
		if hmac.Equal([]byte(r.TokenHash), []byte(h)) {
			return r
		}
	}
	return nil
}

func childOf(old *Row) *Row {
	for _, r := range rows {
		if r.ParentID == old.ID {
			return r
		}
	}
	return nil
}

func plainOf(r *Row) string {
	for p, id := range plaintext {
		if id == r.ID {
			return p
		}
	}
	return ""
}

// mintRow 插入一行并返回它的**明文**（真实系统里这个明文只返回给客户端）。
func mintRow(parent *Row, device, ip string) (string, *Row) {
	seq++
	plain := fmt.Sprintf("rt_%s_%06d", parent.UserID, seq)
	r := &Row{
		ID:        fmt.Sprintf("rt-%06d", seq),
		UserID:    parent.UserID,
		ChainID:   parent.ChainID,
		Gen:       parent.Gen + 1,
		ParentID:  parent.ID,
		TokenHash: hashOf(plain),
		IssuedAt:  now,
		Device:    device,
		IP:        ip,
	}
	rows = append(rows, r)
	plaintext[plain] = r.ID
	return plain, r
}

type Pair struct {
	Access    string
	Refresh   string
	AccessJTI string
	RefreshID string
}

// IssuePair 是登录 / 注册成功后的标准签发入口。
func IssuePair(u *User, pver int, device, ip string) Pair {
	seq++
	chainID := fmt.Sprintf("chain-%s-%d", u.ID, seq)
	plain := fmt.Sprintf("rt_%s_%06d", u.ID, seq)
	r := &Row{
		ID: fmt.Sprintf("rt-%06d", seq), UserID: u.ID, ChainID: chainID, Gen: 1,
		TokenHash: hashOf(plain), IssuedAt: now, Device: device, IP: ip,
	}
	rows = append(rows, r)
	plaintext[plain] = r.ID
	return pairFor(u, pver, plain, r)
}

// pairFor 由一枚 refresh 行造出对应的 access + refresh。
func pairFor(u *User, pver int, refreshPlain string, r *Row) Pair {
	suffix := strings.TrimPrefix(u.ID, "u-")
	ac := Claims{
		UID: u.ID, MID: "m-" + suffix, Fam: "fam-" + suffix, Role: "owner",
		PVer: pver, Typ: "access", IAT: now.Unix(), EXP: now.Unix() + 15*60,
		JTI: r.ID + "-a",
	}
	return Pair{
		Access: signToken(ac), Refresh: refreshPlain,
		AccessJTI: ac.JTI, RefreshID: r.ID,
	}
}

// Rotate 是 POST /api/homeos/auth/refresh 的完整实现。
func Rotate(tok, ip string) (Pair, error) {
	r := findRow(tok)
	if r == nil {
		return Pair{}, ErrNoToken
	}
	u := users[r.UserID]
	if u == nil {
		return Pair{}, fmt.Errorf("%w: no such user", ErrNotActive)
	}
	if u.Status != "active" {
		return Pair{}, fmt.Errorf("%w: status=%s", ErrNotActive, u.Status)
	}
	if u.PwdChanged.After(r.IssuedAt) {
		return Pair{}, fmt.Errorf("%w: pwd_changed=%s issued=%s",
			ErrStaleToken, u.PwdChanged.Format("15:04"), r.IssuedAt.Format("15:04"))
	}
	if r.UsedAt != nil {
		// 幂等：**同一 IP** 的并发重试，返回已存在的子代。
		// IP 只是一个**辅助**信号 —— 主判据仍然是 UsedAt 非空。
		if r.UsedByIP == ip {
			c := childOf(r)
			if c != nil && c.RevokedAt == nil && c.UsedAt == nil {
				return pairFor(u, 7, plainOf(c), c), nil
			}
		}
		// 不同来源的第二次使用 = 重放 → 整链吊销
		v := now
		n := 0
		for _, x := range rows {
			if x.ChainID == r.ChainID && x.RevokedAt == nil {
				x.RevokedAt, x.RevokeWhy = &v, "replay_detected"
				n++
			}
		}
		auditLog = append(auditLog,
			fmt.Sprintf("replay_detected uid=%s chain=%s gen=%d ip=%s revoked=%d",
				r.UserID, r.ChainID, r.Gen, ip, n))
		return Pair{}, fmt.Errorf("%w: chain=%s revoked=%d", ErrNoToken, r.ChainID, n)
	}
	if r.RevokedAt != nil {
		return Pair{}, fmt.Errorf("%w: %s", ErrRevoked, r.RevokeWhy)
	}
	v := now
	r.UsedAt, r.RevokedAt, r.RevokeWhy, r.UsedByIP = &v, &v, "rotated", ip
	np, nr := mintRow(r, r.Device, ip)
	return pairFor(u, 7, np, nr), nil
}

func revokeWhere(where func(*Row) bool, why string) int {
	v := now
	n := 0
	for _, r := range rows {
		if r.RevokedAt == nil && where(r) {
			r.RevokedAt, r.RevokeWhy = &v, why
			n++
		}
	}
	return n
}

func countActive(uid string) int {
	n := 0
	for _, r := range rows {
		if r.UserID == uid && r.RevokedAt == nil && r.UsedAt == nil {
			n++
		}
	}
	return n
}

func ChangePassword(uid string) int {
	u := users[uid]
	u.PwdChanged = now
	u.Version++
	n := revokeWhere(func(r *Row) bool { return r.UserID == uid }, "pwd_changed")
	auditLog = append(auditLog,
		fmt.Sprintf("password_changed uid=%s revoked=%d version=%d", uid, n, u.Version))
	return n
}

func resetAll() {
	users = map[string]*User{
		"u-001": {ID: "u-001", Status: "active", PwdChanged: now, Version: 1},
		"u-002": {ID: "u-002", Status: "active", PwdChanged: now, Version: 1},
	}
	rows = nil
	auditLog = nil
	plaintext = map[string]string{}
	seq = 0
}

