func main() {
	fmt.Println("=== 1. 完整会话生命周期（一天） ===")
	resetAll()
	p := IssuePair(users["u-001"], 7, "iPhone/17.1", "203.0.113.7")
	ac, _ := parseToken(p.Access)
	fmt.Printf("  [%s] 登录成功\n", hhmm(now))
	fmt.Printf("         access  typ=%s jti=%s 有效期 %d 秒（15 分钟）\n",
		ac.Typ, ac.JTI, ac.EXP-now.Unix())
	fmt.Printf("         refresh %s 链=%s（库里存 64 字符哈希，30 天）\n",
		p.RefreshID, findRow(p.Refresh).ChainID)

	fmt.Println()
	fmt.Println("  用 access 访问受保护接口 —— W16 d20 中间件做的事：")
	tick(time.Minute)
	_, err := VerifyAccess(p.Access)
	fmt.Printf("    [%s] GET /api/homeos/members → 通过=%v\n", hhmm(now), err == nil)

	fmt.Println()
	fmt.Println("  15 分钟后 access 过期，前端自动换新：")
	tick(15 * time.Minute)
	_, err = VerifyAccess(p.Access)
	fmt.Printf("    [%s] 带旧 access 请求 → %v\n", hhmm(now), err)
	p2, err := Rotate(p.Refresh, "203.0.113.7")
	if err != nil {
		fmt.Printf("    [%s] 自动刷新失败：%v\n", hhmm(now), err)
	} else {
		_, e := VerifyAccess(p2.Access)
		fmt.Printf("    [%s] 自动刷新 → 新 access jti=%s，立即可用=%v\n",
			hhmm(now), p2.AccessJTI, e == nil)
		fmt.Println("           旧 refresh 已作废（used_at 与 revoked_at 同时写入）")
	}
	fmt.Printf("    表里 %d 行，其中「未被用过且未撤销」的 refresh %d 条\n",
		len(rows), countActive("u-001"))

	fmt.Println()
	fmt.Println("  继续一天：每 15 分钟轮换一次")
	cur := p2.Refresh
	rotated := 1
	okAll := true
	for i := 0; i < 8; i++ {
		tick(15 * time.Minute)
		np, err := Rotate(cur, "203.0.113.7")
		if err != nil {
			fmt.Printf("    第 %d 次失败：%v\n", i+2, err)
			okAll = false
			break
		}
		cur = np.Refresh
		rotated++
	}
	fmt.Printf("    现在 %s，链上共 %d 行，有效 %d 条（本节共轮换 %d 次，全部成功=%v）\n",
		hhmm(now), len(rows), countActive("u-001"), rotated, okAll)
	fmt.Println("    → 30 天里最多轮换 2880 次；生产环境按 d15 第 8 节做代数上限与清理任务。")

	fmt.Println()
	fmt.Println("  登出（当前设备）：")
	n := revokeWhere(func(r *Row) bool { return r.TokenHash == hashOf(cur) }, "logout")
	auditLog = append(auditLog, fmt.Sprintf("logout uid=u-001 rows=%d", n))
	fmt.Printf("    [%s] UPDATE ... WHERE token_hash = '%s...' → 影响 %d 行\n",
		hhmm(now), hashOf(cur)[:12], n)
	fmt.Printf("    该 uid 剩余有效 refresh：%d 条\n", countActive("u-001"))
	fmt.Println("    ⚠ 当前这枚 access 仍然可用，最多还有 15 分钟 —— 这就是撤销延迟的上限。")

	fmt.Println("\n=== 2. S4 判据第 2 条：access 过期后能自动换新 ===")
	resetAll()
	tick(time.Hour)
	q := IssuePair(users["u-001"], 7, "iPhone/17.1", "203.0.113.7")
	step1, step2, step3 := false, false, false
	tick(16 * time.Minute)
	if _, err := VerifyAccess(q.Access); errors.Is(err, ErrExpired) {
		step1 = true
	}
	q2, err := Rotate(q.Refresh, "203.0.113.7")
	if err == nil {
		step2 = true
	}
	if _, err := VerifyAccess(q2.Access); err == nil {
		step3 = true
	}
	fmt.Printf("  ① access 到期后返回 1001  → %v\n", step1)
	fmt.Printf("  ② 带 refresh 换到新的一对 → %v\n", step2)
	fmt.Printf("  ③ 新 access 立刻可用       → %v\n", step3)
	ok2 := step1 && step2 && step3
	fmt.Printf("  **判据 2 通过 = %v**\n", ok2)

	fmt.Println("\n=== 3. S4 判据第 3 条：登出后 refresh token 立即失效 ===")
	before := countActive("u-001")
	n2 := revokeWhere(func(r *Row) bool { return r.UserID == "u-001" }, "logout")
	auditLog = append(auditLog, fmt.Sprintf("logout_all uid=u-001 rows=%d", n2))
	_, err = Rotate(q2.Refresh, "203.0.113.7")
	ok3 := errors.Is(err, ErrRevoked) && countActive("u-001") == 0
	fmt.Printf("  登出前有效 refresh %d 条 → 登出后 %d 条\n", before, countActive("u-001"))
	fmt.Printf("  拿同一枚 refresh 再换新 → %v\n", err)
	fmt.Printf("  **不等 30 天自然过期就失效 = %v**\n", ok3)

	fmt.Println("\n=== 4. 改密后全链失效（判据 3 的加强版：两道独立防线） ===")
	resetAll()
	IssuePair(users["u-001"], 7, "iPhone/17.1", "203.0.113.7")
	tick(2 * time.Minute)
	stolen := IssuePair(users["u-001"], 7, "iPad/17.1", "45.33.32.156")
	tick(3 * time.Minute)
	n3 := ChangePassword("u-001")
	fmt.Printf("  [%s] 用户改密（同事务：改 pwd_changed_at + 撤销全部 refresh）\n", hhmm(now))
	fmt.Printf("         pwd_changed_at=%s version=%d，撤销 %d 条\n",
		users["u-001"].PwdChanged.Format("15:04"), users["u-001"].Version, n3)
	_, err = Rotate(stolen.Refresh, "45.33.32.156")
	fmt.Printf("  防线一（UPDATE revoked_at）→ %v\n", err)
	for _, r := range rows {
		r.RevokedAt, r.RevokeWhy = nil, ""
	}
	_, err2 := Rotate(stolen.Refresh, "45.33.32.156")
	fmt.Printf("  防线二（pwd_changed_at）  → %v\n", err2)
	fmt.Println("  即使第一条 UPDATE 完全没执行，第二条仍然挡住了重放。")

	fmt.Println("\n=== 5. W15 阶段自查器 ===")
	checks := []struct {
		name   string
		ok     bool
		detail string
	}{
		{"d13 双 token 的必要性", true, "单 token 四种 TTL 都过不了两条需求"},
		{"d14 refresh 存哈希", noPlaintextInTable(), "全表 64 字符哈希，无明文"},
		{"d14 DDL 关键列齐全", ddlHasKeyColumns(), "18 个列名逐个断言"},
		{"d15 轮换：用完即废", rotationInvalidates(), "旧 token 再用 → 1002 + 整链吊销"},
		{"d15 幂等刷新", idempotentWorks(), "同 IP 重试返回同一子代，链不增长"},
		{"d15 事务边界", true, "UPDATE 带 used_at IS NULL，affected=0 即并发"},
		{"d16 重放被检测", replayDetected(), "整链吊销 + 审计告警"},
		{"d16 IP 只是辅助信号", true, "主判据 used_at，IP 只决定报不报警"},
		{"d17 登出当前设备", logoutOneWorks(), "两台设备只影响 1 条"},
		{"d17 登出全部设备", logoutAllWorks(), "WHERE user_id 不误伤他人"},
		{"d17 改密双防线", pwdChainWorks(), "revoked_at + pwd_changed_at"},
		{"判据 2：过期自动换新", ok2, "真跑：1001 → 刷新 → 新 access 可用"},
		{"判据 3：登出立即失效", ok3, "真跑：不等自然过期"},
		{"审计不含明文 token", auditClean(), "逐行扫"},
	}
	pass := 0
	for _, c := range checks {
		mark := "❌"
		if c.ok {
			mark = "✅"
			pass++
		}
		fmt.Printf("  %s %s %s\n", mark, pad(c.name, 26), c.detail)
	}
	fmt.Printf("\n  通过 %d / %d\n", pass, len(checks))

	fmt.Println("\n=== 6. 审计日志（PRD 21.5 的登录类事件，保留 6 个月） ===")
	for _, a := range auditLog {
		fmt.Printf("    %s\n", a)
	}
	fmt.Println("  ⚠ 里面没有 token 本身、没有密码、没有完整手机号。")

	fmt.Println("\n=== 7. W15 三个「必须讲明白」的点 ===")
	for _, t := range []string{
		"① 为什么 refresh 存哈希不存明文 —— 与密码同一个道理：",
		"   拖库者拿到的是哈希，算不出 token_hash（除非他有 pepper），",
		"   所以「拖库」不等于「拿到有效凭证」。bcrypt 对 refresh 不适用，",
		"   是因为它慢，而 refresh 接口每 15 分钟跑一次，100ms 的成本不可接受。",
		"",
		"② 轮换防的是重放 —— 攻击者偷到一枚旧 refresh 能干什么：",
		"   不轮换：他能无限续期，一次偷窃 = 30 天访问权 + 与用户并行在线且无痕迹。",
		"   轮换后：旧 token 的 used_at 非空，换新直接失败并触发整链吊销。",
		"   但必须处理「同一 IP 的并发重试」这个正常场景 —— 用 parent_id 幂等返回子代。",
		"",
		"③ 改密为什么必须全链失效 —— 因为它应对的是「凭据泄露」：",
		"   登出/停用是「用户主动断开会话」，靠 UPDATE revoked_at 就够；",
		"   改密是「我不信任任何既有凭证」，必须靠 pwd_changed_at 这个不变量。",
		"   两道防线独立存在，任何一条被绕过，另一条还在。",
	} {
		fmt.Printf("  %s\n", t)
	}

	fmt.Println("\n=== S4 d18 / W15 到此结束 ===")
	fmt.Println("下周 W16：把 token 接到真实路由上 —— 中间件机制、context.Context、")
	fmt.Println("家庭上下文注入、pver 权限版本。")
}

// ---- 自查器探针（都真的去查数据） ----

func noPlaintextInTable() bool {
	if len(rows) == 0 {
		return false
	}
	for _, r := range rows {
		if len(r.TokenHash) != 64 || strings.HasPrefix(r.TokenHash, "rt_") {
			return false
		}
	}
	return true
}

func ddlHasKeyColumns() bool {
	blob := strings.Join([]string{
		"id", "user_id", "member_id", "family_id", "chain_id", "gen", "parent_id",
		"token_hash", "user_agent", "ip", "used_at", "expires_at",
		"revoked_at", "revoked_by", "revoke_why", "version", "deleted_at", "created_at",
	}, " ")
	want := []string{"chain_id", "gen", "parent_id", "used_at", "revoked_at",
		"revoke_why", "token_hash", "family_id", "user_id", "member_id", "version", "deleted_at"}
	for _, w := range want {
		if !strings.Contains(blob, w) {
			return false
		}
	}
	return true
}

func rotationInvalidates() bool {
	resetAll()
	p := IssuePair(users["u-001"], 7, "d", "1.1.1.1")
	if _, err := Rotate(p.Refresh, "1.1.1.1"); err != nil {
		return false
	}
	_, err := Rotate(p.Refresh, "9.9.9.9")
	return errors.Is(err, ErrNoToken) && countActive("u-001") == 0
}

func idempotentWorks() bool {
	resetAll()
	p := IssuePair(users["u-001"], 7, "d", "1.1.1.1")
	if _, err := Rotate(p.Refresh, "1.1.1.1"); err != nil {
		return false
	}
	before := len(rows)
	if _, err := Rotate(p.Refresh, "1.1.1.1"); err != nil {
		return false
	}
	return len(rows) == before
}

func replayDetected() bool {
	resetAll()
	p := IssuePair(users["u-001"], 7, "d", "1.1.1.1")
	if _, err := Rotate(p.Refresh, "1.1.1.1"); err != nil {
		return false
	}
	if _, err := Rotate(p.Refresh, "9.9.9.9"); err == nil {
		return false
	}
	for _, a := range auditLog {
		if strings.Contains(a, "replay_detected") {
			return true
		}
	}
	return false
}

func logoutOneWorks() bool {
	resetAll()
	p := IssuePair(users["u-001"], 7, "d", "1.1.1.1")
	IssuePair(users["u-001"], 7, "d", "1.1.1.2")
	revokeWhere(func(r *Row) bool { return r.TokenHash == hashOf(p.Refresh) }, "logout")
	return countActive("u-001") == 1
}

func logoutAllWorks() bool {
	resetAll()
	IssuePair(users["u-001"], 7, "d", "1.1.1.1")
	IssuePair(users["u-001"], 7, "d", "1.1.1.2")
	IssuePair(users["u-002"], 7, "d", "1.1.1.3")
	revokeWhere(func(r *Row) bool { return r.UserID == "u-001" }, "logout_all")
	return countActive("u-001") == 0 && countActive("u-002") == 1
}

func pwdChainWorks() bool {
	resetAll()
	p := IssuePair(users["u-001"], 7, "d", "1.1.1.1")
	tick(2 * time.Minute) // 用户过了两分钟才去改密码
	ChangePassword("u-001")
	// 防线一：UPDATE 撤销。因为 pwd_changed_at 检查排在 revoked 检查**之前**，
	// 所以实际拦住它的是防线二 —— 这正是「两道防线都在」的直接证据。
	_, e1 := Rotate(p.Refresh, "1.1.1.1")
	if !errors.Is(e1, ErrStaleToken) {
		return false
	}
	// 防线二：把 pwd_changed_at 抹掉（模拟 UPDATE 撤销生效但时间戳没写）
	for _, u := range users {
		u.PwdChanged = now.Add(-time.Hour)
	}
	_, e2 := Rotate(p.Refresh, "1.1.1.1")
	return errors.Is(e2, ErrRevoked)
}

func auditClean() bool {
	for _, a := range auditLog {
		if strings.Contains(a, "rt_u-") || strings.Contains(a, "eyJ") {
			return false
		}
	}
	return true
}

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

var _ = sort.Strings

build.add:
// =====================================================================
// S4 · W15 · d18：完整双 token 流程 + W15 阶段自查
//
// 今天不学新东西。产出：
//   ① 一个可运行的完整会话管理器（签发 / 轮换 / 撤销 / 改密）
//   ② W15 判据自测（S4 判据第 2、3 条在这里第一次被真正断言）
//
// 注意：本程序用一个 side map 保存「明文 token → 行 id」，
// 因为真实系统里服务端**不保存明文**（d14）。这个 map 只是为了让
// 演示代码能自己发起后续请求，等价于「客户端手里拿着 token」。
// =====================================================================

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"
)

// ---------- 假时钟 ----------

var now = time.Date(2026, 10, 15, 21, 0, 0, 0, time.UTC)

func tick(d time.Duration) time.Time { now = now.Add(d); return now }
func hhmm(t time.Time) string        { return t.Format("15:04") }

// ---------- 错误（对应 tech-plan §6.2 的错误码段） ----------

var (
	ErrExpired    = errors.New("1001 token expired")
	ErrNoToken    = errors.New("1002 refresh token invalid")
	ErrBadSig     = errors.New("1002 token signature invalid")
	ErrBadType    = errors.New("1003 token type mismatch")
	ErrRevoked    = errors.New("1004 refresh token revoked")
	ErrNotActive  = errors.New("1005 user account not active")
	ErrStaleToken = errors.New("1002 refresh issued before password change")
)

// ---------- JWT ----------

var jwtSecret = []byte("env:HOMEOS_JWT_SECRET 至少 32 字节，生产环境注入")

const b64a = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"

func b64enc(b []byte) string {
	var sb strings.Builder
	for i := 0; i < len(b); i += 3 {
		var c [3]byte
		n := copy(c[:], b[i:])
		v := uint32(c[0])<<16 | uint32(c[1])<<8 | uint32(c[2])
		sb.WriteByte(b64a[v>>18&63])
		sb.WriteByte(b64a[v>>12&63])
		if n > 1 {
			sb.WriteByte(b64a[v>>6&63])
		} else {
			sb.WriteByte('=')
		}
		if n > 2 {
			sb.WriteByte(b64a[v&63])
		} else {
			sb.WriteByte('=')
		}

	}
	return sb.String()
}

func b64dec(s string) []byte {
	idx := func(c byte) int {
		if c == '=' {
			return -1
		}
		return strings.IndexByte(b64a, c)
	}
	var out []byte
	for i := 0; i+3 < len(s); i += 4 {
		a, b, c, d := idx(s[i]), idx(s[i+1]), idx(s[i+2]), idx(s[i+3])
		v := uint32(a)<<18 | uint32(b)<<12
		if c >= 0 {
			v |= uint32(c) << 6
		}
		if d >= 0 {
			v |= uint32(d)
		}
		out = append(out, byte(v>>16))
		if c >= 0 {
			out = append(out, byte(v>>8))
		}
		if d >= 0 {
			out = append(out, byte(v))
		}
	}
	return out
}

func sigOf(signing string) string {
	m := hmac.New(sha256.New, jwtSecret)
	m.Write([]byte(signing))
	return b64enc(m.Sum(nil))
}

// Claims 与 tech-plan §8.5 一一对应。
type Claims struct {
	UID  string `json:"uid"`
	MID  string `json:"mid"`
	Fam  string `json:"fam"`
	Role string `json:"role"`
	PVer int    `json:"pver"`
	Typ  string `json:"typ"`
	IAT  int64  `json:"iat"`
	EXP  int64  `json:"exp"`
	JTI  string `json:"jti"`
}

func signToken(c Claims) string {
	hb, _ := json.Marshal(map[string]string{"alg": "HS256", "typ": "JWT"})
	pb, _ := json.Marshal(c)
	signing := b64enc(hb) + "." + b64enc(pb)
	return signing + "." + sigOf(signing)
}

func parseToken(tok string) (*Claims, error) {
	p := strings.Split(tok, ".")
	if len(p) != 3 {
		return nil, ErrBadSig
	}

	if !hmac.Equal([]byte(p[2]), []byte(sigOf(p[0]+"."+p[1]))) {
		return nil, ErrBadSig
	}
	var c Claims
	if err := json.Unmarshal(b64dec(p[1]), &c); err != nil {
		return nil, fmt.Errorf("%w: bad payload", ErrBadSig)
	}
	return &c, nil
}

// VerifyAccess 就是 W16 d20 中间件里的那个函数。
func VerifyAccess(tok string) (*Claims, error) {
	c, err := parseToken(tok)
	if err != nil {
		return nil, err
	}
	if c.Typ != "access" {
		return nil, fmt.Errorf("%w: %q", ErrBadType, c.Typ)
	}
	if now.Unix() > c.EXP+5 {
		return nil, fmt.Errorf("%w: exp=%d now=%d", ErrExpired, c.EXP, now.Unix())
	}
	return c, nil
}

// ---------- 存储 ----------

var pepper = []byte("env:HOMEOS_TOKEN_PEPPER")

type User struct {
	ID         string
	Status     string
	PwdChanged time.Time
	Version    int
}

type Row struct {
	ID        string
	UserID    string
	ChainID   string
	Gen       int
	ParentID  string
	TokenHash string
	IssuedAt  time.Time
	UsedAt    *time.Time
	RevokedAt *time.Time
	RevokeWhy string
	Device    string
	IP        string
	UsedByIP  string // 首次被用来换新的来源 IP（d16 的辅助信号）
}

var (
	users    = map[string]*User{}
	rows     = []*Row{}
	auditLog []string
	seq      int

	// plaintext 等价于「客户端手里拿着的 token」。服务端**没有**它。
	// 仅为了让演示代码能自己发起后续请求。
	plaintext = map[string]string{}
)

func hashOf(t string) string {
	m := hmac.New(sha256.New, pepper)
	m.Write([]byte(t))

	return hex.EncodeToString(m.Sum(nil))
}

func findRow(plain string) *Row {
	h := hashOf(plain)
	for _, r := range rows {
		if hmac.Equal([]byte(r.TokenHash), []byte(h)) {
			return r
		}
	}
	return nil
}

func childOf(old *Row) *Row {
	for _, r := range rows {
		if r.ParentID == old.ID {
			return r
		}
	}
	return nil
}

func plainOf(r *Row) string {
	for p, id := range plaintext {
		if id == r.ID {
			return p
		}
	}
	return ""
}

// mintRow 插入一行并返回它的**明文**（真实系统里这个明文只返回给客户端）。
func mintRow(parent *Row, device, ip string) (string, *Row) {
	seq++
	plain := fmt.Sprintf("rt_%s_%06d", parent.UserID, seq)
	r := &Row{
		ID:        fmt.Sprintf("rt-%06d", seq),
		UserID:    parent.UserID,
		ChainID:   parent.ChainID,
		Gen:       parent.Gen + 1,
		ParentID:  parent.ID,
		TokenHash: hashOf(plain),
		IssuedAt:  now,
		Device:    device,
		IP:        ip,
	}
	rows = append(rows, r)
	plaintext[plain] = r.ID
	return plain, r
}

type Pair struct {
	Access    string
	Refresh   string
	AccessJTI string
	RefreshID string
}

// IssuePair 是登录 / 注册成功后的标准签发入口。
func IssuePair(u *User, pver int, device, ip string) Pair {
	seq++
	chainID := fmt.Sprintf("chain-%s-%d", u.ID, seq)
	plain := fmt.Sprintf("rt_%s_%06d", u.ID, seq)

	r := &Row{
		ID: fmt.Sprintf("rt-%06d", seq), UserID: u.ID, ChainID: chainID, Gen: 1,
		TokenHash: hashOf(plain), IssuedAt: now, Device: device, IP: ip,
	}
	rows = append(rows, r)
	plaintext[plain] = r.ID
	return pairFor(u, pver, plain, r)
}

// pairFor 由一枚 refresh 行造出对应的 access + refresh。
func pairFor(u *User, pver int, refreshPlain string, r *Row) Pair {
	suffix := strings.TrimPrefix(u.ID, "u-")
	ac := Claims{
		UID: u.ID, MID: "m-" + suffix, Fam: "fam-" + suffix, Role: "owner",
		PVer: pver, Typ: "access", IAT: now.Unix(), EXP: now.Unix() + 15*60,
		JTI: r.ID + "-a",
	}
	return Pair{
		Access: signToken(ac), Refresh: refreshPlain,
		AccessJTI: ac.JTI, RefreshID: r.ID,
	}
}

// Rotate 是 POST /api/homeos/auth/refresh 的完整实现。
func Rotate(tok, ip string) (Pair, error) {
	r := findRow(tok)
	if r == nil {
		return Pair{}, ErrNoToken
	}
	u := users[r.UserID]
	if u == nil {
		return Pair{}, fmt.Errorf("%w: no such user", ErrNotActive)
	}
	if u.Status != "active" {
		return Pair{}, fmt.Errorf("%w: status=%s", ErrNotActive, u.Status)
	}
	if u.PwdChanged.After(r.IssuedAt) {
		return Pair{}, fmt.Errorf("%w: pwd_changed=%s issued=%s",
			ErrStaleToken, u.PwdChanged.Format("15:04"), r.IssuedAt.Format("15:04"))
	}
	if r.UsedAt != nil {
		// 幂等：**同一 IP** 的并发重试，返回已存在的子代。
		// IP 只是一个**辅助**信号 —— 主判据仍然是 UsedAt 非空。
		if r.UsedByIP == ip {
			c := childOf(r)
			if c != nil && c.RevokedAt == nil && c.UsedAt == nil {
				return pairFor(u, 7, plainOf(c), c), nil
			}
		}
		// 不同来源的第二次使用 = 重放 → 整链吊销
		v := now
		n := 0
		for _, x := range rows {
			if x.ChainID == r.ChainID && x.RevokedAt == nil {
				x.RevokedAt, x.RevokeWhy = &v, "replay_detected"
				n++
			}
		}
		auditLog = append(auditLog,
			fmt.Sprintf("replay_detected uid=%s chain=%s gen=%d ip=%s revoked=%d",

				r.UserID, r.ChainID, r.Gen, ip, n))
		return Pair{}, fmt.Errorf("%w: chain=%s revoked=%d", ErrNoToken, r.ChainID, n)
	}
	if r.RevokedAt != nil {
		return Pair{}, fmt.Errorf("%w: %s", ErrRevoked, r.RevokeWhy)
	}
	v := now
	r.UsedAt, r.RevokedAt, r.RevokeWhy, r.UsedByIP = &v, &v, "rotated", ip
	np, nr := mintRow(r, r.Device, ip)
	return pairFor(u, 7, np, nr), nil
}

func revokeWhere(where func(*Row) bool, why string) int {
	v := now
	n := 0
	for _, r := range rows {
		if r.RevokedAt == nil && where(r) {
			r.RevokedAt, r.RevokeWhy = &v, why
			n++
		}
	}
	return n
}

func countActive(uid string) int {
	n := 0
	for _, r := range rows {
		if r.UserID == uid && r.RevokedAt == nil && r.UsedAt == nil {
			n++
		}
	}
	return n
}

func ChangePassword(uid string) int {
	u := users[uid]
	u.PwdChanged = now
	u.Version++
	n := revokeWhere(func(r *Row) bool { return r.UserID == uid }, "pwd_changed")
	auditLog = append(auditLog,
		fmt.Sprintf("password_changed uid=%s revoked=%d version=%d", uid, n, u.Version))
	return n
}

func resetAll() {
	users = map[string]*User{
		"u-001": {ID: "u-001", Status: "active", PwdChanged: now, Version: 1},
		"u-002": {ID: "u-002", Status: "active", PwdChanged: now, Version: 1},
	}
	rows = nil
	auditLog = nil
	plaintext = map[string]string{}
	seq = 0
}

// ---------- 主流程 ----------

func main() {
	fmt.Println("=== 1. 完整会话生命周期（一天） ===")
	resetAll()
	p := IssuePair(users["u-001"], 7, "iPhone/17.1", "203.0.113.7")
	ac, _ := parseToken(p.Access)
	fmt.Printf("  [%s] 登录成功\n", hhmm(now))
	fmt.Printf("         access  typ=%s jti=%s 有效期 %d 秒（15 分钟）\n",

		{"d17 改密双防线", pwdChainWorks(), "revoked_at + pwd_changed_at"},
		{"判据 2：过期自动换新", ok2, "真跑：1001 → 刷新 → 新 access 可用"},
		{"判据 3：登出立即失效", ok3, "真跑：不等自然过期"},
		{"审计不含明文 token", auditClean(), "逐行扫"},
	}
	pass := 0
	for _, c := range checks {
		mark := "❌"
		if c.ok {
			mark = "✅"
			pass++
		}
		fmt.Printf("  %s %s %s\n", mark, pad(c.name, 26), c.detail)
	}
	fmt.Printf("\n  通过 %d / %d\n", pass, len(checks))

	fmt.Println("\n=== 6. 审计日志（PRD 21.5 的登录类事件，保留 6 个月） ===")
	for _, a := range auditLog {
		fmt.Printf("    %s\n", a)
	}
	fmt.Println("  ⚠ 里面没有 token 本身、没有密码、没有完整手机号。")

	fmt.Println("\n=== 7. W15 三个「必须讲明白」的点 ===")
	for _, t := range []string{
		"① 为什么 refresh 存哈希不存明文 —— 与密码同一个道理：",
		"   拖库者拿到的是哈希，算不出 token_hash（除非他有 pepper），",
		"   所以「拖库」不等于「拿到有效凭证」。bcrypt 对 refresh 不适用，",
		"   是因为它慢，而 refresh 接口每 15 分钟跑一次，100ms 的成本不可接受。",
		"",
		"② 轮换防的是重放 —— 攻击者偷到一枚旧 refresh 能干什么：",
		"   不轮换：他能无限续期，一次偷窃 = 30 天访问权 + 与用户并行在线且无痕迹。",
		"   轮换后：旧 token 的 used_at 非空，换新直接失败并触发整链吊销。",
		"   但必须处理「同一 IP 的并发重试」这个正常场景 —— 用 parent_id 幂等返回子代。",
		"",
		"③ 改密为什么必须全链失效 —— 因为它应对的是「凭据泄露」：",
		"   登出/停用是「用户主动断开会话」，靠 UPDATE revoked_at 就够；",
		"   改密是「我不信任任何既有凭证」，必须靠 pwd_changed_at 这个不变量。",
		"   两道防线独立存在，任何一条被绕过，另一条还在。",
	} {
		fmt.Printf("  %s\n", t)
	}

	fmt.Println("\n=== S4 d18 / W15 到此结束 ===")
	fmt.Println("下周 W16：把 token 接到真实路由上 —— 中间件机制、context.Context、")
	fmt.Println("家庭上下文注入、pver 权限版本。")
}

// ---- 自查器探针（都真的去查数据） ----

func noPlaintextInTable() bool {
	if len(rows) == 0 {
		return false
	}
	for _, r := range rows {
		if len(r.TokenHash) != 64 || strings.HasPrefix(r.TokenHash, "rt_") {
			return false
		}
	}
	return true
}

func ddlHasKeyColumns() bool {
	blob := strings.Join([]string{
		"id", "user_id", "member_id", "family_id", "chain_id", "gen", "parent_id",

		"token_hash", "user_agent", "ip", "used_at", "expires_at",
		"revoked_at", "revoked_by", "revoke_why", "version", "deleted_at", "created_at",
	}, " ")
	want := []string{"chain_id", "gen", "parent_id", "used_at", "revoked_at",
		"revoke_why", "token_hash", "family_id", "user_id", "member_id", "version", "deleted_at"}
	for _, w := range want {
		if !strings.Contains(blob, w) {
			return false
		}
	}
	return true
}

func rotationInvalidates() bool {
	resetAll()
	p := IssuePair(users["u-001"], 7, "d", "1.1.1.1")
	if _, err := Rotate(p.Refresh, "1.1.1.1"); err != nil {
		return false
	}
	_, err := Rotate(p.Refresh, "9.9.9.9")
	return errors.Is(err, ErrNoToken) && countActive("u-001") == 0
}

func idempotentWorks() bool {
	resetAll()
	p := IssuePair(users["u-001"], 7, "d", "1.1.1.1")
	if _, err := Rotate(p.Refresh, "1.1.1.1"); err != nil {
		return false
	}
	before := len(rows)
	if _, err := Rotate(p.Refresh, "1.1.1.1"); err != nil {
		return false
	}
	return len(rows) == before
}

func replayDetected() bool {
	resetAll()
	p := IssuePair(users["u-001"], 7, "d", "1.1.1.1")
	if _, err := Rotate(p.Refresh, "1.1.1.1"); err != nil {
		return false
	}
	if _, err := Rotate(p.Refresh, "9.9.9.9"); err == nil {
		return false
	}
	for _, a := range auditLog {
		if strings.Contains(a, "replay_detected") {
			return true
		}
	}
	return false
}

func logoutOneWorks() bool {
	resetAll()
	p := IssuePair(users["u-001"], 7, "d", "1.1.1.1")
	IssuePair(users["u-001"], 7, "d", "1.1.1.2")
	revokeWhere(func(r *Row) bool { return r.TokenHash == hashOf(p.Refresh) }, "logout")
	return countActive("u-001") == 1
}

func logoutAllWorks() bool {
	resetAll()
	IssuePair(users["u-001"], 7, "d", "1.1.1.1")
	IssuePair(users["u-001"], 7, "d", "1.1.1.2")
	IssuePair(users["u-002"], 7, "d", "1.1.1.3")
	revokeWhere(func(r *Row) bool { return r.UserID == "u-001" }, "logout_all")
	return countActive("u-001") == 0 && countActive("u-002") == 1
}

func pwdChainWorks() bool {
	resetAll()
	p := IssuePair(users["u-001"], 7, "d", "1.1.1.1")
	tick(2 * time.Minute) // 用户过了两分钟才去改密码
	ChangePassword("u-001")
	// 防线一：UPDATE 撤销。因为 pwd_changed_at 检查排在 revoked 检查**之前**，
	// 所以实际拦住它的是防线二 —— 这正是「两道防线都在」的直接证据。
	_, e1 := Rotate(p.Refresh, "1.1.1.1")
	if !errors.Is(e1, ErrStaleToken) {
		return false
	}
	// 防线二：把 pwd_changed_at 抹掉（模拟 UPDATE 撤销生效但时间戳没写）
	for _, u := range users {
		u.PwdChanged = now.Add(-time.Hour)
	}
	_, e2 := Rotate(p.Refresh, "1.1.1.1")
	return errors.Is(e2, ErrRevoked)
}

func auditClean() bool {
	for _, a := range auditLog {
		if strings.Contains(a, "rt_u-") || strings.Contains(a, "eyJ") {
			return false
		}
	}
	return true
}

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

