package main

// =====================================================================
// S4 · W16 · d19：中间件机制与洋葱模型
//
//   Gin 中间件是什么 / 为什么是洋葱模型 / 与 JS 的对比
//
// 本程序用标准库 net/http 手写一个最小框架（35 行），
// 这样你能看清 Gin 的 engine.handleContext 在做什么。
// =====================================================================

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
)

// ---------- 一个最小 HTTP 框架（看清 Gin 的骨架） ----------

// Ctx 是我们自己的请求上下文，替代 Gin 的 *gin.Context。
type Ctx struct {
	W       http.ResponseWriter
	R       *http.Request
	keys    map[string]any
	status  int
	body    string
	aborted bool
}

func (c *Ctx) Set(k string, v any) { c.keys[k] = v }
func (c *Ctx) Get(k string) any    { return c.keys[k] }
func (c *Ctx) Abort(code int) {
	c.aborted = true
	c.status = code
}

// AbortJSON 一步完成「中止 + 写统一响应体」，对应 Gin 的 AbortWithStatusJSON。
func (c *Ctx) AbortJSON(code int, body string) {
	c.aborted = true
	c.status = code
	c.body = body
}

// HandlerFunc 是中间件类型。第二个参数 next 就是 c.Next()。
type HandlerFunc func(c *Ctx, next func())

// Chain 是一条中间件链。
type Chain struct {
	handlers []HandlerFunc
}

func (c *Chain) Use(h ...HandlerFunc) {
	c.handlers = append(c.handlers, h...)
}

func (c *Chain) Handle(final func(*Ctx)) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		ctx := &Ctx{W: w, R: r, keys: map[string]any{}, status: 200}
		// 洋葱的核心：**递归**。第 i 层中间件调用第 i+1 层，
		// 于是每个中间件里写在调用之后的代码（通常用 defer）
		// 会在**所有内层都返回之后**才执行 —— 这就是退出顺序反转的原因。
		c.handle(ctx, 0, final)
		w.WriteHeader(ctx.status)
		_, _ = w.Write([]byte(ctx.body))
	}
}

// handle 是真正的洋葱实现：从 index 开始依次往下跑。
func (ch *Chain) handle(ctx *Ctx, index int, final func(*Ctx)) {
	// 先跑「洋葱芯」：把剩余的中间件与 handler 全部跑完
	ch.core(ctx, index, final)
}

func (ch *Chain) core(ctx *Ctx, index int, final func(*Ctx)) {
	if index < len(ch.handlers) {
		ch.handlers[index](ctx, func() {
			ch.core(ctx, index+1, final)
		})
		return
	}
	final(ctx)
}

// ---------- Gin 风格的真实洋葱链（用 defer） ----------

// Trace 记录中间件的进入/退出顺序，用来展示洋葱模型。
var Trace []string

func Logger() HandlerFunc {
	return func(c *Ctx, next func()) {
		Trace = append(Trace, "Logger  进入")
		c.Set("req_id", "req-"+c.R.Header.Get("X-Request-Id"))
		next() // ← 等价于 c.Next()，不写它就不会往下走
		Trace = append(Trace, "Logger  退出")
	}
}

func Recovery() HandlerFunc {
	return func(c *Ctx, next func()) {
		Trace = append(Trace, "Recovery 进入")
		// 注意：defer 一定要写在 next() **之前**，
		// 这样 recover 才有机会兜住内层的 panic。
		defer func() {
			if r := recover(); r != nil {
				Trace = append(Trace, fmt.Sprintf("Recovery 捕获 panic: %v", r))
				c.status = 500
				c.body = `{"code":5000,"message":"internal error"}`
			}
			Trace = append(Trace, "Recovery 退出")
		}()
		next()
	}
}

func Auth() HandlerFunc {
	return func(c *Ctx, next func()) {
		Trace = append(Trace, "Auth     进入")
		defer func() { Trace = append(Trace, "Auth     退出") }()
		tok := c.R.Header.Get("Authorization")
		if !strings.HasPrefix(tok, "Bearer ") || len(tok) <= 7 {
			// Abort + return，**不调 next()** —— 后面全部不执行
			c.AbortJSON(401, `{"code":1005,"message":"missing or malformed Authorization header"}`)
			return
		}
		c.Set("uid", "u-001")
		next()
	}
}

func FamilyScope() HandlerFunc {
	return func(c *Ctx, next func()) {
		Trace = append(Trace, "Family   进入")
		defer func() { Trace = append(Trace, "Family   退出") }()
		// 如果这里查不到家庭，直接 404（不是 403，见 S5）
		if c.Get("uid") == nil {
			c.AbortJSON(404, `{"code":3001,"message":"no such family"}`)
			return
		}
		c.Set("fam", "fam-001")
		next()
	}
}

// handler 是最终处理函数。
func listMembers(c *Ctx) {
	Trace = append(Trace, "handler  执行")
	c.body = fmt.Sprintf(`{"code":0,"message":"ok","data":{"fam":"%v","req_id":"%v"}}`,
		c.Get("fam"), c.Get("req_id"))
}

func main() {
	fmt.Println("=== 1. 中间件是什么：一次请求经过的完整轨迹 ===")
	chain := &Chain{}
	chain.Use(Logger(), Recovery(), Auth(), FamilyScope())
	h := chain.Handle(listMembers)

	// 正常请求：四层全部进入 → handler → 四层全部退出
	Trace = nil
	req := httptest.NewRequest("GET", "/api/homeos/members", nil)
	req.Header.Set("X-Request-Id", "r-12345")
	req.Header.Set("Authorization", "Bearer eyJ...")
	rec := httptest.NewRecorder()
	h(rec, req)
	fmt.Println("  【正常请求 · 带合法 Authorization】")
	for i, t := range Trace {
		fmt.Printf("    %2d. %s\n", i+1, t)
	}
	fmt.Printf("    响应：%d %s\n", rec.Code, strings.TrimSpace(rec.Body.String()))
	fmt.Println("    ↑ 进入 4 层 → handler → 退出 4 层，**配对完整**。这就是递归带来的洋葱。")

	// 中止：Auth 判定失败，后面的层根本不执行
	fmt.Println()
	Trace = nil
	req2 := httptest.NewRequest("GET", "/api/homeos/members", nil)
	req2.Header.Set("X-Request-Id", "r-12345")
	rec2 := httptest.NewRecorder()
	h(rec2, req2)
	fmt.Println("  【未带 Authorization · 中止】")
	for i, t := range Trace {
		fmt.Printf("    %2d. %s\n", i+1, t)
	}
	fmt.Printf("    响应：%d %s\n", rec2.Code, strings.TrimSpace(rec2.Body.String()))
	fmt.Println("    ↑ Auth 的 defer 仍然执行了（所以「Auth 退出」在轨迹里），")
	fmt.Println("      但 Family 与 handler **一次都没被调用**。")

	fmt.Println("\n=== 2. 洋葱模型：为什么顺序是「进去 4 层，再出来 4 层」 ===")
	fmt.Println("  实际执行的先后（注意 Recovery 在 Auth 之前注册，却在 panic 时先响应）：")
	fmt.Println()
	fmt.Println("    Logger    进入     ← 注册顺序 1")
	fmt.Println("    Recovery  进入     ← 注册顺序 2")
	fmt.Println("    Auth      进入     ← 注册顺序 3")
	fmt.Println("    Family    进入     ← 注册顺序 4")
	fmt.Println("      handler  执行     ← 最内层")
	fmt.Println("    Family    退出     ← handler 返回后逆序")
	fmt.Println("    Auth      退出")
	fmt.Println("    Recovery  退出     ← 如果这里 defer 了 recover，能兜住上面所有 panic")
	fmt.Println("    Logger    退出     ← 最外层，最后写日志")
	fmt.Println()
	fmt.Println("  退出顺序与进入顺序**相反**，这就是「洋葱」。")
	fmt.Println("  它不是审美，是三个刚需：")

	fmt.Println("\n=== 3. 洋葱模型的三个刚需 ===")
	needs := []struct{ title, why, example string }{
		{"① panic 兜底",
			"最外层要在最内层全部崩完之后才有机会恢复",
			"Recovery 必须包在 Auth 外面。如果 Auth 自己崩了而 Recovery 在里面，就没人兜底。"},
		{"② 后置处理",
			"外层要在内层改过响应之后才能动手",
			"Logger 在 handler 之后才能读 status 与耗时；Logger 在 handler 之前读到的永远是 200。"},
		{"③ 短路",
			"某一层判定不通过，后面的层完全不执行",
			"401 直接 Abort，FamilyScope 与 handler 都不会跑。这比 handler 里写一堆 if 好得多。"},
	}
	for _, n := range needs {
		fmt.Printf("  ▸ %s\n", n.title)
		fmt.Printf("      为什么：%s\n", n.why)
		fmt.Printf("      例子：%s\n", n.example)
	}

	fmt.Println("\n=== 4. 中止（Abort）怎么实现的：真跑四种请求 ===")
	cases := []struct {
		name    string
		prepare func(*http.Request)
	}{
		{"正常请求（带 token）", func(r *http.Request) {
			r.Header.Set("Authorization", "Bearer eyJ...")
		}},
		{"没带 Authorization", func(r *http.Request) {}},
		{"Bearer 后面是空的", func(r *http.Request) {
			r.Header.Set("Authorization", "Bearer ")
		}},
		{"格式错误（没有 Bearer 前缀）", func(r *http.Request) {
			r.Header.Set("Authorization", "eyJhbGciOi...")
		}},
	}
	for _, c := range cases {
		Trace = nil
		req := httptest.NewRequest("GET", "/api/homeos/members", nil)
		req.Header.Set("X-Request-Id", "r-1")
		c.prepare(req)
		rec := httptest.NewRecorder()
		h(rec, req)
		fmt.Printf("  %-22s → %d %s\n", c.name, rec.Code, strings.TrimSpace(rec.Body.String()))
		fmt.Printf("  %-22s   轨迹 %d 步：%s\n", "",
			len(Trace), strings.Join(stripRun(Trace), " → "))
	}
	fmt.Println()
	fmt.Println("  注意三种失败都停在 Auth 层。Family 与 handler 一次都没被调用 —— 这就是 Abort。")
	fmt.Println("  另外注意：中止时 Auth 自己的 defer 仍会执行，所以轨迹是「进入…退出」成对的。")
	fmt.Println("  这一点很重要：它意味着「中止」不等于「什么都没做」，")
	fmt.Println("  你在 defer 里写的清理代码（比如记录审计）**照样会跑**。")

	fmt.Println("\n=== 4b. panic 真的能被兜住吗：真跑一次 ===")
	panicky := func(c *Ctx) { panic("boom: nil pointer in handler") }
	panicChain := &Chain{}
	panicChain.Use(Logger(), Recovery(), Auth())
	ph := panicChain.Handle(panicky)
	Trace = nil
	reqP := httptest.NewRequest("GET", "/api/homeos/members", nil)
	reqP.Header.Set("Authorization", "Bearer eyJ...")
	recP := httptest.NewRecorder()
	ph(recP, reqP)
	for _, t := range Trace {
		fmt.Printf("    %s\n", t)
	}
	fmt.Printf("    响应：%d %s\n", recP.Code, strings.TrimSpace(recP.Body.String()))
	fmt.Println("    ↑ 程序没有崩，Recovery 的 defer 里的 recover 生效了。")
	fmt.Println("    注意轨迹：Recovery「捕获 panic」出现在「退出」那一行，")
	fmt.Println("    因为 defer 是在 panic 展开时才执行的。")

	fmt.Println("\n=== 5. handler 里能不能拿到前面中间件放的东西 ===")
	Trace = nil
	req5 := httptest.NewRequest("GET", "/api/homeos/members", nil)
	req5.Header.Set("X-Request-Id", "r-999")
	req5.Header.Set("Authorization", "Bearer eyJ...")
	rec5 := httptest.NewRecorder()
	h(rec5, req5)
	fmt.Printf("  请求头里的 X-Request-Id = %s\n", req5.Header.Get("X-Request-Id"))
	fmt.Printf("  响应体 = %s\n", strings.TrimSpace(rec5.Body.String()))
	fmt.Println("  → handler 通过 c.Get(\"req_id\") 读到的就是 Logger 放进去的值。")
	fmt.Println("  Context 是一个**结构体**，中间件直接往它的字段里写，")
	fmt.Println("  后面那层就能读。不需要返回值、不需要闭包。")
	fmt.Println()
	fmt.Println("  对比 JS 的两种写法：")
	fmt.Println("    Express: res.locals.uid = 'u-001'   （挂在 res 上，类型是 any）")
	fmt.Println("    Koa:     ctx.state.uid = 'u-001'     （挂在 ctx 上）")
	fmt.Println("  Go 的差别：类型是 map[string]any（因为 Gin 的 c.Set 签名如此），")
	fmt.Println("  但**编译期检查是有的** —— 你要 Get 一个不存在的 key，拿到的是 nil，")
	fmt.Println("  而不是 JS 里的 undefined 悄悄混过去。")

	fmt.Println("\n=== 6. Gin 的真实 API 映射（本项目要用的写法） ===")
	rows := []struct{ our, gin, note string }{
		{"&Ctx{W,R,keys}", "*gin.Context", "Gin 的 Context 同时兼任 Request 与 ResponseWriter"},
		{"c.Set(k,v)", "c.Set(k,v)", "完全一样，存进 gin.Context 的 keys map"},
		{"c.Get(k) any", "c.Get(k) any", "一样。注意需要类型断言：v, _ := c.Get(k).(string)"},
		{"c.Abort(401)", "c.AbortWithStatusJSON(401, resp)", "Gin 的 Abort 还要写响应体"},
		{"c.HandlerFunc", "gin.HandlerFunc", "签名一样：func(*Ctx) bool 的对应物是返回 void"},
		{"chain.Use(...)", "r.Use(...)", "注册中间件"},
		{"chain.Handle(h)", "r.GET(path, h)", "挂路由"},
	}
	fmt.Printf("  %s %s %s\n", pad("本文档的简化版", 22), pad("Gin 真实写法", 40), "说明")
	for _, r := range rows {
		fmt.Printf("  %s %s %s\n", pad(r.our, 22), pad(r.gin, 40), r.note)
	}
	fmt.Println()
	fmt.Println("  差别只有一处，但很关键：**本文档的 handler 返回 bool 表示「继续不继续」**。")
	fmt.Println("  Gin 里没有这个返回值 —— 它靠 c.Next() 和 c.Abort()：")
	fmt.Println("    func Auth() gin.HandlerFunc {")
	fmt.Println("      return func(c *gin.Context) {")
	fmt.Println("        if c.GetHeader(\"Authorization\") == \"\" {")
	fmt.Println("          c.AbortWithStatusJSON(401, resp.Fail(1005, \"未登录\"))")
	fmt.Println("          return        // ← return 就是「不继续」")
	fmt.Println("        }")
	fmt.Println("        c.Next()        // ← Next() 才会执行后面的中间件与 handler")
	fmt.Println("      }")
	fmt.Println("    }")
	fmt.Println("  关键点：**Gin 中间件不写 c.Next() 就不会往后走**。")
	fmt.Println("  这是它与 Express 最不一样的地方，也是最容易忘的坑。")

	fmt.Println("\n=== 7. 中间件的执行顺序：注册顺序 vs 优先级 ----------")
	fmt.Println("  Gin 的执行顺序**完全按注册顺序**，没有「谁优先级更高」的概念。")
	fmt.Println("  所以你必须知道这些顺序：")
	order := []struct{ n, name, why string }{
		{"1", "Recovery", "必须在最外层，否则兜不住后面所有 panic"},
		{"2", "Logger", "要在最外层，它要统计的总耗时包含所有内层"},
		{"3", "CORS", "要在鉴权前面，否则预检请求会被 401 挡住"},
		{"4", "RequestID", "要在 Logger 前面，Logger 要打 request_id"},
		{"5", "Auth", "要早，因为它要注入 uid 给后面用"},
		{"6", "FamilyScope", "最内层，它依赖 uid"},
	}
	for _, o := range order {
		fmt.Printf("    %s. %-12s %s\n", o.n, o.name, o.why)
	}
	fmt.Println()
	fmt.Println("  一个真实事故：有人把 Auth 注册在 CORS 前面，")
	fmt.Println("  于是浏览器的 OPTIONS 预检请求也要求 Authorization 头，")
	fmt.Println("  而浏览器发预检时**不会**带自定义头 → 全部预检失败 → 跨域全挂。")
	fmt.Println("  排查这类问题只有一个办法：打印中间件链的执行顺序。")
	fmt.Println("  所以本项目在 d24 会有一个「打印中间件链」的自查项。")

	fmt.Println("\n=== 8. 中间件 vs 拦截器 vs 过滤器：JS 里为什么那么乱 ----------")
	fmt.Println("  Express: 中间件（app.use）")
	fmt.Println("  Koa:     中间件（洋葱，一个 async 函数里 await next()）")
	fmt.Println("  Spring:  Filter（Servlet 层）→ Interceptor（MVC 层）→ AOP（方法层）")
	fmt.Println("  NestJS:  Guard → Interceptor → Pipe → Controller")
	fmt.Println("  Angular: Interceptor（HTTP 层）")
	fmt.Println()
	fmt.Println("  同一件事在五个框架里有十种叫法与两个不同的执行模型（洋葱 vs 直筒）。")
	fmt.Println("  Go 这边只有一种：http.Handler 包装，并且**规定**是洋葱。")
	fmt.Println("  原因很实在：Go 标准库在设计 HTTP 时就把中间件当成")
	fmt.Println("  「把一个 Handler 变成另一个 Handler 的装饰」——")
	fmt.Println("  func(Handler) Handler。这是函数式里最直观的组合子。")
	fmt.Println()
	fmt.Println("  洋葱模型在 JS 里也能手写，但需要 async/await 且每个中间件记得 await next()：")
	fmt.Println("    const m = () => async (req,res,next) => {")
	fmt.Println("      console.log('down')")
	fmt.Println("      await next()")
	fmt.Println("      console.log('up')")
	fmt.Println("    }")
	fmt.Println("  少写一个 await，洋葱就破成直筒，而且不报错 —— 这是 JS 侧最难查的一类 bug。")
	fmt.Println("  Go 的 defer 由编译器保证一定执行，没有这个坑。")

	fmt.Println("\n=== S4 d19 到此结束 ===")
	fmt.Println("明天写真正的鉴权中间件：解析 token、验签、判过期、注入上下文。")
}

func stripRun(t []string) []string {
	out := make([]string, 0, len(t))
	for _, s := range t {
		s = strings.TrimSpace(s)
		if i := strings.Index(s, " "); i > 0 {
			s = s[:i]
		}
		if i := strings.Index(s, "进入"); i > 0 {
			s = s[:i]
		}
		out = append(out, strings.TrimSpace(s))
	}
	return out
}

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

