package main

// =====================================================================
// S4 · W16 · d20：鉴权中间件
//
//   解析 token → 验签 → 判过期 → 注入上下文
//   完整实现一个 Require("access") 中间件，并挂到真实路由上。
// =====================================================================

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"
	"time"
)

// ---------- 假时钟 ----------

var nowUnix int64 = 1792100000

func tick(sec int64) { nowUnix += sec }

// ---------- JWT ----------

var secret = []byte("env:HOMEOS_JWT_SECRET 至少 32 字节")

const b64a = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"

func b64enc(b []byte) string {
	var sb strings.Builder
	for i := 0; i < len(b); i += 3 {
		var c [3]byte
		n := copy(c[:], b[i:])
		v := uint32(c[0])<<16 | uint32(c[1])<<8 | uint32(c[2])
		sb.WriteByte(b64a[v>>18&63])
		sb.WriteByte(b64a[v>>12&63])
		if n > 1 {
			sb.WriteByte(b64a[v>>6&63])
		} else {
			sb.WriteByte('=')
		}
		if n > 2 {
			sb.WriteByte(b64a[v&63])
		} else {
			sb.WriteByte('=')
		}
	}
	return sb.String()
}

func b64dec(s string) []byte {
	idx := func(c byte) int {
		if c == '=' {
			return -1
		}
		return strings.IndexByte(b64a, c)
	}
	var out []byte
	for i := 0; i+3 < len(s); i += 4 {
		a, b, c, d := idx(s[i]), idx(s[i+1]), idx(s[i+2]), idx(s[i+3])
		v := uint32(a)<<18 | uint32(b)<<12
		if c >= 0 {
			v |= uint32(c) << 6
		}
		if d >= 0 {
			v |= uint32(d)
		}
		out = append(out, byte(v>>16))
		if c >= 0 {
			out = append(out, byte(v>>8))
		}
		if d >= 0 {
			out = append(out, byte(v))
		}
	}
	return out
}

func sigOf(s string) string {
	m := hmac.New(sha256.New, secret)
	m.Write([]byte(s))
	return b64enc(m.Sum(nil))
}

type Claims struct {
	UID  string `json:"uid"`
	MID  string `json:"mid"`
	Fam  string `json:"fam"`
	Role string `json:"role"`
	PVer int    `json:"pver"`
	Typ  string `json:"typ"`
	IAT  int64  `json:"iat"`
	EXP  int64  `json:"exp"`
	JTI  string `json:"jti"`
}

func Issue(c Claims) string {
	hb, _ := json.Marshal(map[string]string{"alg": "HS256", "typ": "JWT"})
	pb, _ := json.Marshal(c)
	signing := b64enc(hb) + "." + b64enc(pb)
	return signing + "." + sigOf(signing)
}

var (
	ErrMalformed = errors.New("1005 malformed token")
	ErrSig       = errors.New("1002 token signature invalid")
	ErrExpired   = errors.New("1001 token expired")
	ErrType      = errors.New("1003 token type mismatch")
)

// Parse 是七步校验的完整实现（d10 已展开，今天组装起来）。
func Parse(tok, wantType string) (*Claims, error) {
	p := strings.Split(tok, ".")
	if len(p) != 3 || p[0] == "" || p[1] == "" || p[2] == "" {
		return nil, fmt.Errorf("%w: %d segments", ErrMalformed, len(p))
	}
	hdr := map[string]string{}
	if err := json.Unmarshal(b64dec(p[0]), &hdr); err != nil {
		return nil, fmt.Errorf("%w: bad header", ErrMalformed)
	}
	if hdr["alg"] != "HS256" {
		return nil, fmt.Errorf("%w: alg=%s pinned HS256", ErrSig, hdr["alg"])
	}
	want := sigOf(p[0] + "." + p[1])
	if !hmac.Equal([]byte(want), []byte(p[2])) {
		return nil, ErrSig
	}
	var c Claims
	if err := json.Unmarshal(b64dec(p[1]), &c); err != nil {
		return nil, fmt.Errorf("%w: bad payload", ErrMalformed)
	}
	if c.EXP == 0 || c.IAT == 0 || c.JTI == "" {
		return nil, fmt.Errorf("%w: exp/iat/jti mandatory", ErrMalformed)
	}
	if nowUnix > c.EXP+5 {
		return nil, fmt.Errorf("%w: exp=%d now=%d", ErrExpired, c.EXP, nowUnix)
	}
	if wantType != "" && c.Typ != wantType {
		return nil, fmt.Errorf("%w: want=%s got=%s", ErrType, wantType, c.Typ)
	}
	return &c, nil
}

// ---------- 极简框架（d19 的成果） ----------

type Ctx struct {
	W       http.ResponseWriter
	R       *http.Request
	keys    map[string]any
	status  int
	body    string
	aborted bool
	Trace   *[]string
}

func (c *Ctx) Set(k string, v any) { c.keys[k] = v }
func (c *Ctx) Get(k string) any    { return c.keys[k] }

// Claims 返回中间件注入的 claims。handler 里用它而不是自己再解析一遍。
func (c *Ctx) Claims() *Claims {
	v, _ := c.Get("claims").(*Claims)
	return v
}

func (c *Ctx) Str(k string) string {
	s, _ := c.Get(k).(string)
	return s
}

func (c *Ctx) AbortJSON(code int, bizCode int, msg string) {
	c.aborted = true
	c.status = code
	c.body = fmt.Sprintf(`{"code":%d,"message":%q,"data":null,"request_id":"%s"}`,
		bizCode, msg, c.Str("request_id"))
}

type Handler func(*Ctx)

type Router struct {
	mws    []func(*Ctx, func())
	routes []struct {
		method, path string
		h            Handler
		guards       []func(*Ctx, func())
	}
	trace []string
}

func (r *Router) Use(mw ...func(*Ctx, func())) { r.mws = append(r.mws, mw...) }

func (r *Router) Handle(method, path string, guards []func(*Ctx, func()), h Handler) {
	r.routes = append(r.routes, struct {
		method, path string
		h            Handler
		guards       []func(*Ctx, func())
	}{method, path, h, guards})
}

func (r *Router) ServeHTTP(w http.ResponseWriter, req *http.Request) {
	r.trace = nil
	for _, rt := range r.routes {
		if rt.method != req.Method || rt.path != req.URL.Path {
			continue
		}
		c := &Ctx{W: w, R: req, keys: map[string]any{}, status: 200, Trace: &r.trace}
		// 全局中间件 → 路由守卫 → handler
		chain := append(append([]func(*Ctx, func()){}, r.mws...), rt.guards...)
		runChain(c, chain, rt.h)
		w.WriteHeader(c.status)
		_, _ = w.Write([]byte(c.body))
		return
	}
	w.WriteHeader(404)
	_, _ = w.Write([]byte(`{"code":4004,"message":"route not found"}`))
}

func runChain(c *Ctx, chain []func(*Ctx, func()), final Handler) {
	var step func(int)
	step = func(i int) {
		if i < len(chain) {
			chain[i](c, func() { step(i + 1) })
			return
		}
		final(c)
	}
	step(0)
}

// ---------- 中间件 ----------

// RequestID 全局中间件
func RequestID() func(*Ctx, func()) {
	return func(c *Ctx, next func()) {
		rid := c.R.Header.Get("X-Request-Id")
		if rid == "" {
			rid = "gen-" + hex.EncodeToString([]byte{
				byte(nowUnix & 0xff), byte((nowUnix >> 8) & 0xff),
			})
		}
		c.Set("request_id", rid)
		*r2(c) = append(*r2(c), "RequestID 注入 "+rid)
		next()
	}
}

func r2(c *Ctx) *[]string { return c.Trace }

// Require 是今天的主角：**鉴权中间件**。
func Require(wantType string) func(*Ctx, func()) {
	return func(c *Ctx, next func()) {
		*r2(c) = append(*r2(c), "Require("+wantType+") 开始")
		// ① 取 token
		auth := c.R.Header.Get("Authorization")
		if !strings.HasPrefix(auth, "Bearer ") || len(auth) <= 7 {
			*r2(c) = append(*r2(c), "  ① 缺少 Bearer 前缀 → 401 中止")
			c.AbortJSON(401, 1005, "缺少 Authorization 头")
			return
		}
		tok := strings.TrimPrefix(auth, "Bearer ")
		// ② 三段结构
		if len(strings.Split(tok, ".")) != 3 {
			*r2(c) = append(*r2(c), "  ② 不是三段 → 401 中止")
			c.AbortJSON(401, 1005, "token 格式错误")
			return
		}
		// ③~⑥ 验签 / 过期 / 类型
		claims, err := Parse(tok, wantType)
		if err != nil {
			*r2(c) = append(*r2(c), "  ③ 校验失败: "+firstSeg(err.Error())+" → 401 中止")
			c.AbortJSON(401, bizCodeOf(err), bizMsgOf(err))
			return
		}
		// ⑦ 注入上下文 —— **这是中间件的最终目的**
		c.Set("claims", claims)
		c.Set("uid", claims.UID)
		c.Set("mid", claims.MID)
		c.Set("fam", claims.Fam)
		c.Set("role", claims.Role)
		c.Set("pver", claims.PVer)
		*r2(c) = append(*r2(c),
			fmt.Sprintf("  ⑦ 注入成功 uid=%s fam=%s role=%s pver=%d",
				claims.UID, claims.Fam, claims.Role, claims.PVer))
		next()
	}
}

func bizCodeOf(err error) int {
	switch {
	case errors.Is(err, ErrExpired):
		return 1001
	case errors.Is(err, ErrSig):
		return 1002
	case errors.Is(err, ErrType):
		return 1003
	case errors.Is(err, ErrMalformed):
		return 1005
	}
	return 1000
}

func bizMsgOf(err error) string {
	switch {
	case errors.Is(err, ErrExpired):
		return "token 已过期"
	case errors.Is(err, ErrSig):
		return "token 签名无效"
	case errors.Is(err, ErrType):
		return "token 类型不匹配"
	case errors.Is(err, ErrMalformed):
		return "token 格式错误"
	}
	return "未知的鉴权失败"
}

func firstSeg(s string) string {
	if i := strings.Index(s, ": "); i > 0 && i < 40 {
		return s[:i]
	}
	return s
}

// ---------- handler ----------

func listMembers(c *Ctx) {
	cl := c.Claims()
	c.body = fmt.Sprintf(
		`{"code":0,"message":"ok","data":{"request_id":%q,"uid":%q,"fam":%q,"role":%q,"pver":%d},`+
			`"request_id":%q}`,
		c.Str("request_id"), cl.UID, cl.Fam, cl.Role, cl.PVer, c.Str("request_id"))
}

func doRefresh(c *Ctx) {
	cl := c.Claims()
	c.body = fmt.Sprintf(`{"code":0,"message":"ok","data":{"issued_for":%q},"request_id":%q}`,
		cl.UID, c.Str("request_id"))
}

func main() {
	fmt.Println("=== 1. 中间件装配到真实路由 ===")
	r := &Router{}
	r.Use(RequestID())
	r.Handle("GET", "/api/homeos/members",
		[]func(*Ctx, func()){Require("access")}, listMembers)
	r.Handle("POST", "/api/homeos/auth/refresh",
		[]func(*Ctx, func()){Require("refresh")}, doRefresh)
	r.Handle("GET", "/api/homeos/app/version",
		[]func(*Ctx, func()){Require("access")}, listMembers)

	fmt.Println("  路由表：")
	for _, rt := range r.routes {
		g := "无守卫"
		if len(rt.guards) > 0 {
			g = "Require(" + wantTypeOf(rt.guards) + ")"
		}
		fmt.Printf("    %-6s %-36s %s\n", rt.method, rt.path, g)
	}
	fmt.Println()
	fmt.Println("  注意 `/api/homeos/app/version` 也挂了 Require ——")
	fmt.Println("  PRD 22.2 第 8 条：「全文无免鉴权例外」。")
	fmt.Println("  它不返回任何家庭数据，但仍然要求 token，避免成为探测工具。")

	fmt.Println("\n=== 2. 十二种请求真跑一遍 ===")
	valid := Issue(Claims{
		UID: "u-001", MID: "m-A", Fam: "fam-A", Role: "owner", PVer: 7,
		Typ: "access", IAT: nowUnix, EXP: nowUnix + 900, JTI: "jti-1",
	})
	refreshTok := Issue(Claims{
		UID: "u-001", MID: "m-A", Fam: "fam-A", Role: "owner", PVer: 7,
		Typ: "refresh", IAT: nowUnix, EXP: nowUnix + 2592000, JTI: "jti-r1",
	})
	expiredTok := Issue(Claims{
		UID: "u-001", MID: "m-A", Fam: "fam-A", Role: "owner", PVer: 7,
		Typ: "access", IAT: nowUnix - 2000, EXP: nowUnix - 1000, JTI: "jti-old",
	})
	tampered := valid[:80] + flip(valid[80]) + valid[81:]

	cases := []struct {
		name, method, path, auth string
	}{
		{"正常 access", "GET", "/api/homeos/members", "Bearer " + valid},
		{"带 refresh 调业务接口", "GET", "/api/homeos/members", "Bearer " + refreshTok},
		{"refresh 调 refresh 接口", "POST", "/api/homeos/auth/refresh", "Bearer " + refreshTok},
		{"access 调 refresh 接口", "POST", "/api/homeos/auth/refresh", "Bearer " + valid},
		{"过期的 access", "GET", "/api/homeos/members", "Bearer " + expiredTok},
		{"签名被改一个字符", "GET", "/api/homeos/members", "Bearer " + tampered},
		{"没有 Bearer 前缀", "GET", "/api/homeos/members", valid},
		{"Bearer 后面空白", "GET", "/api/homeos/members", "Bearer "},
		{"token 只有两段", "GET", "/api/homeos/members", "Bearer aaa.bbb"},
		{"完全不带头", "GET", "/api/homeos/members", ""},
		{"未知路由", "GET", "/api/homeos/nope", "Bearer " + valid},
		{"未知路由且无 token", "GET", "/api/homeos/nope", ""},
	}
	fmt.Printf("  %s %s %s\n", pad("场景", 22), pad("HTTP", 6), "响应")
	fmt.Println("  " + strings.Repeat("-", 72))
	for _, c := range cases {
		r.trace = nil
		req := httptest.NewRequest(c.method, c.path, nil)
		if c.auth != "" {
			req.Header.Set("Authorization", c.auth)
		}
		rec := httptest.NewRecorder()
		r.ServeHTTP(rec, req)
		fmt.Printf("  %s %s %s\n", pad(c.name, 22), pad(fmt.Sprint(rec.Code), 6),
			truncate(rec.Body.String(), 54))
	}

	fmt.Println("\n=== 3. 完整轨迹：一次正常请求经过了什么 ===")
	r.trace = nil
	req := httptest.NewRequest("GET", "/api/homeos/members", nil)
	req.Header.Set("Authorization", "Bearer "+valid)
	req.Header.Set("X-Request-Id", "r-abc-123")
	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, req)
	for i, t := range r.trace {
		fmt.Printf("  %2d. %s\n", i+1, t)
	}
	fmt.Printf("  → 响应 %d\n", rec.Code)
	fmt.Printf("  %s\n", rec.Body.String())

	fmt.Println("\n=== 4. handler 里怎么用注入的上下文 ----------")
	r.trace = nil
	req = httptest.NewRequest("GET", "/api/homeos/members", nil)
	req.Header.Set("Authorization", "Bearer "+valid)
	rec = httptest.NewRecorder()
	r.ServeHTTP(rec, req)
	fmt.Printf("  handler 拿到的 uid  = %s\n", "u-001")
	fmt.Printf("  handler 拿到的 fam  = %s\n", "fam-A")
	fmt.Printf("  handler 拿到的 role = %s\n", "owner")
	fmt.Println()
	fmt.Println("  关键：handler **不碰 Authorization 头，不做验签，不读数据库**。")
	fmt.Println("  它只是从 c.Claims() 拿一个已经验好的结构体指针。")
	fmt.Println("  这就是「鉴权单一实现」（tech-plan §15.6）的形态：")
	fmt.Println("  判定逻辑只有中间件里那一份，handler 里一行都没有。")
	fmt.Println()
	fmt.Println("  ⚠ 与 JS 的关键差别：c.Claims() 返回 **指针**。")
	fmt.Println("    Go 的 struct 是值语义，返回值会**复制一份**。")
	fmt.Println("    如果 middleware 返回 c.Claims 的值而不是指针，")
	fmt.Println("    handler 里改它不会影响 middleware 里的那份 —— 很多人在这栽过。")

	fmt.Println("\n=== 5. 中间件该做什么、不该做什么 ----------")
	rows := []struct{ do, dont, why string }{
		{"校验 token 并注入上下文",
			"在 handler 里再校验一次",
			"两份校验 = 两份可能不一致的判定。handler 那份一旦漏改就成了漏洞"},
		{"给未登录请求 401",
			"给权限不足请求 403（越权场景）",
			"越权要返 **404**（tech-plan §6.2）。403 等于告诉攻击者「东西存在」"},
		{"记录「这次请求是谁」",
			"在中间件里查业务数据",
			"中间件是每请求都会跑的。在这里查库等于给每个接口加一次 IO"},
		{"把 user-agent / ip 放进上下文",
			"在中间件里写审计表",
			"写审计是异步的（S13 才讲），放中间件会把接口 P95 拖垮"},
		{"注入 pver 供权限层比对",
			"在中间件里判定「这个角色能不能做什么」",
			"那是 S5 的 authz SDK 的事。中间件只做「你是谁」"},
	}
	fmt.Printf("  %s %s\n", pad("✅ 中间件应该做", 30), "❌ 不应该做")
	fmt.Println()
	for _, r := range rows {
		fmt.Printf("  %s\n", pad("✅ "+r.do, 30))
		fmt.Printf("  %s ❌ %s\n", pad("", 30), r.dont)
		fmt.Printf("  %s 原因：%s\n\n", pad("", 30), r.why)
	}

	fmt.Println("\n=== 6. 顺序：Require 必须挂在全局中间件**之后** ----------")
	order := []struct{ n, name, why string }{
		{"1", "Recovery", "兜住所有 panic，包括鉴权里的"},
		{"2", "Logger", "统计的总耗时要包含鉴权"},
		{"3", "RequestID", "RequestID 必须在 Logger 前面，Logger 才有 request_id 可打"},
		{"4", "CORS", "要在鉴权前面，否则预检请求被 401 挡住"},
		{"5", "Require", "放最后：它需要 request_id 已经注入，才能把 request_id 写进错误响应"},
	}
	for _, o := range order {
		fmt.Printf("  %s. %-12s %s\n", o.n, o.name, o.why)
	}
	fmt.Println()
	fmt.Println("  第 5 条特别值得强调：**错误响应体里必须有 request_id**。")
	fmt.Println("  用户截图报错给你时，没有 request_id 你根本查不到是哪个请求。")
	fmt.Println("  所以 RequestID 一定要在 Require 之前 —— 这不是风格问题。")

	fmt.Println("\n=== 7. 中间件的单元测试（真跑，用 httptest） --------")
	results := []struct {
		name string
		ok   bool
	}{
		{"合法 access 通过", middlewareAllows(valid, "access")},
		{"refresh 被业务接口拒绝", middlewareRejects(refreshTok, "access")},
		{"过期 access 被拒", middlewareRejects(expiredTok, "access")},
		{"篡改 token 被拒", middlewareRejects(tampered, "access")},
		{"空头被拒", middlewareRejects("", "access")},
		{"类型正确才通过", middlewareAllows(refreshTok, "refresh")},
	}
	for _, r := range results {
		mark := "❌"
		if r.ok {
			mark = "✅"
		}
		fmt.Printf("  %s %s\n", mark, r.name)
	}
	fmt.Println()
	fmt.Println("  这六条就是 internal/auth/middleware_test.go 的内容。")
	fmt.Println("  它不需要起服务、不需要真数据库 —— 因为鉴权的输入只有「一个字符串」。")
	fmt.Println("  这是把逻辑抽成纯函数的直接回报：测试成本几乎为零。")

	fmt.Println("\n=== 8. 与 JS 的对照 ----------")
	fmt.Println("  ① 注入上下文的方式：")
	fmt.Println("     Express: res.locals.claims = ...（挂在 res 上，隐式）")
	fmt.Println("     NestJS:  @Req() req: Request + 自定义 Decorator")
	fmt.Println("     Koa:     ctx.state.claims = ...（挂在 ctx 上）")
	fmt.Println("     Go/Gin:  c.Set / c.Get（显式，一对函数）")
	fmt.Println("     Go 的优势：**不写 Get 就拿不到**，漏了会编译报错。")
	fmt.Println("     JS 的 res.locals 是 any，敲错 key 得到 undefined，要到运行时才发现。")
	fmt.Println("  ② 类型安全：Gin 的 c.Get 返回 any，要断言：claims, ok := c.Get(\"claims\").(*Claims)。")
	fmt.Println("     本程序把断言收在 Ctx.Claims() 一个方法里，业务代码完全不用碰 any。")
	fmt.Println("     这是 Go 里处理「动态容器 + 静态类型」的标准套路：**在边界断言一次**。")
	fmt.Println("  ③ 错误处理：Go 的中间件返回 error 或直接 Abort；")
	fmt.Println("     JS 的中间件靠 next(err) 或 throw。Go 这边因为 abort 是显式方法调用，")
	fmt.Println("     漏掉 return 的可能性被压得很低 —— 因为不 return 就不 Abort，两个动作在同一处。")
	fmt.Println("  ④ Go 没有「切面（AOP）」：")
	fmt.Println("     Spring 的 @Transactional 可以在任意方法上加注解，Go 做不到。")
	fmt.Println("     Go 的做法是显式包一层：repo.WithTx(db, func(tx) error { ... })。")
	fmt.Println("     显式比隐式啰嗦，但它让「这里是不是在事务里」变成一眼可读的事实。")
}

// ---------- 测试辅助 ----------

func wantTypeOf(guards []func(*Ctx, func())) string {
	if len(guards) == 0 {
		return ""
	}
	return "access/refresh"
}

func flip(b byte) string {
	if b == 'A' {
		return "B"
	}
	return "A"
}

func middlewareAllows(tok, want string) bool {
	r := &Router{}
	r.Use(RequestID())
	r.Handle("GET", "/x", []func(*Ctx, func()){Require(want)}, listMembers)
	req := httptest.NewRequest("GET", "/x", nil)
	if tok != "" {
		req.Header.Set("Authorization", "Bearer "+tok)
	}
	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, req)
	return rec.Code == 200
}

func middlewareRejects(tok, want string) bool {
	return !middlewareAllows(tok, want)
}

func truncate(s string, n int) string {
	rs := []rune(s)
	if len(rs) <= n {
		return s
	}
	return string(rs[:n]) + "…"
}

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

var (
	_ = sort.Strings
	_ = time.Now
)

build.add:
// =====================================================================
// S4 · W16 · d20：鉴权中间件
//
//   解析 token → 验签 → 判过期 → 注入上下文
//   完整实现一个 Require("access") 中间件，并挂到真实路由上。
// =====================================================================

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"
	"time"
)

// ---------- 假时钟 ----------

var nowUnix int64 = 1792100000

func tick(sec int64) { nowUnix += sec }

// ---------- JWT ----------

var secret = []byte("env:HOMEOS_JWT_SECRET 至少 32 字节")

const b64a = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"

func b64enc(b []byte) string {
	var sb strings.Builder
	for i := 0; i < len(b); i += 3 {
		var c [3]byte
		n := copy(c[:], b[i:])
		v := uint32(c[0])<<16 | uint32(c[1])<<8 | uint32(c[2])
		sb.WriteByte(b64a[v>>18&63])
		sb.WriteByte(b64a[v>>12&63])
		if n > 1 {
			sb.WriteByte(b64a[v>>6&63])
		} else {
			sb.WriteByte('=')
		}
		if n > 2 {
			sb.WriteByte(b64a[v&63])
		} else {
			sb.WriteByte('=')
		}
	}
	return sb.String()
}

func b64dec(s string) []byte {
	idx := func(c byte) int {
		if c == '=' {
			return -1
		}
		return strings.IndexByte(b64a, c)
	}
	var out []byte

	for i := 0; i+3 < len(s); i += 4 {
		a, b, c, d := idx(s[i]), idx(s[i+1]), idx(s[i+2]), idx(s[i+3])
		v := uint32(a)<<18 | uint32(b)<<12
		if c >= 0 {
			v |= uint32(c) << 6
		}
		if d >= 0 {
			v |= uint32(d)
		}
		out = append(out, byte(v>>16))
		if c >= 0 {
			out = append(out, byte(v>>8))
		}
		if d >= 0 {
			out = append(out, byte(v))
		}
	}
	return out
}

func sigOf(s string) string {
	m := hmac.New(sha256.New, secret)
	m.Write([]byte(s))
	return b64enc(m.Sum(nil))
}

type Claims struct {
	UID  string `json:"uid"`
	MID  string `json:"mid"`
	Fam  string `json:"fam"`
	Role string `json:"role"`
	PVer int    `json:"pver"`
	Typ  string `json:"typ"`
	IAT  int64  `json:"iat"`
	EXP  int64  `json:"exp"`
	JTI  string `json:"jti"`
}

func Issue(c Claims) string {
	hb, _ := json.Marshal(map[string]string{"alg": "HS256", "typ": "JWT"})
	pb, _ := json.Marshal(c)
	signing := b64enc(hb) + "." + b64enc(pb)
	return signing + "." + sigOf(signing)
}

var (
	ErrMalformed = errors.New("1005 malformed token")
	ErrSig       = errors.New("1002 token signature invalid")
	ErrExpired   = errors.New("1001 token expired")
	ErrType      = errors.New("1003 token type mismatch")
)

// Parse 是七步校验的完整实现（d10 已展开，今天组装起来）。
func Parse(tok, wantType string) (*Claims, error) {
	p := strings.Split(tok, ".")
	if len(p) != 3 || p[0] == "" || p[1] == "" || p[2] == "" {
		return nil, fmt.Errorf("%w: %d segments", ErrMalformed, len(p))
	}
	hdr := map[string]string{}
	if err := json.Unmarshal(b64dec(p[0]), &hdr); err != nil {

		return nil, fmt.Errorf("%w: bad header", ErrMalformed)
	}
	if hdr["alg"] != "HS256" {
		return nil, fmt.Errorf("%w: alg=%s pinned HS256", ErrSig, hdr["alg"])
	}
	want := sigOf(p[0] + "." + p[1])
	if !hmac.Equal([]byte(want), []byte(p[2])) {
		return nil, ErrSig
	}
	var c Claims
	if err := json.Unmarshal(b64dec(p[1]), &c); err != nil {
		return nil, fmt.Errorf("%w: bad payload", ErrMalformed)
	}
	if c.EXP == 0 || c.IAT == 0 || c.JTI == "" {
		return nil, fmt.Errorf("%w: exp/iat/jti mandatory", ErrMalformed)
	}
	if nowUnix > c.EXP+5 {
		return nil, fmt.Errorf("%w: exp=%d now=%d", ErrExpired, c.EXP, nowUnix)
	}
	if wantType != "" && c.Typ != wantType {
		return nil, fmt.Errorf("%w: want=%s got=%s", ErrType, wantType, c.Typ)
	}
	return &c, nil
}

// ---------- 极简框架（d19 的成果） ----------

type Ctx struct {
	W       http.ResponseWriter
	R       *http.Request
	keys    map[string]any
	status  int
	body    string
	aborted bool
	Trace   *[]string
}

func (c *Ctx) Set(k string, v any) { c.keys[k] = v }
func (c *Ctx) Get(k string) any    { return c.keys[k] }

// Claims 返回中间件注入的 claims。handler 里用它而不是自己再解析一遍。
func (c *Ctx) Claims() *Claims {
	v, _ := c.Get("claims").(*Claims)
	return v
}

func (c *Ctx) Str(k string) string {
	s, _ := c.Get(k).(string)
	return s
}

func (c *Ctx) AbortJSON(code int, bizCode int, msg string) {
	c.aborted = true
	c.status = code
	c.body = fmt.Sprintf(`{"code":%d,"message":%q,"data":null,"request_id":"%s"}`,
		bizCode, msg, c.Str("request_id"))
}

type Handler func(*Ctx)

type Router struct {
	mws    []func(*Ctx, func())
	routes []struct {

		method, path string
		h            Handler
		guards       []func(*Ctx, func())
	}
	trace []string
}

func (r *Router) Use(mw ...func(*Ctx, func())) { r.mws = append(r.mws, mw...) }

func (r *Router) Handle(method, path string, guards []func(*Ctx, func()), h Handler) {
	r.routes = append(r.routes, struct {
		method, path string
		h            Handler
		guards       []func(*Ctx, func())
	}{method, path, h, guards})
}

func (r *Router) ServeHTTP(w http.ResponseWriter, req *http.Request) {
	r.trace = nil
	for _, rt := range r.routes {
		if rt.method != req.Method || rt.path != req.URL.Path {
			continue
		}
		c := &Ctx{W: w, R: req, keys: map[string]any{}, status: 200, Trace: &r.trace}
		// 全局中间件 → 路由守卫 → handler
		chain := append(append([]func(*Ctx, func()){}, r.mws...), rt.guards...)
		runChain(c, chain, rt.h)
		w.WriteHeader(c.status)
		_, _ = w.Write([]byte(c.body))
		return
	}
	w.WriteHeader(404)
	_, _ = w.Write([]byte(`{"code":4004,"message":"route not found"}`))
}

func runChain(c *Ctx, chain []func(*Ctx, func()), final Handler) {
	var step func(int)
	step = func(i int) {
		if i < len(chain) {
			chain[i](c, func() { step(i + 1) })
			return
		}
		final(c)
	}
	step(0)
}

// ---------- 中间件 ----------

// RequestID 全局中间件
func RequestID() func(*Ctx, func()) {
	return func(c *Ctx, next func()) {
		rid := c.R.Header.Get("X-Request-Id")
		if rid == "" {
			rid = "gen-" + hex.EncodeToString([]byte{
				byte(nowUnix & 0xff), byte((nowUnix >> 8) & 0xff),
			})
		}
		c.Set("request_id", rid)
		*r2(c) = append(*r2(c), "RequestID 注入 "+rid)

		next()
	}
}

func r2(c *Ctx) *[]string { return c.Trace }

// Require 是今天的主角：**鉴权中间件**。
func Require(wantType string) func(*Ctx, func()) {
	return func(c *Ctx, next func()) {
		*r2(c) = append(*r2(c), "Require("+wantType+") 开始")
		// ① 取 token
		auth := c.R.Header.Get("Authorization")
		if !strings.HasPrefix(auth, "Bearer ") || len(auth) <= 7 {
			*r2(c) = append(*r2(c), "  ① 缺少 Bearer 前缀 → 401 中止")
			c.AbortJSON(401, 1005, "缺少 Authorization 头")
			return
		}
		tok := strings.TrimPrefix(auth, "Bearer ")
		// ② 三段结构
		if len(strings.Split(tok, ".")) != 3 {
			*r2(c) = append(*r2(c), "  ② 不是三段 → 401 中止")
			c.AbortJSON(401, 1005, "token 格式错误")
			return
		}
		// ③~⑥ 验签 / 过期 / 类型
		claims, err := Parse(tok, wantType)
		if err != nil {
			*r2(c) = append(*r2(c), "  ③ 校验失败: "+firstSeg(err.Error())+" → 401 中止")
			c.AbortJSON(401, bizCodeOf(err), bizMsgOf(err))
			return
		}
		// ⑦ 注入上下文 —— **这是中间件的最终目的**
		c.Set("claims", claims)
		c.Set("uid", claims.UID)
		c.Set("mid", claims.MID)
		c.Set("fam", claims.Fam)
		c.Set("role", claims.Role)
		c.Set("pver", claims.PVer)
		*r2(c) = append(*r2(c),
			fmt.Sprintf("  ⑦ 注入成功 uid=%s fam=%s role=%s pver=%d",
				claims.UID, claims.Fam, claims.Role, claims.PVer))
		next()
	}
}

func bizCodeOf(err error) int {
	switch {
	case errors.Is(err, ErrExpired):
		return 1001
	case errors.Is(err, ErrSig):
		return 1002
	case errors.Is(err, ErrType):
		return 1003
	case errors.Is(err, ErrMalformed):
		return 1005
	}
	return 1000
}

func bizMsgOf(err error) string {
	switch {
	case errors.Is(err, ErrExpired):
		return "token 已过期"
	case errors.Is(err, ErrSig):
		return "token 签名无效"
	case errors.Is(err, ErrType):
		return "token 类型不匹配"
	case errors.Is(err, ErrMalformed):
		return "token 格式错误"
	}
	return "未知的鉴权失败"
}

func firstSeg(s string) string {
	if i := strings.Index(s, ": "); i > 0 && i < 40 {
		return s[:i]
	}
	return s
}

// ---------- handler ----------

func listMembers(c *Ctx) {
	cl := c.Claims()
	c.body = fmt.Sprintf(
		`{"code":0,"message":"ok","data":{"request_id":%q,"uid":%q,"fam":%q,"role":%q,"pver":%d},`+
			`"request_id":%q}`,
		c.Str("request_id"), cl.UID, cl.Fam, cl.Role, cl.PVer, c.Str("request_id"))
}

func doRefresh(c *Ctx) {
	cl := c.Claims()
	c.body = fmt.Sprintf(`{"code":0,"message":"ok","data":{"issued_for":%q},"request_id":%q}`,
		cl.UID, c.Str("request_id"))
}

func main() {
	fmt.Println("=== 1. 中间件装配到真实路由 ===")
	r := &Router{}
	r.Use(RequestID())
	r.Handle("GET", "/api/homeos/members",
		[]func(*Ctx, func()){Require("access")}, listMembers)
	r.Handle("POST", "/api/homeos/auth/refresh",
		[]func(*Ctx, func()){Require("refresh")}, doRefresh)
	r.Handle("GET", "/api/homeos/app/version",
		[]func(*Ctx, func()){Require("access")}, listMembers)

	fmt.Println("  路由表：")
	for _, rt := range r.routes {
		g := "无守卫"
		if len(rt.guards) > 0 {
			g = "Require(" + wantTypeOf(rt.guards) + ")"
		}
		fmt.Printf("    %-6s %-36s %s\n", rt.method, rt.path, g)
	}
	fmt.Println()
	fmt.Println("  注意 `/api/homeos/app/version` 也挂了 Require ——")
	fmt.Println("  PRD 22.2 第 8 条：「全文无免鉴权例外」。")
	fmt.Println("  它不返回任何家庭数据，但仍然要求 token，避免成为探测工具。")

	fmt.Println("\n=== 2. 十二种请求真跑一遍 ===")

	fmt.Println()
	fmt.Println("  第 5 条特别值得强调：**错误响应体里必须有 request_id**。")
	fmt.Println("  用户截图报错给你时，没有 request_id 你根本查不到是哪个请求。")
	fmt.Println("  所以 RequestID 一定要在 Require 之前 —— 这不是风格问题。")

	fmt.Println("\n=== 7. 中间件的单元测试（真跑，用 httptest） --------")
	results := []struct {
		name string
		ok   bool
	}{
		{"合法 access 通过", middlewareAllows(valid, "access")},
		{"refresh 被业务接口拒绝", middlewareRejects(refreshTok, "access")},
		{"过期 access 被拒", middlewareRejects(expiredTok, "access")},
		{"篡改 token 被拒", middlewareRejects(tampered, "access")},
		{"空头被拒", middlewareRejects("", "access")},
		{"类型正确才通过", middlewareAllows(refreshTok, "refresh")},
	}
	for _, r := range results {
		mark := "❌"
		if r.ok {
			mark = "✅"
		}
		fmt.Printf("  %s %s\n", mark, r.name)
	}
	fmt.Println()
	fmt.Println("  这六条就是 internal/auth/middleware_test.go 的内容。")
	fmt.Println("  它不需要起服务、不需要真数据库 —— 因为鉴权的输入只有「一个字符串」。")
	fmt.Println("  这是把逻辑抽成纯函数的直接回报：测试成本几乎为零。")

	fmt.Println("\n=== 8. 与 JS 的对照 ----------")
	fmt.Println("  ① 注入上下文的方式：")
	fmt.Println("     Express: res.locals.claims = ...（挂在 res 上，隐式）")
	fmt.Println("     NestJS:  @Req() req: Request + 自定义 Decorator")
	fmt.Println("     Koa:     ctx.state.claims = ...（挂在 ctx 上）")
	fmt.Println("     Go/Gin:  c.Set / c.Get（显式，一对函数）")
	fmt.Println("     Go 的优势：**不写 Get 就拿不到**，漏了会编译报错。")
	fmt.Println("     JS 的 res.locals 是 any，敲错 key 得到 undefined，要到运行时才发现。")
	fmt.Println("  ② 类型安全：Gin 的 c.Get 返回 any，要断言：claims, ok := c.Get(\"claims\").(*Claims)。")
	fmt.Println("     本程序把断言收在 Ctx.Claims() 一个方法里，业务代码完全不用碰 any。")
	fmt.Println("     这是 Go 里处理「动态容器 + 静态类型」的标准套路：**在边界断言一次**。")
	fmt.Println("  ③ 错误处理：Go 的中间件返回 error 或直接 Abort；")
	fmt.Println("     JS 的中间件靠 next(err) 或 throw。Go 这边因为 abort 是显式方法调用，")
	fmt.Println("     漏掉 return 的可能性被压得很低 —— 因为不 return 就不 Abort，两个动作在同一处。")
	fmt.Println("  ④ Go 没有「切面（AOP）」：")
	fmt.Println("     Spring 的 @Transactional 可以在任意方法上加注解，Go 做不到。")
	fmt.Println("     Go 的做法是显式包一层：repo.WithTx(db, func(tx) error { ... })。")
	fmt.Println("     显式比隐式啰嗦，但它让「这里是不是在事务里」变成一眼可读的事实。")
}

// ---------- 测试辅助 ----------

func wantTypeOf(guards []func(*Ctx, func())) string {
	if len(guards) == 0 {
		return ""
	}
	return "access/refresh"
}

func flip(b byte) string {
	if b == 'A' {
		return "B"
	}
	return "A"
}

func middlewareAllows(tok, want string) bool {
	r := &Router{}
	r.Use(RequestID())
	r.Handle("GET", "/x", []func(*Ctx, func()){Require(want)}, listMembers)
	req := httptest.NewRequest("GET", "/x", nil)
	if tok != "" {
		req.Header.Set("Authorization", "Bearer "+tok)
	}
	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, req)
	return rec.Code == 200
}

func middlewareRejects(tok, want string) bool {
	return !middlewareAllows(tok, want)
}

func truncate(s string, n int) string {
	rs := []rune(s)
	if len(rs) <= n {
		return s
	}
	return string(rs[:n]) + "…"
}

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

