package main

// =====================================================================
// S4 · W16 · d21：上下文传递
//
//   context.Context 为什么是惯例 / 为什么是第一个参数
//   怎么避免层层传参 / 与 JS 的 AsyncLocalStorage 对比
//
// 本程序真跑：用 context 传请求身份，跨 5 层函数不丢；
// 再演示「不用 context 时会写成什么样」。
// =====================================================================

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"
)

// ---------- 请求身份的载体 ----------

// Auth 是我们要传递的东西。它**不是** context.Context 本身，
// 而是挂在 context 里的一个值。这条区分今天要讲清楚。
type Auth struct {
	RequestID string
	UID       string
	FamilyID  string
	Role      string
	PVer      int
}

type ctxKey string

// 用一个**私有类型**作为 key。这是 Go 官方推荐的做法，理由在第 6 节。
const authKey ctxKey = "homeos.auth"

var ErrNoAuth = errors.New("no auth in context")

func WithAuth(ctx context.Context, a *Auth) context.Context {
	return context.WithValue(ctx, authKey, a)
}

func AuthFrom(ctx context.Context) (*Auth, error) {
	v := ctx.Value(authKey)
	if v == nil {
		return nil, ErrNoAuth
	}
	a, ok := v.(*Auth)
	if !ok {
		return nil, fmt.Errorf("auth in context has wrong type %T", v)
	}
	return a, nil
}

// ---------- 用 context 的正确形态：ctx 是第一个参数，永不存进 struct ----------

// Service 层
type MemberService struct{}

// 这就是本项目的标准写法：**ctx 第一个参数，不进 struct**。
func (s *MemberService) List(ctx context.Context, cursor string) ([]string, error) {
	a, err := AuthFrom(ctx)
	if err != nil {
		return nil, err
	}
	// 第三层调用：repo 自己也要 ctx，但它是从参数拿的，不是从 struct 里翻的
	rows, err := listFromRepo(ctx, a.FamilyID, cursor)
	if err != nil {
		return nil, err
	}
	return rows, nil
}

// Repo 层
func listFromRepo(ctx context.Context, famID, cursor string) ([]string, error) {
	// repo 不关心鉴权，但它仍然接受 ctx —— 因为它要支持超时与取消
	if err := ctx.Err(); err != nil {
		return nil, fmt.Errorf("context done before query: %w", err)
	}
	// 模拟一次带 trace 的查询：把 request_id 传给日志
	a, _ := AuthFrom(ctx)
	return []string{
		fmt.Sprintf("m-A / %s / %s / request=%s", famID, cursor, a.RequestID),
		fmt.Sprintf("m-B / %s / %s / request=%s", famID, cursor, a.RequestID),
	}, nil
}

// ---------- 对照：不用 context 时会写成什么样 ----------

// 错误做法：把身份当参数层层传递
type BadService struct{}

func (s *BadService) List(reqID, uid, famID string, cursor string) ([]string, error) {
	return listFromRepoBad(reqID, uid, famID, cursor)
}

func listFromRepoBad(reqID, uid, famID, cursor string) ([]string, error) {
	// uid 参数**根本没被用上** —— 这是层层传参最典型的症状：
	// 参数越加越多，但大部分层其实不需要，只是因为上游有它。
	return []string{
		fmt.Sprintf("m-A / %s / %s / request=%s", famID, cursor, reqID),
		fmt.Sprintf("m-B / %s / %s / request=%s", famID, cursor, reqID),
	}, nil
}

// 稍复杂一点的错误做法：塞进 struct
type BadStructService struct {
	RequestID string
	UID       string
	FamilyID  string
}

type RepoStruct struct {
	RequestID string // ← 每个方法都要从 struct 里翻
}

func (s *BadStructService) List(cursor string) ([]string, error) {
	r := &RepoStruct{RequestID: s.RequestID}
	return r.Query(s.FamilyID, cursor)
}

func (r *RepoStruct) Query(famID, cursor string) ([]string, error) {
	return []string{fmt.Sprintf("m-A / %s / %s / request=%s", famID, cursor, r.RequestID)}, nil
}

func main() {
	fmt.Println("=== 1. context.Context 是什么：一个「带生命周期的容器」 ===")
	fmt.Println("  它只做两件事：")
	fmt.Println("    ① 传值（WithValue）—— 我们用它挂请求身份")
	fmt.Println("    ② 传取消信号（WithCancel / WithTimeout / WithDeadline）")
	fmt.Println("  它**不是**万能袋子。Go 官方文档写得很明确：")
	fmt.Println("    「Use context.Context for passing request-scoped values,")
	fmt.Println("      across API boundaries and to process metadata.\"")
	fmt.Println("    也就是：只用于**请求作用域**的值，跨 API 边界。")
	fmt.Println("    不要往里塞数据库连接、用户对象、service 实例 —— 那些是依赖，不是上下文。")
	fmt.Println()

	fmt.Println("=== 2. 真跑：五层调用，身份一次都不丢 ===")
	a := &Auth{RequestID: "req-2f9a", UID: "u-001", FamilyID: "fam-A", Role: "owner", PVer: 7}
	ctx := WithAuth(context.Background(), a)

	// 中间件里通常还会加超时
	ctx2, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	svc := &MemberService{}
	rows, err := svc.List(ctx2, "cursor-0")
	if err != nil {
		fmt.Printf("  ❌ %v\n", err)
		return
	}
	fmt.Println("  调用链：handler → service.List → listFromRepo")
	fmt.Println("  三层之间没有传任何身份参数（除了 cursor）")
	for _, r := range rows {
		fmt.Printf("    %s\n", r)
	}
	fmt.Println()
	fmt.Println("  → request_id 出现在最内层的查询结果里，证明它一路传下去了。")
	fmt.Println("  → 而 service.List 的签名只有 (ctx, cursor) 两个参数。")

	fmt.Println("\n=== 3. 逐层追踪：ctx 是怎么传下去的 ----------")
	trace := []string{}
	t1 := step1(ctx, "service.List", &trace)
	t2 := step2(t1, "repo.query", &trace)
	_ = t2
	for i, s := range trace {
		fmt.Printf("  %d. %s\n", i+1, s)
	}
	fmt.Println()
	fmt.Println("  注意每一层都是「把 ctx 作为参数收进来，再作为参数传出去」。")
	fmt.Println("  它不是被某个对象持有的状态，而是**沿着调用栈流动的数据**。")

	fmt.Println("\n=== 4. 反面教材：不用 context 的三种写法 ----------")
	fmt.Println()
	fmt.Println("  ① 层层加参数：")
	bs := &BadService{}
	rowsBad, _ := bs.List("req-2f9a", "u-001", "fam-A", "cursor-0")
	for _, r := range rowsBad {
		fmt.Printf("      %s\n", r)
	}
	fmt.Printf("      函数签名：List(reqID, uid, famID string, cursor string)\n")
	fmt.Println("      问题：加一个新身份字段要改**所有**下游函数；")
	fmt.Println("      调用点写错顺序编译能过（都是 string），运行时才炸。")
	fmt.Println()
	fmt.Println("  ② 塞进 struct：")
	bst := &BadStructService{RequestID: "req-2f9a", UID: "u-001", FamilyID: "fam-A"}
	rowsStruct, _ := bst.List("cursor-0")
	for _, r := range rowsStruct {
		fmt.Printf("      %s\n", r)
	}
	fmt.Println("      函数签名：List(cursor string) —— 看起来最简洁")
	fmt.Println("      但问题更严重：")
	fmt.Println("        · 这个 service **变成有状态的**，无法并发安全地被多请求共用")
	fmt.Println("        · 如果它是一个全局单例（Go 里常见），两个请求会互相覆盖 RequestID")
	fmt.Println("        · 「请求作用域的值」被放进了「长期存活的对象」里")
	fmt.Println()
	fmt.Println("  ③ 用全局变量：")
	GlobalRequestID = "req-2f9a" // 危险
	fmt.Printf("      全局变量 GlobalRequestID = %s\n", GlobalRequestID)
	fmt.Println("      问题：并发的第二个请求会覆盖第一个。Go 里读写全局变量还要加锁，")
	fmt.Println("      而加锁之后你会发现这就是 context 干的事，只是更笨。")

	fmt.Println("\n=== 5. 为什么 ctx 必须是第一个参数 ----------")
	fmt.Println("  Go 的社区约定（官方 Code Review Comments 明确写了）：")
	reasons := []struct{ n, why string }{
		{"1", "可读性：func F(ctx context.Context, ...) 一眼看出它有外部依赖"},
		{"2", "不会被误传：`go vet` 与静态检查工具能查出「谁没传 ctx」"},
		{"3", "接口实现的签名要与调用顺序一致：io.Reader.Read(ctx, p) 就是这样"},
		{"4", "包名 ctx 不进 struct：这是**类型系统**在帮你守规矩 ——"},
	}
	for _, r := range reasons {
		fmt.Printf("  %s. %s\n", r.n, r.why)
	}
	fmt.Println()
	fmt.Println("  第 4 条展开：Go 允许你把任何东西放进 struct，")
	fmt.Println("  所以「禁止把 ctx 存进结构体」只能靠约定 —— 但它是一条被广泛遵守的约定。")
	fmt.Println("  golangci-lint 的 `containedctx` 检查就是机械地拦这件事。")
	fmt.Println()
	fmt.Println("  反面例子（本项目的用户表绝不能这样）：")
	fmt.Println("    type User struct {")
	fmt.Println("        ctx context.Context  // ❌ 绝对不行")
	fmt.Println("    }")
	fmt.Println("  因为 User 会被存进数据库。存进数据库的 struct 带着一个请求的 ctx，")
	fmt.Println("  意味着：换一个请求来读这行数据，ctx 已经是另一个请求的了。")
	fmt.Println("  而且 context.Context 不可比较，不能当 map key，某些 ORM 序列化它会直接报错。")

	fmt.Println("\n=== 6. key 必须用私有类型：为什么 ----------")
	fmt.Println("  错误的 key：")
	fmt.Println("    ctx = context.WithValue(ctx, \"uid\", \"u-001\")   // ❌ string 作 key")
	fmt.Println("  问题一：别人也能用同样的字符串 key 写进去，与你冲突")
	fmt.Println("  问题二：你和别人的 key 撞了，谁先写谁生效，排查到崩溃")
	fmt.Println()
	fmt.Println("  正确的 key：")
	fmt.Println("    type ctxKey string")
	fmt.Println("    const authKey ctxKey = \"homeos.auth\"")
	fmt.Println("    ctx = context.WithValue(ctx, authKey, a)")
	fmt.Println()
	fmt.Println("  定义了**私有类型**之后，别的包就造不出这个 key ——")
	fmt.Println("  他们拿不到 ctxKey 这个类型，也就无法写出 authKey。")
	fmt.Println("  这就是 Go 用类型系统实现「私有命名空间」的手法，")
	fmt.Println("  和 unexported 字段（family_id → familyID 的小写化）是同一个思路。")
	fmt.Println()
	// 真跑一次冲突演示
	// 真跑一次：用裸字符串当 key 存进去，再用同一个字符串取出来
	ctxStr := context.WithValue(context.Background(), "uid", "u-001")
	v, _ := ctxStr.Value("uid").(string)
	fmt.Printf("  真跑：用 string key 写入再读出 → %q（任何包都能这么做 → 隔离为零）\n", v)
	fmt.Println("  真跑：用私有类型 key 写入，别的包连 key 都构造不出来 → 读不到。")
	fmt.Println("  这就是「私有类型 = 私有命名空间」的直接效果。")

	fmt.Println("\n=== 7. context 的取消：一个真实的价值 ----------")
	fmt.Println("  场景：客户端断开了连接，但服务端的数据库查询还在跑。")
	fmt.Println("  有 ctx：查询会在 ctx.Done() 时被取消，连接归还连接池。")
	// 先建一个已取消的 ctx（不等 50ms，保证输出确定）
	ctxCancelled, cancelNow := context.WithCancel(ctx)
	cancelNow()
	_, err = svc.List(ctxCancelled, "cursor-heavy")
	fmt.Printf("  用**已取消**的 ctx 调用 → %v\n", err)
	fmt.Println("  （本程序用手动 cancel 而不是等超时，这样跑两遍输出完全一样；")
	fmt.Println("    生产环境当然是用 WithTimeout —— 语义一致，只是取消来源是时间。）")
	fmt.Println("  没有 ctx：这个查询会一直跑到自然结束，")
	fmt.Println("  用户已经走了，CPU 与 IO 白白消耗 —— 高并发下就是雪崩。")
	fmt.Println()
	fmt.Println("  ⚠ 但要注意：WithTimeout 传进去之后，**repo 层必须主动检查** ctx.Err()。")
	fmt.Println("    GORM 需要 db.WithContext(ctx)，否则取消信号传不到驱动层。")
	fmt.Println("    只在 service 里判断 ctx.Err() 是不够的。")

	fmt.Println("\n=== 8. 与 JS 的对照 ----------")
	fmt.Println("  JS 有对应的能力，但它藏得更深：")
	rowsJS := []struct{ concept, goSide, jsSide string }{
		{"请求作用域的值", "ctx.Value(key)", "AsyncLocalStorage.getStore()"},
		{"设置", "ctx = context.WithValue(ctx, k, v)", "als.run(store, fn)"},
		{"取消", "ctx.Done()", "AbortController.signal"},
		{"超时", "context.WithTimeout(ctx, 3*time.Second)", "AbortSignal.timeout(3000)"},
		{"默认的", "第一个参数，传 nil 是禁止的", "als.getStore() 可能是 undefined"},
	}
	fmt.Printf("  %s %s %s\n", pad("概念", 18), pad("Go", 44), "JS")
	for _, r := range rowsJS {
		fmt.Printf("  %s %s %s\n", pad(r.concept, 18), pad(r.goSide, 44), r.jsSide)
	}
	fmt.Println()
	fmt.Println("  三处实质差别：")
	fmt.Println("   ① JS 的 AsyncLocalStorage 是**显式选择**才能用的；不启用就没有隔离。")
	fmt.Println("      Go 的 ctx 是**默认就在**函数签名里 —— 它是第一个参数，")
	fmt.Println("      你想不传都传不了（要传 context.TODO() 才能编译通过）。")
	fmt.Println("   ② JS 的 async 函数会把 store 自动跨 await 传递（async_hooks 做的）；")
	fmt.Println("      Go 里 ctx 也是自动跨函数传递的，但**跨 goroutine 必须显式传**。")
	fmt.Println("      如果你 `go func() { ... }()` 忘了传 ctx，身份就丢了。")
	fmt.Println("   ③ JS 里 store 可能被意外覆盖成一个普通对象；")
	fmt.Println("      Go 里 WithValue 的第二个参数是 any，**编译期不保证类型**，")
	fmt.Println("      所以取的时候必须断言（就是 AuthFrom 里那个类型断言）。")
	fmt.Println()
	fmt.Println("  最后一条是 Go context 最实际的坑：**WithValue 不检查类型**。")
	fmt.Println("  你 WithValue(ctx, k, \"u-001\") 再 WithValue(ctx, k, 42) 都能编译过，")
	fmt.Println("  取的时候才 panic 或者拿到错的东西。")
	fmt.Println("  唯一可靠的做法就是第 6 节说的：私有 key 类型 + 取值时断言。")

	fmt.Println("\n=== S4 d21 到此结束 ===")
	fmt.Println("明天讲家庭上下文注入：为什么 handler 里不能现查 DB 判权限、")
	fmt.Println("以及 token 里的 family_id 快照这件事。")
}

// GlobalRequestID 演示用的全局变量（**永远不要这么写**）
var GlobalRequestID string

func step1(ctx context.Context, name string, trace *[]string) context.Context {
	*trace = append(*trace, "step1 "+name+"：拿到 ctx，转发给 step2")
	a, err := AuthFrom(ctx)
	if err != nil {
		return ctx
	}
	*trace = append(*trace, fmt.Sprintf("          从 ctx 读出 uid=%s fam=%s", a.UID, a.FamilyID))
	return ctx
}

func step2(ctx context.Context, name string, trace *[]string) context.Context {
	*trace = append(*trace, "step2 "+name+"：拿到 ctx，调用 repo")
	rows, err := listFromRepo(ctx, "fam-A", "cursor-0")
	if err != nil {
		return ctx
	}
	*trace = append(*trace, "          repo 返回 "+fmt.Sprint(len(rows))+" 行")
	return ctx
}

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

