package main

// =====================================================================
// S4 · W16 · d21：上下文传递
//
//   context.Context 为什么是惯例 / 为什么是第一个参数
//   怎么避免层层传参 / 与 JS 的 AsyncLocalStorage 对比
//
// 本程序真跑：用 context 传请求身份，跨 5 层函数不丢；
// 再演示「不用 context 时会写成什么样」。

// =====================================================================

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"
)

// ---------- 请求身份的载体 ----------

// Auth 是我们要传递的东西。它**不是** context.Context 本身，
// 而是挂在 context 里的一个值。这条区分今天要讲清楚。

type Auth struct {
	RequestID string
	UID       string
	FamilyID  string
	Role      string
	PVer      int
}

type ctxKey string

// 用一个**私有类型**作为 key。这是 Go 官方推荐的做法，理由在第 6 节。
const authKey ctxKey = "homeos.auth"

var ErrNoAuth = errors.New("no auth in context")

func WithAuth(ctx context.Context, a *Auth) context.Context {
	return context.WithValue(ctx, authKey, a)
}

func AuthFrom(ctx context.Context) (*Auth, error) {
	v := ctx.Value(authKey)
	if v == nil {
		return nil, ErrNoAuth
	}
	a, ok := v.(*Auth)
	if !ok {
		return nil, fmt.Errorf("auth in context has wrong type %T", v)
	}
	return a, nil
}

// ---------- 用 context 的正确形态：ctx 是第一个参数，永不存进 struct ----------

// Service 层
type MemberService struct{}

// 这就是本项目的标准写法：**ctx 第一个参数，不进 struct**。

func (s *MemberService) List(ctx context.Context, cursor string) ([]string, error) {
	a, err := AuthFrom(ctx)
	if err != nil {
		return nil, err
	}
	// 第三层调用：repo 自己也要 ctx，但它是从参数拿的，不是从 struct 里翻的
	rows, err := listFromRepo(ctx, a.FamilyID, cursor)
	if err != nil {
		return nil, err
	}
	return rows, nil
}

// Repo 层
func listFromRepo(ctx context.Context, famID, cursor string) ([]string, error) {
	// repo 不关心鉴权，但它仍然接受 ctx —— 因为它要支持超时与取消
	if err := ctx.Err(); err != nil {
		return nil, fmt.Errorf("context done before query: %w", err)
	}
	// 模拟一次带 trace 的查询：把 request_id 传给日志
	a, _ := AuthFrom(ctx)
	return []string{
		fmt.Sprintf("m-A / %s / %s / request=%s", famID, cursor, a.RequestID),
		fmt.Sprintf("m-B / %s / %s / request=%s", famID, cursor, a.RequestID),
	}, nil
}

// ---------- 对照：不用 context 时会写成什么样 ----------

// 错误做法：把身份当参数层层传递

func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

