		return nil, errors.New("bad signature")
	}
	var c Claims
	if err := json.Unmarshal(b64dec(p[1]), &c); err != nil {
		return nil, err
	}
	return &c, nil
}

// ---------- 数据库 ----------

type Member struct {
	MemberID string
	UserID   string
	FamilyID string
	Role     string
	PVer     int
	Deleted  bool
}

var memberTable = map[string]*Member{} // key = member_id

func memberKey(mid string) string { return mid }

// ---------- 缓存 ----------

// CacheEntry 是一条「某个成员的权限快照」。
type CacheEntry struct {
	MemberID string
	Role     string
	PVer     int
	// CachedAt 是写缓存的时刻（秒）。
	CachedAt int64
	// Source 记录它是被事件失效清掉的，还是自然过期的。
	Source string
}

type AuthzCache struct {
	entries map[string]*CacheEntry
	ttl     int64 // 60 秒（PRD 15.6）
	queries int   // 统计真的打到数据库的次数
}

func NewCache(ttl int64) *AuthzCache {
	return &AuthzCache{entries: map[string]*CacheEntry{}, ttl: ttl}
}

// Lookup 是「用 token 里的 pver 与缓存/数据库比对」的完整逻辑。
func (c *AuthzCache) Lookup(mid string, tokenPVer int, nowUnix int64) (role string, dbPVer int, fromCache bool, err error) {
	e, hit := c.entries[mid]
	if hit && nowUnix-e.CachedAt < c.ttl {
		// 缓存新鲜
		if e.PVer == tokenPVer {
			return e.Role, e.PVer, true, nil
		}
		// 缓存里就是新的 pver，但 token 是旧的 → 权限已变更
		return "", e.PVer, true, ErrStalePerm
	}
	// 缓存过期 → 查库
	c.queries++
	m := memberTable[mid]
	if m == nil || m.Deleted {
		c.entries[mid] = &CacheEntry{MemberID: mid, CachedAt: nowUnix, Source: "db-miss"}
		return "", 0, false, ErrNoMember
	}
	c.entries[mid] = &CacheEntry{
		MemberID: mid, Role: m.Role, PVer: m.PVer, CachedAt: nowUnix, Source: "db",
	}
	if m.PVer != tokenPVer {
		return m.Role, m.PVer, false, ErrStalePerm
	}
	return m.Role, m.PVer, false, nil
}

// InvalidateByEvent 是「收到 homeos.permission.updated 时立刻失效」。
func (c *AuthzCache) InvalidateByEvent(mid string) bool {
	if _, ok := c.entries[mid]; ok {
		delete(c.entries, mid)
		return true
	}
	return false
}

var (
	ErrStalePerm = errors.New("3002 permission snapshot stale: token pver != db pver, 请重新登录")
	ErrNoMember  = errors.New("3001 member not found or removed")
)

func main() {
	reset()

	fmt.Println("=== 1. 没有 pver 会发生什么：先看代价 ============ ")
	u := memberTable["m-A"]
	tok := Issue(Claims{UID: "u-001", MID: "m-A", Fam: "fam-A", Role: "owner",
		PVer: u.PVer, Typ: "access", IAT: 1792100000, EXP: 1792100900, JTI: "jti-1"})
	cl, _ := Parse(tok)
	fmt.Printf("  t0  token: mid=%s role=%s pver=%d exp=%d\n",
		cl.MID, cl.Role, cl.PVer, cl.EXP)
	fmt.Println()
	fmt.Println("  t1  管理员把小双从 owner 降级为 member（只改数据库）：")
	fmt.Println("      UPDATE homeos_member SET role='member' WHERE member_id='m-A'")
	u.Role = "member"
	u.PVer++
	fmt.Printf("      → 数据库现在是 role=%s pver=%d\n", u.Role, u.PVer)
	fmt.Println()
	fmt.Println("  t1+30s  小双用**旧的 token** 请求一个需要 owner 权限的接口：")
	fmt.Println("      中间件验签 → 通过（签名没变）")
	fmt.Println("      中间件不查库 → 认为 role 仍是 owner")
	fmt.Println("      → ⚠ 放行了一个已经降权的操作")
	fmt.Println()
	fmt.Println("  这就是问题的全部：**token 是不可撤销的快照**（W14 d07 讲过）。")
	fmt.Println("  pver 的作用就是给这个快照加一个「有效期由数据库说了算」的标记。")

	fmt.Println("\n=== 2. pver 是什么：一个单调递增的整数 ============ ")
	fmt.Println("  它存在 homeos_member 上，含义是「这个成员的权限被改过几次」。")
	fmt.Println("  变更规则（tech-plan §8.1 / PRD 3.7）：")
	rules := []string{
		"改 role（owner ↔ member ↔ ward ↔ guest）→ pver+1",
		"移除成员（软删）→ pver+1",
		"加入家庭 → 从 1 开始",
		"改 member 的其他权限相关字段（到期时间）→ pver+1",
	}
	for _, r := range rules {
		fmt.Printf("    · %s\n", r)
	}
	fmt.Println()
	fmt.Println("  三条纪律：")
	fmt.Println("    ① **单调递增**，永不回退。所以「比大小」比「比相等」更稳：")
	fmt.Println("       token.pver < db.pver → 旧；token.pver == db.pver → 有效；")
	fmt.Println("       token.pver > db.pver → 异常（不该出现），按无效处理。")
	fmt.Println("    ② **每个家庭各自计数**。A 家的 pver 与 B 家无关（d11 讲过）。")
	fmt.Println("    ③ 放在 member 行上，不放在 family 行上 —— 因为角色是成员的属性。")
	fmt.Println()
	fmt.Println("  为什么不放在 family 上？")
	fmt.Println("    放 family 上的话，改任何一个成员都会让**所有**成员的 token 失效。")
	fmt.Println("    一个家庭可能十几个成员，改一次角色就把全家的会话全踢了。")
	fmt.Println("    放 member 上，影响面精确到「这个人的这一个家庭」。")

	fmt.Println("\n=== 3. 真跑：完整时间线 ============ ")
	reset()
	cache := NewCache(60)
	u = memberTable["m-A"]
	fmt.Printf("  数据库初始：mid=m-A role=%s pver=%d\n", u.Role, u.PVer)
	fmt.Println()
	type step struct {
		at    int64
		label string
		run   func() string
	}
	steps := []step{
		{1792100000, "小双用 token 请求 → 缓存未命中，查库并缓存", func() string {
			role, dbP, cached, err := cache.Lookup("m-A", 1, 1792100000)
			return fmt.Sprintf("role=%s db_pver=%d 缓存=%v err=%v", role, dbP, cached, err)
		}},
		{1792100030, "再次请求 → 命中缓存，不再查库", func() string {
			role, dbP, cached, err := cache.Lookup("m-A", 1, 1792100030)
			return fmt.Sprintf("role=%s db_pver=%d 缓存=%v err=%v（DB 查询累计 %d 次）",
				role, dbP, cached, err, cache.queries)
		}},
		{1792100060, "管理员降权：role→member，pver→2", func() string {
			u.Role = "member"
			u.PVer = 2
			return fmt.Sprintf("数据库现在是 role=%s pver=%d（缓存里还是 pver=1）", u.Role, u.PVer)
		}},
		{1792100061, "小双用**旧 token**（pver=1）请求 → 缓存命中但 pver 不符", func() string {
			role, dbP, cached, err := cache.Lookup("m-A", 1, 1792100061)
			return fmt.Sprintf("role=%s db_pver=%d 缓存=%v err=%v", role, dbP, cached, err)
		}},
	}
	for _, s := range steps {
		fmt.Printf("  [%s] %s\n", hhmm(s.at), s.label)
		fmt.Printf("        → %s\n", s.run())
	}
	fmt.Println()
	fmt.Println("  第四步是关键：**缓存命中了，但比对失败**。")
	fmt.Println("  这正是 pver 的价值 —— 它让「权限已变更」这条信息")
	fmt.Println("  能通过缓存传出来，而不是被缓存吞掉。")

	fmt.Println("\n=== 4. 没有事件失效时：延迟 = 缓存 TTL ============ ")
	reset()
	cache2 := NewCache(60)
	u = memberTable["m-A"]
	cache2.Lookup("m-A", 1, 1792100000) // 缓存 pver=1
	u.Role, u.PVer = "member", 2
	fmt.Println("  降权发生在 1792100000，缓存里是 pver=1")
	fmt.Println("  现在模拟「逐秒请求，直到被判出过期」——")
	firstReject := int64(-1)
	for t := int64(1792100001); t <= 1792100120; t++ {
		_, _, _, err := cache2.Lookup("m-A", 1, t)
		if err != nil && firstReject < 0 {
			firstReject = t
		}
	}
	fmt.Printf("  TTL=60 时，第一次被判出在 %s（%d 秒后）\n",
		hhmm(firstReject), firstReject-1792100000)
	fmt.Println()
	fmt.Println("  这就是 PRD 15.6 那句「进程内权限缓存 TTL 60 秒」的实际含义：")
	fmt.Println("  **权限变更的最坏生效延迟 = 60 秒**（除非有事件把它降到 1 秒）。")

	fmt.Println("\n=== 5. 有了事件失效：延迟 ≈ 1 秒 ============ ")
	reset()
	cache3 := NewCache(60)
	u = memberTable["m-A"]
	cache3.Lookup("m-A", 1, 1792100000)
	u.Role, u.PVer = "member", 2
	fmt.Println("  降权 → 发事件 homeos.permission.updated")
	hit := cache3.InvalidateByEvent("m-A")
	fmt.Printf("  各服务订阅后失效本地缓存 → 命中=%v\n", hit)
	_, _, _, err := cache3.Lookup("m-A", 1, 1792100001)
	fmt.Printf("  下一次请求（1 秒后）：err=%v\n", err)
	fmt.Println("  → 延迟从 60 秒降到「下一个请求」，即 PRD 18.2#6 的「≤1 秒」。")
	fmt.Println()
	fmt.Println("  事件的三种投递方式与取舍：")
	fmt.Println("    · NATS JetStream（tech-plan §3.4.6）：本项目采用")
	fmt.Println("      三个服务都订阅 `homeos.permission.updated`，各自清自己的缓存")
	fmt.Println("    · 请求链路同步调用 homeos：❌ 违反架构红线（联动一律走事件）")
	fmt.Println("    · 只靠 60 秒 TTL 不发事件：✅ 可行，但生效延迟是 60 秒不是 1 秒")
	fmt.Println()
	fmt.Println("  本项目选 JetStream，但**缓存失效不是安全边界的唯一保障**：")
	fmt.Println("  万一消息丢了，最坏也只是退回 60 秒 TTL，access 又只有 15 分钟。")
	fmt.Println("  三层叠加：事件（1 秒）+ TTL（60 秒）+ access TTL（15 分钟）。")

	fmt.Println("\n=== 6. pver 不一致时返回什么 ============ ")
	fmt.Println("  候选方案与取舍：")
	fmt.Printf("  %s %s %s\n", pad("HTTP", 8), pad("业务码", 10), "说明")
	fmt.Printf("  %s %s %s\n", pad("401", 8), pad("1005", 10),
		"✅ 本项目采用：token 已失效，请重新登录")
	fmt.Printf("  %s %s %s\n", pad("401", 8), pad("3002", 10),
		"⚠ 可接受，但 3002 在 S5 里表示「权限不足」，语义会混")
	fmt.Printf("  %s %s %s\n", pad("403", 8), pad("3002", 10),
		"❌ 不用：403 表示「你是谁，但你不能做这件事」")
	fmt.Println()
	fmt.Println("  为什么是 401 而不是 403？因为这件事的性质是「你这枚凭证不再代表当前状态」，")
	fmt.Println("  而不是「你这个人没有权限」。前者要重新拿凭证，后者要换一个动作。")
	fmt.Println("  前端收到 401 会自动尝试 refresh，收到 403 只能弹提示 —— ")
	fmt.Println("  而正确的产品体验是「静默刷新，用户无感」。")
	fmt.Println()
	fmt.Println("  ⚠ 但这里有个坑：**refresh 换来的新 token 的 pver 是什么？**")
	fmt.Println("  必须是**数据库里的当前 pver**，而不是 token 里那个旧的。")
	fmt.Println("  如果照抄 token 里的旧值，用户会永远卡在「pver 不一致」的死循环里。")
	fmt.Println("  这正是 refresh 接口必须查一次数据库的原因 ——")
	fmt.Println("  它顺手就把 member 当前的角色与 pver 读出来，直接用来签发新 token。")
	fmt.Println("  于是 pver 不一致的处理闭环是：")
	fmt.Println("    业务接口 401/1005 → 前端静默 refresh → 服务端查库取新 pver → 签发新 token → 重放原请求")
	fmt.Println("  全程用户无感，且新的权限已经生效。")

	fmt.Println("\n=== 7. 缓存的实现：三条纪律 ============")
	disciplines := []struct{ n, rule, why string }{
		{"1", "缓存 key 必须是 member_id（不是 user_id）",
			"同一用户在多个家庭里是不同成员，pver 也不同。用 user_id 会串"},
		{"2", "缓存 value 必须同时存 role 与 pver",
			"只存 pver 不够：命中时 role 也要从缓存拿，否则省不下那次查询"},
		{"3", "写入必须缓存「查库时看到的值」，不能缓存「算出来的值」",
			"如果中间有降级/兜底逻辑被缓存下来，之后会一直用错的"},
	}
	for _, d := range disciplines {
		fmt.Printf("  %s. %s\n", d.n, d.rule)
		fmt.Printf("     %s\n", d.why)
	}
	fmt.Println()
	fmt.Println("  还有一个必须防的：缓存击穿。")
	fmt.Println("  权限变更那一刻，所有并发请求同时缓存未命中 → 全部打到数据库。")
	fmt.Println("  本项目的量级（家庭自托管、单机）不需要 singleflight，")
	fmt.Println("  但 S13 讲并发时会重新遇到它。")

	fmt.Println("\n=== 8. pver 与 S5 的关系：现在只做对，不做全 ============ ")
	fmt.Println("  tech-plan §8.3：P1 只实现三层权限判定（角色矩阵 / module 可见 / 字段级），")
	fmt.Println("  P1 **不做**家庭级覆盖与通用对象级 ACL（响应里恒返回空数组但保留形状）。")
	fmt.Println()
	fmt.Println("  这个取舍对 pver 的影响：")
	fmt.Println("    · 因为只有一层，所以「权限变了」就等价于「这个成员的 role 或 module 配置变了」")
	fmt.Println("    · 两者都触发 pver+1，所以一个 pver 就够用")
	fmt.Println("    · 如果将来实现了 family_overrides，就要引入**两层版本号**")
	fmt.Println("      （家庭级 pver + 成员级 pver），任一变化都应导致失效")
	fmt.Println("  所以现在不要把 pver 设计成「只能表达角色变化」——")
	fmt.Println("  它的名字应该是「权限版本」而不是「角色版本」。")

	fmt.Println("\n=== 9. 与 JS 的对照 ----------")
	fmt.Println("  ① 版本号这个模式 JS 里也有，名字一样：")
	fmt.Println("     Express: if (req.user.version !== db.user.version) throw new StaleError()")
	fmt.Println("     但 JS 的 session 通常存在内存/Redis 里，改完 session 立刻生效，")
	fmt.Println("     所以「版本号」在 JS 的 session 方案里很少需要。")
	fmt.Println("     **JWT 让它重新变得必要** —— 因为 JWT 不可撤销。")
	fmt.Println("  ② 缓存失效：JS 里通常是 `cache.delete(key)` 显式调，")
	fmt.Println("     或者靠 TTL。本项目是「事件订阅 + 显式 delete」，理由相同：")
	fmt.Println("     只靠 TTL 无法满足「≤1 秒生效」这个硬判据。")
	fmt.Println("  ③ Go 里 map 要并发安全：")
	fmt.Println("     本程序的 AuthzCache 用了普通 map，**并发下会 panic**。")
	fmt.Println("     真实实现必须是 sync.Map 或 map + sync.RWMutex。")
	fmt.Println("     这里为了输出确定没有加锁，但 S13 会专门讲这件事 ——")
	fmt.Println("     `go test -race` 会立刻抓出这个问题（tech-plan 10.2 第 5 道门禁）。")

	fmt.Println("\n=== S4 d23 到此结束 ===")
	fmt.Println("明天 W16 收口：把中间件接到真实路由上，并做阶段自查。")
}

func reset() {
	memberTable = map[string]*Member{
		"m-A":  {MemberID: "m-A", UserID: "u-001", FamilyID: "fam-A", Role: "owner", PVer: 1},
		"m-A2": {MemberID: "m-A2", UserID: "u-002", FamilyID: "fam-A", Role: "member", PVer: 1},
		"m-B":  {MemberID: "m-B", UserID: "u-001", FamilyID: "fam-B", Role: "member", PVer: 1},
	}
}

func hhmm(unix int64) string {
	// 1792100000 = 2026-10-15 09:33:20 UTC
	const base = 1792100000
	h := (unix - base) / 60
	m := (unix - base) % 60
	return fmt.Sprintf("t0+%02d:%02d", h, m)
}

var _ = sort.Strings

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

build.add:
// =====================================================================
// S4 · W16 · d23：pver 权限版本号
//
//   解决「改了权限但 token 还没过期」的问题
//   缓存 TTL 与事件失效、真跑一次降权的时间线
// =====================================================================

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strings"
)

// ---------- JWT ----------

var secret = []byte("env:HOMEOS_JWT_SECRET")

const b64a = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"

func b64enc(b []byte) string {
	var sb strings.Builder
	for i := 0; i < len(b); i += 3 {
		var c [3]byte
		n := copy(c[:], b[i:])
		v := uint32(c[0])<<16 | uint32(c[1])<<8 | uint32(c[2])
		sb.WriteByte(b64a[v>>18&63])
		sb.WriteByte(b64a[v>>12&63])
		if n > 1 {
			sb.WriteByte(b64a[v>>6&63])
		} else {
			sb.WriteByte('=')
		}
		if n > 2 {
			sb.WriteByte(b64a[v&63])
		} else {
			sb.WriteByte('=')
		}
	}
	return sb.String()
}

func b64dec(s string) []byte {
	idx := func(c byte) int {
		if c == '=' {
			return -1
		}
		return strings.IndexByte(b64a, c)
	}
	var out []byte
	for i := 0; i+3 < len(s); i += 4 {
		a, b, c, d := idx(s[i]), idx(s[i+1]), idx(s[i+2]), idx(s[i+3])
		v := uint32(a)<<18 | uint32(b)<<12
		if c >= 0 {
			v |= uint32(c) << 6
		}
		if d >= 0 {
			v |= uint32(d)
		}
		out = append(out, byte(v>>16))

		if c >= 0 {
			out = append(out, byte(v>>8))
		}
		if d >= 0 {
			out = append(out, byte(v))
		}
	}
	return out
}

func sigOf(s string) string {
	m := hmac.New(sha256.New, secret)
	m.Write([]byte(s))
	return b64enc(m.Sum(nil))
}

type Claims struct {
	UID  string `json:"uid"`
	MID  string `json:"mid"`
	Fam  string `json:"fam"`
	Role string `json:"role"`
	PVer int    `json:"pver"`
	Typ  string `json:"typ"`
	IAT  int64  `json:"iat"`
	EXP  int64  `json:"exp"`
	JTI  string `json:"jti"`
}

func Issue(c Claims) string {
	hb, _ := json.Marshal(map[string]string{"alg": "HS256", "typ": "JWT"})
	pb, _ := json.Marshal(c)
	signing := b64enc(hb) + "." + b64enc(pb)
	return signing + "." + sigOf(signing)
}

func Parse(tok string) (*Claims, error) {
	p := strings.Split(tok, ".")
	if len(p) != 3 || !hmac.Equal([]byte(p[2]), []byte(sigOf(p[0]+"."+p[1]))) {
		return nil, errors.New("bad signature")
	}
	var c Claims
	if err := json.Unmarshal(b64dec(p[1]), &c); err != nil {
		return nil, err
	}
	return &c, nil
}

// ---------- 数据库 ----------

type Member struct {
	MemberID string
	UserID   string
	FamilyID string
	Role     string
	PVer     int
	Deleted  bool
}

var memberTable = map[string]*Member{} // key = member_id

func memberKey(mid string) string { return mid }

// ---------- 缓存 ----------

// CacheEntry 是一条「某个成员的权限快照」。
type CacheEntry struct {
	MemberID string
	Role     string

	PVer     int
	// CachedAt 是写缓存的时刻（秒）。
	CachedAt int64
	// Source 记录它是被事件失效清掉的，还是自然过期的。
	Source string
}

type AuthzCache struct {
	entries map[string]*CacheEntry
	ttl     int64 // 60 秒（PRD 15.6）
	queries int   // 统计真的打到数据库的次数
}

func NewCache(ttl int64) *AuthzCache {
	return &AuthzCache{entries: map[string]*CacheEntry{}, ttl: ttl}
}

// Lookup 是「用 token 里的 pver 与缓存/数据库比对」的完整逻辑。
func (c *AuthzCache) Lookup(mid string, tokenPVer int, nowUnix int64) (role string, dbPVer int, fromCache bool, err error) {
	e, hit := c.entries[mid]
	if hit && nowUnix-e.CachedAt < c.ttl {
		// 缓存新鲜
		if e.PVer == tokenPVer {
			return e.Role, e.PVer, true, nil
		}
		// 缓存里就是新的 pver，但 token 是旧的 → 权限已变更
		return "", e.PVer, true, ErrStalePerm
	}
	// 缓存过期 → 查库
	c.queries++
	m := memberTable[mid]
	if m == nil || m.Deleted {
		c.entries[mid] = &CacheEntry{MemberID: mid, CachedAt: nowUnix, Source: "db-miss"}
		return "", 0, false, ErrNoMember
	}
	c.entries[mid] = &CacheEntry{
		MemberID: mid, Role: m.Role, PVer: m.PVer, CachedAt: nowUnix, Source: "db",
	}
	if m.PVer != tokenPVer {
		return m.Role, m.PVer, false, ErrStalePerm
	}
	return m.Role, m.PVer, false, nil
}

// InvalidateByEvent 是「收到 homeos.permission.updated 时立刻失效」。
func (c *AuthzCache) InvalidateByEvent(mid string) bool {
	if _, ok := c.entries[mid]; ok {
		delete(c.entries, mid)
		return true
	}
	return false
}

var (
	ErrStalePerm = errors.New("3002 permission snapshot stale: token pver != db pver, 请重新登录")
	ErrNoMember  = errors.New("3001 member not found or removed")
)

func main() {
	reset()

	fmt.Println("=== 1. 没有 pver 会发生什么：先看代价 ============ ")
	u := memberTable["m-A"]
	tok := Issue(Claims{UID: "u-001", MID: "m-A", Fam: "fam-A", Role: "owner",
		PVer: u.PVer, Typ: "access", IAT: 1792100000, EXP: 1792100900, JTI: "jti-1"})

