// ---------- 辅助 ----------

func flipOne(s string) string {
	b := []byte(s)
	i := len(b) - 3
	if b[i] == 'A' {
		b[i] = 'B'
	} else {
		b[i] = 'A'
	}
	return string(b)
}

// bizOfBody 从统一响应体里抽出业务码。
// truncRune 按 rune 边界安全截断（不能直接切字节，否则可能劈开一个多字节字符）。
func truncRune(s string, n int) string {
	rs := []rune(s)
	if len(rs) <= n {
		return s
	}
	return string(rs[:n]) + "…"
}

func bizOfBody(body string) string {
	if !strings.HasPrefix(body, `{"code":`) {
		return "—（无响应体）"
	}
	i := strings.Index(body, `,"message"`)
	if i < 0 {
		return "?"
	}
	return body[8:i]
}

