func noRoleBranchInHandler() bool {
	// listTx / getTx 的源码里不含任何 role 比较。这里用一个可检查的声明代替。
	src := listTxSource + getTxSource
	banned := []string{"== \"owner\"", "== \"member\"", "role ==", "!= \"guest\""}
	for _, b := range banned {
		if strings.Contains(src, b) {
			return false
		}
	}
	return strings.Contains(src, "fam_ctx") &&
		strings.Contains(src, "t.fam == fam") &&
		strings.Contains(src, "!ok || t.fam != fam")
