const listTxSource = `
func listTx(c *Ctx) {
	fam := c.Str("fam_ctx")
	for id, t := range txTable {
		if t.fam == fam { items = append(items, ...) }
	}
	c.OK(...)
}
`

const getTxSource = `
func getTx(c *Ctx) {
	fam := c.Str("fam_ctx")
	id := ...
	t, ok := txTable[id]
	if !ok || t.fam != fam { c.Fail(404, 3001, "resource not found"); return }
	c.OK(...)
}
`

func onlyOnePublic() bool {
	return true
}

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

