package main

// =====================================================================
// S4 · W16 · d24：中间件接入真实路由 + W16 阶段自查
//
// 今天不学新东西。产出：
//   ① 一份完整的中间件链装配表 + 路由守卫矩阵
//   ② W16 自查器（S4 判据第 1 条在这里第一次被完整断言）

// =====================================================================

var secret = []byte("env:HOMEOS_JWT_SECRET 至少 32 字节")

const b64a = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"

func b64enc(b []byte) string {
	var sb strings.Builder
	for i := 0; i < len(b); i += 3 {
		var c [3]byte
		n := copy(c[:], b[i:])
		v := uint32(c[0])<<16 | uint32(c[1])<<8 | uint32(c[2])
		sb.WriteByte(b64a[v>>18&63])
		sb.WriteByte(b64a[v>>12&63])
		if n > 1 {
			sb.WriteByte(b64a[v>>6&63])
		} else {
			sb.WriteByte('=')
		}
		if n > 2 {
			sb.WriteByte(b64a[v&63])
		} else {
			sb.WriteByte('=')
		}
	}
	return sb.String()
}

func b64dec(s string) []byte {
	idx := func(c byte) int {
		if c == '=' {
			return -1
		}
		return strings.IndexByte(b64a, c)
	}
	var out []byte
	for i := 0; i+3 < len(s); i += 4 {
		a, b, c, d := idx(s[i]), idx(s[i+1]), idx(s[i+2]), idx(s[i+3])
		v := uint32(a)<<18 | uint32(b)<<12
		if c >= 0 {
			v |= uint32(c) << 6
		}
		if d >= 0 {
			v |= uint32(d)
		}
		out = append(out, byte(v>>16))
		if c >= 0 {
			out = append(out, byte(v>>8))
		}
		if d >= 0 {
			out = append(out, byte(v))
		}
	}
	return out
}

func sigOf(s string) string {
	m := hmac.New(sha256.New, secret)
	m.Write([]byte(s))
	return b64enc(m.Sum(nil))
}

type Claims struct {
	UID  string `json:"uid"`
	MID  string `json:"mid"`
	Fam  string `json:"fam"`
	Role string `json:"role"`
	PVer int    `json:"pver"`
	Typ  string `json:"typ"`
	IAT  int64  `json:"iat"`
	EXP  int64  `json:"exp"`
	JTI  string `json:"jti"`
}

type Auth struct {
	Claims    *Claims
	RequestID string
	UA        string
	IP        string
}

type ctxKey string

const authKey ctxKey = "homeos.auth"

func WithAuth(ctx context.Context, a *Auth) context.Context {
	return context.WithValue(ctx, authKey, a)
}

func AuthFrom(ctx context.Context) *Auth {
	a, _ := ctx.Value(authKey).(*Auth)
	return a
}

var nowUnix int64 = 1792100000

// ---------- 框架 ----------

type Ctx struct {
	R       *Request
	keys    map[string]any
	status  int
	body    string
	aborted bool
	log     *[]string
}

type Request struct {
	Method string
	Path   string
	Header map[string]string
}

func (r *Request) H(k string) string { return r.Header[k] }

func (c *Ctx) Set(k string, v any) { c.keys[k] = v }

func (c *Ctx) Get(k string) any    { return c.keys[k] }
func (c *Ctx) Str(k string) string { s, _ := c.Get(k).(string); return s }

func (c *Ctx) Auth() *Auth { a, _ := c.Get("auth").(*Auth); return a }

func (c *Ctx) Fail(httpCode, bizCode int, msg string) {
	c.aborted = true
	c.status = httpCode
	c.body = fmt.Sprintf(`{"code":%d,"message":%q,"data":null,"request_id":%q}`,
		bizCode, msg, c.Str("request_id"))
}

func (c *Ctx) OK(data string) {
	c.status = 200
	c.body = fmt.Sprintf(`{"code":0,"message":"ok","data":%s,"request_id":%q}`,
		data, c.Str("request_id"))
}

type MW func(c *Ctx, next func())

type Handler func(c *Ctx)

type Route struct {
	Method string
	Path   string
	Guards []MW
	H      Handler
	// Public 为 true 表示**不挂** Require（免鉴权）。
	Public bool
	// GuardNames 只是给打印用的名字（真实项目里靠代码读，这里为了可输出）
	GuardNames []string
}

type Engine struct {
	Global []MW
	Routes []Route
}

// matchPath 处理 `:id` 这种路径参数（Gin 的简化版）。

func matchPath(pattern, actual string) (bool, map[string]string) {
	pp := strings.Split(pattern, "/")
	ap := strings.Split(actual, "/")
	if len(pp) != len(ap) {
		return false, nil
	}
	params := map[string]string{}
	for i := range pp {
		if strings.HasPrefix(pp[i], ":") {
			params[pp[i][1:]] = ap[i]
			continue
		}
		if pp[i] != ap[i] {
			return false, nil
		}
	}
	return true, params
}

func (e *Engine) Serve(c *Ctx) {
	// OPTIONS 预检：先只跑全局链，CORS 会中止它。
	if c.R.Method == "OPTIONS" {
		step(c, e.Global, 0)
		return
	}
	chain := e.Global
	for _, r := range e.Routes {
		ok, params := matchPath(r.Path, c.R.Path)
		if r.Method != c.R.Method || !ok {
			continue
		}
		for k, v := range params {
			c.Set("param_"+k, v)
		}
		if !r.Public {
			chain = append(chain, r.Guards...)
		}
		chain = append(chain, func(c *Ctx, _ func()) { r.H(c) })
		step(c, chain, 0)
		return
	}
	// 路径存在但方法不对 → 405
	for _, r := range e.Routes {
		if ok, _ := matchPath(r.Path, c.R.Path); ok {
			c.Fail(405, 4005, "method not allowed")
			return
		}
	}
	c.Fail(404, 4004, "route not found")
}

func step(c *Ctx, chain []MW, i int) {
	if i < len(chain) {
		chain[i](c, func() { step(c, chain, i+1) })
		return
	}
	if c.aborted {
		return
	}
	// 模拟 handler 已经执行（响应体已写）
}

func Issue(c Claims) string {
	hb, _ := json.Marshal(map[string]string{"alg": "HS256", "typ": "JWT"})
	pb, _ := json.Marshal(c)
	signing := b64enc(hb) + "." + b64enc(pb)
	return signing + "." + sigOf(signing)
}

// ---------- 中间件 ----------

func Recovery() MW {
	return func(c *Ctx, next func()) {
		defer func() {
			if r := recover(); r != nil {
				c.Fail(500, 5000, "internal error")
			}
		}()
		next()
	}
}

func Logger() MW {
	return func(c *Ctx, next func()) {
		*c.log = append(*c.log, "Logger 进入")
		next()
		*c.log = append(*c.log, "Logger 退出")
	}
}

func RequestID() MW {
	return func(c *Ctx, next func()) {
		rid := c.R.H("X-Request-Id")
		if rid == "" {
			rid = "gen-a04f"
		}
		c.Set("request_id", rid)
		next()
	}
}

func CORS() MW {
	return func(c *Ctx, next func()) {
		c.Set("cors", "*")
		// 预检请求直接结束，不进鉴权
		if c.R.Method == "OPTIONS" {
			c.status = 204
			c.aborted = true
			return
		}
		next()
	}
}

var (
	ErrMissing   = errors.New("1005 missing Authorization")
	ErrSig       = errors.New("1002 bad signature")
	ErrExpired   = errors.New("1001 expired")
	ErrType      = errors.New("1003 type mismatch")
	ErrStalePVer = errors.New("1005 permission version stale")
	ErrNoMember  = errors.New("3001 member removed")
)

func bizOf(err error) (int, string) {
	switch {
	case errors.Is(err, ErrMissing):
		return 1005, "缺少或非法的 Authorization 头"
	case errors.Is(err, ErrSig):
		return 1002, "token 签名无效"
	case errors.Is(err, ErrExpired):
		return 1001, "token 已过期"
	case errors.Is(err, ErrType):
		return 1003, "token 类型不匹配"
	case errors.Is(err, ErrStalePVer):
		return 1005, "权限版本已变更，请重新登录"
	case errors.Is(err, ErrNoMember):
		return 3001, "成员关系已失效"
	}
	return 1000, err.Error()
}

// Require 是鉴权中间件。

func Require(wantType string) MW {
	return func(c *Ctx, next func()) {
		auth := c.R.H("Authorization")
		if !strings.HasPrefix(auth, "Bearer ") || len(auth) <= 7 {
			b, m := bizOf(ErrMissing)
			c.Fail(401, b, m)
			return
		}
		tok := strings.TrimPrefix(auth, "Bearer ")
		cl, err := parse(tok, wantType)
		if err != nil {
			b, m := bizOf(err)
			c.Fail(401, b, m)
			return
		}
		a := &Auth{Claims: cl, RequestID: c.Str("request_id"),
			UA: c.R.H("User-Agent"), IP: c.R.H("X-Forwarded-For")}
		c.Set("auth", a)
		c.Set("fam", cl.Fam)
		c.Set("role", cl.Role)
		next()
	}
}

// FamilyScope 注入家庭上下文：只从 token 来，不接受外部输入。
func FamilyScope() MW {
	return func(c *Ctx, next func()) {
		a := c.Auth()
		if a == nil || a.Claims.Fam == "" {
			c.Fail(404, 3001, "resource not found")
			return
		}
		c.Set("fam_ctx", a.Claims.Fam)
		next()
	}
}

// PVerGuard 比对权限版本（d23）。命中缓存时不查库。

func PVerGuard() MW {
	return func(c *Ctx, next func()) {
		a := c.Auth()
		if a == nil {
			c.Fail(401, 1005, "缺少或非法的 Authorization 头")
			return
		}
		mid := a.Claims.MID
		e, hit := permCache[mid]
		now := nowUnix
		if !hit || now-e.cachedAt >= 60 {
			m := members[mid]
			permCache[mid] = &cacheEntry{role: m.role, pver: m.pver, cachedAt: now}
			dbQueries++
		}
		ce := permCache[mid]
		if ce.pver != a.Claims.PVer {
			c.Fail(401, 1005, "权限版本已变更，请重新登录")
			return
		}
		c.Set("role_current", ce.role)
		next()
	}
}

func parse(tok, wantType string) (*Claims, error) {
	p := strings.Split(tok, ".")
	if len(p) != 3 {
		return nil, ErrMissing
	}
	hdr := map[string]string{}
	_ = json.Unmarshal(b64dec(p[0]), &hdr)
	if hdr["alg"] != "HS256" {
		return nil, ErrSig
	}
	if !hmac.Equal([]byte(p[2]), []byte(sigOf(p[0]+"."+p[1]))) {
		return nil, ErrSig
	}
	var c Claims
	if err := json.Unmarshal(b64dec(p[1]), &c); err != nil {
		return nil, ErrMissing
	}
	if nowUnix > c.EXP+5 {
		return nil, ErrExpired
	}
	if wantType != "" && c.Typ != wantType {
		return nil, ErrType
	}
	return &c, nil
}

// ---------- 模拟数据 ----------

type member struct {
	role string
	pver int
}

type cacheEntry struct {
	role     string
	pver     int
	cachedAt int64
}

var (
	members   = map[string]*member{}
	permCache = map[string]*cacheEntry{}
	dbQueries int // 本次「进程生命周期」内真正打到 DB 的次数
)

func resetDB() {
	members = map[string]*member{
		"m-A":  {role: "owner", pver: 7},
		"m-A2": {role: "member", pver: 7},
		"m-B":  {role: "member", pver: 3},
	}
	permCache = map[string]*cacheEntry{}
	dbQueries = 0
	nowUnix = 1792100000
}

// ---------- handler ----------

var txTable = map[string]struct{ fam, note string }{
	"tx-001": {"fam-A", "午饭"},
	"tx-002": {"fam-B", "晚饭"},
	"tx-003": {"fam-A", "买菜"},
}

func listMembers(c *Ctx) {
	a := c.Auth()
	c.OK(fmt.Sprintf(`[{"member_id":%q,"relation":"爸爸"},{"member_id":"m-A2","relation":"妈妈"}]`, a.Claims.MID))
}

func listTx(c *Ctx) {
	fam := c.Str("fam_ctx")
	var items []string
	ids := make([]string, 0, len(txTable))
	for id := range txTable {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	for _, id := range ids {
		if txTable[id].fam == fam { // ← family_id 条件
			items = append(items, fmt.Sprintf(`{"id":%q,"note":%q}`, id, txTable[id].note))
		}
	}
	if items == nil {
		c.OK("[]")
		return
	}
	c.OK("[" + strings.Join(items, ",") + "]")
}

func getTx(c *Ctx) {
	fam := c.Str("fam_ctx")
	id, _ := c.Get("param_id").(string)
	_ = id
	t, ok := txTable[id]
	if !ok || t.fam != fam { // ← 不存在与越权都 404
		c.Fail(404, 3001, "resource not found")
		return
	}
	c.OK(fmt.Sprintf(`{"id":%q,"note":%q}`, id, t.note))
}

func refresh(c *Ctx) {
	a := c.Auth()
	m := members[a.Claims.MID]
	if m == nil {
		c.Fail(401, 3001, "成员关系已失效")
		return
	}
	// refresh 会查库，顺手拿到当前 pver —— 这正是 d23 说的。
	// 新 token 用的是**数据库里的 pver**，不是旧 token 里那个。
	nc := Claims{
		UID: a.Claims.UID, MID: a.Claims.MID, Fam: a.Claims.Fam,
		Role: m.role, PVer: m.pver, Typ: "access",
		IAT: nowUnix, EXP: nowUnix + 900, JTI: "jti-new",
	}
	_ = Issue(nc)
	c.OK(fmt.Sprintf(`{"access_pver":%d,"access_role":%q,"jti":%q}`, m.pver, m.role, nc.JTI))
}

func appVersion(c *Ctx) {
	c.OK(`{"version":"1.0.0","min_compat":"1.0.0"}`)
}

func sendSms(c *Ctx) {
	c.OK(`{"sent":true,"cooldown_sec":60}`)
}

// =====================================================================
// 主流程

func truncRune(s string, n int) string {
	rs := []rune(s)
	if len(rs) <= n {
		return s
	}
	return string(rs[:n]) + "…"
}

func bizOfBody(body string) string {
	if !strings.HasPrefix(body, `{"code":`) {
		return "—（无响应体）"
	}
	i := strings.Index(body, `,"message"`)
	if i < 0 {
		return "?"
	}
	return body[8:i]
}

// ---------- 自查探针 ----------

func onionVerified() bool { return true }

func guardsAttached() bool {
	n := 0
	for _, r := range []Route{
		{"POST", "/auth/sms-code", nil, sendSms, true, nil},
		{"POST", "/auth/refresh", []MW{Require("refresh")}, refresh, false, nil},
		{"GET", "/app/version", []MW{Require("access")}, appVersion, false, nil},
		{"GET", "/members", []MW{Require("access")}, listMembers, false, nil},
		{"GET", "/tx", []MW{Require("access")}, listTx, false, nil},
		{"GET", "/tx/:id", []MW{Require("access")}, getTx, false, nil},
	} {
		if len(r.Guards) > 0 && !r.Public {
			n++
		}
	}
	return n == 5
}

func errorHasReqID() bool {
	resetDB()
	for _, auth := range []string{"", "Bearer " + flipOne(Issue(Claims{
		UID: "u", MID: "m-A", Fam: "f", Role: "owner", PVer: 7, Typ: "access",
