		log := []string{}
		ctx := &Ctx{R: &Request{Method: "GET", Path: "/api/homeos/members",
			Header: map[string]string{"Authorization": auth, "X-Request-Id": "rid-1"}},
			keys: map[string]any{}, status: 200, log: &log}
		(&Engine{Global: []MW{Recovery(), RequestID()},
