}

func famFromTokenOnly() bool {
	resetDB()
	tokA := Issue(Claims{UID: "u-001", MID: "m-A", Fam: "fam-A", Role: "owner",
		PVer: 7, Typ: "access", IAT: nowUnix, EXP: nowUnix + 900, JTI: "a"})
