	}
	fmt.Println()
	fmt.Println("  关键结论：**本项目因为 access 走 Authorization 头而不是 Cookie，")
	fmt.Println("  CSRF 风险天然就低。** 但 refresh 必须在 Cookie 里（否则 XSS 能读到它），")
	fmt.Println("  所以 refresh 那条路径必须有 CSRF 防御。三层都要有，不是因为有风险，")
	fmt.Println("  而是因为「没有攻击路径」和「有防御」是两件事 —— 前者依赖客户端行为，后者依赖服务端。")

	fmt.Println("\n=== 3. 漏洞三：日志泄露 —— 真跑一遍 ============ ")
	fmt.Println("  两个 logger，同样的输入，一个脱敏一个不脱敏：")
	fmt.Println()
	rawTok := "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1aWQiOiJ1LTAwMSIsImZhbSI6ImZhbS0wMDEwMDEifQ.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c"
	inputs := []string{
