		safe := &Logger{Safe: true}
		unsafe.Log("%s", in)
		safe.Log("%s", in)
		show := func(s string) string {
			r := []rune(s)
			if len(r) > 96 {
				return string(r[:94]) + "…"
			}
			return s
		}
		fmt.Printf("    原始  : %s\n", show(unsafe.lines[0]))
		fmt.Printf("    脱敏后: %s\n\n", show(safe.lines[0]))
	}
	fmt.Println("  对照结论：")
	fmt.Println("    · token：必须脱敏。日志保留 6 个月（PRD 21.4），")
	fmt.Println("      一枚 refresh 泄露的有效期是 30 天，日志泄露窗口远长于它。")
	fmt.Println("    · 手机号：必须脱敏。它是 L2 敏感数据，且日志无法按用户请求删除。")
