		{"09", "每条路由必须挂 guard",
			"扫 router.go 里的注册调用，除 /auth/* 白名单外必须有中间件",
			"新加路由忘挂中间件是最高频的漏洞"},
		{"08", "CORS 不得为 *",
			"grep -rn 'Access-Control-Allow-Origin.*\\*' srv/",
			"配置文件里的一行，review 时最容易看漏"},
		{"11", "生产包不含验证码回显",
			"构建后 grep 二进制里是否含 debug_sms_code 符号",
			"「方便测试」的开关忘了关是经典事故"},
		{"12", "前端 bundle 里不出现 JWT secret",
			"grep -rn 'HOMEOS_JWT_SECRET' web/",
			"密钥进 git 仓库比进 bundle 更糟，两者都要拦"},
	}
	for _, m := range mechanical {
		fmt.Printf("  ▸ %s  %s\n", m.id, m.rule)
		fmt.Printf("      怎么查：%s\n", m.how)
		fmt.Printf("      为什么必须机械拦：%s\n", m.whyIt)
	}
	fmt.Println()
	fmt.Println("  对照 tech-plan §10.2 的五道门禁，这六条应该归进门禁 4「分域与鉴权门禁」。")
