		{"5", "中间人抓包", "HTTPS（Nginx 终止 TLS）+ HSTS"},
		{"6", "拿到 refresh 后长期续期", "轮换链 + 改密全链失效（W15）"},
		{"7", "降权用户仍能操作", "pver 比对，≤60 秒（d23）"},
		{"8", "读取别的家庭的数据", "WHERE family_id = ctx.fam，越权返 404（d22）"},
	}
	for _, c := range chain {
		fmt.Printf("  第 %s 步  %s\n", c.step, c.action)
		fmt.Printf("         被什么挡住：%s\n", c.blockedBy)
