package main

// =====================================================================
// S4 · W17 · d25：常见鉴权漏洞盘点
//
//   token 放哪（为什么不能放 localStorage）/ CSRF / 日志泄露
//
// 本程序用**真跑**的实验演示三条漏洞链，不是只列清单。

type BrowserStore struct {
	LocalStorage   map[string]string // 任何 JS 都能读
	SessionStorage map[string]string
	Cookies        map[string]Cookie
}

type Cookie struct {
	Value    string
	HttpOnly bool // JS 读不到
	Secure   bool
	SameSite string // Strict / Lax / None
	Path     string
	MaxAge   int
}

func newBrowser() *BrowserStore {
	return &BrowserStore{
		LocalStorage: map[string]string{}, SessionStorage: map[string]string{},
		Cookies: map[string]Cookie{},
	}
}

// attackXSS 模拟一段注入到页面里的第三方脚本。
// 它能调用 setToken / getToken —— 因为 localStorage 对它完全开放。

func attackXSS(b *BrowserStore) string {
	stolen := b.LocalStorage["access_token"]
	b.LocalStorage["access_token"] = "" // 顺便用掉它，让受害者察觉不到
	return stolen
}

// =====================================================================
// 漏洞二：CSRF —— Cookie 会自动带上，Authorization 头不会
// =====================================================================

type BrowserRequest struct {
	Method  string
	URL     string
	Headers map[string]string
	// AutoHeaders 是浏览器**自动**加上的请求头（Cookie）。
	// 攻击者的 JS / 表单无法控制它们。
	AutoHeaders map[string]string
}

// DoRequest 模拟浏览器发请求并到达服务端。
// 服务端只检查「有没有凭证」，不检查「这个凭证是不是**这次操作**带来的」。

func DoRequest(r BrowserRequest) (int, string) {
	// 服务端的 cookie jar
	serverCookies, _ := r.AutoHeaders["Cookie"]
	if r.Headers["Authorization"] != "" {
		if strings.HasPrefix(r.Headers["Authorization"], "Bearer ") {
			return 200, `{"code":0,"message":"ok"}`
		}
		return 401, `{"code":1005,"message":"bad Authorization"}`
	}
	if serverCookies != "" && strings.Contains(serverCookies, "session=") {
		return 200, `{"code":0,"message":"ok"}` // ← 没有 CSRF 校验，Cookie 自动认证
	}
	return 401, `{"code":1005,"message":"not authenticated"}`
}

// =====================================================================
// 漏洞三：日志泄露

// =====================================================================

type Logger struct {
	lines []string
	// Safe 表示这个 logger 会做脱敏。
	Safe bool
}

func (l *Logger) Log(format string, args ...any) {
	msg := fmt.Sprintf(format, args...)
	if l.Safe {
		msg = redact(msg)
	}
	l.lines = append(l.lines, msg)
}

func redact(s string) string {
	// 脱敏：把 JWT 换成 <redacted>
	if i := strings.Index(s, "eyJ"); i >= 0 {
		end := i
		for end < len(s) && s[end] != ' ' && s[end] != '"' {
			end++
		}
		return s[:i] + "<redacted-jwt:" + fmt.Sprint(end-i) + ">" + s[end:]
	}
	// 手机号脱敏：逐个扫描 11 位数字串，命中就替换并跳过这 11 位
	// （不能原地 copy —— 两次替换的长度不一致会导致后面的匹配被破坏）
	r := []rune(s)
	var out []rune
	for i := 0; i < len(r); {
		if i+11 <= len(r) {
			ok := true
			for k := 0; k < 11; k++ {
				if r[i+k] < '0' || r[i+k] > '9' {
					ok = false
					break
				}
			}
			if ok {
				out = append(out, []rune(r[i:i+3])...)
				out = append(out, []rune("****")...)
				out = append(out, []rune(r[i+7:i+11])...)
				i += 11
				continue
			}
		}
		out = append(out, r[i])
		i++
	}
	return string(out)
}

// =====================================================================
// 漏洞四：其他三类（用表格 + 可判定的检查）
// =====================================================================

type Finding struct {
