func main() {
	fmt.Println("=== 1. 漏洞一：localStorage 里的 token，一次 XSS 全完 ============ ")
	fmt.Println("  场景：页面引了一个第三方统计脚本，它被注入了 3 行代码。")
	b := newBrowser()
	b.LocalStorage["access_token"] = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1aWQiOiJ1LTAwMSJ9.SIG"
	b.LocalStorage["refresh_token"] = "rt_u-001_000123.eyJhbGciOiJIUzI1NiJ9.eyJ0eXAiOiJyZWZyZXNoIn0.SIG"
	b.LocalStorage["family_id"] = "fam-A"
	fmt.Println("  注入前 localStorage：")
	for _, k := range []string{"access_token", "refresh_token", "family_id"} {
		v := b.LocalStorage[k]
		if len(v) > 34 {
			v = v[:34] + "..."
		}
		fmt.Printf("    %-16s = %s\n", k, v)
	}
	stolen := attackXSS(b)
	fmt.Println()
	fmt.Println("  注入的脚本执行 `localStorage.getItem('access_token')`：")
	fmt.Printf("    拿到 %s\n", stolen[:34]+"...")
	fmt.Printf("    拿到 refresh = %s...\n", b.LocalStorage["refresh_token"][:16])
	fmt.Println()
	fmt.Println("  攻击者拿到 access 后能做什么：读这个用户的所有数据（直到 15 分钟后过期）")
	fmt.Println("  攻击者拿到 refresh 后能做什么：**再要 30 天** —— 它可以自己换新的")
	fmt.Println("  这就是「refresh 危害远大于 access」的量化含义：30 天 vs 15 分钟，差 2880 倍。")
	fmt.Println()
	fmt.Println("  正确的存放方式：")
	stores := []struct{ where, access, refresh, note string }{
		{"内存变量（JS 对象）", "✅ 放这里", "❌", "页面刷新就没了 —— 这是特性，access 本来就 15 分钟"},
		{"localStorage", "❌ 禁", "❌ 禁", "XSS 可读。S4 明令禁止"},
		{"sessionStorage", "⚠ 可接受", "❌ 禁", "关掉标签页就没了，能挡掉一部分 XSS 持久化"},
		{"Cookie HttpOnly", "—", "✅ 放这里", "JS 读不到，XSS 拿不走（这是它唯一的价值）"},
	}
	fmt.Printf("  %s %s %s %s\n", pad("位置", 20), pad("access", 12), pad("refresh", 12), "说明")
	for _, s := range stores {
		fmt.Printf("  %s %s %s %s\n", pad(s.where, 20), pad(s.access, 12), pad(s.refresh, 12), s.note)
	}
	fmt.Println()
	fmt.Println("  为什么「放内存」可以接受？因为前端本来就知道自己有没有登录：")
	fmt.Println("  登录状态用**用户级**信息表示（user_id、nickname），")
	fmt.Println("  而凭证只是「兑换券」。刷新后前端不知道登录态怎么办？")
	fmt.Println("  → **静默调 refresh**（refresh 在 HttpOnly Cookie 里，自动带上）。")
	fmt.Println("  → 用户完全无感。这就是 d13 讲的双 token 设计在存储层的直接回报。")

	fmt.Println("\n=== 2. 漏洞二：CSRF —— Cookie 认证的固有代价 ============ ")
	fmt.Println("  先看清差别：浏览器**自动**加的请求头，攻击者的 JS 控制不了。")
	demo := []struct {
		name string
		req  BrowserRequest
	}{
		{"用户正常操作：JS 带 Authorization 头", BrowserRequest{
			Method: "POST", URL: "/api/homeos/members",
			Headers: map[string]string{"Authorization": "Bearer eyJ..."},
		}},
		{"CSRF：攻击者页面里的表单提交", BrowserRequest{
			Method:  "POST",
			URL:     "https://evil.com/csrf",
			Headers: map[string]string{"Content-Type": "application/x-www-form-urlencoded"},
			// 浏览器自动把 homecube 的 cookie 带上了 —— 攻击者无法阻止这一点
			AutoHeaders: map[string]string{"Cookie": "session=abc123"},
		}},
		{"CSRF：用 fetch + credentials:include", BrowserRequest{
			Method:  "POST",
			URL:     "https://evil.com/csrf",
			Headers: map[string]string{"Content-Type": "application/json"},
			// 这条在有 SameSite 时不会带上 Cookie，但服务端仍应独立校验
			AutoHeaders: map[string]string{},
		}},
	}
	for _, d := range demo {
		code, body := DoRequest(d.req)
		fmt.Printf("  %-38s → %d %s\n", d.name, code, body)
	}
	fmt.Println()
	fmt.Println("  第二条是真正的 CSRF：请求从 evil.com 发出，")
	fmt.Println("  但服务端看到的凭证是**用户的 Cookie**，于是以为用户在操作。")
	fmt.Println()
	fmt.Println("  三层防御，缺一不可：")
	defs := []struct{ layer, how, blocks, note string }{
		{"① SameSite Cookie", "Set-Cookie: refresh=...; HttpOnly; Secure; SameSite=Strict",
			"跨站请求根本不带 Cookie",
			"最省事的一层。SameSite=Lax 也能挡掉大部分（非 GET 的跨站请求）"},
		{"② 自定义请求头", "要求写操作带 X-Requested-With: XMLHttpRequest",
			"跨站表单发不了自定义头（触发预检，预检又被 CORS 拒）",
			"本项目采用。它配合「Authorization 头而非 Cookie」时其实是冗余的"},
		{"③ Origin/Referer 校验", "校验 Origin 是否在白名单",
			"伪造不了 —— 浏览器会自己填真实 origin",
			"作为第二层兜底，成本极低"},
	}
	for _, d := range defs {
		fmt.Printf("  ▸ %s\n", d.layer)
		fmt.Printf("      做法：%s\n", d.how)
		fmt.Printf("      挡住：%s\n", d.blocks)
		fmt.Printf("      %s\n", d.note)
	}
	fmt.Println()
	fmt.Println("  关键结论：**本项目因为 access 走 Authorization 头而不是 Cookie，")
	fmt.Println("  CSRF 风险天然就低。** 但 refresh 必须在 Cookie 里（否则 XSS 能读到它），")
	fmt.Println("  所以 refresh 那条路径必须有 CSRF 防御。三层都要有，不是因为有风险，")
	fmt.Println("  而是因为「没有攻击路径」和「有防御」是两件事 —— 前者依赖客户端行为，后者依赖服务端。")

	fmt.Println("\n=== 3. 漏洞三：日志泄露 —— 真跑一遍 ============ ")
	fmt.Println("  两个 logger，同样的输入，一个脱敏一个不脱敏：")
	fmt.Println()
	rawTok := "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1aWQiOiJ1LTAwMSIsImZhbSI6ImZhbS0wMDEwMDEifQ.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c"
	inputs := []string{
		fmt.Sprintf(`[auth] user login ok, Authorization: Bearer %s`, rawTok),
		fmt.Sprintf(`[auth] verifying token %s`, rawTok),
		`[auth] sms sent to 13800000001 purpose=login`,
		`[auth] user 13800000002 login failed, password mismatch`,
	}
	for _, in := range inputs {
		unsafe := &Logger{}
		safe := &Logger{Safe: true}
		unsafe.Log("%s", in)
		safe.Log("%s", in)
		show := func(s string) string {
			r := []rune(s)
			if len(r) > 96 {
				return string(r[:94]) + "…"
			}
			return s
		}
		fmt.Printf("    原始  : %s\n", show(unsafe.lines[0]))
		fmt.Printf("    脱敏后: %s\n\n", show(safe.lines[0]))
	}
	fmt.Println("  对照结论：")
	fmt.Println("    · token：必须脱敏。日志保留 6 个月（PRD 21.4），")
	fmt.Println("      一枚 refresh 泄露的有效期是 30 天，日志泄露窗口远长于它。")
	fmt.Println("    · 手机号：必须脱敏。它是 L2 敏感数据，且日志无法按用户请求删除。")
	fmt.Println()
	fmt.Println("  Nginx 层的具体配置（很多人漏掉这一处）：")
	fmt.Println("    # 默认配置会把 Authorization 头写进 access log")
	fmt.Println("    log_format safe '$remote_addr - $request_method $uri $status $request_time';")
	fmt.Println("    access_log /var/log/nginx/access.log safe;")
	fmt.Println("    # 这样 $http_authorization 根本没被 log_format 引用，就不会被记录。")
	fmt.Println("  这比「写了之后再过滤」更可靠 —— 因为过滤逻辑一旦漏了一条规则就泄露了。")

	fmt.Println("\n=== 4. 十二条漏洞的完整清单 ============ ")
	sorted := make([]Finding, len(findings))
	copy(sorted, findings)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].ID < sorted[j].ID })
	fmt.Printf("  %s %s %s %s\n", pad("#", 4), pad("漏洞", 30), pad("位置", 8), "后果")
	for _, f := range sorted {
		fmt.Printf("  %s %s %s %s\n", pad(f.ID, 4), pad(f.Name, 30), pad(f.Where, 8), f.Evidence)
	}
	fmt.Println()
	fmt.Println("  逐条的修法：")
	for _, f := range sorted {
		fmt.Printf("  %s %s\n", pad(f.ID, 4), f.Fix)
	}

	fmt.Println("\n=== 5. 哪些必须由 CI 机械拦截 ============ ")
	mechanical := []struct {
		id    string
		rule  string
		how   string
		whyIt string
	}{
		{"01", "前端代码里不出现 localStorage.setItem('access_token'|'refresh_token')",
			"grep -rn \"localStorage.setItem.*token\" web/",
			"这是最容易被「临时调试」留下的漏洞，必须机械拦"},
		{"04", "日志里不出现整枚 token",
			"grep -rn 'Authorization.*%s\\|Bearer.*%v\\|token.*%s' srv/ | grep -i log",
			"人工 review 一定会漏 —— 日志语句太常见了"},
		{"09", "每条路由必须挂 guard",
			"扫 router.go 里的注册调用，除 /auth/* 白名单外必须有中间件",
			"新加路由忘挂中间件是最高频的漏洞"},
		{"08", "CORS 不得为 *",
			"grep -rn 'Access-Control-Allow-Origin.*\\*' srv/",
			"配置文件里的一行，review 时最容易看漏"},
		{"11", "生产包不含验证码回显",
			"构建后 grep 二进制里是否含 debug_sms_code 符号",
			"「方便测试」的开关忘了关是经典事故"},
		{"12", "前端 bundle 里不出现 JWT secret",
			"grep -rn 'HOMEOS_JWT_SECRET' web/",
			"密钥进 git 仓库比进 bundle 更糟，两者都要拦"},
	}
	for _, m := range mechanical {
		fmt.Printf("  ▸ %s  %s\n", m.id, m.rule)
		fmt.Printf("      怎么查：%s\n", m.how)
		fmt.Printf("      为什么必须机械拦：%s\n", m.whyIt)
	}
	fmt.Println()
	fmt.Println("  对照 tech-plan §10.2 的五道门禁，这六条应该归进门禁 4「分域与鉴权门禁」。")
	fmt.Println("  它现在列的是「路由全在 /api/{code}/*；handler 内无自写角色判定」——")
	fmt.Println("  d25 这六条是它的自然扩展，也是本项目该补的。")

	fmt.Println("\n=== 6. 一个攻击者的完整链路：把这些串起来 ============ ")
	fmt.Println("  假设攻击者拿到了一个普通用户的邮箱，且知道 App 在用验证码登录：")
	chain := []struct {
		step, action, blockedBy string
	}{
		{"1", "撞库：批量尝试手机号+密码", "d28 锁定 + d27 限流：5 次失败即锁"},
		{"2", "短信轰炸：大量调用 sms-code", "每分钟 1 次 + 每天 10 次（d04）"},
		{"3", "钓鱼：伪造登录页收集验证码", "PRD 20.4 的合规文本 + 用户教育，服务端管不了"},
		{"4", "XSS 偷 token", "token 存内存 + refresh 在 HttpOnly Cookie（d25）"},
		{"5", "中间人抓包", "HTTPS（Nginx 终止 TLS）+ HSTS"},
		{"6", "拿到 refresh 后长期续期", "轮换链 + 改密全链失效（W15）"},
		{"7", "降权用户仍能操作", "pver 比对，≤60 秒（d23）"},
		{"8", "读取别的家庭的数据", "WHERE family_id = ctx.fam，越权返 404（d22）"},
	}
	for _, c := range chain {
		fmt.Printf("  第 %s 步  %s\n", c.step, c.action)
		fmt.Printf("         被什么挡住：%s\n", c.blockedBy)
	}
	fmt.Println()
	fmt.Println("  这条链上有 6 步被本阶段的技术措施挡住，2 步（钓鱼、合规）超出服务端范围。")
	fmt.Println("  **安全不是某一个环节做对了，而是每一环都让上一环的成本变高。**")
	fmt.Println("  这也是为什么 tech-plan 22.2 的架构红线不接受「先这样以后再改」——")
	fmt.Println("  因为「以后再改」意味着中间那几环现在是敞开的。")

	fmt.Println("\n=== 7. 与 JS 的对照 ============ ")
	fmt.Println("  ① 本地存储的安全性完全取决于框架：")
	fmt.Println("     localStorage     → 任何脚本可读（含 XSS）")
	fmt.Println("     sessionStorage   → 同上，但生命周期短")
	fmt.Println("     IndexedDB        → 同上")
	fmt.Println("     HttpOnly Cookie  → JS 读不到 ✅")
	fmt.Println("     WebCrypto 加密后存 localStorage → 密钥也在前端，等于没加密")
	fmt.Println("     最后一个是常见的自欺欺人：把 token 用 AES 加密存 localStorage，")
	fmt.Println("     密钥硬编码在 bundle 里。攻击者读 bundle 就拿到密钥。")
	fmt.Println()
	fmt.Println("  ② CSRF 防护库：JS 生态有 csurf、csrf-csrf 等，Go 没有标准库实现。")
	fmt.Println("     本项目手写 SameSite + Origin 校验即可，不需要引入依赖。")
	fmt.Println("     tech-plan §22.1 第 2 条：任何加中间件都要评审。")
	fmt.Println()
	fmt.Println("  ③ 敏感信息扫描：Go 这边靠 grep + golangci-lint 的 gosec 规则。")
	fmt.Println("     JS 这边靠 eslint 的 no-eval / detect-non-literal-regexp 之类。")
	fmt.Println("     两者都只是辅助 —— 真正的防线是 review 时问「这行会不会进日志」。")

	fmt.Println("\n=== S4 d25 到此结束 ===")
	fmt.Println("明天讲 401 vs 403 的区别与本项目的返回约定 —— ")
	fmt.Println("今天提到的「越权返 404」会给出完整的码表。")
}

// pad 按显示宽度左对齐补空格（中文占 2 列）

func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

