package main

// =====================================================================
// S4 · W17 · d26：401 vs 403 的区别与本项目的返回约定
//
//   三种「拒绝」的语义差异、完整错误码表、前端该做什么
// =====================================================================

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// =====================================================================
// 拒绝的三种形态
// =====================================================================

type RejectKind int

const (
	RejectUnauthorized RejectKind = iota // 401：你是谁？
	RejectForbidden                      // 403：你是谁，但你不能
	RejectNotFound                       // 404：东西不存在（或者你没权限看）
)

func (k RejectKind) String() string {
	switch k {
	case RejectUnauthorized:
		return "401 Unauthorized"
	case RejectForbidden:
		return "403 Forbidden"
	default:
		return "404 Not Found"
	}
}

// Resource 是一个「资源」。关键：**只有 owner 与 viewer 知道它存在**。
type Resource struct {
	ID        string
	OwnerID   string
	FamilyID  string
	ViewerIDs []string // 可以读的人
	WriterIDs []string // 可以改的人
	Deleted   bool
}

type Subject struct {
	UserID string
	// Authed 表示凭证有效；Identified 表示凭证有效且能识别出是谁。
	Identified bool
}

// Decide 是本项目「统一返回约定」的实现。
// 输入：请求的方法、目标资源、当前用户、要做的动作。
// 输出：HTTP 状态、业务码、以及**给不给��露存在性**的判断依据。
type Decision struct {
	HTTP      int
	BizCode   int
	Message   string
	Action    string // 前端该做什么
	Leaks     bool   // 这个返回是否泄露了「资源存在」
	Rationale string
}

var (
	// —— 401 段（tech-plan §6.2 的 1001-1010）——
	CodeTokenExpired   = 1001
	CodeRefreshInvalid = 1002
	CodeTypeMismatch   = 1003
	CodeTokenRevoked   = 1004
	CodeNoAuthHeader   = 1005
	CodeNotYetValid    = 1006
	// —— 3001-3004（家庭与成员）——
	CodeNoSuchFamily = 3001
	CodeNoPermission = 3002
	// —— 4001-4002（业务规则）——
	CodeBizConflict = 4001
	// —— 0 / 5000 ——
	CodeOK      = 0
	CodeServer  = 5000
	CodeUnknown = 4004
)

// Decide 判定：这是本项目 W17 最重要的一段逻辑。
func Decide(sub Subject, res *Resource, action string) Decision {
	// 规则一：身份不明 → 401。这一步与资源存不存在**无关**。
	if !sub.Identified {
		return Decision{
			HTTP: 401, BizCode: CodeNoAuthHeader,
			Message:   "缺少或无效的 Authorization 头",
			Action:    "access 过期 → 静默 refresh；refresh 无效 → 清本地登录态，回登录页",
			Leaks:     false,
			Rationale: "「你是谁」都无法回答时不该谈资源 —— 401 与资源无关，",
		}
	}

	// 规则二：资源不存在或已软删 → 404
	if res == nil || res.Deleted {
		return Decision{
			HTTP: 404, BizCode: CodeNoSuchFamily,
			Message:   "resource not found",
			Action:    "提示「内容不存在或已删除」；不要提示「无权限」",
			Leaks:     false,
			Rationale: "真的不存在与无权访问返回**完全相同**的响应体 —— 这是 non-enumeration",
		}
	}

	// 规则三：资源存在但没有这个家庭 → 也 404（不泄露「它存在但不属于你」）
	if res.FamilyID != subFamily(sub) {
		return Decision{
			HTTP: 404, BizCode: CodeNoSuchFamily,
			Message:   "resource not found",
			Action:    "同上。用户不应该知道「这个 id 在别的家庭存在」",
			Leaks:     false,
			Rationale: "跨家庭访问一律 404（tech-plan §6.2 / PRD 3.4.1 多租户隔离）",
		}
	}

	// 到这里才允许区分：资源在你家，且你知道它存在。
	// —— 这是一个**已知存在**的资源，403 在这里是安全的。
	allowed := false
	switch action {
	case "read":
		allowed = contains(res.ViewerIDs, sub.UserID)
	case "write":
		allowed = contains(res.WriterIDs, sub.UserID)
	}
	if !allowed {
		return Decision{
			HTTP: 403, BizCode: CodeNoPermission,
			Message:   fmt.Sprintf("当前角色（%s）不能%s这个对象", subRole(sub), action),
			Action:    "提示「你没有这个操作的权限」；同时落审计（PRD 15.6）",
			Leaks:     false,
			Rationale: "调用方已经知道这个对象存在（他就是在操作它），403 不泄露新信息",
		}
	}

	return Decision{0, CodeOK, "ok", "正常返回", false, "通过"}
}

// subject 的家庭与角色：本程序从 token 里取。
func subFamily(s Subject) string { return subjectFamily[s.UserID] }
func subRole(s Subject) string   { return subjectRole[s.UserID] }

var (
	subjectFamily = map[string]string{"u-owner": "fam-A", "u-member": "fam-A", "u-x": "fam-B"}
	subjectRole   = map[string]string{"u-owner": "owner", "u-member": "member", "u-x": "owner"}
)

func contains(list []string, v string) bool {
	for _, x := range list {
		if x == v {
			return true
		}
	}
	return false
}

// =====================================================================
// 完整错误码表
// =====================================================================

type CodeRow struct {
	HTTP     int
	Code     int
	Meaning  string
	Kind     string
	Frontend string
}

func codeTable() []CodeRow {
	return []CodeRow{
		{401, CodeTokenExpired, "token 已过期", "认证",
			"静默 refresh → 成功则重放原请求；失败则转 1002 处理"},
		{401, CodeRefreshInvalid, "refresh 无效 / 已撤销 / 已重放", "认证",
			"清掉本地登录态，回登录页。不要重试（重试也是一样的错）"},
		{401, CodeTypeMismatch, "token 类型不匹配", "认证",
			"这是客户端 bug。记日志上报，不给用户看技术细节"},
		{401, CodeTokenRevoked, "token 已被撤销", "认证",
			"清登录态，回登录页。提示「你的账号在其他设备登录过」"},
		{401, CodeNoAuthHeader, "缺少或非法 Authorization 头", "认证",
			"同上。可能是用户清过缓存"},
		{401, CodeNotYetValid, "token 尚未生效（时钟漂移）", "认证",
			"自动重试一次；连续失败则当 1005 处理"},
		{429, 1003, "触发限流", "认证",
			"读 Retry-After 秒数，显示倒计时，不要自动重试"},
		{404, CodeNoSuchFamily, "资源不存在 / 不属于你 / 已删除", "家庭",
			"统一提示「内容不存在或已删除」。**不要**提示无权限"},
		{403, CodeNoPermission, "你知道它存在，但你不能做这个操作", "家庭",
			"提示权限不足；落审计；连续 5 次通知管理员（PRD 15.6）"},
		{409, CodeBizConflict, "业务冲突（版本、唯一约束等）", "业务",
			"按具体业务码给提示；版本冲突要提示「数据已被他人修改，请刷新」"},
		{400, 4000, "参数格式错误", "业务",
			"把出错字段与规则回给前端，让它就地高亮"},
		{400, 4001, "业务规则不满足（密码强度、余额非 0 不能归档）", "业务",
			"把违规的规则名回给前端，让它就地高亮"},
		{405, 4005, "方法不允许", "路由",
			"客户端 bug，通常不该出现"},
		{500, CodeServer, "服务端错误", "服务端",
			"提示「服务开小差了」+ request_id；**不展示** panic 细节"},
		{500, CodeUnknown, "路由不存在", "路由",
			"客户端 bug"},
	}
}

// =====================================================================
// 主流程
// =====================================================================

func main() {
	fmt.Println("=== 1. 三种「拒绝」的语义：一句话区分 ============ ")
	kinds := []struct {
		k        RejectKind
		question string
		means    string
		askAgain string
	}{
		{RejectUnauthorized, "你是谁？", "凭证无效或缺失", "换一个凭证再来"},
		{RejectForbidden, "你是谁？你能吗？", "身份清楚，但这个操作不允许", "换个操作或换个人来"},
		{RejectNotFound, "有没有这个东西？", "答案必须是「没有」", "不用再试了"},
	}
	for _, k := range kinds {
		fmt.Printf("  %-20s 问的是「%s」\n", k.k, k.question)
		fmt.Printf("  %-20s 含义：%s\n", "", k.means)
		fmt.Printf("  %-20s 下一步：%s\n\n", "", k.askAgain)
	}
	fmt.Println("  三个最常见的混淆：")
	fmt.Println("    · 未登录返回 403 → 前端会显示「权限不足」，用户完全不知道要登录")
	fmt.Println("    · 越权返回 403 → **泄露存在性**，攻击者能枚举 id（tech-plan §6.2 明令禁止）")
	fmt.Println("    · 登录失败返回 403 → 前端不会触发 refresh，用户被卡在死循环里")

	fmt.Println("\n=== 2. 逐个场景真跑：三个身份 × 三类资源 × 两种动作 ============ ")
	subjectFamily = map[string]string{"u-owner": "fam-A", "u-member": "fam-A", "u-x": "fam-B"}
	subjectRole = map[string]string{"u-owner": "owner", "u-member": "member", "u-x": "owner"}
	resources := []*Resource{
		{ID: "tx-001", OwnerID: "u-owner", FamilyID: "fam-A",
			ViewerIDs: []string{"u-owner", "u-member"}, WriterIDs: []string{"u-owner", "u-member"}},
		{ID: "tx-002", OwnerID: "u-owner", FamilyID: "fam-B",
			ViewerIDs: []string{"u-x"}, WriterIDs: []string{"u-x"}},
		{ID: "tx-003", OwnerID: "u-member", FamilyID: "fam-A",
			ViewerIDs: []string{"u-member"}, WriterIDs: []string{"u-member"}},
	}
	subjects := []struct {
		s   Subject
		tag string
	}{
		{Subject{UserID: "anon", Identified: false}, "未登录"},
		{Subject{UserID: "u-owner", Identified: true}, "A 家 owner"},
		{Subject{UserID: "u-member", Identified: true}, "A 家 member"},
		{Subject{UserID: "u-x", Identified: true}, "B 家 owner"},
	}
	resTags := []struct {
		r   *Resource
		tag string
	}{
		{resources[0], "tx-001（fam-A，全家可读写）"},
		{resources[1], "tx-002（fam-B，别家数据）"},
		{resources[2], "tx-003（fam-A，仅作者可读写）"},
		{nil, "不存在的 tx-999"},
	}
	fmt.Printf("  %s %s %s %s %s\n", pad("身份", 14), pad("目标", 34), pad("动作", 6),
		pad("HTTP", 6), "业务码")
	fmt.Println("  " + strings.Repeat("-", 78))
	for _, sub := range subjects {
		for _, rt := range resTags {
			for _, act := range []string{"read", "write"} {
				d := Decide(sub.s, rt.r, act)
				fmt.Printf("  %s %s %s %s %d\n", pad(sub.tag, 14), pad(rt.tag, 34),
					pad(act, 6), pad(fmt.Sprint(d.HTTP), 6), d.BizCode)
			}
		}
	}

	fmt.Println("\n=== 3. 关键一行：跨家庭访问返回的响应体，逐字相同 ============ ")
	subA := Subject{UserID: "u-owner", Identified: true}
	dCross := Decide(subA, resources[1], "read") // 读 tx-002（fam-B）
	dMiss := Decide(subA, nil, "read")           // 读不存在的
	fmt.Printf("  读 tx-002（B 家的）→ %d %s\n", dCross.HTTP, dCross.Message)
	fmt.Printf("  读 tx-999（不存在） → %d %s\n", dMiss.HTTP, dMiss.Message)
	fmt.Printf("  两者响应体是否**逐字相同**：%v\n", dCross.Message == dMiss.Message)
	fmt.Println()
	fmt.Println("  如果返回 403「权限不足」，攻击者就知道 tx-002 真实存在；")
	fmt.Println("  他可以逐个 id 试过去，枚举出「哪些 id 存在」，即使读不到内容。")
	fmt.Println("  这就是 PRD 3.4.4 / tech-plan §6.2 说的「不泄露存在性」。")

	fmt.Println("\n=== 4. 那 403 什么时候可以用：唯一的窄门 ============ ")
	fmt.Println("  条件：调用方**本来就知道这个对象存在**。具体只有这几种情况：")
	doors := []struct{ scene, why, code string }{
		{"在家庭成员列表里看到某人，然后尝试把他降级",
			"列表已经告诉用户「他是成员」，403 不泄露任何新信息",
			"403 / 3002"},
		{"用户尝试导出家庭数据但角色不够",
			"PRD 15.4 明确规定 guest 「不可导出」—— 这是产品规则，不是隐藏信息",
			"403 / 3002"},
		{"用户尝试修改他人创建的待办",
			"待办列表里所有人都能看到「谁创建的」，存在性是公开的",
			"403 / 3002"},
		{"用户尝试停用一个面（只有管理员可以）",
			"面配置列表对全家可见（PRD 17.8），存在性已知",
			"403 / 3002"},
	}
	for _, d := range doors {
		fmt.Printf("  ▸ %s\n", d.scene)
		fmt.Printf("      为什么安全：%s\n", d.why)
		fmt.Printf("      返回：%s\n", d.code)
	}
	fmt.Println()
	fmt.Println("  共同点：**「它存在」这条信息本来就公开**。")
	fmt.Println("  判断方法很简单一句话：")
	fmt.Println("    「如果这个对象不存在，用户会觉得意外吗？」")
	fmt.Println("    会觉得意外（比如他刚在列表里看到过） → 403")
	fmt.Println("    不会觉得意外（他只是随便猜了个 id） → 404")
	fmt.Println()
	fmt.Println("  这也是 S5 越权测试要逐格断言的原因：25 格 × 每格的「存在性是否公开」要单独判。")

	fmt.Println("\n=== 5. 本项目的完整错误码表 ============ ")
	rows := codeTable()
	sort.Slice(rows, func(i, j int) bool {
		if rows[i].HTTP != rows[j].HTTP {
			return rows[i].HTTP < rows[j].HTTP
		}
		return rows[i].Code < rows[j].Code
	})
	fmt.Printf("  %s %s %s %s %s\n", pad("HTTP", 6), pad("code", 6), pad("含义", 40),
		pad("段", 8), "前端动作")
	fmt.Println("  " + strings.Repeat("-", 118))
	for _, r := range rows {
		fmt.Printf("  %s %s %s %s %s\n", pad(fmt.Sprint(r.HTTP), 6), pad(fmt.Sprint(r.Code), 6),
			pad(r.Meaning, 40), pad(r.Kind, 8), r.Frontend)
	}
	fmt.Println()
	fmt.Println("  分段口径（tech-plan §6.2）：")
	fmt.Println("    1001-1010  认证与令牌        0     成功")
	fmt.Println("    3001-3004  家庭与成员        5000  服务端错误")
	fmt.Println("    4001-4002  业务规则          4004/4005/405 由路由层使用")
	fmt.Println()
	fmt.Println("  ⚠ 这张表要写进 OpenAPI 并版本控制 —— tech-plan §10.2 门禁 3 会检查")
	fmt.Println("    向后兼容。改一个码的含义 = 破坏性变更，必须升版本。")

	fmt.Println("\n=== 6. 401 的六种：前端必须分别处理 ============ ")
	fmt.Println("  把 1001-1006 混成「未登录」会导致：")
	fmt.Println("    · 用户每 15 分钟被踢一次（1001 被当成 1002 处理）")
	fmt.Println("    · 用户明明登录了却一直回登录页（1002 被当成 1001，反复 refresh）")
	fmt.Println("    · 刷新失败后无限重试（1004 被当成 1001）")
	fmt.Println()
	split := []struct {
		code     int
		group    string
		handling string
	}{
		{1001, "可恢复", "静默 refresh → 重放原请求。用户无感。失败则落到下面那组"},
		{1002, "不可恢复", "refresh 本身无效 → 清登录态 → 回登录页"},
		{1003, "客户端 bug", "记日志上报，不弹窗。用户不该看到"},
		{1004, "不可恢复", "清登录态 → 回登录页 → 提示「账号已在其他设备登录」"},
		{1005, "不可恢复", "清登录态 → 回登录页（用户可能清过缓存）"},
		{1006, "可恢复", "自动重试一次。连续两次则当 1005 处理"},
	}
	fmt.Printf("  %s %s %s\n", pad("code", 6), pad("分类", 14), "处理")
	for _, s := range split {
		fmt.Printf("  %s %s %s\n", pad(fmt.Sprint(s.code), 6), pad(s.group, 14), s.handling)
	}
	fmt.Println()
	fmt.Println("  这个分组必须写进联调文档，并在前端代码里**用 switch 实现**，")
	fmt.Println("  而不是 `if (code === 401) { logout() }`。")
	fmt.Println("  Go 后端这边最好做的是：每个码一个 sentinel error，")
	fmt.Println("  handler 里 errors.Is 判定，然后一个集中的 map[string]int 转 HTTP。")

	fmt.Println("\n=== 7. 判定函数本身：四条规则的顺序不可换 ============ ")
	order := []string{
		"① 身份不明 → 401（**与资源无关**，哪怕资源根本不存在也是 401）",
		"② 资源不存在 / 已软删 → 404",
		"③ 资源存在但不属于你的家庭 → 404",
		"④ 资源属于你家，你也知道它存在，但没有这个动作的权限 → 403",
	}
	for _, o := range order {
		fmt.Printf("  %s\n", o)
	}
	fmt.Println()
	fmt.Println("  顺序换错会怎样：")
	wrong := []struct{ bad, why string }{
		{"先判 ④ 再判 ③", "跨家庭访问会返回 403 → 泄露「这个 id 在别家有」"},
		{"先判 ② 再判 ①", "未登录用户探测 id 时会得到 404 与 401 的差异 → 泄露 id 是否存在"},
		{"① 与 ④ 合并成一个 403", "未登录用户看到「权限不足」，完全不知道要登录"},
	}
	for _, w := range wrong {
		fmt.Printf("  ❌ %s\n", w.bad)
		fmt.Printf("     %s\n", w.why)
	}
	fmt.Println()
	fmt.Println("  第一条尤其反直觉，但它是**安全**要求：")
	fmt.Println("  未登录状态下的探测（枚举 id 是否存在）不应该有任何信息量差异，")
	fmt.Println("  而 401 vs 404 的差异恰恰泄露了「这个 id 是不是有效格式的 id」。")
	fmt.Println("  所以规则 ① 必须在 ② ③ 之前。")

	fmt.Println("\n=== 8. 与 JS 的对照 ============ ")
	fmt.Println("  ① Express 里这三件事默认**不做**：")
	fmt.Println("     · 没有内置 401/403 的语义（res.status(401).end() 就结束了）")
	fmt.Println("     · Cookie 会自动带上 → CSRF 需要额外中间件")
	fmt.Println("     · 没有「统一响应体」的概念（各家自己写）")
	fmt.Println("  本项目显式定义 Envelope（tech-plan §6.2）与码表，好处是：")
	fmt.Println("     · 前端可以按 code 做逻辑（1001 vs 1002），不用解析 message")
	fmt.Println("     · i18n 时 message 可以随便改，code 不变")
	fmt.Println("     · 测试可以断言 code，不需要断言文案")
	fmt.Println("  ② 前端 fetch 拿到 401 时：")
	fmt.Println("     fetch 不会自动抛异常 —— 它**照常 resolve**，只是 res.ok === false。")
	fmt.Println("     所以「统一在拦截器里处理」必须是显式写的，不是自动的。")
	fmt.Println("     JS: if (!res.ok && res.status === 401) await tryRefresh()")
	fmt.Println("     Go 后端这边要做的只是把 HTTP 码与业务码都填对。")
	fmt.Println("  ③ Go 里定义这些码的方式（推荐）：")
	fmt.Println("     var ErrTokenExpired = errors.New(\"1001 token expired\")")
	fmt.Println("     // 然后在 handler 里 errors.Is(err, ErrTokenExpired)")
	fmt.Println("     // 最后由一个 Error() 中间件统一转成 HTTP + Envelope")
	fmt.Println("     好处：码与错误一一对应，改一处不会漏另一处。")
	fmt.Println("     （d03/d10 讲过 Go 的 error 三件套，这里是它的应用。）")

	fmt.Println("\n=== S4 d26 到此结束 ===")
	fmt.Println("明天讲限流实现：令牌桶 vs 滑动窗口，用 Go 跑一个真的令牌桶。")
}

var _ = errors.New

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

