type RejectKind int

const (
	RejectUnauthorized RejectKind = iota // 401：你是谁？
	RejectForbidden                      // 403：你是谁，但你不能
	RejectNotFound                       // 404：东西不存在（或者你没权限看）
)

func (k RejectKind) String() string {
	switch k {
	case RejectUnauthorized:
		return "401 Unauthorized"
	case RejectForbidden:
		return "403 Forbidden"
	default:
		return "404 Not Found"
	}
}

// Resource 是一个「资源」。关键：**只有 owner 与 viewer 知道它存在**。

type Resource struct {
	ID        string
	OwnerID   string
	FamilyID  string
	ViewerIDs []string // 可以读的人
	WriterIDs []string // 可以改的人
	Deleted   bool
}

type Subject struct {
	UserID string
	// Authed 表示凭证有效；Identified 表示凭证有效且能识别出是谁。
	Identified bool
}

// Decide 是本项目「统一返回约定」的实现。
// 输入：请求的方法、目标资源、当前用户、要做的动作。
// 输出：HTTP 状态、业务码、以及**给不给��露存在性**的判断依据。
type Decision struct {
	HTTP      int
	BizCode   int
	Message   string
	Action    string // 前端该做什么
	Leaks     bool   // 这个返回是否泄露了「资源存在」
	Rationale string
}

var (
	// —— 401 段（tech-plan §6.2 的 1001-1010）——
	CodeTokenExpired   = 1001
	CodeRefreshInvalid = 1002
	CodeTypeMismatch   = 1003
	CodeTokenRevoked   = 1004
	CodeNoAuthHeader   = 1005
	CodeNotYetValid    = 1006
	// —— 3001-3004（家庭与成员）——
	CodeNoSuchFamily = 3001
	CodeNoPermission = 3002
	// —— 4001-4002（业务规则）——
	CodeBizConflict = 4001
	// —— 0 / 5000 ——
	CodeOK      = 0
	CodeServer  = 5000
	CodeUnknown = 4004
)

// Decide 判定：这是本项目 W17 最重要的一段逻辑。

func Decide(sub Subject, res *Resource, action string) Decision {
	// 规则一：身份不明 → 401。这一步与资源存不存在**无关**。
	if !sub.Identified {
		return Decision{
			HTTP: 401, BizCode: CodeNoAuthHeader,
			Message:   "缺少或无效的 Authorization 头",
			Action:    "access 过期 → 静默 refresh；refresh 无效 → 清本地登录态，回登录页",
			Leaks:     false,
			Rationale: "「你是谁」都无法回答时不该谈资源 —— 401 与资源无关，",
		}
	}

	// 规则二：资源不存在或已软删 → 404
	if res == nil || res.Deleted {
		return Decision{
			HTTP: 404, BizCode: CodeNoSuchFamily,
			Message:   "resource not found",
			Action:    "提示「内容不存在或已删除」；不要提示「无权限」",
			Leaks:     false,
			Rationale: "真的不存在与无权访问返回**完全相同**的响应体 —— 这是 non-enumeration",
		}
	}

	// 规则三：资源存在但没有这个家庭 → 也 404（不泄露「它存在但不属于你」）
	if res.FamilyID != subFamily(sub) {
		return Decision{
			HTTP: 404, BizCode: CodeNoSuchFamily,
			Message:   "resource not found",
			Action:    "同上。用户不应该知道「这个 id 在别的家庭存在」",
			Leaks:     false,
			Rationale: "跨家庭访问一律 404（tech-plan §6.2 / PRD 3.4.1 多租户隔离）",
		}
	}

	// 到这里才允许区分：资源在你家，且你知道它存在。
	// —— 这是一个**已知存在**的资源，403 在这里是安全的。
	allowed := false
	switch action {
	case "read":
		allowed = contains(res.ViewerIDs, sub.UserID)
	case "write":
		allowed = contains(res.WriterIDs, sub.UserID)
	}
	if !allowed {
		return Decision{
			HTTP: 403, BizCode: CodeNoPermission,
			Message:   fmt.Sprintf("当前角色（%s）不能%s这个对象", subRole(sub), action),
			Action:    "提示「你没有这个操作的权限」；同时落审计（PRD 15.6）",
			Leaks:     false,
			Rationale: "调用方已经知道这个对象存在（他就是在操作它），403 不泄露新信息",
		}
	}

	return Decision{0, CodeOK, "ok", "正常返回", false, "通过"}
}

// subject 的家庭与角色：本程序从 token 里取。

func subFamily(s Subject) string { return subjectFamily[s.UserID] }
func subRole(s Subject) string   { return subjectRole[s.UserID] }

var (
	subjectFamily = map[string]string{"u-owner": "fam-A", "u-member": "fam-A", "u-x": "fam-B"}
	subjectRole   = map[string]string{"u-owner": "owner", "u-member": "member", "u-x": "owner"}
)

func contains(list []string, v string) bool {
	for _, x := range list {
		if x == v {
			return true
		}
	}
	return false
}

// =====================================================================
// 完整错误码表

func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

