package main

// =====================================================================
// S4 · W17 · d27：限流实现
//
//   令牌桶 vs 滑动窗口，用 Go 真跑一个令牌桶
//
// 时间全部用假时钟手动推进 —— 输出完全确定，
// 但每个时间点上的令牌数、允许/拒绝都是真的算出来的。

type TokenBucket struct {
	capacity   float64 // 桶容量 = 允许的突发量
	tokens     float64 // 当前令牌数
	refillRate float64 // 每秒补多少令牌 = 稳态速率
	now        float64 // 当前时间（秒）
}

func NewTokenBucket(capacity, refillRate float64, now float64) *TokenBucket {
	return &TokenBucket{capacity: capacity, tokens: capacity, refillRate: refillRate, now: now}
}

type Verdict struct {
	Allowed bool
	Tokens  float64 // 判定后的剩余令牌
	RetryIn float64 // 被拒时建议等多少秒
}

func (b *TokenBucket) Advance(to float64) {
	if to <= b.now {
		return
	}
	dt := to - b.now
	b.tokens = math.Min(b.capacity, b.tokens+dt*b.refillRate)
	b.now = to
}

func (b *TokenBucket) Allow() Verdict {
	if b.tokens >= 1 {
		b.tokens--
		return Verdict{Allowed: true, Tokens: b.tokens}
	}
	need := (1 - b.tokens) / b.refillRate
	return Verdict{Allowed: false, Tokens: b.tokens, RetryIn: need}
}

// =====================================================================
// 二、固定窗口
// =====================================================================

type FixedWindow struct {
	limit  int
	window float64
	count  int
	start  float64
}

func NewFixedWindow(limit int, window, now float64) *FixedWindow {
	return &FixedWindow{limit: limit, window: window, count: 0, start: now}
}

func (w *FixedWindow) Allow(now float64) bool {
	if now-w.start >= w.window {
		w.start = now
		w.count = 0
	}
	if w.count >= w.limit {
		return false
	}
	w.count++
	return true
}

// =====================================================================
// 三、滑动窗口（日志法）

// =====================================================================

type SlidingWindow struct {
	limit  int
	window float64
	hits   []float64 // 每次通过的时间戳
}

func NewSlidingWindow(limit int, window float64) *SlidingWindow {
	return &SlidingWindow{limit: limit, window: window}
}

func (w *SlidingWindow) Allow(now float64) bool {
	// 丢弃窗口外的记录
	cut := now - w.window
	kept := w.hits[:0]
	for _, t := range w.hits {
		if t > cut {
			kept = append(kept, t)
		}
	}
	w.hits = kept
	if len(w.hits) >= w.limit {
		return false
	}
	w.hits = append(w.hits, now)
	return true
}

// =====================================================================
// 四、场景与期望

func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

