package main

// =====================================================================
// S4 · W17 · d28：登录失败次数限制与锁定
//
//   它和限流（d27）是两种不同的机制
//   指数退避、计数窗口、锁定时长、解锁方式
// =====================================================================

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// =====================================================================
// 假时钟
// =====================================================================

var now float64 = 0 // 起点：2026-10-15 20:00:00

func tick(d float64) float64 { now += d; return now }

// =====================================================================
// 用户表里的两个字段（d03 DDL 里已经埋好的）
// =====================================================================

type User struct {
	ID          string
	Phone       string
	Status      string // active / locked / disabled
	FailedCnt   int
	LockedUntil *float64
	// LockLevel 记录「这是第几次被锁」，用于指数退避。
	LockLevel int
}

var users = map[string]*User{}
var audit []string

// =====================================================================
// 策略：指数退避 + 计数窗口
// =====================================================================

// backoffSeconds 是「第 level 次锁定持续多久」。
// 30s → 60s → 300s → 900s → 1800s（封顶）
func backoffSeconds(level int) float64 {
	table := []float64{30, 60, 300, 900, 1800}
	if level < 1 {
		level = 1
	}
	if level > len(table) {
		return table[len(table)-1]
	}
	return table[level-1]
}

// MaxFailBeforeLock 是「连续失败多少次就锁」。
// PRD 3.4.8 对设备锁 PIN 写的是「连续 5 次失败即锁定」；
// 登录这里用 5 次同样的口径（S4 取值，写进 tech-plan §8 补充）。
const MaxFailBeforeLock = 5

// CountWindow 是「失败次数在多长时间内算连续」。
// 超过这个窗口，计数器清零 —— 因为「10 分钟前错 3 次、刚才错 2 次」
// 不该和「刚刚连错 5 次」同等对待。
const CountWindow = 15 * 60

// 内存里的失败计数（真实实现放 Redis 或数据库）
type failCounter struct {
	count int
	last  float64
}

var failStore = map[string]*failCounter{}

type LoginResult struct {
	OK          bool
	HTTP        int
	Code        int
	Message     string
	Frontend    string
	LockLevel   int
	LockedUntil float64
}

// Login 是完整的登录判定：状态 → 锁定检查 → 密码校验 → 计数/锁定。
func Login(phone, password string) LoginResult {
	u, ok := users[phone]
	if !ok {
		// 用户不存在：也要跑一次 bcrypt 防用户枚举（d03 讲过）
		return LoginResult{false, 401, 1005, "手机号或密码错误",
			"与「密码错」完全相同的文案。不要提示「该手机号未注册」", 0, 0}
	}

	// ① 永久停用
	if u.Status == "disabled" {
		return LoginResult{false, 403, 3002, "账号已被停用，请联系家庭管理员",
			"显示文案，不要引导重试", 0, 0}
	}

	// ② 临时锁定
	if u.LockedUntil != nil && now < *u.LockedUntil {
		left := *u.LockedUntil - now
		return LoginResult{false, 429, 1003,
			fmt.Sprintf("尝试次数过多，请在 %d 秒后重试", int(left)),
			fmt.Sprintf("显示倒计时 %d 秒，期间禁用输入框", int(left)), u.LockLevel, 0}
	}
	if u.LockedUntil != nil && now >= *u.LockedUntil {
		// 锁到期：自动解锁，把计数清零
		u.LockedUntil = nil
		u.FailedCnt = 0
		audit = append(audit, fmt.Sprintf("[t=%3.0f] AUTO_UNLOCK phone=%s", now, mask(phone)))
	}

	// ③ 密码校验（本程序用固定口令模拟，避免 bcrypt 的耗时）
	if password != "SunsetRiver42" {
		// 计数窗口：超过 15 分钟就清零
		fc := failStore[phone]
		if fc == nil || now-fc.last > CountWindow {
			fc = &failCounter{}
			failStore[phone] = fc
		}
		fc.count++
		fc.last = now
		u.FailedCnt = fc.count

		if fc.count >= MaxFailBeforeLock {
			// 达到阈值 → 锁定
			u.LockLevel++
			d := backoffSeconds(u.LockLevel)
			until := now + d
			u.LockedUntil = &until
			u.Status = "locked"
			fc.count = 0
			audit = append(audit, fmt.Sprintf("[t=%3.0f] LOCK phone=%s level=%d until=t=%.0f (%.0fs)",
				now, mask(phone), u.LockLevel, until, d))
			return LoginResult{false, 429, 1003,
				fmt.Sprintf("尝试次数过多，账号已锁定 %d 秒", int(d)),
				"提示「请在 N 分钟后重试，或用手机号验证码登录」", u.LockLevel, until}
		}
		audit = append(audit, fmt.Sprintf("[t=%3.0f] LOGIN_FAIL phone=%s cnt=%d/%d",
			now, mask(phone), fc.count, MaxFailBeforeLock))
		return LoginResult{false, 401, 1005, "手机号或密码错误",
			fmt.Sprintf("还可尝试 %d 次", MaxFailBeforeLock-fc.count), 0, 0}
	}

	// ④ 成功：清零一切
	fc := failStore[phone]
	if fc != nil {
		fc.count = 0
	}
	u.FailedCnt = 0
	if u.LockedUntil != nil {
		u.LockedUntil = nil
	}
	if u.LockLevel > 0 {
		u.LockLevel = 0 // 一次成功就清空退避级别
	}
	u.Status = "active"
	audit = append(audit, fmt.Sprintf("[t=%3.0f] LOGIN_OK   phone=%s", now, mask(phone)))
	return LoginResult{true, 200, 0, "ok", "正常返回", 0, 0}
}

func mask(p string) string { return p[:3] + "****" + p[7:] }

// =========================================================================
// 主流程
// =========================================================================

func main() {
	reset()

	fmt.Println("=== 1. 锁定与限流是两种不同的东西 ============ ")
	fmt.Println("  d27 的限流管的是「请求速率」，d28 的锁定管的是「失败次数」。")
	fmt.Printf("  %s %s %s %s\n", pad("", 18), pad("限流（令牌桶）", 26), pad("锁定（本节）", 26), pad("谁能解除", 18))
	cmp := []struct{ aspect, rate, lock, who string }{
		{"触发条件", "单位时间请求**总量**超限", "连续**认证失败**达阈值", "—"},
		{"计数对象", "IP 或接口维度（无身份）", "手机号 / 用户维度（有身份）", "—"},
		{"状态存哪", "进程内 map（无持久）", "**数据库**（users 表）", "—"},
		{"误伤谁", "NAT 后面的所有人", "单个账号", "—"},
		{"能否绕过", "换个 IP 就能", "换个账号就行（但那是另一个账号的问题）", "—"},
		{"服务目标", "防服务被打挂（可用性）", "防账号被猜破（安全性）", "—"},
		{"自动恢复", "等令牌补满即可", "等锁定到期（自动）", "服务端自动"},
		{"手动解除", "不适用", "管理员解锁 / 用户验证手机号", "人或时间"},
		{"返回值", "429 / 1003", "429 / 1003（或 401 / 1005）", "—"},
	}
	for _, c := range cmp {
		fmt.Printf("  %s %s %s %s\n", pad(c.aspect, 18), pad(c.rate, 26), pad(c.lock, 26), c.who)
	}
	fmt.Println()
	fmt.Println("  一句话：限流保护**服务器**，锁定保护**账号**。")
	fmt.Println("  两者都要有：只有锁定的话，攻击者可以用 10000 个账号各试 4 次，")
	fmt.Println("  服务器扛得住但数据库被打满；只有限流的话，单个账号能被无限猜。")

	fmt.Println("\n=== 2. 完整场景一：连续输错 5 次，真跑 ============ ")
	fmt.Println("  阈值：连续 5 次失败即锁定。退避：30s → 60s → 300s → 900s → 1800s")
	reset()
	attempts := []struct {
		what, pw string
		gap      float64 // 这次尝试前先推进多少秒
	}{
		{"第 1 次输错", "wrong1", 0},
		{"第 2 次输错", "wrong2", 3},
		{"第 3 次输错", "wrong3", 2},
		{"第 4 次输错", "wrong4", 5},
		{"第 5 次输错", "wrong5", 1},
		{"第 6 次（已锁定）", "SunsetRiver42", 2},
		{"第 7 次（已锁定）", "SunsetRiver42", 3},
	}
	for _, a := range attempts {
		tick(a.gap)
		r := Login("13800000001", a.pw)
		if r.OK {
			fmt.Printf("    [%3.0f] %s → ✅ 登录成功\n", now, a.what)
			continue
		}
		tag := fmt.Sprintf("%d %s", r.HTTP, r.Message)
		fmt.Printf("    [%3.0f] %s → ❌ %s\n", now, pad(a.what, 22), tag)
		if r.HTTP == 429 {
			fmt.Printf("         前端：%s\n", r.Frontend)
		}
	}
	u := users["13800000001"]
	fmt.Printf("\n  此刻 users 表：status=%s failed_cnt=%d lock_level=%d\n",
		u.Status, u.FailedCnt, u.LockLevel)
	fmt.Println("  注意 status 是 locked 但 **lock_level = 1** ——")
	fmt.Println("  这是「第一次被锁」。下一次锁定会退避到 60 秒。")
	fmt.Println()
	fmt.Println("  ⚠ 关键设计：status=locked 与 locked_until 是**两件事**。")
	fmt.Println("    · locked_until 有值 → 临时锁定，到期自动恢复 active")
	fmt.Println("    · status=disabled → 永久停用，必须管理员解除")
	fmt.Println("  如果只用 status 一个字段表达所有锁定，那么「锁 30 秒」和")
	fmt.Println("  「永久封号」就没法区分了 —— 而它们的处理方式完全相反。")

	fmt.Println("\n=== 3. 完整场景二：等待到期自动解锁 ============ ")
	fmt.Printf("  接着上一节，锁定截止到 t=%.0f。\n", *u.LockedUntil)
	fmt.Println("  用户等不及，用手机号验证码登录：")
	fmt.Println("    → 这是 PRD 3.4.8 明确允许的路径（「忘记口令的唯一恢复路径是手机号重验」）")
	fmt.Println("    → 本项目的登录入口本来就有验证码，所以这条恢复路径天然存在")
	fmt.Println()
	tick(10)
	fmt.Printf("  [%3.0f] 锁定期内再试正确密码 → ", now)
	r := Login("13800000001", "SunsetRiver42")
	fmt.Printf("❌ %s\n", r.Message)
	tick(21) // 现在 t = 31 > 30
	fmt.Printf("  [%3.0f] 超过 30 秒，再试正确密码 → ", now)
	r = Login("13800000001", "SunsetRiver42")
	if r.OK {
		fmt.Printf("✅ 成功（锁定已自动过期）\n")
	} else {
		fmt.Printf("❌ %s\n", r.Message)
	}
	fmt.Println("  审计日志里自动有一条 AUTO_UNLOCK —— 锁定到期不需要任何定时任务。")
	fmt.Println("  它是**惰性**的：只有用户下次尝试时才被检测到并清理。")
	fmt.Println("  这是刻意的设计：省掉一个每分钟扫全表的任务。")

	fmt.Println("\n=== 4. 完整场景三：反复触发 → 指数退避 ============ ")
	fmt.Println("  同一个账号反复输错，观察锁定时长怎么翻倍：")
	reset()
	fmt.Printf("  %s %s %s %s\n", pad("第几次被锁", 12), pad("锁定时长", 12), pad("解除时刻", 12), "累计等待")
	total := 0.0
	for i := 1; i <= 5; i++ {
		for k := 0; k < MaxFailBeforeLock; k++ {
			Login("13800000001", fmt.Sprintf("wrong-%d-%d", i, k))
		}
		u := users["13800000001"]
		d := backoffSeconds(u.LockLevel)
		total += d
		fmt.Printf("  %s %s %s %s\n", pad(fmt.Sprintf("第 %d 次", i), 12),
			pad(fmt.Sprintf("%.0f 秒", d), 12),
			pad(fmt.Sprintf("t=%.0f", *u.LockedUntil), 12),
			fmt.Sprintf("%.0f 秒", total))
		// 等锁过期，让下一次尝试能真正走到锁定逻辑
		tick(*u.LockedUntil - now)
		// 再失败一次以清掉 locked_until
		Login("13800000001", "wrong-probe")
	}
	fmt.Println()
	fmt.Println("  为什么退避？固定 30 秒的话，攻击者每 30 秒试一批，")
	fmt.Println("  平均速度是固定的，而且**永远锁不死**。")
	fmt.Println("  指数退避让「反复尝试」的代价呈指数上升：")
	fmt.Println("    试 1 万次密码，固定 30 秒锁定 → 需要约 3.5 天")
	fmt.Println("    同样 1 万次，指数退避   → 需要约 41 天")
	fmt.Println("  这是 PRD 3.4.8 对设备锁 PIN 用的同一套退避表（30s/1min/5min），")
	fmt.Println("  我们把 5min 之后延长到 15min/30min，因为登录窗口比 PIN 锁更长。")

	fmt.Println("\n=== 5. 计数窗口：为什么 15 分钟 ============ ")
	reset()
	fmt.Println("  场景 A：真正的攻击（短时间内连续错）")
	tick(0)
	for i := 0; i < 4; i++ {
		Login("13800000001", "wrong")
		tick(2)
	}
	fmt.Printf("    20:00-20:00 连续错 4 次 → failed_cnt = %d\n", users["13800000001"].FailedCnt)
	Login("13800000001", "wrong") // 第 5 次
	fmt.Printf("    第 5 次 → 已锁定=%v\n", users["13800000001"].LockedUntil != nil)

	reset()
	fmt.Println()
	fmt.Println("  场景 B：三个孩子轮流用这台电脑")
	for round := 0; round < 5; round++ {
		for _, who := range []string{"13800000002", "13800000003", "13800000004"} {
			Login(who, "wrong")
		}
	}
	fmt.Printf("    三个账号各错 5 次（共 15 次）→ 每个账号 lock_level = %d\n",
		users["13800000002"].LockLevel)
	fmt.Println("    共享 IP 的限流（d27）会拦住这波，但**锁定是按账号算的**，")
	fmt.Println("    所以三个人都被锁了 —— 体验很差，但安全上是对的。")
	fmt.Println("    这就是为什么锁定阈值不能太低，也不能把计数窗口拉得太长。")
	fmt.Println()
	fmt.Println("  场景 C：间隔超过窗口就不算连续")
	reset()
	Login("13800000001", "wrong")
	tick(1)
	Login("13800000001", "wrong")
	fmt.Printf("    10:00 错 2 次 → failed_cnt = %d\n", users["13800000001"].FailedCnt)
	tick(CountWindow + 1)
	Login("13800000001", "wrong")
	fmt.Printf("    10:16 错 1 次 → failed_cnt = %d（窗口 15 分钟已过，计数重置）\n",
		users["13800000001"].FailedCnt)

	fmt.Println("\n=== 6. 解锁的三条路，各走一遍 ============ ")
	unlocks := []struct{ way, how, security, note string }{
		{"① 等到期", "locked_until 过期后下次请求自动解锁",
			"低。攻击者愿意等就能继续",
			"这是默认路径。前端要显示准确剩余秒数"},
		{"② 验证码登录", "用户用手机号验证码换一个新 access",
			"中。前提是攻击者拿不到验证码",
			"PRD 3.4.8 对 PIN 明确写了这是「唯一恢复路径」。本项目登录本来就有验证码"},
		{"③ 管理员解锁", "owner 在成员管理里把 status 改回 active",
			"高。需要家庭内管理员权限",
			"PRD 3.7 L413 的成员管理。这里要注意：解锁要落审计"},
	}
	for _, u := range unlocks {
		fmt.Printf("  ▸ %s\n", u.way)
		fmt.Printf("      怎么走：%s\n", u.how)
		fmt.Printf("      安全性：%s\n", u.security)
		fmt.Printf("      %s\n", u.note)
	}
	fmt.Println()
	fmt.Println("  ⚠ 绝不要提供的第四条路：「点一下就解锁」")
	fmt.Println("    那等于没有锁定 —— 攻击者点一下继续试。")
	fmt.Println("  ⚠ 也不能提供「安全问题答案」式的解锁。PRD 15.3 的角色矩阵里")
	fmt.Println("    guest 是限时只读可撤销的，说明本项目**不做**密码找回问题。")

	fmt.Println("\n=== 7. 一个必须说清的问题：锁定会不会被用来 DoS ============ ")
	fmt.Println("  攻击者知道小双的手机号（很多场景下不难得到），")
	fmt.Println("  只要连续输错 5 次就能把他的账号锁 30 秒，反复操作就能")
	fmt.Println("  让小双**永远登不进去**。这是一个真实且常见的攻击（叫 DoS on auth）。")
	fmt.Println()
	mitigations := []struct{ name, how, cost string }{
		{"退避封顶 30 分钟", "锁 5 次以上固定 30 分钟，不再指数增长",
			"攻击者能造成的破坏上限被限定为「每次 30 分钟」"},
		{"验证码解锁", "锁定期间允许用验证码登录直接绕过",
			"攻击者拿不到验证码 → DoS 失效。本项目已有这条路（d06）"},
		{"不锁定「已登录设备」", "只对**从未成功登录过**的设备做锁定",
			"复杂度高，且防不住「先正常登录再 DoS」"},
		{"通知用户", "被锁时给手机号发一条「有人尝试登录你的账号」",
			"PRD 15.6：「连续 5 次触发通知管理员」。用户能及时知道"},
	}
	fmt.Println("  四个缓解手段：")
	for _, m := range mitigations {
		fmt.Printf("  ▸ %s\n", m.name)
		fmt.Printf("      %s\n", m.how)
		fmt.Printf("      代价：%s\n", m.cost)
	}
	fmt.Println()
	fmt.Println("  本项目采用前两个（退避封顶 + 验证码解锁）。")
	fmt.Println("  第二个尤其关键：**验证码路径本来就要做（PRD 主登录方式），")
	fmt.Println("  它顺带就是最好的锁定恢复机制**。")
	fmt.Println("  这是一个很好的架构回报：主要选择与安全需求恰好同向。")

	fmt.Println("\n=== 8. 与「密码强度」「限流」三者的关系 ============ ")
	fmt.Println("  它们不是替代关系，是三层：")
	layers := []struct{ layer, what, blocks, layerNote string }{
		{"① 密码强度", "拒绝弱口令（长度/多样性/黑名单）",
			"让密码本身难猜", "减少「需要试的次数」"},
		{"② 锁定", "连续失败达阈值就锁",
			"让在线猜测的**速率**趋近于零", "增加「猜中所需的时间」"},
		{"③ 限流", "单位时间请求数超限就拒",
			"让单 IP 的请求**总量**有上限", "保护服务本身"},
	}
	for _, l := range layers {
		fmt.Printf("  ▪ %s\n", l.layer)
		fmt.Printf("      %s\n", l.what)
		fmt.Printf("      挡住：%s\n", l.blocks)
		fmt.Printf("      作用：%s\n", l.layerNote)
	}
	fmt.Println()
	fmt.Println("  量化一下：10 位纯小写密码（26^10 ≈ 1.4e14 组合）")
	fmt.Println("    · 没有锁定：GPU 每秒 1e11 次 → 约 16 天")
	fmt.Println("    · 有锁定（5 次/30 秒起步 + 退避）：速率降到 1e11 → 0.006 次/秒")
	fmt.Println("      实际速率约 1/30 到 1/1800 次/秒之间 → **数十年到上千年**")
	fmt.Println("    · 有 12 位混合字符（72^12 ≈ 1e22）：即使没有锁定也要几万年")
	fmt.Println()
	fmt.Println("  所以「密码强度」与「锁定」是**互补**的：")
	fmt.Println("  弱密码靠锁定拖住时间，强密码让锁定都不必要。")
	fmt.Println("  本项目两条都要 —— 因为总会有用户用 6 位纯数字。")

	fmt.Println("\n=== 9. 审计日志（真跑，最后打印） ============ ")
	reset()
	// 重放一遍场景 1 的序列，好让日志有内容
	for _, a := range []string{"wrong1", "wrong2", "wrong3", "wrong4", "wrong5"} {
		Login("13800000001", a)
		tick(1)
	}
	Login("13800000001", "SunsetRiver42")
	tick(40)
	Login("13800000001", "SunsetRiver42")
	fmt.Println("  重放结果：")
	for _, l := range audit {
		fmt.Printf("    %s\n", l)
	}
	fmt.Println()
	fmt.Println("  PRD 21.5 要求的审计事件里，「登录」是一类；")
	fmt.Println("  PRD 21.4 要求登录与会话记录保留 **6 个月**。")
	fmt.Println("  这些日志里没有密码、没有 token、没有完整手机号。")

	fmt.Println("\n=== 10. 与 JS 的对照 ============ ")
	fmt.Println("  ① 状态存哪：")
	fmt.Println("     本项目的 failed_cnt / locked_until **在数据库里**（d03 的 DDL 已经埋好）。")
	fmt.Println("     这与 d27 的限流不同 —— 限流是「无状态的速率控制」，")
	fmt.Println("     锁定是「账号状态」，必须持久化，否则重启服务就全部解锁了。")
	fmt.Println()
	fmt.Println("  ② Node 里常见写法：")
	fmt.Println("     Redis: await redis.set(`login:fail:${phone}`, n, { EX: window })")
	fmt.Println("     Postgres: UPDATE homeos_user SET failed_attempts = failed_attempts + 1")
	fmt.Println("     Go/GORM 用后者，与表结构一致，不引入新依赖（tech-plan §22.1）。")
	fmt.Println()
	fmt.Println("  ③ 并发：两个并发的失败请求可能都读到 failed_cnt=4，都认为「还没到 5」。")
	fmt.Println("     正确做法是用 SQL 的原子更新（下面第 11 节的伪码）。")
	fmt.Println("     JS 里同理，只是大家更习惯用 Redis 的原子命令。")

	fmt.Println("\n=== 11. 关键实现：原子更新（伪码，真跑对比） ============ ")
	fmt.Println("  ❌ 非原子：先 SELECT 再 UPDATE")
	fmt.Println("    SELECT failed_attempts FROM homeos_user WHERE phone = ?")
	fmt.Println("    if failed_attempts < 5 {")
	fmt.Println("      UPDATE homeos_user SET failed_attempts = failed_attempts + 1 WHERE id = ?")
	fmt.Println("    }")
	fmt.Println("    问题：两个并发请求都读到 4 → 都判断「< 5」→ 都更新 → 实际变成 6")
	fmt.Println("    而且**都没有触发锁定**，因为判断用的是旧值。")
	fmt.Println()
	fmt.Println("  ✅ 原子：UPDATE 带 WHERE 条件，用 affected_rows 判断")
	fmt.Println("    UPDATE homeos_user")
	fmt.Println("       SET failed_attempts = failed_attempts + 1,")
	fmt.Println("           status = CASE WHEN failed_attempts + 1 >= 5")
	fmt.Println("                       THEN 'locked' ELSE status END,")
	fmt.Println("           locked_until = CASE WHEN failed_attempts + 1 >= 5")
	fmt.Println("                              THEN now() + interval '30 seconds' ELSE locked_until END")
	fmt.Println("     WHERE id = ? AND status = 'active'")
	fmt.Println("    if affectedRows == 1 { 重置计数 } else { 已被锁定或并发已处理 }")
	fmt.Println()
	fmt.Println("  这与 S3 d23 的乐观锁、S4 d15 的 used_at IS NULL 是**同一个模式**：")
	fmt.Println("  把判断融进 UPDATE 的 WHERE，用 affected_rows 作为「是我干的」的唯一凭证。")
	fmt.Println("  写事务时反复出现的这个模式，值得单独记住。")

	fmt.Println("\n=== S4 d28 到此结束 ===")
	fmt.Println("明天是 A1 认证 7 条接口的实现清单：逐条对照技术方案。")
}

func reset() {
	users = map[string]*User{
		"13800000001": {ID: "u-001", Phone: "13800000001", Status: "active"},
		"13800000002": {ID: "u-002", Phone: "13800000002", Status: "active"},
		"13800000003": {ID: "u-003", Phone: "13800000003", Status: "active"},
		"13800000004": {ID: "u-004", Phone: "13800000004", Status: "active"},
	}
	failStore = map[string]*failCounter{}
	audit = nil
	now = 0
}

var _ = errors.New
var _ = sort.Strings

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

