// =====================================================================

type User struct {
	ID          string
	Phone       string
	Status      string // active / locked / disabled
	FailedCnt   int
	LockedUntil *float64
	// LockLevel 记录「这是第几次被锁」，用于指数退避。
	LockLevel int
}

var users = map[string]*User{}
var audit []string

// =====================================================================
// 策略：指数退避 + 计数窗口

func backoffSeconds(level int) float64 {
	table := []float64{30, 60, 300, 900, 1800}
	if level < 1 {
		level = 1
	}
	if level > len(table) {
		return table[len(table)-1]
	}
	return table[level-1]
}

// MaxFailBeforeLock 是「连续失败多少次就锁」。
// PRD 3.4.8 对设备锁 PIN 写的是「连续 5 次失败即锁定」；
// 登录这里用 5 次同样的口径（S4 取值，写进 tech-plan §8 补充）。
const MaxFailBeforeLock = 5

// CountWindow 是「失败次数在多长时间内算连续」。
// 超过这个窗口，计数器清零 —— 因为「10 分钟前错 3 次、刚才错 2 次」
// 不该和「刚刚连错 5 次」同等对待。
const CountWindow = 15 * 60

// 内存里的失败计数（真实实现放 Redis 或数据库）

type failCounter struct {
	count int
	last  float64
}

var failStore = map[string]*failCounter{}

type LoginResult struct {
	OK          bool
	HTTP        int
	Code        int
	Message     string
	Frontend    string
	LockLevel   int
	LockedUntil float64
}

// Login 是完整的登录判定：状态 → 锁定检查 → 密码校验 → 计数/锁定。
func Login(phone, password string) LoginResult {
	u, ok := users[phone]
	if !ok {
		// 用户不存在：也要跑一次 bcrypt 防用户枚举（d03 讲过）
		return LoginResult{false, 401, 1005, "手机号或密码错误",
			"与「密码错」完全相同的文案。不要提示「该手机号未注册」", 0, 0}
	}

	// ① 永久停用
	if u.Status == "disabled" {
		return LoginResult{false, 403, 3002, "账号已被停用，请联系家庭管理员",
			"显示文案，不要引导重试", 0, 0}
	}

	// ② 临时锁定
	if u.LockedUntil != nil && now < *u.LockedUntil {
		left := *u.LockedUntil - now
		return LoginResult{false, 429, 1003,
			fmt.Sprintf("尝试次数过多，请在 %d 秒后重试", int(left)),
			fmt.Sprintf("显示倒计时 %d 秒，期间禁用输入框", int(left)), u.LockLevel, 0}
	}
	if u.LockedUntil != nil && now >= *u.LockedUntil {
		// 锁到期：自动解锁，把计数清零
		u.LockedUntil = nil
		u.FailedCnt = 0
		audit = append(audit, fmt.Sprintf("[t=%3.0f] AUTO_UNLOCK phone=%s", now, mask(phone)))
	}

	// ③ 密码校验（本程序用固定口令模拟，避免 bcrypt 的耗时）
	if password != "SunsetRiver42" {
		// 计数窗口：超过 15 分钟就清零
		fc := failStore[phone]
		if fc == nil || now-fc.last > CountWindow {
			fc = &failCounter{}
			failStore[phone] = fc
		}
		fc.count++
		fc.last = now
		u.FailedCnt = fc.count

		if fc.count >= MaxFailBeforeLock {
			// 达到阈值 → 锁定
			u.LockLevel++
			d := backoffSeconds(u.LockLevel)
			until := now + d
			u.LockedUntil = &until
			u.Status = "locked"
			fc.count = 0
			audit = append(audit, fmt.Sprintf("[t=%3.0f] LOCK phone=%s level=%d until=t=%.0f (%.0fs)",
				now, mask(phone), u.LockLevel, until, d))
			return LoginResult{false, 429, 1003,
				fmt.Sprintf("尝试次数过多，账号已锁定 %d 秒", int(d)),
				"提示「请在 N 分钟后重试，或用手机号验证码登录」", u.LockLevel, until}
		}
		audit = append(audit, fmt.Sprintf("[t=%3.0f] LOGIN_FAIL phone=%s cnt=%d/%d",
			now, mask(phone), fc.count, MaxFailBeforeLock))
		return LoginResult{false, 401, 1005, "手机号或密码错误",
			fmt.Sprintf("还可尝试 %d 次", MaxFailBeforeLock-fc.count), 0, 0}
	}

	// ④ 成功：清零一切
	fc := failStore[phone]
	if fc != nil {
		fc.count = 0
	}
	u.FailedCnt = 0
	if u.LockedUntil != nil {
		u.LockedUntil = nil
	}
	if u.LockLevel > 0 {
		u.LockLevel = 0 // 一次成功就清空退避级别
	}
	u.Status = "active"
	audit = append(audit, fmt.Sprintf("[t=%3.0f] LOGIN_OK   phone=%s", now, mask(phone)))
	return LoginResult{true, 200, 0, "ok", "正常返回", 0, 0}
}

func mask(p string) string { return p[:3] + "****" + p[7:] }

// =========================================================================
// 主流程

func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

