package main

// =====================================================================
// S4 · W17 · d29：A1 认证 7 条接口的实现清单
//
//   逐条对照 tech-plan §8.5 / PRD 3.7，给出每条的：
//   路由、守卫、请求/响应契约、错误码、对应到本周哪几天
// =====================================================================

import (
	"fmt"
	"sort"
	"strings"
)

// =====================================================================
// 接口定义
// =====================================================================

type Param struct {
	Name, In, Type, Required, Note string
}

type Resp struct {
	HTTP    int
	Code    int
	Payload string
}

type Endpoint struct {
	ID      string
	Method  string
	Path    string
	Public  bool
	Guards  []string
	Purpose string
	Req     []Param
	OK      Resp
	Errors  []Resp
	Days    []string
	Notes   []string
}

var endpoints = []Endpoint{
	{
		ID: "A1-1", Method: "POST", Path: "/api/homeos/auth/sms-code", Public: true,
		Guards:  []string{"RateLimit(1/min, 10/day)", "NoCache"},
		Purpose: "发送短信验证码。这是**唯一**的免鉴权业务接口。",
		Req: []Param{
			{"phone", "body", "string", "是", "11 位纯数字"},
			{"purpose", "body", "string", "是", "register / login / reset_password 三选一"},
			{"device_id", "body", "string", "否", "写进 homeos_sms_log 便于排查"},
		},
		OK: Resp{200, 0, `{"code":0,"message":"ok","data":{"sent":true,"cooldown_sec":60,"request_id":"..."}`},
		Errors: []Resp{
			{400, 4000, "手机号格式错误 / purpose 非法"},
			{429, 1003, "触发限流（每分钟 1 次或每天 10 次）"},
			{400, 1004, "验证码过于频繁（连续 3 次错误后拒发 1 小时）"},
			{500, 5000, "短信网关失败（本期未接商用通道，返回 sent=true 但记日志）"},
		},
		Days: []string{"d04", "d27"},
		Notes: []string{
			"PRD 14.6 明确本期**不接商用短信通道**，所以实现是「生成码 + 记日志 + 返回 sent=true」。",
			"  但流水线的形状要按真实通道设计，将来换成 adapter 接口即可。",
			"验证码只存 SHA-256(pepper + code)，**不存明文**（d04）。",
		},
	},
	{
		ID: "A1-2", Method: "POST", Path: "/api/homeos/auth/register", Public: true,
		Guards:  []string{"RateLimit(5/min per IP)", "NoCache"},
		Purpose: "手机号 + 密码 + 验证码注册。成功后按 d05 的折中方案**同时签发一对 token**。",
		Req: []Param{
			{"phone", "body", "string", "是", "11 位"},
