// hasAll 判断所有文件都包含某个标记
func fileHas(path, marker string) bool {
	for _, f := range files {
		if f.Path == path {
			return f.Has[marker]
		}
	}
	return false
}

func fileLacks(path, marker string) bool {
	for _, f := range files {
		if f.Path == path {
			return f.Missing[marker]
		}
	}
	return false
}

// anyFileHas 任意文件包含某标记（用于「全项目都没有 X」这类断言）
func anyFileHas(marker string) bool {
	for _, f := range files {
		if f.Has[marker] {
			return true
		}
	}
	return false
}

func anyFileMissing(marker string) bool {
	for _, f := range files {
		if f.Missing[marker] {
			return true
		}
	}
	return false
}

