// runChecks 跑全部断言，返回每条的结果。
func runChecks() []bool {
	out := make([]bool, len(checks))
	for i, c := range checks {
		ok, _ := c.Run()
		out[i] = ok
	}
	return out
}

// s4CheckScript 返回 scripts/s4-check.sh 的完整内容。
func s4CheckScript() string {
	return `#!/usr/bin/env bash
# scripts/s4-check.sh —— S4 身份与鉴权门禁
#
# 零依赖：只用 grep + awk，不起服务、不连库、不需要 Go 工具链。
# 退出码：0 = 全过，1 = 有失败，2 = 脚本自身出错。
set -uo pipefail

cd "$(dirname "$0")/.." || exit 2

FAIL=0
pass() { printf '  \033[32mPASS\033[0m  %s\n' "$1"; }
fail() { printf '  \033[31mFAIL\033[0m  %s\n' "$1"; FAIL=1; }

# ---- 0. 关键文件存在性：路径写错时必须 exit 2 而不是 1 ----
REQUIRED=(
  internal/auth/jwt.go
  internal/auth/middleware.go
  internal/auth/password.go
  internal/auth/refresh.go
  internal/auth/limit.go
  internal/auth/lock.go
  internal/handler/auth.go
  migrations/homeos/homeos_0001_create_user.up.sql
  migrations/homeos/homeos_0007_create_refresh_token.up.sql
)
for f in "\${REQUIRED[@]}"; do
  [ -f "$f" ] || { echo "  FATAL: 缺少 $f" >&2; exit 2; }
done

# ---- 1. W13 密码与身份 ----
grep -rqE 'md5\.Sum|sha1\.Sum' internal/ \
  && fail "C01 发现 MD5/SHA-1 用于密码" || pass "C01 无 MD5/SHA-1 存密码"

grep -q 'bcrypt.DefaultCost' internal/auth/password.go \
  && pass "C02 使用 bcrypt.DefaultCost" || fail "C02 未使用 bcrypt.DefaultCost"

grep -q 'locked_until' migrations/homeos/homeos_0001_create_user.up.sql \
  && pass "C04 users 表有锁定字段" || fail "C04 users 表缺 locked_until"

grep -q 'WHERE deleted_at IS NULL' migrations/homeos/homeos_0001_create_user.up.sql \
  && pass "C05 唯一索引带软删条件" || fail "C05 唯一索引缺 WHERE deleted_at IS NULL"

# ---- 2. W14 JWT ----
grep -q 'alg != "HS256"' internal/auth/jwt.go \
  && pass "C06 alg 钉死 HS256" || fail "C06 alg 未钉死（算法混淆风险）"

grep -rq 'jwt.Alg(.*header' internal/auth/jwt.go \
  && fail "C06 从 header 读取算法" || pass "C06 不从 header 读算法"

grep -q 'hmac.Equal' internal/auth/jwt.go \
  && pass "C07 签名用恒定时间比较" || fail "C07 签名未用 hmac.Equal"

for k in 'c.EXP' 'c.IAT' 'Leeway' 'c.Iss' 'c.Aud' 'wantType'; do
  grep -q "$k" internal/auth/jwt.go \
    && pass "C08..C10 jwt.go 含 $k" || fail "C08..C10 jwt.go 缺 $k"
done

# ---- 3. handler 纯净度（鉴权单一实现） ----
if grep -rnE 'role ==|role !=|jwt\.Parse|bcrypt\.Compare' \
     internal/handler/ --include='*.go' | grep -v _test.go >/dev/null; then
  fail "C22/C23 handler 里出现角色判定或重复验签"
else
  pass "C22/C23 handler 里零角色判定、零重复验签"
fi

grep -q 'ScopedToFamily\|Where("family_id' internal/repo/member.go \
  && pass "C24 repo 有 family 作用域" || fail "C24 repo 缺 family 作用域"

# ---- 4. refresh 与失效链 ----
for col in chain_id gen parent_id used_at revoked_at revoke_why; do
  grep -q "$col" migrations/homeos/homeos_0007_create_refresh_token.up.sql \
    && pass "C14/C15 refresh 表含 $col" || fail "C14/C15 refresh 表缺 $col"
done

grep -rq 'SELECT token FROM\|token TEXT' internal/repo/ \
  && fail "C16 refresh 疑似明文存储" || pass "C16 refresh 只存哈希"

grep -q 'db.Transaction' internal/auth/refresh.go \
  && pass "C17 轮换在同一事务内" || fail "C17 轮换未包事务"

grep -q 'PwdChanged' internal/auth/refresh.go \
  && pass "C20 refresh 校验 pwd_changed_at" || fail "C20 refresh 未校验 pwd_changed_at"

# ---- 5. A1 七条接口 ----
n=$(grep -cE '"/(sms-code|register|login|refresh|logout|logout-all|password)"' \\
     internal/handler/auth.go)
[ "$n" -ge 7 ] \
  && pass "C26 A1 七条接口齐全（$n）" || fail "C26 A1 接口只有 $n 条"

# ---- 6. 路由分域（门禁 4 的一部分） ----
bad=$(grep -oE '"/api/[a-z]+/' internal/router.go | grep -v '/api/homeos/' | sort -u)
[ -z "$bad" ] \
  && pass "C27 路由全在 /api/homeos/ 下" \
  || fail "C27 路由越域: $bad"

# ---- 7. 限流与锁定 ----
grep -q 'TokenBucket' internal/auth/limit.go \
  && pass "C28 有令牌桶" || fail "C28 缺令牌桶"

grep -q 'StatusTooManyRequests\|429' internal/auth/limit.go \
  && pass "C29 限流返 429" || fail "C29 限流未返 429"

grep -q 'backoff' internal/auth/lock.go \
  && pass "C30 有指数退避" || fail "C30 缺指数退避"

grep -q 'LockedUntil' internal/auth/lock.go \
  && pass "C31 有自动解锁" || fail "C31 缺自动解锁"

# ---- 8. 敏感信息不落日志 ----
grep -rn 'log.*Authorization.*%s\|log.*Bearer.*%v' srv/ internal/ \\
  | grep -v _test.go >/dev/null \
  && fail "C33 日志里可能打印整枚 token" || pass "C33 日志未打印整枚 token"

grep -rn 'log.*1[3-9][0-9]\\{9\\}' internal/ | grep -v _test.go >/dev/null \
  && fail "C34 日志里可能打印完整手机号" || pass "C34 日志未打印完整手机号"

# ---- 汇总 ----
if [ "$FAIL" -eq 0 ]; then
  echo "s4-check: ALL PASS"
  exit 0
fi
echo "s4-check: FAILED"
exit 1`
}

var _ = os.Stdout

// pad 按显示宽度左对齐补空格（中文占 2 列）
func pad(s string, width int) string {
	w := 0
	for _, r := range s {
		if isWide(r) {
			w += 2
		} else {
			w++
		}
	}
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func isWide(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F, r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3, r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE6F, r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6:
		return true
	}
	return false
}

