func main() {
	fmt.Println("=== 1. scripts/s4-check.sh 的真身 ============ ")
	fmt.Println("  （下面这段是**真项目里要用的脚本**，本程序逐行打印它）")
	fmt.Println()
	script := s4CheckScript()
	for _, line := range strings.Split(script, "\n") {
		if strings.HasPrefix(line, "#") && !strings.Contains(line, "!/") {
			fmt.Printf("  \033[1m%s\033[0m\n", line)
			continue
		}
		fmt.Printf("  %s\n", line)
	}

	fmt.Println("\n=== 2. 真跑这个脚本 ============ ")
	fmt.Println("  本机没有真实项目，所以跑的是一个**内存版**：")
	fmt.Println("  `files` 变量模拟了 10 个源文件的「包含/不包含」标记集合，")
	fmt.Println("  检查项与真实脚本一一对应（同样的 grep 语义、同样的判据）。")
	fmt.Println()
	runChecks() // 先跑一遍全量，确认没有 panic
	fmt.Printf("  扫描了 %d 个文件、%d 条断言\n", len(files), len(checks))
	fmt.Println()

	// 分组打印
	groups := map[string][]int{}
	order := []string{}
	for i, c := range checks {
		if _, ok := groups[c.Group]; !ok {
			order = append(order, c.Group)
		}
		groups[c.Group] = append(groups[c.Group], i)
	}
	sort.Strings(order)
	passAll := 0
	for _, g := range order {
		idxs := groups[g]
		gp := 0
		for _, i := range idxs {
			c := checks[i]

		ok, detail := c.Run()
		mark := "❌"
		if ok {
			mark = "✅"
			gp++
			passAll++
		}
		fmt.Printf("  %s %s %-30s %s\n", mark, pad(c.ID, 5), pad(c.Name, 30), detail)
	}
	fmt.Printf("     —— %s：通过 %d/%d\n\n", g, gp, len(idxs))
}

fmt.Printf("  ════════════════════════════════════════\n")
fmt.Printf("  总结果：通过 %d / %d\n", passAll, len(checks))
if passAll == len(checks) {
	fmt.Println("  ✅ S4 阶段判据自测全部通过")
} else {
	fmt.Println("  ❌ 有未通过项 —— 不要进入 S5")
}

fmt.Println("\n=== 3. 这个脚本检查不了什么（重要） ============ ")
fmt.Println("  grep 能查「某个危险写法出现了没有」，查不了「逻辑对不对」。以下必须靠测试：")
untestable := []struct {
	what, why, coveredBy string
}{
	{"轮换的事务原子性", "读代码看不出事务边界对不对，要跑",
		"test: 并发刷新 + 强制回滚"},
	{"越权返回 404", "handler 写了 404 也可能是错的分支写了",
		"test: 用 A 家 token 读 B 家数据（S5 逐格）"},
	{"重放检测的准确性", "有没有把合法并发误判成重放",
		"test: 同 IP 双击 + 跨 IP 重放两个样本"},
	{"锁定的原子性", "两个并发失败会不会都判「未到 5 次」",
		"test: 并发 10 次错误请求，断言 locked=true"},
	{"限流的正确性", "参数写错（比如 refill 单位是毫秒）grep 看不出来",
		"test: 假时钟推进，断言边界时刻"},
}
for _, u := range untestable {
	fmt.Printf("  ▪ %s\n", u.what)
	fmt.Printf("      %s\n", u.why)
	fmt.Printf("      覆盖：%s\n", u.coveredBy)
}
fmt.Println()
fmt.Println("  结论：**脚本过 ≠ 代码对**。脚本的作用是「挡住明显的退化」，")
fmt.Println("  而 S4 的五条判据（learning-plan）必须靠 `go test` 逐条断言。")
fmt.Println("  这也是 tech-plan §10.2 五道门禁里「测试门禁」单独存在的原因。")

fmt.Println("\n=== 4. 门禁化之后的样子 ============ ")
fmt.Println("  S4 的检查分成三层，本节对应第一层：")
layers := []struct{ layer, tool, when, blocks string }{
